#include <stdlib.h>
#include <string.h>

typedef struct {
    long timestamp;
    int sourceID;
    int destinationID;
    int payloadLength;
} DataPacket;

DataPacket* initializeDataPackets(int initialCapacity) {
    // Allocate memory for the array of data packets
    DataPacket* dataPackets = (DataPacket*)malloc(initialCapacity * sizeof(DataPacket));
    if (!dataPackets) {
        return NULL;
    }

    // Initialize the array with empty packets
    for (int i = 0; i < initialCapacity; i++) {
        dataPackets[i].timestamp = 0;
        dataPackets[i].sourceID = 0;
        dataPackets[i].destinationID = 0;
        dataPackets[i].payloadLength = 0;
    }

    return dataPackets;
}

void addDataPacket(DataPacket* dataPackets, int capacity, DataPacket newPacket) {
    // Check if the array is full and needs to be resized
    if (capacity == 0 || capacity == dataPackets->size) {
        // Double the size of the array
        capacity *= 2;
        DataPacket* newDataPackets = (DataPacket*)realloc(dataPackets, capacity * sizeof(DataPacket));
        if (!newDataPackets) {
            return;
        }
        dataPackets = newDataPackets;
    }

    // Add the new packet to the end of the array
    dataPackets[dataPackets->size++] = newPacket;
}

void updateDataPacket(DataPacket* dataPackets, int capacity, int sourceID, int destinationID, DataPacket updatedPacket) {
    // Find the packet with the matching source and destination IDs
    for (int i = 0; i < capacity; i++) {
        if (dataPackets[i].sourceID == sourceID && dataPackets[i].destinationID == destinationID) {
            // Update the packet with the new values
            dataPackets[i] = updatedPacket;
            return;
        }
    }
}

DataPacket* getDataPacket(DataPacket* dataPackets, int capacity, int sourceID, int destinationID) {
    // Find the packet with the matching source and destination IDs
    for (int i = 0; i < capacity; i++) {
        if (dataPackets[i].sourceID == sourceID && dataPackets[i].destinationID == destinationID) {
            return &dataPackets[i];
        }
    }

    // If no matching packet is found, return NULL
    return NULL;
}

void freeDataPackets(DataPacket* dataPackets, int capacity) {
    // Free the memory allocated for the array of data packets
    free(dataPackets);
}
