// Define the record structure
typedef struct {
    int value;
} Record;

// Define the function to allocate and initialize memory for arrays
void allocate_memory(int num_records, int max_value) {
    // Allocate memory for the offset array
    long *offset_array = (long *)malloc(num_records * sizeof(long));
    if (!offset_array) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for the key array
    int *key_array = (int *)malloc(num_records * sizeof(int));
    if (!key_array) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offset_array);
        return;
    }

    // Allocate memory for the record array
    Record *record_array = (Record *)malloc(num_records * sizeof(Record));
    if (!record_array) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offset_array);
        free(key_array);
        return;
    }

    // Initialize the offset and key arrays
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % max_value;
        key_array[i] = i;
    }

    // Initialize the record array
    for (int i = 0; i < num_records; i++) {
        record_array[i].value = rand() % max_value;
    }

    // Free memory when no longer needed
    free(offset_array);
    free(key_array);
    free(record_array);
}

// Define the validation function to ensure memory allocation does not exceed a specified maximum size threshold
void validate_memory(int num_records, int max_value) {
    // Calculate the total memory required for the arrays
    long total_memory = (num_records * sizeof(long)) + (num_records * sizeof(int)) + (num_records * sizeof(Record));

    // Check if the total memory exceeds the maximum size threshold
    if (total_memory > max_value) {
        printf("Error: Total memory allocation exceeds maximum size threshold\n");
    }
}

// Define a thread-safe function to free all allocated memory once records are no longer needed
void free_memory(Record *record_array, int num_records) {
    // Free the record array
    free(record_array);

    // Free the key and offset arrays
    free((int *)record_array[0].value);
    free((long *)record_array[0].value);
}
