public class PokemonReport {
    public static String getPokemonReport(Pokemon pokemon) {
        // Fetch the Pokemon's type and name from an external API
        String type = fetchTypeFromAPI(pokemon.getId());
        String name = fetchNameFromAPI(pokemon.getId());

        // Use a switch statement to determine weaknesses, resistances, and immunities based on the Pokemon's type
        List<String> weaknesses = new ArrayList<>();
        List<String> resistances = new ArrayList<>();
        List<String> immunities = new ArrayList<>();

        switch (type) {
            case "Fire":
                weaknesses.add("Water");
                break;
            case "Water":
                weaknesses.add("Fire");
                break;
            case "Grass":
                weaknesses.add("Fire");
                weaknesses.add("Ice");
                break;
            case "Ice":
                weaknesses.add("Grass");
                break;
            default:
                // Handle cases where a type has no weaknesses but does have resistances or immunities
                if (type.equals("Poison")) {
                    resistances.add("Fighting");
                    resistances.add("Ground");
                } else if (type.equals("Flying")) {
                    resistances.add("Electric");
                    resistances.add("Ice");
                } else if (type.equals("Bug")) {
                    immunities.add("Poison");
                }
        }

        // Combine the weaknesses from each type
        List<String> combinedWeaknesses = new ArrayList<>();
        for (String type : pokemon.getTypes()) {
