            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();
            int responseCode = connection.getResponseCode();
            if (responseCode == 200) {
                BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
                String line;
                StringBuilder builder = new StringBuilder();
                while ((line = reader.readLine()) != null) {
                    builder.append(line);
                }
                JSONObject json = new JSONObject(builder.toString());
                return json.getString("types");
            } else {
                // Handle API failure gracefully
                System.out.println("API request failed with response code " + responseCode);
                return null;
            }
        } catch (IOException | JSONException e) {
            // Handle network errors and JSON parsing exceptions gracefully
            System.out.println("Error fetching Pokemon type: " + e.getMessage());
            return null;
        }
    }

    private static String fetchNameFromAPI(int id) {
        // Fetch the Pokemon's name from an external API using a network request
        try {
            URL url = new URL("https://pokeapi.co/api/v2/pokemon/" + id);
