#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure to hold the thread pool data
typedef struct {
    int max_threads; // Maximum number of threads in the pool
    int num_threads; // Current number of threads in the pool
    pthread_t *threads; // Array of thread IDs
    semaphore_t sem; // Semaphore to synchronize access to the pool
} thread_pool_t;

// Initialize the thread pool with a given maximum number of threads
void init_thread_pool(thread_pool_t *pool, int max_threads) {
    pool->max_threads = max_threads;
    pool->num_threads = 0;
    pool->threads = malloc(sizeof(pthread_t) * max_threads);
    sem_init(&pool->sem, 0, 1); // Initialize the semaphore to 1
}

// Execute a set of tasks concurrently using the thread pool
void execute_tasks(thread_pool_t *pool, void (*task)(void *), void **args, int num_tasks) {
    for (int i = 0; i < num_tasks; i++) {
        // Acquire a semaphore to access the pool
        sem_wait(&pool->sem);
        if (pool->num_threads < pool->max_threads) {
            // Create a new thread and execute the task
            pthread_create(&pool->threads[pool->num_threads], NULL, task, args[i]);
            pool->num_threads++;
        } else {
            // Wait for a thread to finish before creating a new one
            sem_wait(&pool->sem);
            pthread_join(pool->threads[pool->num_threads], NULL);
            pool->num_threads--;
        }
        // Release the semaphore
        sem_post(&pool->sem);
    }
}

// Clean up the thread pool and free all resources
void cleanup_thread_pool(thread_pool_t *pool) {
    for (int i = 0; i < pool->num_threads; i++) {
        pthread_join(pool->threads[i], NULL);
    }
    sem_destroy(&pool->sem);
    free(pool->threads);
}
