#include <boost/asio.hpp>
#include <boost/bind.hpp>
#include <boost/thread.hpp>
#include <boost/circular_buffer.hpp>
#include <boost/algorithm/string.hpp>
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <set>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

using namespace boost;
using namespace std;

// Define the Sandesh client class
class SandeshClient {
public:
    // Constructor
    SandeshClient(const string& configFile) : configFile_(configFile), servers_(), proxySessions_(), requestStats_() {}

    // Destructor
    ~SandeshClient() {}

    // Initialize the client with the configuration file
    void init();

    // Send a GET request to the server
    void sendGetRequest(const string& url);

    // Handle the response from the server
    void handleResponse(const boost::system::error_code& error, size_t bytesTransferred);

private:
    // Configuration file path
    const string configFile_;

    // Map of servers and their corresponding proxy sessions
    map<string, set<int>> servers_;

    // Set of active proxy sessions
    set<int> proxySessions_;

    // Rolling statistics window for requests
    circular_buffer<RequestStats> requestStats_;
};

// Define the RequestStats struct to store request metrics
struct RequestStats {
    int successfulRequests;
    int failedRequests;
    int proxySessions;
    double successRate;
};

// Initialize the client with the configuration file
void SandeshClient::init() {
    // Load the server addresses from the configuration file
    ifstream configFile(configFile_);
    string line;
    while (getline(configFile, line)) {
        vector<string> tokens = boost::split(line, " ");
        servers_.insert({tokens[0], set<int>()});
    }
}

// Send a GET request to the server
void SandeshClient::sendGetRequest(const string& url) {
    // Find the next available proxy session
    int proxySession = 0;
    for (auto it = servers_.begin(); it != servers_.end(); ++it) {
        if (it->second.size() < 10) {
            proxySession = *(it->second.begin());
            break;
        }
    }

    // Create a new HTTP GET request
    auto request = make_shared<http::request<http::string_body>>(http::verb::get, url);

    // Set the proxy session ID in the request headers
    request->set(http::field::proxy_session, to_string(proxySession));

    // Send the request asynchronously
    http::async_write(socket_, *request, boost::bind(&SandeshClient::handleResponse, this, placeholders::error, placeholders::bytes_transferred));
}

// Handle the response from the server
void SandeshClient::handleResponse(const boost::system::error_code& error, size_t bytesTransferred) {
    // Check for any errors
    if (error) {
        cerr << "Error: " << error.message() << endl;
        return;
    }

    // Parse the response headers and body
    auto response = make_shared<http::response<http::string_body>>(*request);
    http::read(socket_, *response, boost::bind(&SandeshClient::handleResponse, this, placeholders::error, placeholders::bytes_transferred));

    // Update the request statistics
    updateRequestStats();

    // Print out the request and response metrics
    printMetrics();
}

// Update the request statistics
void SandeshClient::updateRequestStats() {
    // Increment the number of successful requests
    if (response->result_int() == 200) {
        requestStats_.push_back({1, 0, proxySession_, 1.0});
    } else {
        requestStats_.push_back({0, 1, proxySession_, 0.0});
    }
}

// Print out the request and response metrics
void SandeshClient::printMetrics() {
    // Calculate the total number of requests, successful requests, failed requests, and proxy sessions
    int totalRequests = 0;
    int successfulRequests = 0;
    int failedRequests = 0;
    int proxySessions = 0;
    for (auto it = requestStats_.begin(); it != requestStats_.end(); ++it) {
        totalRequests += it->successfulRequests + it->failedRequests;
        successfulRequests += it->successfulRequests;
        failedRequests += it->failedRequests;
        proxySessions += it->proxySessions;
    }

    // Calculate the success rate
    double successRate = 0.0;
    if (totalRequests > 0) {
        successRate = successfulRequests / totalRequests;
    }

    // Print out the metrics
    cout << "Total requests: " << totalRequests << endl;
    cout << "Successful requests: " << successfulRequests << endl;
    cout << "Failed requests: " << failedRequests << endl;
    cout << "Proxy sessions: " << proxySessions << endl;
    cout << "Success rate: " << successRate * 100.0 << "%" << endl;
}
