#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <vector>

namespace Logging {
    class Logger {
    public:
        Logger() = default;
        ~Logger() = default;

        static void setLogLevel(const std::string& level) {
            // Set the log level based on the input string
            if (level == "DEBUG") {
                m_logLevel = LogLevel::DEBUG;
            } else if (level == "INFO") {
                m_logLevel = LogLevel::INFO;
            } else if (level == "WARNING") {
                m_logLevel = LogLevel::WARNING;
            } else if (level == "ERROR") {
                m_logLevel = LogLevel::ERROR;
            } else {
                // Default to INFO level if the input string is not recognized
                m_logLevel = LogLevel::INFO;
            }
        }

        static void setLogOutput(const std::string& output) {
            // Set the log output based on the input string
            if (output == "console") {
                m_logOutput = LogOutput::CONSOLE;
            } else if (output == "file") {
                m_logOutput = LogOutput::FILE;
            } else if (output == "both") {
                m_logOutput = LogOutput::BOTH;
            } else {
                // Default to console output if the input string is not recognized
                m_logOutput = LogOutput::CONSOLE;
            }
        }

        static void log(const std::string& message) {
            // Acquire a lock on the logger instance
            std::lock_guard<std::mutex> lock(m_mutex);

            // Check if the current thread is allowed to log messages at this level
            if (m_logLevel == LogLevel::DEBUG && m_logOutput != LogOutput::CONSOLE) {
                return;
            } else if (m_logLevel == LogLevel::INFO && m_logOutput != LogOutput::BOTH) {
                return;
            } else if (m_logLevel == LogLevel::WARNING && m_logOutput != LogOutput::CONSOLE && m_logOutput != LogOutput::FILE) {
                return;
            } else if (m_logLevel == LogLevel::ERROR && m_logOutput != LogOutput::CONSOLE && m_logOutput != LogOutput::FILE && m_logOutput != LogOutput::BOTH) {
                return;
            }

            // Write the log message to the appropriate output stream
            if (m_logOutput == LogOutput::CONSOLE || m_logOutput == LogOutput::BOTH) {
                std::cout << "[" << m_logLevel << "] " << message << std::endl;
            }
            if (m_logOutput == LogOutput::FILE || m_logOutput == LogOutput::BOTH) {
                // Use the C++20 `std::sync_stream` to write the log message to a file in a thread-safe manner
                std::ofstream logFile("log.txt", std::ios::app);
                logFile << "[" << m_logLevel << "] " << message << std::endl;
            }
        }

    private:
        // Define the logging levels and output streams
        enum class LogLevel { DEBUG, INFO, WARNING, ERROR };
        enum class LogOutput { CONSOLE, FILE, BOTH };

        // Use a mutex to ensure thread-safe access to the logger instance
        static std::mutex m_mutex;

        // Set the default log level and output stream
        static LogLevel m_logLevel = LogLevel::INFO;
        static LogOutput m_logOutput = LogOutput::CONSOLE;
    };
}
```
This code defines a custom thread-safe logging mechanism in C++ using a namespace, a class with a constructor and destructor, and a static member variable for the logger instance. The class provides methods to set the log level and output destination, as well as a method to log messages at different levels. The `log` method acquires a lock on the logger instance before writing the message to the appropriate output stream using the C++20 `std::sync_stream`.']

['```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;

public static IDataReader ExecuteQuery(SqlConnection connection, List<FilterCriteria> filterCriteria, string baseCommandString)
{
    // Validate input parameters
    if (connection == null) throw new ArgumentNullException(nameof(connection));
    if (filterCriteria == null) throw new ArgumentNullException(nameof(filterCriteria));
    if (baseCommandString == null) throw new ArgumentNullException(nameof(baseCommandString));

    // Build the SQL query based on the filter criteria
    var query = baseCommandString;
    foreach (var criterion in filterCriteria)
    {
        switch (criterion.Operator)
        {
            case FilterOperator.Equals:
                query += $" WHERE {criterion.Column} = @{criterion.ParameterName}";
                break;
            case FilterOperator.NotEquals:
                query += $" WHERE {criterion.Column} != @{criterion.ParameterName}";
                break;
            case FilterOperator.GreaterThan:
                query += $" WHERE {criterion.Column} > @{criterion.ParameterName}";
                break;
            case FilterOperator.LessThan:
                query += $" WHERE {criterion.Column} < @{criterion.ParameterName}";
                break;
            case FilterOperator.GreaterThanOrEqualTo:
                query += $" WHERE {criterion.Column} >= @{criterion.ParameterName}";
                break;
            case FilterOperator.LessThanOrEqualTo:
                query += $" WHERE {criterion.Column} <= @{criterion.ParameterName}";
                break;
        }
    }

    // Add ordering and pagination if necessary
    if (filterCriteria.Any(c => c.OrderBy != null))
    {
        query += " ORDER BY ";
        foreach (var criterion in filterCriteria.Where(c => c.OrderBy != null))
        {
            query += $"{criterion.Column} {criterion.OrderBy}, ";
        }
        query = query.Substring(0, query.Length - 2);
    }
    if (filterCriteria.Any(c => c.PageSize != null))
    {
        query += $" OFFSET @{FilterCriteria.ParameterName} ROWS FETCH NEXT @{FilterCriteria.PageSize} ROWS ONLY";
    }

    // Execute the SQL query and return an IDataReader for the result set
    var command = new SqlCommand(query, connection);
    foreach (var criterion in filterCriteria)
    {
        command.Parameters.AddWithValue($"@{criterion.ParameterName}", criterion.Value);
    }
    return command.ExecuteReader();
}
```
This method takes a `SqlConnection` object, a list of `FilterCriteria` objects, and a base SQL command string as input parameters. It constructs a dynamic SQL query based on the filter criteria provided by the user, and executes it using an `SqlCommand` object. The resulting `IDataReader` object is returned to the caller.

The method first validates the input parameters to ensure that they are not null. Then, it builds the SQL query based on the filter criteria provided by the user. It uses a loop to iterate over the list of filter criteria and constructs the SQL query accordingly. For example, if the user provides a filter criterion for a column with an operator of "Equals", the method will add a `WHERE` clause to the SQL query using the column name and parameter value provided by the user.

The method also adds ordering and pagination to the SQL query if necessary. If the user provides any filter criteria that specifies an order-by or page size, the method will add appropriate clauses to the SQL query. For example, if the user provides a filter criterion for a column with an order-by value of "DESC", the method will add an `ORDER BY` clause to the SQL query using the column name and direction provided by the user. Similarly, if the user provides a filter criterion for a page size, the method will add a `OFFSET` and `FETCH NEXT` clause to the SQL query using the page size provided by the user.

Once the SQL query has been constructed, the method executes it using an `SqlCommand` object and returns an `IDataReader` object for the result set. The caller can then use this `IDataReader` object to retrieve data from the database.']

