<?php

function handleUserRequest($_REQUEST) {
    // Initialize variables
    $id = isset($_REQUEST['id']) ? $_REQUEST['id'] : null;
    $name = $_REQUEST['name'];
    $email = $_REQUEST['email'];
    $password = $_REQUEST['password'];
    $sub_action = isset($_REQUEST['sub_action']) ? $_REQUEST['sub_action'] : null;

    // Validate input data
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return json_encode([
            'message' => 'error',
            'data' => [
                'error' => 'Invalid email address.'
            ]
        ]);
    }

    if (strlen($password) < 8) {
        return json_encode([
            'message' => 'error',
            'data' => [
                'error' => 'Password must be at least 8 characters long.'
            ]
        ]);
    }

    // Check for duplicate entries
    $duplicate = checkDuplicate($name, $email);
    if ($duplicate) {
        return json_encode([
            'message' => 'error',
            'data' => [
                'error' => 'A user with the same name and email already exists.'
            ]
        ]);
    }

    // Prepare statement for database interaction
    $stmt = $pdo->prepare('SELECT * FROM users WHERE id = :id');
    $stmt->bindParam(':id', $id, PDO::PARAM_INT);

    // Check if user exists
    if ($stmt->execute() && $stmt->rowCount() > 0) {
        // Update user account
        $user = $stmt->fetch(PDO::FETCH_ASSOC);
        $updateStmt = $pdo->prepare('UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id');
        $updateStmt->bindParam(':name', $name, PDO::PARAM_STR);
        $updateStmt->bindParam(':email', $email, PDO::PARAM_STR);
        $updateStmt->bindParam(':password', $password, PDO::PARAM_STR);
        $updateStmt->bindParam(':id', $id, PDO::PARAM_INT);

        if ($updateStmt->execute()) {
            return json_encode([
                'message' => 'success',
                'data' => [
                    'user' => $user
                ]
            ]);
        } else {
            return json_encode([
                'message' => 'error',
                'data' => [
                    'error' => 'Error updating user account.'
                ]
            ]);
        }
    } else {
        // Create new user account
        $insertStmt = $pdo->prepare('INSERT INTO users (name, email, password) VALUES (:name, :email, :password)');
        $insertStmt->bindParam(':name', $name, PDO::PARAM_STR);
        $insertStmt->bindParam(':email', $email, PDO::PARAM_STR);
        $insertStmt->bindParam(':password', $password, PDO::PARAM_STR);

        if ($insertStmt->execute()) {
            return json_encode([
                'message' => 'success',
                'data' => [
                    'user' => $insertStmt->fetch(PDO::FETCH_ASSOC)
                ]
            ]);
        } else {
            return json_encode([
                'message' => 'error',
                'data' => [
                    'error' => 'Error creating new user account.'
                ]
            ]);
        }
    }
}

function checkDuplicate($name, $email) {
    // Prepare statement for database interaction
    $stmt = $pdo->prepare('SELECT * FROM users WHERE name = :name AND email = :email');
    $stmt->bindParam(':name', $name, PDO::PARAM_STR);
    $stmt->bindParam(':email', $email, PDO::PARAM_STR);

    // Check if duplicate exists
    if ($stmt->execute() && $stmt->rowCount() > 0) {
        return true;
    } else {
        return false;
    }
}
```
