import { import } from 'module';

function runTests(moduleName, testCases, maxConcurrency) {
  const module = await import(moduleName);
  const blueslip = module.blueslip;
  const resetBlueslip = blueslip.reset();

  let successfulTests = 0;
  let erroredTests = 0;
  let totalTests = testCases.length;

  const startTime = Date.now();

  for (const testCase of testCases) {
    try {
      await Promise.all(testCase(), { concurrency: maxConcurrency });
      successfulTests++;
    } catch (error) {
      erroredTests++;
      console.log(`Error in ${moduleName} - ${testCase.name}:`, error);
    } finally {
      resetBlueslip();
    }
  }

  const endTime = Date.now();
  const duration = endTime - startTime;

  console.log(`${totalTests} tests executed in ${duration}ms`);
  console.log(`${successfulTests} successful, ${erroredTests} errored`);

  return { totalTests, successfulTests, erroredTests };
}
```
This code uses the `import` statement to load the module and access its exports, including the `blueslip` mocking library. It then defines a function that takes three arguments: `moduleName`, an array of test functions, and `maxConcurrency`, an integer specifying the maximum number of tests that can run simultaneously.

The function first loads the module using `import` and gets a reference to its exports, including the `blueslip` mocking library. It then defines a custom reset function for the `blueslip` library, which is used to reset the library after each test case.

