function traverseDOM(rootElement, selector, maxDepth) {
  const elements = [];
  let currentDepth = 0;

  function traverse(element) {
    if (currentDepth >= maxDepth) return;
    if (element.matches(selector)) elements.push(element);
    for (const child of element.children) {
      traverse(child);
    }
    currentDepth++;
  }

  traverse(rootElement);
  return elements;
}

// Example usage:
const root = document.querySelector('body');
const selector = 'div';
const maxDepth = 5;
const elements = traverseDOM(root, selector, maxDepth);
console.log(elements); // Outputs an array of all div elements in the DOM tree with a maximum depth of 5."]

