// JavaScript module for dynamic script loading and execution
(function() {
  // Define an object to store loaded scripts
  var loadedScripts = {};

  // Function to load a script asynchronously
  function loadScript(url) {
    return new Promise((resolve, reject) => {
      // Check if the script has already been loaded
      if (loadedScripts[url]) {
        resolve();
      } else {
        // Create a new script element and set its attributes
        var script = document.createElement("script");
        script.src = url;
        script.async = true;

        // Add an event listener to handle successful loading
        script.addEventListener("load", () => {
          loadedScripts[url] = true;
          resolve();
        });

        // Add an event listener to handle errors during loading
        script.addEventListener("error", (event) => {
          reject(new Error(`Failed to load script ${url}: ${event.message}`));
        });

        // Append the script element to the document head
        document.head.appendChild(script);
      }
    });
  }

  // Function to execute a script
  function executeScript(url) {
    return new Promise((resolve, reject) => {
      // Check if the script has already been loaded
      if (loadedScripts[url]) {
        resolve();
      } else {
        loadScript(url).then(() => {
          // Get a reference to the script element
          var script = document.querySelector(`script[src="${url}"]`);

          // Execute the script and handle any errors that occur
          try {
            script.parentNode.removeChild(script);
            resolve();
          } catch (error) {
            reject(new Error(`Failed to execute script ${url}: ${error.message}`));
          }
        });
      }
    });
  }

  // Function to load and execute a set of scripts
  function loadAndExecuteScripts(urls) {
    return Promise.all(urls.map((url) => loadScript(url).then(() => executeScript(url))));
  }

  // Export the module functions
  window.dynamicScriptLoader = {
    loadScript,
    executeScript,
    loadAndExecuteScripts,
  };
})();
```
