['```java
import java.util.*;

public class RequestProcessor {
    private static final int THRESHOLD = 10; // adjustable threshold value

    public static List<RequestInterval> processRequests(List<Request> requests) {
        IntervalTree tree = new IntervalTree();
        for (Request request : requests) {
            long startTime = request.getStartTime();
            long endTime = request.getEndTime();
            int priority = request.getPriorityLevel();
            RequestInterval interval = new RequestInterval(startTime, endTime, priority);
            tree.add(interval);
        }

        List<RequestInterval> nonOverlappingIntervals = new ArrayList<>();
        for (RequestInterval interval : tree) {
            if (interval.getPriorityLevel() <= THRESHOLD) {
                nonOverlappingIntervals.add(interval);
            }
        }

        return nonOverlappingIntervals;
    }
}

class Request {
    private long startTime;
    private long endTime;
    private int priorityLevel;

    public Request(long startTime, long endTime, int priorityLevel) {
        this.startTime = startTime;
        this.endTime = endTime;
        this.priorityLevel = priorityLevel;
    }

    public long getStartTime() {
        return startTime;
    }

    public long getEndTime() {
        return endTime;
    }

    public int getPriorityLevel() {
        return priorityLevel;
    }
}

class RequestInterval implements Comparable<RequestInterval> {
    private long startTime;
    private long endTime;
    private int priorityLevel;

    public RequestInterval(long startTime, long endTime, int priorityLevel) {
        this.startTime = startTime;
        this.endTime = endTime;
        this.priorityLevel = priorityLevel;
    }

    @Override
    public int compareTo(RequestInterval other) {
        if (this.startTime < other.startTime) {
            return -1;
        } else if (this.startTime > other.startTime) {
            return 1;
        } else {
            return 0;
        }
    }

    public long getStartTime() {
        return startTime;
    }

    public long getEndTime() {
        return endTime;
    }

    public int getPriorityLevel() {
        return priorityLevel;
    }
}

class IntervalTree {
    private List<RequestInterval> intervals = new ArrayList<>();

    public void add(RequestInterval interval) {
        intervals.add(interval);
    }

    public Iterator<RequestInterval> iterator() {
        return intervals.iterator();
    }
}
```']

