public class ServiceManager {
    private static final int MIN_DELAY = 10; // minimum delay in seconds
    private static final int MAX_DELAY = 60; // maximum delay in seconds

    private static final String SERVICE_NAME = "my-service";

    private static final Random RANDOM = new Random();

    public static void main(String[] args) {
        while (true) {
            try {
                startService();
                TimeUnit.SECONDS.sleep(getDelay());
                stopService();
            } catch (InterruptedException e) {
                // handle interruption gracefully
            }
        }
    }

    private static void startService() throws InterruptedException {
        System.out.println("Starting " + SERVICE_NAME);
        // perform service startup actions here
        TimeUnit.SECONDS.sleep(getDelay());
    }

    private static void stopService() throws InterruptedException {
        System.out.println("Stopping " + SERVICE_NAME);
        // perform service shutdown actions here
        TimeUnit.SECONDS.sleep(getDelay());
    }

    private static int getDelay() {
        return RANDOM.nextInt(MAX_DELAY - MIN_DELAY + 1) + MIN_DELAY;
    }
}

