    // Measure the time taken for compilation and record the resident set size before and after compilation
    let elapsed = start.elapsed();
    resident_set_size_before = get_resident_set_size(None);
    result.map(|()| {
        resident_set_size_after = get_resident_set_size(None);
    }).unwrap_or_else(|e| {
        early_error(&format!("Compilation failed: {}", e));
    });

    // Retry failed compilations a specified number of times before giving up
    let mut retries = 0;
    while retries < MAX_RETRIES && exit_code != 0 {
        retries += 1;
        resident_set_size_before = get_resident_set_size(None);
        result = catch_with_exit_code(|cx| {
            rustc_driver::run(&mut cx, &[], &[])
        });
        resident_set_size_after = get_resident_set_size(None);
        result.map(|()| {
            exit_code = 0;
        }).unwrap_or_else(|e| {
            early_error(&format!("Compilation failed: {}", e));
        });
    }

    // Log detailed metrics about each compilation attempt, including success/failure status, elapsed time, and resource usage
    log_metrics(retries, exit_code, elapsed, resident_set_size_before, resident_set_size_after);

    // Return the exit code of the subprocess
    exit_code
}

struct CustomLoggingHook;

impl rustc_driver::Hook for CustomLoggingHook {
    fn on_compile_start(&mut self, _: &rustc_driver::CrateContext) {}

    fn on_compile_finish(&mut self, cx: &rustc_driver::CrateContext) -> i32 {
        let exit_code = cx.exit_code;
        log_metrics(0, exit_code, time::Instant::now().elapsed(), 0, 0);
        exit_code
