// Define the structure for a transaction
typedef struct {
    int id;
    double weighted_sum;
    long age;
} Transaction;

// Define the structure for the moving average
typedef struct {
    int size;
    double sum;
    double *values;
} MovingAverage;

// Define the function to calculate the moving average
void calculate_moving_average(MovingAverage *ma, Transaction *t) {
    // Update the sum and values array
    ma->sum += t->weighted_sum;
    ma->values[ma->size++] = t->weighted_sum;

    // If the size of the moving average is greater than 100, remove the oldest value
    if (ma->size > 100) {
        ma->sum -= ma->values[0];
        memmove(ma->values, ma->values + 1, sizeof(double) * (ma->size - 1));
    }
}

// Define the function to filter transactions based on age and weighted sum threshold
int filter_transactions(Transaction *t, int max_age, double weighted_sum_threshold) {
    // Check if the transaction is older than the maximum age
    if (t->age > max_age) {
        return 1;
    }

    // Check if the transaction's weighted sum exceeds the threshold
    if (t->weighted_sum > weighted_sum_threshold) {
        return 2;
    }

    // If none of the above conditions are met, return 0
    return 0;
}

// Define the function to process a transaction and update metrics
void process_transaction(Transaction *t, int *processed_transactions, int *filtered_transactions) {
    // Increment the number of processed transactions
    (*processed_transactions)++;

    // Filter the transaction based on age and weighted sum threshold
    if (filter_transactions(t, 5000, 90.0 * get_moving_average()) == 1) {
        // Increment the number of filtered transactions due to age
        (*filtered_transactions)++;
    } else if (filter_transactions(t, 5000, 90.0 * get_moving_average()) == 2) {
        // Increment the number of filtered transactions due to weighted sum threshold
        (*filtered_transactions)++;
    }
}

// Define the function to return the maximum weighted sum and corresponding transaction ID
int get_max_weighted_sum(Transaction *t, int size) {
    // Initialize variables
    double max_weighted_sum = -1.0;
    int max_id = -1;

    // Iterate over the transactions and find the maximum weighted sum
    for (int i = 0; i < size; i++) {
        if (t[i].weighted_sum > max_weighted_sum) {
            max_weighted_sum = t[i].weighted_sum;
            max_id = t[i].id;
        }
    }

    // Return the maximum weighted sum and corresponding transaction ID, or -1 if no valid transactions were processed
    return (max_id == -1) ? -1 : max_id;
}

// Define the function to handle incoming transactions and update metrics
void handle_incoming_transactions(Transaction *t, int size, int *processed_transactions, int *filtered_transactions) {
    // Iterate over the transactions and process them
    for (int i = 0; i < size; i++) {
        process_transaction(&t[i], processed_transactions, filtered_transactions);
    }
}

// Define the function to calculate the moving average of the weighted sums over the last 100 transactions
double get_moving_average(Transaction *t, int size) {
    // Initialize variables
    MovingAverage ma;
    ma.size = 0;
    ma.sum = 0.0;
    ma.values = (double *)malloc(sizeof(double) * 100);

    // Iterate over the transactions and calculate the moving average
    for (int i = 0; i < size; i++) {
        calculate_moving_average(&ma, &t[i]);
    }

    // Return the moving average
    return ma.sum / ma.size;
}

// Define the function to ensure thread safety for concurrent access from multiple threads handling different transaction streams
void synchronize(Transaction *t, int size) {
    // Use a mutex to protect the shared data structure
    pthread_mutex_lock(&mutex);

    // Handle incoming transactions and update metrics
    handle_incoming_transactions(t, size, &processed_transactions, &filtered_transactions);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}
```
This code defines a function `handle_incoming_transactions` that takes an array of transactions and processes them using the specified criteria. It also maintains moving averages of the weighted sums over the last 100 transactions to ensure the current transaction does not violate this average threshold. The function returns the maximum weighted sum of all processed transactions along with the corresponding transaction ID, or `-1` if no valid transactions were processed.

The code also defines a function `get_moving_average` that calculates the moving average of the weighted sums over the last 100 transactions. This function uses a mutex to ensure thread safety for concurrent access from multiple threads handling different transaction streams.

Finally, the code defines a function `synchronize` that ensures thread safety for concurrent access from multiple threads handling different transaction streams by using a mutex to protect the shared data structure."]

