#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

void modify_filename(char* filename, char* filetype) {
    // Get the original filename and extension
    char* orig_filename = strrchr(filename, '.');
    if (orig_filename == NULL) {
        orig_filename = filename;
    } else {
        orig_filename++; // Skip the dot
    }

    // Generate a random sequence of digits
    int num_digits = strlen(orig_filename);
    char* rand_seq = (char*)malloc(num_digits + 1);
    for (int i = 0; i < num_digits; i++) {
        rand_seq[i] = '0' + (rand() % 10);
    }
    rand_seq[num_digits] = '\0';

    // Construct the new filename
    char* new_filename = (char*)malloc(256);
    sprintf(new_filename, "%s%s.%s", orig_filename, rand_seq, filetype);

    // Check for uniqueness by appending a random number until no conflict is found
    int i = 0;
    while (access(new_filename, F_OK) == 0) {
        sprintf(new_filename, "%s%d.%s", orig_filename, i++, filetype);
    }

    // Free memory and return the new filename
    free(rand_seq);
    free(new_filename);
    return;
}
```
This function takes a `char*` pointer to the original filename as input, and modifies its extension to include a sequence of random digits followed by the specified file type. The resulting filename is guaranteed to be unique among all files in the current directory.

