#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <string.h>

// Define the key length and number of iterations for the KDF
#define KEY_LEN 32
#define ITERATIONS 10000

// Define the initialization vector size
#define IV_SIZE AES_BLOCK_SIZE

// Define the maximum buffer size for encryption/decryption
#define MAX_BUFFER_SIZE (1 << 24)

// Define the error codes for the cipher functions
#define CIPHER_ERROR -1
#define INVALID_PARAMETERS -2
#define MEMORY_ALLOCATION_FAILED -3

// Define the structure to hold the initialization context
typedef struct {
    AES_KEY aes_key; // The encryption key
    unsigned char iv[IV_SIZE]; // The initialization vector
} init_context_t;

// Function to initialize the cipher with a given password and generate an IV
int init_cipher(const char* password, init_context_t* context) {
    // Check if the parameters are valid
    if (password == NULL || context == NULL) {
        return INVALID_PARAMETERS;
    }

    // Generate a cryptographically secure initialization vector using OpenSSL's random number generator
    if (!RAND_bytes(context->iv, IV_SIZE)) {
        return CIPHER_ERROR;
    }

    // Derive the encryption key securely from the password using a salted key derivation function (KDF)
    unsigned char salt[KEY_LEN];
    if (!RAND_bytes(salt, KEY_LEN)) {
        return CIPHER_ERROR;
    }
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return MEMORY_ALLOCATION_FAILED;
    }
    if (!EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha1(), salt, (unsigned char*)password, strlen(password), ITERATIONS, context->aes_key.key, NULL)) {
        return CIPHER_ERROR;
    }
    EVP_CIPHER_CTX_free(ctx);

    // Set the encryption key and initialization vector in the context
    AES_set_encrypt_key(&context->aes_key, KEY_LEN * 8);
    memcpy(context->iv, salt, KEY_LEN);

    return 0;
}

// Function to clean up resources used by the cipher when it is no longer needed
void cleanup_cipher(init_context_t* context) {
    // Check if the parameters are valid
    if (context == NULL) {
        return;
    }

    // Clean up the encryption key and initialization vector in the context
    AES_KEY_free(&context->aes_key);
    memset(context->iv, 0, IV_SIZE);
}

// Function to encrypt data using the initialized cipher
int encrypt(const unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext, init_context_t* context) {
    // Check if the parameters are valid
    if (plaintext == NULL || plaintext_len == 0 || ciphertext == NULL || context == NULL) {
        return INVALID_PARAMETERS;
    }

    // Initialize the encryption context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return MEMORY_ALLOCATION_FAILED;
    }
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, context->aes_key.key, context->iv)) {
        return CIPHER_ERROR;
    }

    // Encrypt the data in blocks
    size_t ciphertext_len = 0;
    while (plaintext_len > 0) {
        // Calculate the number of bytes to encrypt in this block
        size_t block_size = plaintext_len < MAX_BUFFER_SIZE ? plaintext_len : MAX_BUFFER_SIZE;

        // Encrypt the data block
        if (!EVP_EncryptUpdate(ctx, ciphertext + ciphertext_len, &block_size, plaintext, block_size)) {
            return CIPHER_ERROR;
        }
        ciphertext_len += block_size;

        // Update the plaintext pointer and length
        plaintext += block_size;
        plaintext_len -= block_size;
    }

    // Finalize the encryption
    if (!EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &block_size)) {
        return CIPHER_ERROR;
    }
    ciphertext_len += block_size;

    // Clean up the encryption context
    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

// Function to decrypt data using the initialized cipher
int decrypt(const unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext, init_context_t* context) {
    // Check if the parameters are valid
    if (ciphertext == NULL || ciphertext_len == 0 || plaintext == NULL || context == NULL) {
        return INVALID_PARAMETERS;
    }

    // Initialize the decryption context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return MEMORY_ALLOCATION_FAILED;
    }
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, context->aes_key.key, context->iv)) {
        return CIPHER_ERROR;
    }

    // Decrypt the data in blocks
    size_t plaintext_len = 0;
    while (ciphertext_len > 0) {
        // Calculate the number of bytes to decrypt in this block
        size_t block_size = ciphertext_len < MAX_BUFFER_SIZE ? ciphertext_len : MAX_BUFFER_SIZE;

        // Decrypt the data block
        if (!EVP_DecryptUpdate(ctx, plaintext + plaintext_len, &block_size, ciphertext, block_size)) {
            return CIPHER_ERROR;
        }
        plaintext_len += block_size;

        // Update the ciphertext pointer and length
        ciphertext += block_size;
        ciphertext_len -= block_size;
    }

    // Finalize the decryption
    if (!EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &block_size)) {
        return CIPHER_ERROR;
    }
    plaintext_len += block_size;

    // Clean up the decryption context
    EVP_CIPHER_CTX_free(ctx);

    return plaintext_len;
}
```
This code implements a function to initialize an AES-256-CBC cipher with a given password, generating an initialization vector (IV) securely using OpenSSL's random number generator. The IV is generated using the `RAND_bytes` function from OpenSSL.

The function also derives the encryption key securely from the password using a salted key derivation function (KDF), rather than SHA-1. The KDF used is `EVP_BytesToKey`, which takes the password, salt, and number of iterations as input and generates the encryption key.

The function also includes error handling for potential issues during the cipher setup and cleanup processes.

