#include <sys/stat.h>
#include <fcntl.h>
#include <zlib.h>

int compress_png(const char* file_name, const char* dest_dir, int compression_level) {
    // Check if the input file exists and is a PNG file
    struct stat st;
    if (stat(file_name, &st) == -1 || S_ISREG(st.st_mode) == 0) {
        return 1;
    }

    // Create the destination directory if it does not exist
    char dest_dir_path[PATH_MAX];
    snprintf(dest_dir_path, PATH_MAX, "%s", dest_dir);
    if (access(dest_dir_path, F_OK) == -1) {
        mkdir(dest_dir_path, 0755);
    }

    // Open the input file and compress it using zlib
    FILE* infile = fopen(file_name, "rb");
    if (infile == NULL) {
        return 1;
    }
    gzFile outfile = gzdopen(fileno(infile), "wb");
    if (outfile == NULL) {
        fclose(infile);
        return 1;
    }
    int ret = gzwrite(outfile, file_name, strlen(file_name));
    if (ret < 0) {
        fclose(infile);
        gzclose(outfile);
        return 1;
    }

    // Save the compressed file in the destination directory with a .zip extension
    char dest_path[PATH_MAX];
    snprintf(dest_path, PATH_MAX, "%s/%s.zip", dest_dir, file_name);
    FILE* outfile = fopen(dest_path, "wb");
    if (outfile == NULL) {
        fclose(infile);
        gzclose(outfile);
        return 1;
    }
    ret = fwrite(gzbuffer(outfile), 1, gztell(outfile), outfile);
    if (ret < 0) {
        fclose(infile);
        gzclose(outfile);
        return 1;
    }

    // Close the files and return success
    fclose(infile);
    gzclose(outfile);
    return 0;
}
