    private static readonly object _lock = new object();

    public static void AddNewWebsite(string directory, string websiteName)
    {
        // Verify if a web.config file exists within the directory
        if (!File.Exists(Path.Combine(directory, "web.config")))
        {
            Console.WriteLine($"Warning: No web.config file found in {directory}");
            return;
        }

