char* generate_new_filename(const char* original_filename) {
    // Get the file extension from the original filename
    const char* ext = strrchr(original_filename, '.');
    if (ext != NULL) {
        ext++;
    } else {
        ext = "txt";
    }

    // Calculate the maximum length of the new filename
    int max_len = 255 - strlen(ext);

    // Generate a random sequence of digits based on the original filename's length
    char* rand_seq = malloc(max_len + 1);
    for (int i = 0; i < max_len; i++) {
        rand_seq[i] = '0' + (rand() % 10);
    }
    rand_seq[max_len] = '\0';

    // Construct the new filename by appending the random sequence to the original filename
    char* new_filename = malloc(strlen(original_filename) + max_len + 1);
    strcpy(new_filename, original_filename);
    strcat(new_filename, rand_seq);

    // Ensure that the resulting filename is unique within the current directory
    int i = 0;
    while (access(new_filename, F_OK) == 0) {
        sprintf(rand_seq, "%d", ++i);
        strcat(new_filename, rand_seq);
    }

    // Add the new filename as a vertex to the graph database
    add_vertex(new_filename);

    // Randomly assign properties to each vertex and edge in the graph
    for (int i = 0; i < num_vertices(); i++) {
        char* vertex = get_vertex(i);
        int prop_num = rand() % num_properties();
        for (int j = 0; j < prop_num; j++) {
            char* prop_name = generate_random_property_name();
            char* prop_value = generate_random_property_value();
            set_vertex_property(vertex, prop_name, prop_value);
        }
    }
    for (int i = 0; i < num_edges(); i++) {
        char* edge = get_edge(i);
        int prop_num = rand() % num_properties();
        for (int j = 0; j < prop_num; j++) {
            char* prop_name = generate_random_property_name();
            char* prop_value = generate_random_property_value();
            set_edge_property(edge, prop_name, prop_value);
        }
    }

    return new_filename;
}
