// Define the structure to hold a record with an integer key and long offset
typedef struct {
    int key;
    long offset;
} Record;

// Define the structure to hold a set of records
typedef struct {
    int id; // unique identifier for each set
    size_t num_records; // number of records in the set
    Record *records; // pointer to an array of records
} Set;

// Define the shared memory pool
static void *shared_memory = NULL;
static size_t shared_size = 0;

// Define the lock for synchronizing access to the shared memory pool
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize a set of records with random integer values within a specified range
void init_set(Set *set, int min_key, int max_key) {
    // Allocate memory for the set
    size_t num_records = 100; // arbitrary number of records in the set
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    assert(records != NULL);

    // Initialize each record with a random integer value within the specified range
    for (size_t i = 0; i < num_records; i++) {
        records[i].key = min_key + rand() % (max_key - min_key + 1);
        records[i].offset = 0; // arbitrary offset value
    }

    // Set the number of records and pointer to the array of records in the set
    set->num_records = num_records;
    set->records = records;
}

// Add a new set to the shared memory pool
void add_set(int id, int min_key, int max_key) {
    // Acquire the lock for synchronizing access to the shared memory pool
    pthread_mutex_lock(&mutex);

    // Check if there is enough space in the shared memory pool to allocate a new set
    size_t required_size = sizeof(Set) + (num_records * sizeof(Record));
    if (shared_size + required_size > MAX_SHARED_SIZE) {
        printf("Memory usage breach detected! Not enough space in the shared memory pool to allocate a new set.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Allocate memory for the new set
    Set *new_set = (Set *)malloc(required_size);
    assert(new_set != NULL);

    // Initialize the new set with random integer values within the specified range
    init_set(new_set, min_key, max_key);

    // Add the new set to the shared memory pool
    new_set->id = id;
    shared_size += required_size;
    shared_memory = realloc(shared_memory, shared_size);
    assert(shared_memory != NULL);
    memcpy((char *)shared_memory + (shared_size - required_size), new_set, required_size);

    // Release the lock for synchronizing access to the shared memory pool
    pthread_mutex_unlock(&mutex);
}

// Remove a set from the shared memory pool
void remove_set(int id) {
    // Acquire the lock for synchronizing access to the shared memory pool
    pthread_mutex_lock(&mutex);

    // Find the set with the specified ID in the shared memory pool
    Set *set = (Set *)((char *)shared_memory + sizeof(Set));
    while (set < (Set *)((char *)shared_memory + shared_size)) {
        if (set->id == id) {
            // Remove the set from the shared memory pool
            size_t required_size = sizeof(Set) + (set->num_records * sizeof(Record));
            shared_size -= required_size;
            shared_memory = realloc(shared_memory, shared_size);
            assert(shared_memory != NULL);
            break;
        }
        set = (Set *)((char *)set + sizeof(Set) + (set->num_records * sizeof(Record)));
    }

    // Release the lock for synchronizing access to the shared memory pool
    pthread_mutex_unlock(&mutex);
}

// Access a set in the shared memory pool
void access_set(int id) {
    // Acquire the lock for synchronizing access to the shared memory pool
    pthread_mutex_lock(&mutex);

    // Find the set with the specified ID in the shared memory pool
    Set *set = (Set *)((char *)shared_memory + sizeof(Set));
    while (set < (Set *)((char *)shared_memory + shared_size)) {
        if (set->id == id) {
            // Access the set
            break;
        }
        set = (Set *)((char *)set + sizeof(Set) + (set->num_records * sizeof(Record)));
    }

    // Release the lock for synchronizing access to the shared memory pool
    pthread_mutex_unlock(&mutex);
}

// Update a record in a set in the shared memory pool
void update_record(int id, int key) {
    // Acquire the lock for synchronizing access to the shared memory pool
    pthread_mutex_lock(&mutex);

    // Find the set with the specified ID in the shared memory pool
    Set *set = (Set *)((char *)shared_memory + sizeof(Set));
    while (set < (Set *)((char *)shared_memory + shared_size)) {
        if (set->id == id) {
            // Find the record with the specified key in the set
            Record *record = (Record *)((char *)set + sizeof(Set));
            while (record < (Record *)((char *)set + sizeof(Set) + (set->num_records * sizeof(Record)))) {
                if (record->key == key) {
                    // Update the record
                    break;
                }
                record = (Record *)((char *)record + sizeof(Record));
            }
        }
        set = (Set *)((char *)set + sizeof(Set) + (set->num_records * sizeof(Record)));
    }

    // Release the lock for synchronizing access to the shared memory pool
    pthread_mutex_unlock(&mutex);
}
