import os

class MD5Hasher:
    def __init__(self):
        self.cache = {}

    def get_hash(self, filepath):
        if filepath in self.cache:
            return self.cache[filepath]

        with open(filepath, 'rb') as f:
            hash = hashlib.md5()
            while True:
                chunk = f.read(1024)
                if not chunk:
                    break
                hash.update(chunk)
            self.cache[filepath] = hash.hexdigest()
        return self.cache[filepath]

