// Define constants for the transaction processing system
#define MAX_TRANSACTIONS 10000
#define AGE_THRESHOLD 5000 // 5 seconds in milliseconds
#define NUMBER_LIMIT 100
#define WEIGHTED_SUM_THRESHOLD 90.0
#define MOVING_AVERAGE_WINDOW 100
#define MEMORY_POOL_SIZE 5000000 // 5 MB
#define LOGGING_BUFFER_SIZE 1024 * 1024 // 1 MB

// Define data structures for transactions and the moving average
typedef struct {
    int id;
    long long timestamp;
    double weightedSum;
} Transaction;

typedef struct {
    int count;
    double sum;
} MovingAverage;

// Define a custom memory pool allocator for efficient memory management
void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Error: Out of memory\n");
        exit(1);
    }
    return ptr;
}

// Define a thread-safe logging system for recording transaction information
void logTransaction(int id, long long timestamp, double weightedSum, int filteredOut, char* reason) {
    // Use a circular buffer to store the last hour of logs
    static char* buffer = malloc(LOGGING_BUFFER_SIZE);
    static int head = 0;
    static int tail = 0;
    static int count = 0;

    // Write the log entry to the buffer
    snprintf(buffer + head, LOGGING_BUFFER_SIZE - head, "%d,%lld,%f,%d,%s\n", id, timestamp, weightedSum, filteredOut, reason);
    head = (head + strlen(buffer + head)) % LOGGING_BUFFER_SIZE;
    count++;

    // If the buffer is full, overwrite the oldest entry
    if (count == LOGGING_BUFFER_SIZE) {
        tail = (tail + 1) % LOGGING_BUFFER_SIZE;
        count--;
    }
}

// Define a thread-safe moving average calculator for calculating the weighted sum threshold
void calculateMovingAverage(Transaction* transactions, int numTransactions) {
    // Use a rolling window to calculate the moving average over the last 100 transactions
    static MovingAverage movingAverage = {0, 0};
    static int head = 0;
    static int tail = 0;

    // Update the moving average and calculate the weighted sum threshold
    for (int i = 0; i < numTransactions; i++) {
        movingAverage.sum += transactions[i].weightedSum;
        movingAverage.count++;

        if (movingAverage.count > MOVING_AVERAGE_WINDOW) {
            movingAverage.sum -= transactions[tail].weightedSum;
            movingAverage.count--;
            tail = (tail + 1) % MOVING_AVERAGE_WINDOW;
        }
    }

    // Calculate the weighted sum threshold based on the moving average and adjust for margin of error
    double threshold = movingAverage.sum * WEIGHTED_SUM_THRESHOLD - (movingAverage.sum / 100) * 2;

    // Print the updated moving average and weighted sum threshold to the console
    printf("Moving Average: %f\nWeighted Sum Threshold: %f\n", movingAverage.sum, threshold);
}

// Define a thread-safe transaction processing function for managing incoming transactions
void processTransactions(Transaction* transactions, int numTransactions) {
    // Initialize the memory pool and logging system
    void* memoryPool = allocateMemory(MEMORY_POOL_SIZE);
    logTransaction(-1, -1, -1, 0, "Initialization");

    // Loop through each transaction and filter it based on age, number limit, and weighted sum threshold
    for (int i = 0; i < numTransactions; i++) {
        Transaction* transaction = transactions + i;

        // Check if the transaction is too old and filter it out if necessary
        long long currentTime = getCurrentTime();
        if (currentTime - transaction->timestamp > AGE_THRESHOLD) {
            logTransaction(transaction->id, transaction->timestamp, transaction->weightedSum, 1, "Age");
            continue;
        }

        // Check if the number of transactions in the last 10 milliseconds exceeds the limit and filter it out if necessary
        int numTransactionsInLastMillisecond = getNumTransactionsInLastMillisecond(transaction->timestamp);
        if (numTransactionsInLastMillisecond > NUMBER_LIMIT) {
            logTransaction(transaction->id, transaction->timestamp, transaction->weightedSum, 1, "Number Limit");
            continue;
        }

        // Check if the weighted sum of all transactions in the last 10 milliseconds exceeds the threshold and filter it out if necessary
        double weightedSum = getWeightedSumInLastMillisecond(transaction->timestamp);
        if (weightedSum > WEIGHTED_SUM_THRESHOLD) {
            logTransaction(transaction->id, transaction->timestamp, weightedSum, 1, "Weighted Sum");
            continue;
        }

        // If the transaction passes all filters, add it to the memory pool and update the moving average
        void* ptr = allocateMemory(sizeof(Transaction));
        memcpy(ptr, transaction, sizeof(Transaction));
        logTransaction(transaction->id, transaction->timestamp, weightedSum, 0, "Accepted");
    }
}

