// Define the AES-256-CBC cipher and its initialization context
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[AES_BLOCK_SIZE];
} aes256cbc_ctx;

// Initialize the AES-256-CBC cipher with a given password and generate an IV
int aes256cbc_init(const unsigned char *password, size_t password_len, aes256cbc_ctx **ctx) {
    // Allocate memory for the initialization context
    *ctx = (aes256cbc_ctx *)malloc(sizeof(aes256cbc_ctx));
    if (*ctx == NULL) {
        return -1;
    }

    // Generate a cryptographically secure IV using OpenSSL's secure random number generator
    if (RAND_bytes((*ctx)->iv, AES_BLOCK_SIZE) != 1) {
