#include <openssl/evp.h>
#include <openssl/err.h>

// Define the encryption context structure
typedef struct {
    AES_KEY key; // Encryption key
    unsigned char iv[AES_BLOCK_SIZE]; // Initialization vector
    int initialized; // Flag to indicate if the cipher is initialized
} EncryptionContext;

// Define the configuration structure
typedef struct {
    char* directory; // Directory structure for file naming conventions
    char* filename; // File name with metadata fields
    unsigned char password[AES_MAX_KEY_SIZE]; // Password for key derivation
} Configuration;

// Function to initialize the encryption context
int initEncryptionContext(EncryptionContext* ctx, const Configuration* config) {
    // Check if the cipher is already initialized
    if (ctx->initialized) {
        return 0;
    }

    // Generate a cryptographically secure initialization vector using OpenSSL's secure random number generator
    RAND_bytes(ctx->iv, AES_BLOCK_SIZE);

    // Derive the encryption key securely from the password using a salted key derivation function (KDF) with adjustable parameters for key length and iterations
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), config->password, strlen(config->password), 1000, ctx->key.key, NULL);

    // Initialize the AES-256-CBC cipher with the derived key and initialization vector
    if (!AES_set_encrypt_key(ctx->key.key, 256, &ctx->key)) {
        return -1;
    }
    if (!AES_cbc_encrypt(ctx->iv, ctx->iv, AES_BLOCK_SIZE, &ctx->key, NULL, NULL, 0)) {
        return -2;
    }

    // Set the initialized flag to indicate that the cipher is now initialized
    ctx->initialized = 1;

    return 0;
}

// Function to encrypt and decrypt data using the initialized cipher
int encryptDecryptData(EncryptionContext* ctx, const unsigned char* input, size_t inputLen, unsigned char* output, size_t outputLen) {
    // Check if the cipher is initialized
    if (!ctx->initialized) {
        return -1;
    }

    // Encrypt the data using AES-256-CBC
    int len = AES_cbc_encrypt(input, output, inputLen, &ctx->key, ctx->iv, NULL, 0);
    if (len < 0) {
        return -2;
    }

    // Decrypt the data using AES-256-CBC
    len = AES_cbc_decrypt(output, output, inputLen, &ctx->key, ctx->iv, NULL, 0);
    if (len < 0) {
        return -3;
    }

    return len;
}

// Function to handle errors during resource allocation and deallocation
void handleError(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(1);
}

int main() {
    // Define the configuration structure
    Configuration config = {"/path/to/directory", "filename.txt", "password"};

    // Initialize the encryption context
    EncryptionContext ctx;
    initEncryptionContext(&ctx, &config);

    // Encrypt and decrypt data using the initialized cipher
    unsigned char input[1024];
    size_t inputLen = 1024;
    unsigned char output[1024];
    size_t outputLen = 1024;
    encryptDecryptData(&ctx, input, inputLen, output, outputLen);

    // Handle errors during resource allocation and deallocation
    handleError("Failed to allocate resources");

    return 0;
}
```
This code implements the given programming task by defining a structure for the encryption context, a function to initialize the encryption context, a function to encrypt and decrypt data using the initialized cipher, and a main function that demonstrates how to use these functions. The encryption context structure includes an AES-256-CBC key, an initialization vector, and a flag to indicate if the cipher is initialized. The initEncryptionContext function generates a cryptographically secure initialization vector using OpenSSL's secure random number generator and derives the encryption key securely from the password using a salted key derivation function (KDF) with adjustable parameters for key length and iterations. The encryptDecryptData function encrypts and decrypts data using AES-256-CBC, and handles errors during resource allocation and deallocation using the handleError function. The main function demonstrates how to use these functions by initializing the encryption context, encrypting and decrypting data, and handling errors.']

