// Define an array of DataPackets
DataPacket* packets = NULL;
int numPackets = 0;

// Function to generate a secure, random string of a specified length using a predefined character set
char* generateRandomString(int length) {
    char* str = malloc(length + 1);
    for (int i = 0; i < length; i++) {
        int index = rand() % (sizeof(CHARSET) - 1);
        str[i] = CHARSET[index];
    }
    str[length] = '\0';
    return str;
}

// Function to initialize and manage a dynamic array of DataPackets
void initDataPacketArray() {
    packets = malloc(sizeof(DataPacket) * INITIAL_CAPACITY);
    numPackets = 0;
}

// Function to add a new packet to the array
void addPacket(long timestamp, int sourceID, int destinationID, int payloadLength) {
    // Check if the array needs to be resized
    if (numPackets == INITIAL_CAPACITY) {
        packets = realloc(packets, sizeof(DataPacket) * (INITIAL_CAPACITY + RESIZE_FACTOR));
    }

    // Add the new packet to the array
    packets[numPackets].timestamp = timestamp;
    packets[numPackets].sourceID = sourceID;
    packets[numPackets].destinationID = destinationID;
    packets[numPackets].payloadLength = payloadLength;
    numPackets++;
}

// Function to update an existing packet in the array by sourceID and destinationID
void updatePacket(long timestamp, int sourceID, int destinationID, int payloadLength) {
    // Find the index of the packet to be updated
    int index = findPacketIndex(sourceID, destinationID);

    // Update the packet if it exists
    if (index != -1) {
        packets[index].timestamp = timestamp;
        packets[index].payloadLength = payloadLength;
    }
}

// Function to retrieve a packet from the array by sourceID and destinationID
DataPacket* getPacket(int sourceID, int destinationID) {
    // Find the index of the packet to be retrieved
    int index = findPacketIndex(sourceID, destinationID);

    // Return the packet if it exists
    if (index != -1) {
        return &packets[index];
    } else {
        return NULL;
    }
}

// Function to find the index of a packet in the array by sourceID and destinationID
int findPacketIndex(int sourceID, int destinationID) {
    for (int i = 0; i < numPackets; i++) {
        if (packets[i].sourceID == sourceID && packets[i].destinationID == destinationID) {
            return i;
        }
    }
    return -1;
}

// Function to generate a unique identifier for a new packet
char* generatePacketIdentifier() {
    // Generate a random string of the specified length using the predefined character set
    char* str = generateRandomString(IDENTIFIER_LENGTH);

    // Check if the generated string is already in use as an identifier
    while (isIdentifierInUse(str)) {
        free(str);
        str = generateRandomString(IDENTIFIER_LENGTH);
    }

    return str;
}

// Function to check if a generated identifier is already in use as an identifier
bool isIdentifierInUse(char* identifier) {
    for (int i = 0; i < numPackets; i++) {
        if (strcmp(identifier, packets[i].identifier) == 0) {
            return true;
        }
    }
    return false;
}

// Function to generate an authentication token for a user profile
char* generateAuthenticationToken() {
    // Generate a random string of the specified length using the predefined character set
    char* str = generateRandomString(TOKEN_LENGTH);

    // Check if the generated string is already in use as an authentication token
    while (isTokenInUse(str)) {
        free(str);
        str = generateRandomString(TOKEN_LENGTH);
    }

    return str;
}

// Function to check if a generated authentication token is already in use
bool isTokenInUse(char* token) {
    for (int i = 0; i < numPackets; i++) {
        if (strcmp(token, packets[i].authenticationToken) == 0) {
            return true;
        }
    }
    return false;
}
