// Define a struct to represent a user record
struct User {
    int id;
    char username[51];
    char email[256];
    int age;
};

// Define a linked list node to store valid user records
typedef struct Node {
    struct User *user;
    struct Node *next;
} Node;

// Function to process a CSV file containing user information
void processCSVFile(const char *filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Initialize a linked list to store valid user records
    Node *head = NULL;
    Node *tail = NULL;

    // Read each line of the file and process it
    char line[1024];
    while (fgets(line, sizeof(line), file) != NULL) {
        // Remove any trailing newline characters
        int len = strlen(line);
        if (line[len-1] == '\n') {
            line[len-1] = '\0';
        }

        // Split the line into fields using commas as delimiters
        char *fields[4];
        int numFields = 0;
        for (int i = 0; i < len; i++) {
            if (line[i] == ',') {
                fields[numFields++] = &line[i+1];
            }
        }

        // Validate the user ID, username, email, and age
        int id = atoi(fields[0]);
        char *username = fields[1];
        char *email = fields[2];
        int age = atoi(fields[3]);
        if (id > 0 && strlen(username) <= 50 && isValidEmail(email) && age >= 0 && age < 150) {
            // Create a new user record and add it to the linked list
            struct User *user = malloc(sizeof(struct User));
            user->id = id;
            strcpy(user->username, username);
            strcpy(user->email, email);
            user->age = age;
            if (head == NULL) {
                head = tail = malloc(sizeof(Node));
            } else {
                tail->next = malloc(sizeof(Node));
                tail = tail->next;
            }
            tail->user = user;
        }
    }

    // Calculate and print the average age of all users
    int totalAge = 0;
    int numUsers = 0;
    for (Node *node = head; node != NULL; node = node->next) {
        totalAge += node->user->age;
        numUsers++;
    }
    if (numUsers > 0) {
        printf("Average age: %d\n", totalAge / numUsers);
    } else {
        printf("No valid user records provided\n");
    }

    // Clean up the linked list and close the file
    while (head != NULL) {
        Node *node = head;
        head = head->next;
        free(node);
    }
    fclose(file);
}

