void* manage_thread_pool(int* states, int num_states, FSA* fsa, int last_state) {
    // Initialize thread pool
    pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * num_threads);
    if (!threads) {
        return NULL;
    }

    // Create state list by finding states in FSA
    int* state_list = (int*)malloc(sizeof(int) * num_states);
    if (!state_list) {
        free(threads);
        return NULL;
    }

    // Update 'next' pointer of last state to point to new state list
    state_list[num_states - 1]->next = state_list;

    // Execute tasks concurrently
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, task, &state_list[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up thread pool and state list
    free(threads);
    free(state_list);

    return state_list;
}
