// Load a state object from a file using an ObjectInputStream
public static MoSTState loadStateFromFile(String filename) {
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filename))) {
        // Read the state object from the file
        MoSTState state = (MoSTState)ois.readObject();
        return state;
    } catch (IOException | ClassNotFoundException e) {
        System.out.println("Error: Failed to load state from file");
        e.printStackTrace();
        return null;
    } finally {
        // Close the ObjectInputStream regardless of whether an exception was thrown
        try {
            ois.close();
        } catch (IOException e) {
            System.out.println("Error: Failed to close ObjectInputStream");
            e.printStackTrace();
        }
    }
}
