char* generate_unique_filename(const char* directory, const char* base_filename) {
    // Get the length of the original filename
    int base_filename_len = strlen(base_filename);

    // Determine the file type extension based on the original filename's extension
    const char* extension = strrchr(base_filename, '.');
    if (extension) {
        extension++;
    } else {
        extension = ".dat";
    }

    // Generate a random number to append to the filename
    int random_number = rand() % 10000;

    // Construct the new filename by appending the random number and the file type extension
    char* new_filename = (char*)malloc(256);
    sprintf(new_filename, "%s%d%s", directory, random_number, extension);

    // Check for uniqueness by appending a random number to the filename until no conflict is found
    while (access(new_filename, F_OK) == 0) {
        random_number = rand() % 10000;
        sprintf(new_filename, "%s%d%s", directory, random_number, extension);
    }

    // Return the unique filename
    return new_filename;
}
