using namespace std;

string generateUniqueFileName(const forward_list<string>& list, const string& directoryPath, const string& baseFilename, const string& arg1, const string& arg2) {
    // Insert the second argument after the first occurrence of the first argument in the list
    auto it = find(list.begin(), list.end(), arg1);
    if (it != list.end()) {
        list.insert_after(it, arg2);
    } else {
        list.push_back(arg2);
    }

    // Generate a unique file name within the specified directory
    string newFilename = baseFilename;
    int randomNumber = rand() % 1000000000 + 1;
    sprintf(newFilename, "%s_%d", newFilename.c_str(), randomNumber);

    // Ensure that the total length of the new file name does not exceed 255 characters
    if (newFilename.length() > 255) {
        newFilename = newFilename.substr(0, 255);
    }

    // Determine the appropriate file type extension based on the original filename's extension
    string extension;
    size_t dotIndex = baseFilename.find_last_of('.');
    if (dotIndex != string::npos) {
        extension = baseFilename.substr(dotIndex);
    } else {
        extension = ".dat";
    }

    // Append the sequence of random alphanumeric characters to the new filename
    string randomSequence;
    for (int i = 0; i < 32 - newFilename.length(); i++) {
        int randomChar = rand() % 62 + 48;
        if (randomChar >= 58) {
            randomChar += 7;
        }
        randomSequence += char(randomChar);
    }
    newFilename += randomSequence;

    // Check for uniqueness by appending a random number to the filename until no conflict is found
    string finalFilename = newFilename + extension;
    while (true) {
        ifstream file(directoryPath + "/" + finalFilename);
        if (!file.good()) {
            break;
        }
        sprintf(finalFilename, "%s_%d", newFilename.c_str(), randomNumber++);
    }

    // Handle performance implications of repeated directory checks for uniqueness
    // Explore potential optimizations to improve efficiency

    return finalFilename;
}
