#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>

// Define a struct to represent a user record
struct User {
    int id;
    char username[51];
    char email[256];
    int age;
};

// Define a doubly linked list structure for storing valid user records
typedef struct Node {
    struct User *data;
    struct Node *next;
    struct Node *prev;
} Node;

// Define a hash map to quickly look up user records by ID
typedef struct HashMap {
    int size;
    struct Node **buckets;
} HashMap;

// Function to process a CSV file containing user information
void processCSV(char *filename) {
    // Open the CSV file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Initialize a doubly linked list and hash map for storing valid user records
    Node *head = NULL;
    HashMap *map = createHashMap(1000000);

    // Read each line of the CSV file and process it
    char line[256];
    while (fgets(line, sizeof(line), file) != NULL) {
        // Ignore empty lines or lines that are too long
        if (strlen(line) == 0 || strlen(line) > 256) {
            continue;
        }

        // Split the line into fields using commas as delimiters
        char *fields[4];
        int numFields = splitLine(line, ",", fields);
        if (numFields != 4) {
            printf("Error: invalid number of fields in line %d\n", lineNumber);
            continue;
        }

        // Validate the user ID, username, email, and age
        int id = atoi(fields[0]);
        if (id <= 0) {
            printf("Error: invalid user ID in line %d\n", lineNumber);
            continue;
        }
        char *username = fields[1];
        if (strlen(username) == 0 || strlen(username) > 50) {
            printf("Error: invalid username in line %d\n", lineNumber);
            continue;
        }
        char *email = fields[2];
        if (!validateEmail(email)) {
            printf("Error: invalid email address in line %d\n", lineNumber);
            continue;
        }
        int age = atoi(fields[3]);
        if (age < 0 || age >= 150) {
            printf("Error: invalid age in line %d\n", lineNumber);
            continue;
        }

        // Create a new user record and add it to the doubly linked list and hash map
        struct User *user = malloc(sizeof(struct User));
        user->id = id;
        strcpy(user->username, username);
        strcpy(user->email, email);
        user->age = age;
        addUserToMap(map, user);
        addNodeToList(&head, user);
    }

    // Calculate and print the average age of all users
    int totalAge = 0;
    Node *node = head;
    while (node != NULL) {
        totalAge += node->data->age;
        node = node->next;
    }
    printf("Average age: %d\n", round(totalAge / map->size));

    // Clean up memory and close the file
    freeHashMap(map);
    freeList(&head);
    fclose(file);
}

// Function to create a hash map for storing user records by ID
HashMap *createHashMap(int size) {
    HashMap *map = malloc(sizeof(HashMap));
    map->size = size;
    map->buckets = calloc(size, sizeof(struct Node*));
    return map;
}

// Function to add a user record to the hash map by ID
void addUserToMap(HashMap *map, struct User *user) {
    int bucketIndex = user->id % map->size;
    struct Node **bucket = &map->buckets[bucketIndex];
    while (*bucket != NULL && (*bucket)->data->id < user->id) {
        bucket = &(*bucket)->next;
    }
    if (*bucket == NULL || (*bucket)->data->id > user->id) {
        *bucket = malloc(sizeof(struct Node));
        (*bucket)->data = user;
        (*bucket)->next = NULL;
        (*bucket)->prev = NULL;
    } else {
        // Handle duplicate user IDs by appending a suffix (e.g., "_2", "_3", etc.) to the offending record
        int suffix = 1;
        while (getUserFromMap(map, user->id + suffix) != NULL) {
            suffix++;
        }
        char newUsername[51];
        sprintf(newUsername, "%s_%d", user->username, suffix);
        strcpy((*bucket)->data->username, newUsername);
    }
}

// Function to get a user record from the hash map by ID
struct User *getUserFromMap(HashMap *map, int id) {
    int bucketIndex = id % map->size;
    struct Node **bucket = &map->buckets[bucketIndex];
    while (*bucket != NULL && (*bucket)->data->id < id) {
        bucket = &(*bucket)->next;
    }
    if (*bucket == NULL || (*bucket)->data->id > id) {
        return NULL;
    } else {
        return (*bucket)->data;
    }
}

// Function to add a node to the doubly linked list of user records
void addNodeToList(Node **head, struct User *user) {
    Node *node = malloc(sizeof(Node));
    node->data = user;
    node->next = NULL;
    if (*head == NULL) {
        *head = node;
    } else {
        node->prev = *head;
        (*head)->next = node;
        *head = node;
    }
}

// Function to free the memory used by a doubly linked list of user records
void freeList(Node **head) {
    Node *node = *head;
    while (node != NULL) {
        Node *next = node->next;
        free(node);
        node = next;
    }
}

// Function to free the memory used by a hash map of user records
void freeHashMap(HashMap *map) {
    for (int i = 0; i < map->size; i++) {
        Node **bucket = &map->buckets[i];
        while (*bucket != NULL) {
            Node *next = (*bucket)->next;
            free((*bucket)->data);
            free(*bucket);
            *bucket = next;
        }
    }
    free(map->buckets);
    free(map);
}

// Function to validate an email address using a regular expression
int validateEmail(char *email) {
