#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>

// Function to read integers from standard input and store them in an array
int* read_integers(char* command, int* num_ints) {
    // Initialize the array to hold the integers
    int* arr = malloc(10 * sizeof(int));
    if (arr == NULL) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    // Read the integers from standard input
    for (int i = 0; i < 1000 && scanf("%d", &arr[i]) == 1; i++) {
        if (arr[i] < 0 || arr[i] >= 1000000000) {
            printf("Error: Invalid input\n");
            free(arr);
            return NULL;
        }
    }

    // Check if the array is empty
    if (i == 0) {
        printf("No integers provided\n");
        free(arr);
        return NULL;
    }

    // Store the number of integers read in the output parameter
    *num_ints = i;

    // Return the array
    return arr;
}

// Function to find and print the largest integer in an array
void print_largest(int* arr, int num_ints) {
    if (num_ints == 0) {
        printf("No integers provided\n");
        return;
    }

    // Initialize the largest integer as the first element of the array
    int largest = arr[0];

    // Iterate over the remaining elements and find the largest one
    for (int i = 1; i < num_ints; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    // Print the largest integer
    printf("Largest integer: %d\n", largest);
}

// Function to perform a specific operation based on a given command line option using OpenSSL
void* perform_operation(char* command, int* num_ints) {
    // Check if the command is valid
    if (strcmp(command, "encrypt") == 0 || strcmp(command, "decrypt") == 0) {
        // Read the integers from standard input and store them in an array
        int* arr = read_integers(command, num_ints);
        if (arr == NULL) {
            return NULL;
        }

        // Perform the operation on the array using OpenSSL
        AES_KEY key;
        AES_set_encrypt_key(key, 128, &key);
        for (int i = 0; i < *num_ints; i++) {
            arr[i] = AES_encrypt(arr[i], key);
        }

        // Print the largest integer in the array
        print_largest(arr, *num_ints);

        // Free the memory allocated for the array
        free(arr);
    } else {
        printf("Error: Invalid command\n");
        return NULL;
    }
}
