    // Read the number of integers in the list from the file
    int num_ints;
    int* arr = read_integers(filename, &num_ints);
    if (!arr) {
        fprintf(stderr, "Error: unable to read integers from file %s\n", filename);
        return;
    }

    // Validate the input and print error messages if necessary
    validate_input(arr, num_ints);

    // Find the largest integer in the list
    int largest = find_largest(arr, num_ints);

    // Print the largest integer
    printf("The largest integer in file %s is %d\n", filename, largest);

    // Free the memory allocated for the array
    free(arr);
}

// Function to process multiple files concurrently using multi-threading
void process_files(char** filenames, int num_filenames) {
    pthread_t* threads = (pthread_t*)malloc(num_filenames * sizeof(pthread_t));
    if (!threads) {
        fprintf(stderr, "Error: unable to allocate memory for thread IDs\n");
        return;
    }

    // Create a thread for each file
    int i;
    for (i = 0; i < num_filenames; i++) {
        pthread_create(&threads[i], NULL, process_file, filenames[i]);
    }

    // Wait for all threads to complete
    for (i = 0; i < num_filenames; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
}
