#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>

// Define a structure to store information about each file being processed
typedef struct {
    char *filename; // Name of the file being processed
    int num_integers; // Number of integers in the file
    int max_integer; // Largest integer in the file
} FileInfo;

// Define a structure to store information about each thread
typedef struct {
    pthread_t thread; // Thread ID
    semaphore_t semaphore; // Semaphore for synchronizing access to shared resources
    int num_files; // Number of files being processed by the thread
    FileInfo *file_info; // Array of file information structures
} ThreadInfo;

// Define a function to read and validate integers from standard input
int read_integers(char **str, int *num_integers) {
    char *token = NULL;
    int integer = 0;
    int num_tokens = 0;

    // Read the next token from standard input
    while ((token = strtok(NULL, " \n")) != NULL) {
        // Check if the token is a valid integer
        if (sscanf(token, "%d", &integer) == 1 && integer > 0) {
            // Add the integer to the array of integers
            *num_integers = (*num_integers) + 1;
            str[*num_integers - 1] = token;
        } else {
            // Print an error message and return -1 if the token is not a valid integer
            fprintf(stderr, "Error: Invalid input. Please enter only positive integers.\n");
            return -1;
        }
    }

    // Return the number of integers read
    return *num_integers;
}

// Define a function to find and print the largest integer in an array of integers
int find_largest_integer(char **str, int num_integers) {
    int i = 0;
    int max_integer = INT_MIN;

    // Loop through each integer in the array
    for (i = 0; i < num_integers; i++) {
        // Check if the current integer is larger than the largest integer found so far
        if (atoi(str[i]) > max_integer) {
            // Update the largest integer found so far
            max_integer = atoi(str[i]);
        }
    }

    // Print the largest integer found
    printf("The largest integer in the array is %d\n", max_integer);

    // Return the largest integer found
    return max_integer;
}

// Define a function to process a file of integers concurrently using multiple threads
void *process_file(void *arg) {
    ThreadInfo *thread_info = (ThreadInfo *) arg;
    int i = 0;
    char **str = NULL;
    int num_integers = 0;
    int max_integer = INT_MIN;

    // Loop through each file being processed by the thread
    for (i = 0; i < thread_info->num_files; i++) {
        // Read and validate the integers in the file
        num_integers = read_integers(str, &thread_info->file_info[i].num_integers);
        if (num_integers == -1) {
            // Print an error message and return if there was an error reading the integers
            fprintf(stderr, "Error: %s\n", strerror(errno));
            return NULL;
        }

        // Find and print the largest integer in the array of integers
        max_integer = find_largest_integer(str, num_integers);
    }

    // Return the largest integer found
    return (void *) &max_integer;
}

// Define a function to process multiple files concurrently using multiple threads
void process_files(char **filenames, int num_files) {
    ThreadInfo *thread_info = NULL;
    pthread_t thread = 0;
    int i = 0;
    int status = 0;

    // Allocate memory for the array of file information structures
    thread_info = (ThreadInfo *) malloc(sizeof(ThreadInfo) * num_files);
    if (thread_info == NULL) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        return;
    }

    // Initialize the array of file information structures
    for (i = 0; i < num_files; i++) {
        thread_info[i].filename = filenames[i];
        thread_info[i].num_integers = 0;
        thread_info[i].max_integer = INT_MIN;
    }

    // Create a semaphore for synchronizing access to shared resources
    semaphore_t semaphore = semaphore_create(1);
    if (semaphore == NULL) {
        fprintf(stderr, "Error: %s\n", strerror(errno));
        return;
    }

    // Loop through each file being processed by the thread
    for (i = 0; i < num_files; i++) {
        // Create a new thread to process the current file
        status = pthread_create(&thread, NULL, process_file, &thread_info[i]);
        if (status != 0) {
            fprintf(stderr, "Error: %s\n", strerror(errno));
            return;
        }

        // Wait for the thread to finish processing the current file
        status = pthread_join(thread, NULL);
        if (status != 0) {
            fprintf(stderr, "Error: %s\n", strerror(errno));
            return;
        }
    }

    // Free the memory allocated for the array of file information structures
    free(thread_info);
}

// Define a function to print processing statistics
void print_statistics() {
    printf("Processing Statistics:\n");
    printf("\tNumber of files processed: %d\n", num_files);
    printf("\tTotal number of integers read: %d\n", total_num_integers);
    printf("\tAverage processing time per file: %.2f seconds\n", average_processing_time);
}

// Define a function to handle errors during parsing or processing
void handle_error(char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main(int argc, char **argv) {
    // Check if the user has specified any input files
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [input_files]\n", argv[0]);
        return 1;
    }

    // Initialize variables for processing statistics
    int num_files = 0;
    int total_num_integers = 0;
    double average_processing_time = 0.0;

    // Loop through each input file specified by the user
    for (int i = 1; i < argc; i++) {
        // Open the current input file and read its contents
        FILE *file = fopen(argv[i], "r");
        if (file == NULL) {
            handle_error("Error opening input file");
            return 1;
        }

        // Read the next line from the file
        char *line = NULL;
        size_t len = 0;
        ssize_t read = getline(&line, &len, file);
        if (read == -1) {
            handle_error("Error reading input file");
            return 1;
        }

        // Close the current input file
