    TaskWorkerManager(int maxTasksPerWorker, int workerId) : maxTasks_(maxTasksPerWorker), workerId_(workerId) {}

    // Initialize workers with configuration parameters specifying the maximum number of tasks they can process before being reconfigured.
    void initWorkers() {
        for (int i = 0; i < numWorkers_; ++i) {
            workers_.push_back(new TaskWorker(maxTasks_, workerId_));
        }
    }

    // Associate workers with unique identifiers and operate concurrently, possibly across different processes within a distributed system.
    void associateWorkers() {
        for (int i = 0; i < numWorkers_; ++i) {
            workers_[i]->setWorkerId(workerId_);
        }
    }

    // Process tasks concurrently, possibly across multiple processes and nodes.
    void processTasks() {
        for (int i = 0; i < numWorkers_; ++i) {
            workers_[i]->processTask();
        }
    }

    // Detect and handle resource exhaustion by logging warnings if any worker exceeds its configured limits for consecutive task processing.
    void detectResourceExhaustion() {
        for (int i = 0; i < numWorkers_; ++i) {
            if (workers_[i]->getNumTasksProcessed() > maxTasks_) {
                std::cout << "Worker " << workers_[i]->getWorkerId() << " exceeded its configured limit of " << maxTasks_ << " tasks." << std::endl;
            }
        }
    }

private:
