// Function to parse a JSON file and extract integers
int parse_json(const char *filename) {
    // Open the JSON file
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return -1;
    }

