        json_node_t *node = json_parser_get_root(parser);

        // Check if the current node is an integer
        if (json_node_is_integer(node)) {
            // Extract the integer value
            int value = json_node_get_int(node);

            // Check if the integer is positive
            if (value <= 0) {
