#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Function to generate a unique file name within a specified directory
char* generate_unique_filename(const char* dir, const char* base_filename) {
    // Get the length of the directory path and the base filename
    size_t dir_len = strlen(dir);
    size_t base_filename_len = strlen(base_filename);

    // Determine the appropriate file type extension based on the original filename's extension, falling back to ".dat" if no extension is present
    const char* ext = get_file_extension(base_filename);
    size_t ext_len = strlen(ext);

    // Generate a sequence of random alphanumeric characters for the unique identifier
    char* id = generate_random_id(32 - base_filename_len - ext_len);

    // Build the new file name by appending the unique identifier to the base filename and the appropriate file type extension
    size_t new_filename_len = dir_len + base_filename_len + strlen(id) + ext_len;
    char* new_filename = malloc(new_filename_len);
    snprintf(new_filename, new_filename_len, "%s%s%s", dir, base_filename, id, ext);

    // Check for conflicts by appending a unique identifier to the filename and checking for its existence in the directory
    char* conflict_id = generate_random_id(32 - base_filename_len - ext_len);
    while (file_exists(new_filename)) {
        snprintf(new_filename, new_filename_len, "%s%s%s", dir, base_filename, conflict_id, ext);
    }

    // Free the memory allocated for the unique identifier and return the new file name
    free(conflict_id);
    return new_filename;
}

// Function to get the appropriate file type extension based on the original filename's extension, falling back to ".dat" if no extension is present
const char* get_file_extension(const char* filename) {
    const char* ext = strrchr(filename, '.');
    return (ext != NULL) ? ext : ".dat";
}

// Function to generate a sequence of random alphanumeric characters for the unique identifier
char* generate_random_id(size_t len) {
    // Generate a random number between 0 and 2^32-1 (4 bytes)
    uint32_t rand_num = arc4random();

    // Convert the random number to a string of alphanumeric characters
    char* id = malloc(len + 1);
    for (size_t i = 0; i < len; i++) {
        id[i] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"[rand_num % 62];
        rand_num /= 62;
    }
    id[len] = '\0';

    return id;
}

// Function to check if a file exists in the directory
int file_exists(const char* filename) {
    struct stat st;
    return (stat(filename, &st) == 0);
