// Define the error codes for the encryption process
#define ENCRYPTION_SUCCESS 0
#define INVALID_DIRECTORY_PATH -1
#define INVALID_CONFIGURATION_FILE -2
#define CIPHER_INITIALIZATION_FAILURE -3
#define NONCE_GENERATION_FAILURE -4
#define KEY_DERIVATION_FAILURE -5
#define FILE_READ_ERROR -6
#define FILE_WRITE_ERROR -7
#define MEMORY_ALLOCATION_FAILURE -8
#define THREAD_SAFETY_VIOLATION -9
#define EXPORT_KEY_MATERIAL_FAILURE -10

// Define the configuration parameters for the encryption process
#define AES_CIPHER "aes-256-gcm"
#define KEY_LENGTH 32
#define ITERATIONS 10000
#define NONCE_SIZE 12
#define BLOCK_SIZE 16

// Define the logging levels for the encryption process
#define LOGGING_LEVEL_DEBUG 0
#define LOGGING_LEVEL_INFO 1
#define LOGGING_LEVEL_WARNING 2
#define LOGGING_LEVEL_ERROR 3

// Define the logging function for the encryption process
void log(int level, char* message) {
    if (level <= LOGGING_LEVEL_DEBUG) {
        printf("[DEBUG] %s\n", message);
    } else if (level <= LOGGING_LEVEL_INFO) {
        printf("[INFO] %s\n", message);
    } else if (level <= LOGGING_LEVEL_WARNING) {
        printf("[WARNING] %s\n", message);
    } else {
        printf("[ERROR] %s\n", message);
    }
}

// Define the encryption function for the specified directory and configuration file
int encrypt(char* directory_path, char* config_file) {
    // Check if the directory path is valid
    if (directory_path == NULL || strlen(directory_path) == 0) {
        log(LOGGING_LEVEL_ERROR, "Invalid directory path");
        return INVALID_DIRECTORY_PATH;
    }

    // Check if the configuration file is valid
    if (config_file == NULL || strlen(config_file) == 0) {
        log(LOGGING_LEVEL_ERROR, "Invalid configuration file");
        return INVALID_CONFIGURATION_FILE;
    }

    // Initialize the AES-256-GCM cipher with a password provided by the user
    EVP_CIPHER_CTX* ctx = NULL;
    int ret = 0;
    if ((ret = EVP_EncryptInit_ex(ctx, EVP_get_cipherbyname(AES_CIPHER), NULL, NULL, NULL)) != 1) {
        log(LOGGING_LEVEL_ERROR, "Failed to initialize the cipher");
        return CIPHER_INITIALIZATION_FAILURE;
    }

    // Generate a cryptographically secure nonce using OpenSSL's secure random number generator
    unsigned char nonce[NONCE_SIZE];
    if (RAND_bytes(nonce, NONCE_SIZE) != 1) {
        log(LOGGING_LEVEL_ERROR, "Failed to generate the nonce");
        return NONCE_GENERATION_FAILURE;
    }

    // Derive the encryption key securely from the password using a salted key derivation function (KDF) with adjustable parameters for key length and iterations
    unsigned char key[KEY_LENGTH];
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), nonce, NONCE_SIZE, ITERATIONS, EVP_sha256(), KEY_LENGTH, key) != 1) {
        log(LOGGING_LEVEL_ERROR, "Failed to derive the encryption key");
        return KEY_DERIVATION_FAILURE;
    }

    // Initialize the cipher with the derived key and nonce
    if ((ret = EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce)) != 1) {
        log(LOGGING_LEVEL_ERROR, "Failed to initialize the cipher");
        return CIPHER_INITIALIZATION_FAILURE;
    }

    // Encrypt and decrypt files in the specified directory according to the configuration
    DIR* dir = opendir(directory_path);
    struct dirent* entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        char* filename = entry->d_name;
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
            continue;
        }

        // Encrypt the file
        FILE* infile = fopen(filename, "rb");
        if (infile == NULL) {
            log(LOGGING_LEVEL_ERROR, "Failed to open the input file");
            return FILE_READ_ERROR;
        }

        // Create a new output file with the same name as the input file but with an added ".enc" extension
        char* outfilename = (char*)malloc(strlen(filename) + 4);
        strcpy(outfilename, filename);
        strcat(outfilename, ".enc");
        FILE* outfile = fopen(outfilename, "wb");
        if (outfile == NULL) {
            log(LOGGING_LEVEL_ERROR, "Failed to create the output file");
            return FILE_WRITE_ERROR;
        }

        // Encrypt the input file and write it to the output file
        unsigned char buffer[BLOCK_SIZE];
        int read = 0;
        while ((read = fread(buffer, 1, BLOCK_SIZE, infile)) > 0) {
            if (EVP_EncryptUpdate(ctx, buffer, &read, buffer, read) != 1) {
                log(LOGGING_LEVEL_ERROR, "Failed to encrypt the input file");
                return FILE_WRITE_ERROR;
            }
            fwrite(buffer, 1, read, outfile);
        }

        // Clean up resources
        fclose(infile);
        fclose(outfile);
        free(outfilename);
    }

    // Clean up resources
    EVP_CIPHER_CTX_free(ctx);
    closedir(dir);

    return ENCRYPTION_SUCCESS;
}
```
