        if (!graph.containsVertex(vertexId)) {
            graph.addVertex(vertexId, vertex);
        }
    }

    // Iterate over the list of edges and add them to the graph
    for (Edge edge : edges) {
        // Generate unique identifiers for the source and target vertices based on the global counter
        String sourceVertexId = "v" + vertexIdCounter++;
        String targetVertexId = "v" + vertexIdCounter++;

        // Set properties on the edge, ensuring that property values do not exceed the specified size limit
        edge.setProperty("weight", edge.getWeight());
        edge.setProperty("type", edge.getType());

        // Add the edge to the graph, ensuring that it is added only once within the same transaction
        if (!graph.containsEdge(sourceVertexId, targetVertexId)) {
            graph.addEdge(sourceVertexId, targetVertexId, edge);
