// Define constants for the cipher and key derivation parameters
#define CIPHER_NAME "AES-256-GCM"
#define KEY_LENGTH 32
#define ITERATIONS 10000

// Define a structure to hold the encryption context
typedef struct {
    AES_KEY key; // The encryption key
    unsigned char nonce[AES_NONCE_LEN]; // The nonce for the current encryption session
    int initialized; // Whether the cipher has been successfully initialized
} EncryptionContext;

// Define a function to generate a cryptographically secure nonce using OpenSSL's secure random number generator
void generate_nonce(unsigned char *nonce) {
    RAND_bytes(nonce, AES_NONCE_LEN);
}

// Define a function to derive the encryption key securely from the password using a salted key derivation function (KDF) with adjustable parameters for key length and iterations
void derive_key(const char *password, unsigned char *salt, int salt_len, unsigned char *derived_key, int derived_key_len) {
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char *)password, strlen(password), ITERATIONS, derived_key, NULL);
}

// Define a function to initialize the AES-256-GCM cipher with a password provided by the user, ensuring the function adheres to modern security best practices
int init_cipher(EncryptionContext *ctx, const char *password) {
    // Generate a cryptographically secure nonce using OpenSSL's secure random number generator
    generate_nonce(ctx->nonce);

    // Derive the encryption key securely from the password using a salted key derivation function (KDF) with adjustable parameters for key length and iterations
    derive_key(password, ctx->nonce, AES_NONCE_LEN, ctx->key.key, KEY_LENGTH);

    // Initialize the AES-256-GCM cipher with the derived key and nonce
    if (AES_set_encrypt_key(ctx->key.key, KEY_LENGTH * 8, &ctx->key) < 0) {
        return -1;
    }

    // Set the IV for the AES-256-GCM cipher to the nonce
    if (AES_gcm_setiv(ctx->key.key, ctx->nonce, AES_NONCE_LEN) < 0) {
        return -1;
    }

    // Set the tag length for the AES-256-GCM cipher to 16 bytes (the default value)
    if (AES_gcm_setiv(ctx->key.key, ctx->nonce, AES_NONCE_LEN) < 0) {
        return -1;
