// Function to parse the TIFF file and extract information about its bits per sample, sample per pixel, and extra samples
int secureParseTIFFAndEncrypt(const char* tiffFilePath, const char* password, const char* encryptionOption) {
    // Open the TIFF file for reading
    FILE* tiffFile = fopen(tiffFilePath, "rb");
    if (tiffFile == NULL) {
        printf("Error: Could not open TIFF file %s\n", tiffFilePath);
        return ERROR_OPENING_FILE;
    }

    // Read the TIFF header and check for errors
    unsigned char header[12];
    if (fread(header, 1, 12, tiffFile) != 12) {
        printf("Error: Could not read TIFF header\n");
        fclose(tiffFile);
        return ERROR_READING_HEADER;
    }

    // Check the TIFF version and endianness
    if (header[0] != 'I' || header[1] != 'I') {
        printf("Error: Unsupported TIFF version\n");
        fclose(tiffFile);
        return ERROR_UNSUPPORTED_VERSION;
    }

    // Check the bits per sample and sample per pixel
    unsigned short bitsPerSample = header[10] | (header[11] << 8);
    unsigned short samplesPerPixel = header[12] | (header[13] << 8);
    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16) {
        printf("Error: Unsupported bits per sample\n");
        fclose(tiffFile);
        return ERROR_UNSUPPORTED_BIT_DEPTH;
    }

    // Check for extra samples and handle them appropriately
    unsigned short extraSamples = header[14] | (header[15] << 8);
    if (extraSamples > 0) {
        printf("Error: Extra samples not supported\n");
        fclose(tiffFile);
        return ERROR_EXTRA_SAMPLES;
    }

    // Initialize the OpenSSL library and create a new context for encryption
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: Could not initialize OpenSSL\n");
        fclose(tiffFile);
        return ERROR_CIPHER_SETUP;
    }

    // Set the encryption option and password for the context
    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, password, NULL);
    if (ret != 1) {
        printf("Error: Could not set encryption options\n");
        fclose(tiffFile);
        return ERROR_CIPHER_SETUP;
    }

    // Generate a cryptographically secure initialization vector and derive the encryption key from the password using a salted key derivation function
    unsigned char iv[AES_BLOCK_SIZE];
    ret = EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, iv);
    if (ret != 1) {
        printf("Error: Could not generate initialization vector\n");
        fclose(tiffFile);
        return ERROR_CIPHER_SETUP;
    }

    // Allocate memory for the encryption key and copy it from the context
    unsigned char* key = malloc(AES_KEY_LENGTH);
    if (key == NULL) {
        printf("Error: Could not allocate memory for encryption key\n");
        fclose(tiffFile);
        return ERROR_MEMORY_ALLOCATION;
    }
    memcpy(key, EVP_CIPHER_CTX_key(ctx), AES_KEY_LENGTH);

    // Allocate memory for the initialization context and copy the encryption key and IV from the context
    initContext* init = malloc(sizeof(initContext));
    if (init == NULL) {
        printf("Error: Could not allocate memory for initialization context\n");
        fclose(tiffFile);
        return ERROR_MEMORY_ALLOCATION;
    }
    memcpy(init->iv, iv, AES_BLOCK_SIZE);
    memcpy(init->aesKey, key, AES_KEY_LENGTH);

    // Free the memory for the encryption key and initialization vector
    free(key);
    OPENSSL_cleanse(iv, AES_BLOCK_SIZE);

    // Read the TIFF data and encrypt it using the OpenSSL library
    unsigned char* buffer = malloc(TIFF_BUFFER_SIZE);
    if (buffer == NULL) {
        printf("Error: Could not allocate memory for TIFF buffer\n");
        fclose(tiffFile);
        return ERROR_MEMORY_ALLOCATION;
    }
    size_t readSize = 0;
    while ((readSize = fread(buffer, 1, TIFF_BUFFER_SIZE, tiffFile)) > 0) {
        // Encrypt the data using the OpenSSL library
        ret = EVP_EncryptUpdate(ctx, buffer, &readSize, buffer, readSize);
        if (ret != 1) {
            printf("Error: Could not encrypt TIFF data\n");
            fclose(tiffFile);
            return ERROR_CIPHER_UPDATE;
        }
    }

    // Finalize the encryption and free the memory for the initialization context
    ret = EVP_EncryptFinal_ex(ctx, buffer, &readSize);
    if (ret != 1) {
        printf("Error: Could not finalize encryption\n");
        fclose(tiffFile);
        return ERROR_CIPHER_FINAL;
    }
    EVP_CIPHER_CTX_free(ctx);
    free(init);

    // Write the encrypted TIFF data to a new file
    FILE* encryptedTiff = fopen("encrypted.tif", "wb");
    if (encryptedTiff == NULL) {
        printf("Error: Could not open encrypted TIFF file\n");
        fclose(tiffFile);
        return ERROR_OPENING_FILE;
    }
    fwrite(buffer, 1, readSize, encryptedTiff);
    fclose(encryptedTiff);

    // Free the memory for the TIFF buffer and close the file
    free(buffer);
    fclose(tiffFile);

    return 0;
}
