#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <assert.h>

// Define a struct to represent a user record
struct User {
    int id;
    char username[51];
    char email[256];
    int age;
};

// Define a hash map data structure for storing valid user records
typedef struct HashMap {
    struct User *users;
    size_t capacity;
    size_t size;
} HashMap;

// Initialize an empty hash map with the given capacity
void initHashMap(HashMap *map, size_t capacity) {
    map->users = (struct User *)malloc(capacity * sizeof(struct User));
    assert(map->users != NULL);
    map->capacity = capacity;
    map->size = 0;
}

// Insert a user record into the hash map
void insertUser(HashMap *map, struct User user) {
    if (map->size == map->capacity) {
        // Resize the hash map if it's full
        size_t newCapacity = map->capacity * 2;
        struct User *newUsers = (struct User *)realloc(map->users, newCapacity * sizeof(struct User));
        assert(newUsers != NULL);
        map->users = newUsers;
        map->capacity = newCapacity;
    }
    map->users[map->size++] = user;
}

// Look up a user record in the hash map by ID
struct User *lookupUser(HashMap *map, int id) {
    for (int i = 0; i < map->size; i++) {
        if (map->users[i].id == id) {
            return &map->users[i];
        }
    }
    return NULL;
}

// Remove a user record from the hash map by ID
void removeUser(HashMap *map, int id) {
    for (int i = 0; i < map->size; i++) {
        if (map->users[i].id == id) {
            // Shift all subsequent records to fill the gap
            for (int j = i + 1; j < map->size; j++) {
                map->users[j - 1] = map->users[j];
            }
            map->size--;
            return;
        }
    }
}

// Process a CSV file containing user information
void processCSV(const char *filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Initialize an empty hash map with a capacity of 1 billion
    HashMap users;
    initHashMap(&users, 1000000000);

    // Read each line from the file and process it
    char line[256];
    while (fgets(line, sizeof(line), file) != NULL) {
        // Parse the line into a user record
        struct User user;
        sscanf(line, "%d,%s,%s,%d", &user.id, user.username, user.email, &user.age);

        // Validate the user record and handle any errors
        if (user.id <= 0 || strlen(user.username) == 0 || strlen(user.email) == 0 || user.age < 0 || user.age >= 150) {
            printf("Error: invalid user record %s\n", line);
            continue;
        }

        // Check if the user ID is already in use and handle duplicates
        struct User *existingUser = lookupUser(&users, user.id);
        if (existingUser != NULL) {
            int suffix = 2;
            while (lookupUser(&users, user.id + suffix) != NULL) {
                suffix++;
            }
            user.id += suffix;
        }

        // Insert the valid user record into the hash map
        insertUser(&users, user);
    }

    // Calculate and print the average age of all users
    int totalAge = 0;
    for (int i = 0; i < users.size; i++) {
        totalAge += users.users[i].age;
    }
    printf("Average age: %d\n", round(totalAge / (double)users.size));

    // Clean up the hash map and close the file
    free(users.users);
    fclose(file);
}

int main() {
    processCSV("users.csv");
    return 0;
}
```
This code uses a hash map to store valid user records, which allows for fast insertions and deletions and efficient lookup by ID. The `sscanf` function is used to parse each line of the CSV file into a `struct User`, which is then validated for correctness before being inserted into the hash map. If a duplicate user ID is encountered, a suffix is appended to the offending record until uniqueness is achieved. The average age of all users is calculated and printed at the end of processing.

The trade-offs between using a hash map versus a balanced tree for indexing user records are:

* Hash maps have faster insertion and deletion times, but slower lookup times.
* Balanced trees have slower insertion and deletion times, but faster lookup times.

In this code, a hash map is used because it provides fast insertions and deletions and efficient lookup by ID. However, if the number of user records becomes very large, a balanced tree may be more appropriate to ensure efficient lookup times.

The impact of different memory allocation strategies on system performance and resource utilization depends on the specific requirements of the application. In this code, the `malloc` function is used to allocate memory for the hash map, which can lead to fragmentation and increased memory usage over time. To mitigate this, a more efficient memory allocation strategy such as a pool allocator or a garbage collector could be used.

