// Define a struct to represent a user record
struct User {
    int id;
    char username[51];
    char email[256];
    int age;
};

// Define a hash map to store valid user records
typedef struct HashMap {
    struct User *users;
    size_t capacity;
    size_t size;
} HashMap;

// Initialize an empty hash map with the given capacity
HashMap *initHashMap(size_t capacity) {
    HashMap *map = malloc(sizeof(HashMap));
    if (!map) return NULL;
    map->users = calloc(capacity, sizeof(struct User));
    if (!map->users) {
        free(map);
        return NULL;
    }
    map->capacity = capacity;
    map->size = 0;
    return map;
}

// Insert a user record into the hash map
void insertUser(HashMap *map, struct User user) {
    if (map->size == map->capacity) {
        // Resize the hash map if it's full
        size_t newCapacity = map->capacity * 2;
        struct User *newUsers = realloc(map->users, newCapacity * sizeof(struct User));
        if (!newUsers) return;
        map->users = newUsers;
        map->capacity = newCapacity;
    }
    map->users[map->size++] = user;
}

// Look up a user record in the hash map by ID
struct User *lookupUser(HashMap *map, int id) {
    for (int i = 0; i < map->size; i++) {
        if (map->users[i].id == id) return &map->users[i];
    }
    return NULL;
}

// Remove a user record from the hash map by ID
void removeUser(HashMap *map, int id) {
    for (int i = 0; i < map->size; i++) {
        if (map->users[i].id == id) {
            // Shift all subsequent records to fill the gap
            memmove(&map->users[i], &map->users[i + 1], (map->size - i - 1) * sizeof(struct User));
            map->size--;
            return;
        }
    }
}

// Parse a user record from a CSV line and validate its fields
struct User parseUser(char *line, size_t length) {
    struct User user = {0};
    char *token = strtok(line, ",");
    if (!token) return user; // Empty line
    user.id = atoi(token);
    token = strtok(NULL, ",");
    if (!token) return user; // Missing username
    strncpy(user.username, token, 50);
    token = strtok(NULL, ",");
    if (!token) return user; // Missing email
    strncpy(user.email, token, 256);
    token = strtok(NULL, ",");
    if (!token) return user; // Missing age
    user.age = atoi(token);
    if (user.id <= 0 || user.age < 0 || user.age >= 150) return user; // Invalid ID or age
    if (!isValidEmail(user.email)) return user; // Invalid email
    if (!isValidUsername(user.username)) return user; // Invalid username
    return user;
}

// Validate a user ID is positive integer
int isPositiveInt(char *str) {
    int i = 0;
    while (i < strlen(str) && isdigit(str[i])) i++;
    return i == strlen(str) && str[0] != '0';
}

// Validate a username is non-empty string up to 50 characters
int isValidUsername(char *str) {
    if (strlen(str) > 50) return 0;
    for (int i = 0; i < strlen(str); i++) {
        if (!isalnum(str[i]) && str[i] != '_') return 0;
    }
    return 1;
}

// Validate an email address follows standard format
