// Calculate the average age of all users in the hash map
double calculateAverageAge(HashMap *map) {
    double sum = 0;
    for (int i = 0; i < map->size; i++) {
        sum += map->users[i].age;
    }
    return round(sum / map->size);
}

// Print the average age of all users in the hash map
void printAverageAge(HashMap *map) {
    double average = calculateAverageAge(map);
    printf("Average age: %d\n", (int)average);
}

// Process a potentially large CSV file containing user information
void processCSVFile(char *filename, size_t capacity) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (!file) return;

    // Initialize an empty hash map with the given capacity
    HashMap *map = initHashMap(capacity);
    if (!map) {
        fclose(file);
        return;
    }

    // Read each line of the file and parse a user record from it
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        struct User user = parseUser(line, strlen(line));
        if (!user.id) continue; // Skip invalid records
        // Handle duplicate user IDs by appending a suffix until uniqueness is achieved
        int id = user.id;
        while (lookupUser(map, id)) {
            id++;
            user.id = id;
        }
        insertUser(map, user);
    }

    // Calculate and print the average age of all users in the hash map
    printAverageAge(map);

    // Clean up resources
    fclose(file);
    freeHashMap(map);
}

// Free a hash map and its associated memory
void freeHashMap(HashMap *map) {
    if (!map) return;
    free(map->users);
    free(map);
}
