// Define the weighted sum threshold for filtering transactions (as a percentage of the moving average)
#define WEIGHTED_SUM_THRESHOLD 0.9

// Define the number of milliseconds to maintain a rolling window for calculating the moving average
#define ROLLING_WINDOW_MS 10

// Define the number of transactions to keep in the rolling window for calculating the moving average
#define ROLLING_WINDOW_SIZE 100

// Define the margin of error for the weighted sum threshold (as a percentage)
