#define LOGGING_MAX_FILES 5

// Define the transaction structure
struct Transaction {
    int id;
    long long timestamp;
    double weightedSum;
};

// Define the moving average structure
struct MovingAverage {
    int size;
    double sum;
    double buffer[ROLLING_WINDOW_SIZE];
};

// Define the transaction processing function
void processTransaction(struct Transaction *transaction) {
    // Calculate the age of the transaction (in seconds)
    long long age = (long long)(time(NULL) - transaction->timestamp) / 1000;

    // Filter transactions based on age threshold
    if (age > AGE_THRESHOLD) {
        printf("Filtered out transaction %d due to age\n", transaction->id);
        return;
    }

    // Calculate the weighted sum of the transaction
    double weightedSum = transaction->weightedSum;

    // Filter transactions based on weighted sum threshold
    if (weightedSum > WEIGHTED_SUM_THRESHOLD * getMovingAverage()) {
        printf("Filtered out transaction %d due to weighted sum\n", transaction->id);
        return;
    }

    // Update the moving average with the new transaction's weighted sum
    updateMovingAverage(weightedSum);

    // Increment the total number of processed transactions
    totalProcessedTransactions++;
}

// Define the function to get the current moving average
double getMovingAverage() {
    return rollingWindow.sum / rollingWindow.size;
}

// Define the function to update the moving average with a new transaction's weighted sum
void updateMovingAverage(double weightedSum) {
    // Add the new transaction's weighted sum to the buffer
    rollingWindow.buffer[rollingWindow.index] = weightedSum;

    // Increment the index and size of the buffer
    rollingWindow.index++;
    if (rollingWindow.index == ROLLING_WINDOW_SIZE) {
        rollingWindow.index = 0;
    }
    rollingWindow.size++;

    // Update the sum of the buffer
    rollingWindow.sum += weightedSum;
}

// Define the function to calculate the maximum weighted sum of all processed transactions
