    int max = -1;
    for (int i = 0; i < totalProcessedTransactions; i++) {
        if (transactions[i].weightedSum > max) {
            max = transactions[i].weightedSum;
        }
    }
    return max;
}

// Define the function to get the corresponding transaction ID for a maximum weighted sum
int getTransactionID(int maxWeightedSum) {
    for (int i = 0; i < totalProcessedTransactions; i++) {
        if (transactions[i].weightedSum == maxWeightedSum) {
            return transactions[i].id;
        }
    }
    return -1;
}

// Define the function to filter transactions based on the age threshold
void filterByAge(struct Transaction *transaction) {
    // Calculate the age of the transaction (in seconds)
    long long age = (long long)(time(NULL) - transaction->timestamp) / 1000;

    // Filter transactions based on age threshold
    if (age > AGE_THRESHOLD) {
        printf("Filtered out transaction %d due to age\n", transaction->id);
        return;
    }
}

// Define the function to filter transactions based on the number limit
void filterByNumber(struct Transaction *transaction) {
    // Calculate the number of transactions in the last 10 milliseconds
    int count = 0;
    for (int i = 0; i < totalProcessedTransactions; i++) {
        if ((time(NULL) - transactions[i].timestamp) / 1000 <= ROLLING_WINDOW_MS) {
            count++;
        }
    }

    // Filter transactions based on number limit
    if (count > WEIGHTED_SUM_THRESHOLD * getMovingAverage()) {
        printf("Filtered out transaction %d due to number\n", transaction->id);
        return;
    }
}

// Define the function to filter transactions based on the weighted sum threshold
void filterByWeightedSum(struct Transaction *transaction) {
    // Calculate the weighted sum of the transaction
    double weightedSum = transaction->weightedSum;

    // Filter transactions based on weighted sum threshold
    if (weightedSum > WEIGHTED_SUM_THRESHOLD * getMovingAverage()) {
        printf("Filtered out transaction %d due to weighted sum\n", transaction->id);
        return;
    }
}

// Define the function to update metrics such as the total number of processed transactions, the number of transactions filtered out due to age, the number of transactions filtered out due to the number limit, and the number of transactions filtered out due to the weighted sum threshold
void updateMetrics(struct Transaction *transaction) {
    // Increment the total number of processed transactions
    totalProcessedTransactions++;

    // Filter transactions based on age threshold
    if (filterByAge(transaction)) {
        ageFilteredTransactions++;
    }

