#include <openssl/evp.h>
#include <openssl/err.h>

// Define the encryption context structure
typedef struct {
    AES_KEY aes_key; // The AES key used for encryption and decryption
    unsigned char nonce[16]; // The nonce used to generate the initialization vector
    int initialized; // Whether the cipher has been successfully initialized
} EncryptionContext;

// Define the logging context structure
typedef struct {
    FILE *log_file; // The log file handle
    int verbosity; // The level of verbosity for the logging system
} LoggingContext;

// Define the encryption configuration structure
typedef struct {
    char *password; // The password used to generate the AES key
    unsigned char salt[16]; // The salt used to derive the AES key
    int iterations; // The number of iterations for the KDF
    int key_length; // The length of the derived AES key
} EncryptionConfiguration;

// Define the encryption function prototype
void encrypt(EncryptionContext *context, const char *directory_path, const char *config_file);

// Define the decryption function prototype
void decrypt(EncryptionContext *context, const char *directory_path, const char *config_file);

// Define the logging function prototype
void log_event(LoggingContext *logging_context, const char *message);

// Initialize the encryption context with a password and configuration file
int initialize_encryption_context(EncryptionContext *context, const char *password, const char *config_file) {
    // Load the encryption configuration from the configuration file
    EncryptionConfiguration config;
    if (!load_encryption_configuration(&config, config_file)) {
        return 0;
    }

    // Generate a cryptographically secure nonce using OpenSSL's secure random number generator
    if (RAND_bytes(context->nonce, sizeof(context->nonce)) != 1) {
        log_event(logging_context, "Failed to generate nonce");
        return 0;
    }

    // Derive the encryption key securely from the password using a salted key derivation function (KDF) with adjustable parameters for key length and iterations
    if (!derive_key(&config, context->nonce, &context->aes_key)) {
        log_event(logging_context, "Failed to derive encryption key");
        return 0;
    }

    // Initialize the AES-256-GCM cipher with the derived key and nonce
    if (AES_set_encrypt_key(&context->aes_key, sizeof(context->aes_key)) != 1) {
        log_event(logging_context, "Failed to initialize AES cipher");
        return 0;
    }

    // Set the initialized flag to indicate that the context has been successfully initialized
    context->initialized = 1;

    return 1;
}

// Initialize the logging context with a log file handle and verbosity level
int initialize_logging_context(LoggingContext *logging_context, FILE *log_file, int verbosity) {
    // Set the log file handle and verbosity level
    logging_context->log_file = log_file;
    logging_context->verbosity = verbosity;

    return 1;
}

// Load the encryption configuration from a file
int load_encryption_configuration(EncryptionConfiguration *config, const char *config_file) {
    // Open the configuration file for reading
    FILE *config_file_handle = fopen(config_file, "r");
    if (config_file_handle == NULL) {
        log_event(logging_context, "Failed to open encryption configuration file");
        return 0;
    }

    // Read the password and salt from the configuration file
    char *password = NULL;
    unsigned char salt[16];
    int iterations = 0;
    int key_length = 0;
    if (fscanf(config_file_handle, "%s %s %d %d", &password, &salt, &iterations, &key_length) != 4) {
        log_event(logging_context, "Failed to read encryption configuration");
        fclose(config_file_handle);
        return 0;
    }

    // Set the password, salt, iterations, and key length in the encryption configuration structure
    config->password = password;
    memcpy(config->salt, salt, sizeof(config->salt));
    config->iterations = iterations;
    config->key_length = key_length;

    // Close the configuration file handle
    fclose(config_file_handle);

    return 1;
}

// Derive the encryption key securely from a password using a salted key derivation function (KDF) with adjustable parameters for key length and iterations
int derive_key(EncryptionConfiguration *config, const unsigned char *nonce, AES_KEY *aes_key) {
    // Initialize the KDF with the specified parameters
    EVP_PBE_CTX *kdf = EVP_PBE_CTX_new(EVP_PBE_TYPE_SCRYPT, NULL, config->salt, sizeof(config->salt), config->iterations);
    if (kdf == NULL) {
        log_event(logging_context, "Failed to initialize KDF");
        return 0;
    }

    // Derive the encryption key from the password using the KDF
    int key_length = EVP_PBE_key_from_password(kdf, config->password, strlen(config->password), aes_key);
    if (key_length <= 0) {
        log_event(logging_context, "Failed to derive encryption key");
        return 0;
    }

    // Set the key length in the AES_KEY structure
    aes_key->key_len = key_length;

    // Clean up the KDF context
    EVP_PBE_CTX_free(kdf);

    return 1;
}

// Encrypt and decrypt files in the specified directory using the AES-256-GCM cipher
void encrypt(EncryptionContext *context, const char *directory_path, const char *config_file) {
    // Initialize the encryption context with the password and configuration file
    if (!initialize_encryption_context(context, config_file)) {
        log_event(logging_context, "Failed to initialize encryption context");
        return;
    }

    // Open the directory for reading
    DIR *directory = opendir(directory_path);
    if (directory == NULL) {
        log_event(logging_context, "Failed to open directory");
        return;
    }

    // Iterate over each file in the directory and encrypt/decrypt it as needed
    struct dirent *file;
    while ((file = readdir(directory)) != NULL) {
        // Skip hidden files and directories
        if (file->d_name[0] == '.') {
            continue;
        }

        // Build the file path
        char file_path[PATH_MAX];
        strcpy(file_path, directory_path);
        strcat(file_path, "/");
        strcat(file_path, file->d_name);

        // Encrypt/decrypt the file as needed
        if (encrypt_file(context, file_path)) {
            log_event(logging_context, "Encrypted file: %s", file_path);
        } else {
            log_event(logging_context, "Failed to encrypt file: %s", file_path);
        }
    }

    // Close the directory handle
    closedir(directory);
}

// Encrypt a single file using the AES-256-GCM cipher
int encrypt_file(EncryptionContext *context, const char *file_path) {
    // Open the file for reading
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        log_event(logging_context, "Failed to open file: %s", file_path);
        return 0;
    }

    // Create a temporary file for writing the encrypted data
    char temp_file_path[PATH_MAX];
    strcpy(temp_file_path, file_path);
    strcat(temp_file_path, ".tmp");
    FILE *temp_file = fopen(temp_file_path, "w");
    if (temp_file == NULL) {
        log_event(logging_context, "Failed to create temporary file: %s", temp_file_path);
        return 0;
    }

    // Initialize the AES-256-GCM cipher with the derived key and nonce
    if (AES_set_encrypt_key(&context->aes_key, sizeof(context->aes_key)) != 1) {
        log_event(logging_context, "Failed to initialize AES cipher");
        return 0;
    }

    // Encrypt the file data and write it to the temporary file
    unsigned char buffer[4096];
    int bytes_read = 0;
    while ((bytes_read = fread(buffer, sizeof(unsigned char), sizeof(buffer), file)) > 0) {
        // Encrypt the data using AES-256-GCM
        unsigned char ciphertext[4096];
        int ciphertext_len = AES_encrypt(buffer, ciphertext, sizeof(ciphertext), &context->aes_key);
        if (ciphertext_len <= 0) {
            log_event(logging_context, "Failed to encrypt data");
            return 0;
        }

        // Write the encrypted data to the temporary file
        fwrite(ciphertext, sizeof(unsigned char), ciphertext_len, temp_file);
    }

    // Close the file and temporary file handles
    fclose(file);
    fclose(temp_file);

    // Rename the temporary file to the original file name
    if (rename(temp_file_path, file_path) != 0) {
        log_event(logging_context, "Failed to rename temporary file: %s", temp_file_path);
        return 0;
    }

    return 1;
}

// Decrypt a single file using the AES-256-GCM cipher
int decrypt_file(EncryptionContext *context, const char *file_path) {
    // Open the file for reading
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        log_event(logging_context, "Failed to open file: %s", file_path);
        return 0;
    }

    // Create a temporary file for writing the decrypted data
    char temp_file_path[PATH_MAX];
    strcpy(temp_file_path, file_path);
    strcat(temp_file_path, ".tmp");
    FILE *temp_file = fopen(temp_file_path, "w");
    if (temp_file == NULL) {
        log_event(logging_context, "Failed to create temporary file: %s", temp_file_path);
        return 0;
    }

    // Initialize the AES-256-GCM cipher with the derived key and nonce
    if (AES_set_decrypt_key(&context->aes_key, sizeof(context->aes_key)) != 1) {
        log_event(logging_context, "Failed to initialize AES cipher");
        return 0;
    }

    // Decrypt the file data and write it to the temporary file
    unsigned char buffer[4096];
    int bytes_read = 0;
    while ((bytes_read = fread(buffer, sizeof(unsigned char), sizeof(buffer), file)) > 0) {
        // Decrypt the data using AES-256-GCM
        unsigned char plaintext[4096];
        int plaintext_len = AES_decrypt(buffer, plaintext, sizeof(plaintext), &context->aes_key);
        if (plaintext_len <= 0) {
            log_event(logging_context, "Failed to decrypt data");
            return 0;
        }

        // Write the decrypted data to the temporary file
        fwrite(plaintext, sizeof(unsigned char), plaintext_len, temp_file);
    }

    // Close the file and temporary file handles
    fclose(file);
    fclose(temp_file);

    // Rename the temporary file to the original file name
    if (rename(temp_file_path, file_path) != 0) {
        log_event(logging_context, "Failed to rename temporary file: %s", temp_file_path);
        return 0;
    }

    return 1;
}

// Encrypt and decrypt files in the specified directory using the AES-256-GCM cipher
void decrypt(EncryptionContext *context, const char *directory_path, const char *config_file) {
    // Initialize the encryption context with the password and configuration file
    if (!initialize_encryption_context(context, config_file)) {
        log_event(logging_context, "Failed to initialize encryption context");
        return;
    }

    // Open the directory for reading
    DIR *directory = opendir(directory_path);
    if (directory == NULL) {
        log_event(logging_context, "Failed to open directory");
        return;
    }

    // Iterate over each file in the directory and decrypt it as needed
    struct dirent *file;
    while ((file = readdir(directory)) != NULL) {
        // Skip hidden files and directories
        if (file->d_name[0] == '.') {
            continue;
        }

        // Build the file path
        char file_path[PATH_MAX];
        strcpy(file_path, directory_path);
        strcat(file_path, "/");
        strcat(file_path, file->d_name);

        // Decrypt the file as needed
        if (decrypt_file(context, file_path)) {
            log_event(logging_context, "Decrypted file: %s", file_path);
        } else {
            log_event(logging_context, "Failed to decrypt file: %s", file_path);
        }
    }

    // Close the directory handle
    closedir(directory);
}
```

