// Define the dynamic array for storing DataPackets
typedef struct {
    DataPacket** packets;
    size_t capacity;
    size_t count;
} DynamicArray;

// Function to initialize a new DynamicArray
DynamicArray* initDynamicArray(size_t initialCapacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) {
        return NULL;
    }
    array->packets = malloc(initialCapacity * sizeof(DataPacket*));
    if (array->packets == NULL) {
        free(array);
        return NULL;
    }
    array->capacity = initialCapacity;
    array->count = 0;
    return array;
}

// Function to add a new DataPacket to the DynamicArray
void addDataPacket(DynamicArray* array, long timestamp, int sourceID, int destinationID, char* payload, size_t payloadLength) {
    // Check if the dynamic array needs to be resized
    if (array->count == array->capacity) {
        // Double the capacity of the dynamic array
        array->capacity *= 2;
        DataPacket** newPackets = realloc(array->packets, array->capacity * sizeof(DataPacket*));
        if (newPackets == NULL) {
            free(array->packets);
            return;
        }
        array->packets = newPackets;
    }
    // Create a new DataPacket and add it to the dynamic array
    DataPacket* packet = malloc(sizeof(DataPacket));
    if (packet == NULL) {
        free(array->packets);
        return;
    }
    packet->timestamp = timestamp;
    packet->sourceID = sourceID;
    packet->destinationID = destinationID;
    packet->payloadLength = payloadLength;
    packet->payload = malloc(payloadLength * sizeof(char));
    if (packet->payload == NULL) {
        free(packet);
        return;
    }
    memcpy(packet->payload, payload, payloadLength);
    array->packets[array->count++] = packet;
}

// Function to update an existing DataPacket in the DynamicArray
void updateDataPacket(DynamicArray* array, int sourceID, int destinationID, char* payload, size_t payloadLength) {
    // Find the index of the DataPacket to be updated
    size_t index = 0;
    while (index < array->count && (array->packets[index]->sourceID != sourceID || array->packets[index]->destinationID != destinationID)) {
        index++;
    }
    // Check if the DataPacket was found
    if (index == array->count) {
        return;
    }
    // Update the payload of the DataPacket
    free(array->packets[index]->payload);
    array->packets[index]->payload = malloc(payloadLength * sizeof(char));
    if (array->packets[index]->payload == NULL) {
        return;
    }
    memcpy(array->packets[index]->payload, payload, payloadLength);
}

// Function to retrieve a DataPacket from the DynamicArray
DataPacket* getDataPacket(DynamicArray* array, int sourceID, int destinationID) {
    // Find the index of the DataPacket to be retrieved
    size_t index = 0;
    while (index < array->count && (array->packets[index]->sourceID != sourceID || array->packets[index]->destinationID != destinationID)) {
        index++;
    }
    // Check if the DataPacket was found
    if (index == array->count) {
        return NULL;
    }
    return array->packets[index];
}

// Function to remove a DataPacket from the DynamicArray
void removeDataPacket(DynamicArray* array, int sourceID, int destinationID) {
    // Find the index of the DataPacket to be removed
    size_t index = 0;
    while (index < array->count && (array->packets[index]->sourceID != sourceID || array->packets[index]->destinationID != destinationID)) {
        index++;
    }
    // Check if the DataPacket was found
    if (index == array->count) {
        return;
    }
    // Remove the DataPacket from the dynamic array
    free(array->packets[index]->payload);
    free(array->packets[index]);
    for (size_t i = index; i < array->count - 1; i++) {
        array->packets[i] = array->packets[i + 1];
    }
    array->count--;
}

// Function to garbage collect unused payload buffers in the DynamicArray
void garbageCollect(DynamicArray* array) {
    // Iterate over all DataPackets in the dynamic array
    for (size_t i = 0; i < array->count; i++) {
        // Check if the payload buffer is not used by any other DataPacket
        bool unused = true;
        for (size_t j = 0; j < array->count; j++) {
            if (i != j && array->packets[j]->payload == array->packets[i]->payload) {
                unused = false;
                break;
            }
        }
        // If the payload buffer is not used, free it
        if (unused) {
            free(array->packets[i]->payload);
        }
    }
}

