// Define the structure for a data packet
typedef struct DataPacket {
    uint64_t timestamp;
    uint32_t sourceID;
    uint32_t destinationID;
    size_t payloadLength;
    char* payload;
} DataPacket;

// Define the dynamic array for storing data packets
typedef struct DataPacketArray {
    DataPacket** packets;
    size_t capacity;
    size_t count;
} DataPacketArray;

// Initialize a new data packet array with a given capacity
DataPacketArray* initDataPacketArray(size_t capacity) {
    DataPacketArray* arr = malloc(sizeof(DataPacketArray));
    if (!arr) {
        return NULL;
    }
    arr->packets = calloc(capacity, sizeof(DataPacket*));
    if (!arr->packets) {
        free(arr);
        return NULL;
    }
    arr->capacity = capacity;
    arr->count = 0;
    return arr;
}

// Add a new data packet to the array
bool addDataPacket(DataPacketArray* arr, DataPacket* packet) {
    if (arr->count >= arr->capacity) {
        // Array is full, cannot add more packets
        return false;
    }
    arr->packets[arr->count++] = packet;
    return true;
}

// Update a data packet in the array by source and destination IDs
bool updateDataPacket(DataPacketArray* arr, uint32_t sourceID, uint32_t destinationID, DataPacket* newPacket) {
    for (size_t i = 0; i < arr->count; i++) {
        if (arr->packets[i]->sourceID == sourceID && arr->packets[i]->destinationID == destinationID) {
            // Found the packet to update, replace it with the new one
            free(arr->packets[i]->payload);
            arr->packets[i] = newPacket;
            return true;
        }
    }
    // Packet not found, cannot update
    return false;
}

// Retrieve a data packet from the array by source and destination IDs
DataPacket* getDataPacket(DataPacketArray* arr, uint32_t sourceID, uint32_t destinationID) {
    for (size_t i = 0; i < arr->count; i++) {
        if (arr->packets[i]->sourceID == sourceID && arr->packets[i]->destinationID == destinationID) {
            return arr->packets[i];
        }
    }
    // Packet not found
    return NULL;
}

// Calculate the MD5 hash of a given string input
char* md5Hash(const char* input) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input, strlen(input), digest);
    char* hash = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (!hash) {
        return NULL;
    }
    for (size_t i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(&hash[i * 2], "%02x", digest[i]);
    }
    hash[MD5_DIGEST_LENGTH * 2] = '\0';
    return hash;
}

// Free a data packet structure and its payload buffer
void freeDataPacket(DataPacket* packet) {
    if (packet->payload) {
        free(packet->payload);
    }
    free(packet);
}

// Free all data packets in the array and reset the count to 0
void clearDataPacketArray(DataPacketArray* arr) {
    for (size_t i = 0; i < arr->count; i++) {
        freeDataPacket(arr->packets[i]);
    }
    arr->count = 0;
}

// Free the dynamic array and all its data packets
void freeDataPacketArray(DataPacketArray* arr) {
    clearDataPacketArray(arr);
    free(arr->packets);
    free(arr);
}
