class TaskWorkerManager {
private:
    std::map<std::string, std::unique_ptr<TaskWorker>> workers_;
    std::mutex mutex_;
    int maxTasksPerWorker_;

public:
    TaskWorkerManager(int maxTasksPerWorker) : maxTasksPerWorker_(maxTasksPerWorker) {}

    void addWorker(const std::string& workerId, const std::string& dataType) {
        std::lock_guard<std::mutex> lock(mutex_);
        workers_.emplace(workerId, std::make_unique<TaskWorker>(dataType));
    }

    void removeWorker(const std::string& workerId) {
        std::lock_guard<std::mutex> lock(mutex_);
        workers_.erase(workerId);
    }

    void processTask(const std::string& workerId, const Task& task) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = workers_.find(workerId);
        if (it != workers_.end()) {
            it->second->processTask(task);
        } else {
            // Handle worker not found
        }
    }

    void reconfigureWorker(const std::string& workerId, int maxTasks) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = workers_.find(workerId);
        if (it != workers_.end()) {
            it->second->setMaxTasks(maxTasks);
        } else {
            // Handle worker not found
        }
    }

private:
    class TaskWorker {
    private:
        std::string dataType_;
        int maxTasks_;
        int numTasksProcessed_;

    public:
        TaskWorker(const std::string& dataType) : dataType_(dataType), maxTasks_(0), numTasksProcessed_(0) {}

