            if (numTasksProcessed_ < maxTasks_) {
                // Process task
                ++numTasksProcessed_;
            } else {
                // Handle resource exhaustion
            }
        }

        void setMaxTasks(int maxTasks) {
            maxTasks_ = maxTasks;
        }
    };
};
