#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define the encryption context structure
typedef struct {
    AES_KEY aes_key; // The AES key used for encryption and decryption
    unsigned char nonce[16]; // The nonce used to initialize the cipher
    int initialized; // Whether the context has been initialized or not
} EncryptionContext;

// Define the logging system structure
typedef struct {
    FILE *log_file; // The log file handle
    int verbosity; // The current logging level (0-3)
} LoggingSystem;

// Define the encryption function prototype
void encrypt_file(const char *filename, const char *password, EncryptionContext *context);

// Define the decryption function prototype
void decrypt_file(const char *filename, const char *password, EncryptionContext *context);

// Define the initialization function prototype
int initialize_encryption_context(const char *password, EncryptionContext *context);

// Define the cleanup function prototype
void cleanup_encryption_context(EncryptionContext *context);

// Define the logging system functions
void log_event(LoggingSystem *logging_system, int level, const char *message);
void set_verbosity(LoggingSystem *logging_system, int level);

// Define the encryption and decryption functions
void encrypt_file(const char *filename, const char *password, EncryptionContext *context) {
    // Check if the file exists and is readable
    if (!file_exists(filename)) {
        log_event(logging_system, 1, "File does not exist");
        return;
    }
    if (!is_readable(filename)) {
        log_event(logging_system, 2, "File is not readable");
        return;
    }

    // Initialize the encryption context if necessary
    if (!context->initialized) {
        initialize_encryption_context(password, context);
    }

    // Open the file for reading and writing
    FILE *file = fopen(filename, "r+");
    if (file == NULL) {
        log_event(logging_system, 3, "Failed to open file for reading and writing");
        return;
    }

    // Read the file contents into a buffer
    char *buffer = malloc(sizeof(char) * BUFSIZ);
    size_t read_size = fread(buffer, sizeof(char), BUFSIZ, file);
    if (ferror(file)) {
        log_event(logging_system, 4, "Failed to read from file");
        return;
    }

    // Encrypt the buffer using AES-256-GCM
    size_t encrypted_size = AES_BLOCK_SIZE + (read_size / AES_BLOCK_SIZE) * AES_GCM_TAG_LEN;
    char *encrypted_buffer = malloc(sizeof(char) * encrypted_size);
    int ret = AES_GCM_encrypt(context->aes_key, buffer, read_size, encrypted_buffer, encrypted_size, context->nonce, NULL, 0, NULL);
    if (ret != 1) {
        log_event(logging_system, 5, "Failed to encrypt file");
        return;
    }

    // Write the encrypted buffer back to the file
    size_t write_size = fwrite(encrypted_buffer, sizeof(char), encrypted_size, file);
    if (ferror(file)) {
        log_event(logging_system, 6, "Failed to write to file");
        return;
    }

    // Close the file and free resources
    fclose(file);
    free(buffer);
    free(encrypted_buffer);
}

void decrypt_file(const char *filename, const char *password, EncryptionContext *context) {
    // Check if the file exists and is readable
    if (!file_exists(filename)) {
        log_event(logging_system, 1, "File does not exist");
        return;
    }
    if (!is_readable(filename)) {
        log_event(logging_system, 2, "File is not readable");
        return;
    }

    // Initialize the encryption context if necessary
    if (!context->initialized) {
        initialize_encryption_context(password, context);
    }

    // Open the file for reading and writing
    FILE *file = fopen(filename, "r+");
    if (file == NULL) {
        log_event(logging_system, 3, "Failed to open file for reading and writing");
        return;
    }

    // Read the file contents into a buffer
    char *buffer = malloc(sizeof(char) * BUFSIZ);
    size_t read_size = fread(buffer, sizeof(char), BUFSIZ, file);
    if (ferror(file)) {
        log_event(logging_system, 4, "Failed to read from file");
        return;
    }

    // Decrypt the buffer using AES-256-GCM
    size_t decrypted_size = read_size - AES_BLOCK_SIZE - AES_GCM_TAG_LEN;
    char *decrypted_buffer = malloc(sizeof(char) * decrypted_size);
    int ret = AES_GCM_decrypt(context->aes_key, buffer, read_size, decrypted_buffer, decrypted_size, context->nonce, NULL, 0, NULL);
    if (ret != 1) {
        log_event(logging_system, 5, "Failed to decrypt file");
        return;
    }

    // Write the decrypted buffer back to the file
    size_t write_size = fwrite(decrypted_buffer, sizeof(char), decrypted_size, file);
    if (ferror(file)) {
        log_event(logging_system, 6, "Failed to write to file");
        return;
    }

    // Close the file and free resources
    fclose(file);
    free(buffer);
    free(decrypted_buffer);
}

// Define the initialization function
int initialize_encryption_context(const char *password, EncryptionContext *context) {
    // Generate a cryptographically secure nonce using OpenSSL's secure random number generator
    if (RAND_bytes(context->nonce, 16) != 1) {
        log_event(logging_system, 7, "Failed to generate nonce");
        return -1;
    }

    // Derive the encryption key securely from the password using a salted key derivation function (KDF) with adjustable parameters for key length and iterations
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), context->nonce, 16, 10000, EVP_sha256(), AES_KEY_LEN, context->aes_key) != 1) {
        log_event(logging_system, 8, "Failed to derive key from password");
        return -1;
    }

    // Set the initialized flag to indicate that the context has been initialized successfully
    context->initialized = 1;

    // Log the successful initialization event
    log_event(logging_system, 9, "Encryption context initialized successfully");

    return 0;
}

// Define the cleanup function
void cleanup_encryption_context(EncryptionContext *context) {
    // Clear the AES key and nonce
    memset(context->aes_key, 0, sizeof(AES_KEY));
    memset(context->nonce, 0, sizeof(unsigned char) * 16);

    // Set the initialized flag to indicate that the context has been cleaned up successfully
    context->initialized = 0;

    // Log the successful cleanup event
    log_event(logging_system, 10, "Encryption context cleaned up successfully");
}

// Define the logging system functions
void log_event(LoggingSystem *logging_system, int level, const char *message) {
    // Check if the logging level is high enough to log the message
    if (level > logging_system->verbosity) {
        return;
    }

    // Open the log file for writing
    FILE *log_file = fopen(logging_system->log_file, "a");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return;
    }

    // Write the message to the log file
    fprintf(log_file, "%s", message);

    // Close the log file
    fclose(log_file);
}

void set_verbosity(LoggingSystem *logging_system, int level) {
    logging_system->verbosity = level;
}
