char* get_unique_filename(const char* orig_filename) {
    // Get the file extension from the original filename
    const char* ext = strrchr(orig_filename, '.');
    if (ext == NULL) {
        ext = DEFAULT_FILE_TYPE;
    } else {
        ext++;
    }

    // Generate a random string with a length of up to 10 digits
    char* rand_str = rand_string(MIN(MAX_RAND_LEN, strlen(ext)));

    // Construct the new filename by appending the random string and the file extension
    int len = strlen(orig_filename) + strlen(rand_str) + strlen(ext);
    char* new_filename = malloc(len + 1);
    snprintf(new_filename, len + 1, "%s%s%s", orig_filename, rand_str, ext);

    // Check if the new filename is unique among all files in the current directory
    int attempts = 0;
    while (attempts < MAX_ATTEMPTS) {
        struct stat sb;
        if (stat(new_filename, &sb) == -1) {
            break;
        }
        // If not unique, append a random number to the filename and try again
        char* rand_num = rand_string(1);
        snprintf(new_filename, len + 1, "%s%s", orig_filename, rand_num);
        attempts++;
    }

    // Return the new filename
    return new_filename;
}

