unsigned long validateFileContent(const char* filename, int fd) {
    // Allocate memory for the file content buffer
    char* buffer = malloc(MAX_FILESIZE * sizeof(char));
    if (buffer == NULL) {
        perror("malloc");
        return -1;
    }

    // Read the file descriptor into the buffer
    ssize_t num_bytes = read(fd, buffer, MAX_FILESIZE);
    if (num_bytes < 0) {
        perror("read");
        free(buffer);
        return -1;
    }

    // Compute the checksum of the file content using a hash function
    unsigned long checksum = computeChecksum(buffer, num_bytes);

    // Free the memory allocated for the buffer
    free(buffer);

    return checksum;
}

// Function to compute the checksum of a file content using a hash function
unsigned long computeChecksum(const char* buffer, size_t num_bytes) {
    // Initialize the checksum with a random value
    unsigned long checksum = 0xDEADBEEF;

    // Compute the checksum of the file content using a hash function
    for (size_t i = 0; i < num_bytes; i++) {
        checksum += buffer[i];
    }

    return checksum;
}
