    char* decodedMetadata = decodeMetadata(buffer, bytesRead);
    if (decodedMetadata == NULL) {
        printf("Error: unable to decode metadata from file %s\n", filePath);
        return;
    }

    // Compute the hash of the decoded metadata
    char* hash = computeHash(decodedMetadata, bytesRead);
    if (hash == NULL) {
        printf("Error: unable to compute hash for metadata from file %s\n", filePath);
        return;
    }

    // Free the memory allocated for the buffer
