#include <errno.h>
#include <stdbool.h>
#include <limits.h>
#include <inttypes.h>
#include <assert.h>

#define BUFFER_SIZE 4096
#define MAX_FILENAME_LEN 256
#define MAX_SERVER_NAME_LEN 128
#define MAX_TRANSFORMATION_RULES 16

typedef struct {
    char filename[MAX_FILENAME_LEN];
    char server_name[MAX_SERVER_NAME_LEN];
    int num_rules;
    char rules[MAX_TRANSFORMATION_RULES][BUFFER_SIZE];
} log_file_t;

typedef struct {
    char filename[MAX_FILENAME_LEN];
    char server_name[MAX_SERVER_NAME_LEN];
    int num_rules;
    char rules[MAX_TRANSFORMATION_RULES][BUFFER_SIZE];
} output_file_t;

typedef struct {
    log_file_t *log_files;
    size_t num_log_files;
    output_file_t *output_files;
    size_t num_output_files;
} processing_context_t;

void processAndTransformLogs(processing_context_t *ctx) {
    // Validate input parameters
    if (ctx == NULL || ctx->log_files == NULL || ctx->num_log_files == 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Initialize output files
    for (size_t i = 0; i < ctx->num_output_files; ++i) {
        output_file_t *out_file = &ctx->output_files[i];
        snprintf(out_file->filename, MAX_FILENAME_LEN, "%s-%s.log", out_file->server_name, out_file->rules);
    }

    // Open log files and output files for reading/writing
    int *fd = malloc(ctx->num_log_files * sizeof(int));
    if (fd == NULL) {
        fprintf(stderr, "Failed to allocate memory for file descriptors\n");
        return;
    }
    for (size_t i = 0; i < ctx->num_log_files; ++i) {
        log_file_t *in_file = &ctx->log_files[i];
        fd[i] = open(in_file->filename, O_RDONLY);
        if (fd[i] == -1) {
            perror("Failed to open input file");
            return;
        }
    }
    for (size_t i = 0; i < ctx->num_output_files; ++i) {
        output_file_t *out_file = &ctx->output_files[i];
        fd[i + ctx->num_log_files] = open(out_file->filename, O_WRONLY | O_CREAT, 0644);
        if (fd[i + ctx->num_log_files] == -1) {
            perror("Failed to create output file");
            return;
        }
    }

    // Read and process logs in a loop
    char *buffer = malloc(BUFFER_SIZE);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for buffer\n");
        return;
    }
    while (true) {
        bool all_files_closed = true;
        for (size_t i = 0; i < ctx->num_log_files + ctx->num_output_files; ++i) {
            if (fd[i] != -1) {
                all_files_closed = false;
                break;
            }
        }
        if (all_files_closed) {
            break;
        }

        // Read from log files and process logs
        for (size_t i = 0; i < ctx->num_log_files; ++i) {
            log_file_t *in_file = &ctx->log_files[i];
            ssize_t bytes_read = read(fd[i], buffer, BUFFER_SIZE);
            if (bytes_read == -1) {
                perror("Failed to read from input file");
                return;
            } else if (bytes_read == 0) {
                close(fd[i]);
                fd[i] = -1;
            } else {
                // Process log entries and write to output files
                for (size_t j = 0; j < bytes_read / sizeof(log_entry_t); ++j) {
                    log_entry_t *entry = (log_entry_t *)&buffer[j];
                    // Apply transformation rules
                    for (size_t k = 0; k < in_file->num_rules; ++k) {
                        char *rule = in_file->rules[k];
                        if (strcmp(rule, "cpu") == 0) {
                            entry->cpu_usage = entry->cpu_usage * 100;
                        } else if (strcmp(rule, "mem") == 0) {
                            entry->memory_consumption = entry->memory_consumption / 1024;
                        } else if (strcmp(rule, "net") == 0) {
                            entry->network_io = entry->network_io * 8;
                        } else if (strcmp(rule, "err") == 0) {
                            entry->error_rate = entry->error_rate * 100;
                        }
                    }
                }
                // Write to output files
                for (size_t j = 0; j < ctx->num_output_files; ++j) {
                    output_file_t *out_file = &ctx->output_files[j];
                    if (strcmp(out_file->server_name, in_file->server_name) == 0) {
                        ssize_t bytes_written = write(fd[i + ctx->num_log_files], buffer, bytes_read);
                        if (bytes_written == -1) {
                            perror("Failed to write to output file");
                            return;
                        }
                    }
                }
            }
        }
    }

    // Close files and free resources
    for (size_t i = 0; i < ctx->num_log_files + ctx->num_output_files; ++i) {
        if (fd[i] != -1) {
            close(fd[i]);
        }
    }
    free(buffer);
    free(fd);
}
