#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <zlib.h>
#include <json-c/json.h>

#define MAX_LOG_ENTRIES 100000
#define MAX_FILENAME_LEN 256
#define MAX_SERVER_NAME_LEN 64
#define MAX_TRANSFORMATION_RULES 10

typedef struct {
    char filename[MAX_FILENAME_LEN];
    char server_name[MAX_SERVER_NAME_LEN];
    int num_rules;
    char rules[MAX_TRANSFORMATION_RULES][MAX_FILENAME_LEN];
} log_file_t;

typedef struct {
    json_object *json;
    char *server_name;
    char *rule;
} log_entry_t;

void processAndTransformLogs(log_file_t *files, int num_files) {
    // Initialize variables
    int i, j, k;
    json_object *json;
    char *server_name;
    char *rule;
    log_entry_t *entries[MAX_LOG_ENTRIES];
    int num_entries = 0;
    int num_valid_entries = 0;
    int num_skipped_entries = 0;
    double processing_time = 0.0;

    // Open output file for writing
    FILE *output_file = fopen("transformed_logs.json", "w");
    if (output_file == NULL) {
        printf("Error opening output file\n");
        return;
    }

    // Process each log file
    for (i = 0; i < num_files; i++) {
        // Open log file for reading
        int fd = open(files[i].filename, O_RDONLY);
        if (fd == -1) {
            printf("Error opening log file %s\n", files[i].filename);
            continue;
        }

        // Read log entries from file
        while ((json = json_object_from_file(fd)) != NULL) {
            // Extract server name and rule from JSON object
            server_name = json_object_get_string(json, "server_name");
            rule = json_object_get_string(json, "rule");

            // Check if entry is valid
            if (server_name == NULL || rule == NULL) {
                num_skipped_entries++;
                continue;
            }

            // Add entry to list of valid entries
            log_entry_t *entry = malloc(sizeof(log_entry_t));
            entry->json = json;
            entry->server_name = server_name;
            entry->rule = rule;
            entries[num_entries++] = entry;
            num_valid_entries++;
        }

        // Close log file
        close(fd);
    }

    // Process valid entries
    for (i = 0; i < num_valid_entries; i++) {
        // Extract server name and rule from entry
        json = entries[i]->json;
        server_name = entries[i]->server_name;
        rule = entries[i]->rule;

        // Apply transformation rules to JSON object
        for (j = 0; j < files[i].num_rules; j++) {
            if (strcmp(files[i].rules[j], "cpu") == 0) {
                json_object *cpu_usage = json_object_get_object(json, "cpu_usage");
                if (cpu_usage != NULL) {
                    json_object *cpu_usage_percentage = json_object_get_number(cpu_usage);
                    if (cpu_usage_percentage != NULL) {
                        json_object_put(json);
                        json = json_object_new_int(cpu_usage_percentage * 100);
                    }
                }
            } else if (strcmp(files[i].rules[j], "memory") == 0) {
                json_object *memory_usage = json_object_get_object(json, "memory_usage");
                if (memory_usage != NULL) {
                    json_object *memory_usage_percentage = json_object_get_number(memory_usage);
                    if (memory_usage_percentage != NULL) {
                        json_object_put(json);
                        json = json_object_new_int(memory_usage_percentage * 100);
                    }
                }
            } else if (strcmp(files[i].rules[j], "network") == 0) {
                json_object *network_io = json_object_get_object(json, "network_io");
                if (network_io != NULL) {
                    json_object *network_io_bytes = json_object_get_number(network_io);
                    if (network_io_bytes != NULL) {
                        json_object_put(json);
                        json = json_object_new_int(network_io_bytes / 1024);
                    }
                }
            } else if (strcmp(files[i].rules[j], "errors") == 0) {
                json_object *error_rate = json_object_get_object(json, "error_rate");
                if (error_rate != NULL) {
                    json_object *error_rate_percentage = json_object_get_number(error_rate);
                    if (error_rate_percentage != NULL) {
                        json_object_put(json);
                        json = json_object_new_int(error_rate_percentage * 100);
                    }
                }
            }
        }

        // Write transformed JSON object to output file
        fprintf(output_file, "%s\n", json_object_to_json_string(json));

        // Free memory for entry
        free(entries[i]);
    }

    // Close output file
    fclose(output_file);
}

int main(int argc, char *argv[]) {
    // Check command-line arguments
    if (argc < 2) {
        printf("Usage: %s [log files]\n", argv[0]);
        return 1;
    }

    // Initialize variables
    int i, j;
    log_file_t *files = malloc(sizeof(log_file_t) * (argc - 1));
    for (i = 0; i < argc - 1; i++) {
        files[i].filename = argv[i + 1];
        files[i].server_name = NULL;
        files[i].num_rules = 0;
        for (j = 0; j < MAX_TRANSFORMATION_RULES; j++) {
            files[i].rules[j] = NULL;
        }
    }

    // Process log files
    processAndTransformLogs(files, argc - 1);

    // Free memory for files array
    free(files);

    return 0;
}
