    if (checksum == NULL) {
        printf("Error: unable to allocate memory for checksum\n");
        free(buffer);
        fclose(file);
        return NULL;
    }

    sprintf(checksum, "%d", hash_function(buffer, bytes_read));

    // Close the file and free the buffer
    fclose(file);
    free(buffer);

    return checksum;
