// Struct to store the results for each endpoint
typedef struct {
    char *url;
    int version;
    char **strings;
    size_t num_strings;
} EndpointResult;

// Function to parse JSON data and filter out whitespace-only strings
static void parseJSONData(const char *json, char ***strings, size_t *num_strings) {
    // Initialize the output variables
    *strings = NULL;
    *num_strings = 0;

    // Parse the JSON data using a JSON parser library
    json_object *root = json_parse(json);
    if (!root) {
        fprintf(stderr, "Error parsing JSON data\n");
        return;
    }

    // Get the array of strings from the root object
    json_array *strings_array = json_object_get_array(root);
    if (!strings_array) {
        fprintf(stderr, "Error getting string array\n");
        return;
    }

    // Allocate memory for the output strings and initialize them to NULL
    *strings = malloc(sizeof(char *) * json_array_get_count(strings_array));
    if (!*strings) {
        fprintf(stderr, "Error allocating memory for output strings\n");
        return;
    }

    // Iterate over the array of strings and filter out whitespace-only strings
    size_t i = 0;
    json_array_foreach(strings_array, i, string) {
        const char *str = json_object_get_string(string);
        if (str && strlen(str) > 0) {
            (*strings)[i] = strdup(str);
            (*num_strings)++;
        } else {
            (*strings)[i] = NULL;
        }
    }
}

// Function to transform an endpoint URL and append a timestamp, version number, and checksum
static void transformEndpointURL(char *url, char **timestamp, int *version, char **checksum) {
    // Get the current time in seconds since the epoch
    time_t now = time(NULL);

    // Allocate memory for the output variables
    *timestamp = malloc(sizeof(char) * 20);
    if (!*timestamp) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return;
    }
    *version = 1;
    *checksum = malloc(sizeof(char) * SHA_DIGEST_LENGTH * 2 + 1);
    if (!*checksum) {
        fprintf(stderr, "Error allocating memory for checksum\n");
        return;
    }

    // Format the timestamp and version number
    struct tm *tm = localtime(&now);
    strftime(*timestamp, 20, "%Y-%m-%dT%H:%M:%S", tm);
    snprintf(*version, 10, "%d", *version);

    // Compute the checksum of the URL and append it to the output variables
    SHA_CTX ctx;
    SHA1_Init(&ctx);
    SHA1_Update(&ctx, url, strlen(url));
    unsigned char digest[SHA_DIGEST_LENGTH];
    SHA1_Final(digest, &ctx);
    for (int i = 0; i < SHA_DIGEST_LENGTH; i++) {
        snprintf(*checksum + i * 2, 3, "%02x", digest[i]);
    }
}

// Function to process and transform data from an array of API endpoints
void batchProcessAndTransformData(char **endpoints, size_t num_endpoints) {
    // Initialize the output variables
    EndpointResult *results = malloc(sizeof(EndpointResult) * num_endpoints);
    if (!results) {
        fprintf(stderr, "Error allocating memory for results\n");
        return;
    }

    // Iterate over the array of endpoints and process each one
    size_t i = 0;
    for (i = 0; i < num_endpoints; i++) {
        char *endpoint = endpoints[i];
        char **strings = NULL;
        size_t num_strings = 0;

        // Get the JSON data from the endpoint and parse it
        CURL *curl = curl_easy_init();
        if (!curl) {
            fprintf(stderr, "Error initializing cURL\n");
            return;
        }
        curl_easy_setopt(curl, CURLOPT_URL, endpoint);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeJSONData);
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error performing cURL request: %s\n", curl_easy_strerror(res));
            return;
        }
        char *json = malloc(sizeof(char) * 1024);
        if (!json) {
            fprintf(stderr, "Error allocating memory for JSON data\n");
            return;
        }
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &res);
        if (res != 200) {
            fprintf(stderr, "Error getting response code: %d\n", res);
            return;
        }
        curl_easy_cleanup(curl);
        parseJSONData(json, &strings, &num_strings);

        // Filter out whitespace-only strings and transform the endpoint URL
        char **filtered_strings = malloc(sizeof(char *) * num_strings);
        size_t filtered_num_strings = 0;
        for (size_t j = 0; j < num_strings; j++) {
            if (strlen(strings[j]) > 0) {
                filtered_strings[filtered_num_strings++] = strings[j];
            }
        }
        char *timestamp = NULL;
        int version = 1;
        char *checksum = NULL;
        transformEndpointURL(endpoint, &timestamp, &version, &checksum);

        // Store the results for this endpoint in a structured format
        results[i].url = strdup(endpoint);
        results[i].version = version;
        results[i].strings = filtered_strings;
        results[i].num_strings = filtered_num_strings;
    }
}
