// Define a function to process a single file and generate a report
int process_file(const char *filename) {
    // Read the comma-separated list of integers from the file
    int count = read_integers(filename, &integers);
    if (count == -1) {
        perror("read_integers");
        return -1;
    }

    // Find the largest integer in the array
    int largest = find_largest_integer(integers, count);

    // Generate a unique identifier based on the largest integer and file content
    char *identifier = generate_identifier(largest, filename);

    // Generate a new file name with the modified extension
    char *new_filename = generate_new_filename(filename, ".csv");

    // Write the modified file to disk
    FILE *file = fopen(new_filename, "w");
    if (file == NULL) {
        perror("fopen");
        return -1;
    }
    for (int i = 0; i < count; i++) {
        fprintf(file, "%d\n", integers[i]);
    }
    fclose(file);

    // Generate a report for the processed file
    char *report = malloc(strlen(filename) + strlen(identifier) + 100);
    sprintf(report, "Largest integer: %d\nChecksum: %ld\nVersion: %d", largest, checksum, version);

    // Store the report in a subdirectory named "reports" within the specified directory path
    char *reports_dir = malloc(strlen(filename) + strlen("reports") + 10);
    sprintf(reports_dir, "%s/reports", filename);
    if (mkdir(reports_dir, 0755) == -1 && errno != EEXIST) {
        perror("mkdir");
        return -1;
    }
    char *report_filename = malloc(strlen(identifier) + strlen(".txt") + 10);
    sprintf(report_filename, "%s.txt", identifier);
    FILE *report_file = fopen(report_filename, "w");
    if (report_file == NULL) {
        perror("fopen");
        return -1;
    }
    fputs(report, report_file);
    fclose(report_file);

    // Free any dynamically allocated memory
    free(identifier);
    free(new_filename);
    free(reports_dir);
    free(report_filename);

    return 0;
}

// Define a function to process multiple files in parallel using threads
void *process_files_parallel(void *args) {
    // Get the directory path and thread ID from the arguments
    char *directory = (char *) args;
    int thread_id = pthread_self();

    // Iterate over all files in the directory
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        perror("opendir");
        return NULL;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip files that are not .csv files
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char *filename = malloc(strlen(directory) + strlen(entry->d_name) + 10);
        sprintf(filename, "%s/%s", directory, entry->d_name);
        if (access(filename, F_OK) == -1) {
            perror("access");
            continue;
        }
        if (strcmp(entry->d_name + strlen(entry->d_name) - 4, ".csv") != 0) {
            continue;
        }

        // Process the file in a separate thread
        pthread_t thread;
        int rc = pthread_create(&thread, NULL, process_file, filename);
        if (rc != 0) {
            perror("pthread_create");
            continue;
        }
    }
    closedir(dir);

    return NULL;
}

// Define a function to process multiple files sequentially
void process_files_sequential(const char *directory) {
    // Iterate over all files in the directory
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        perror("opendir");
        return;
    }
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip files that are not .csv files
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char *filename = malloc(strlen(directory) + strlen(entry->d_name) + 10);
        sprintf(filename, "%s/%s", directory, entry->d_name);
        if (access(filename, F_OK) == -1) {
            perror("access");
            continue;
        }
        if (strcmp(entry->d_name + strlen(entry->d_name) - 4, ".csv") != 0) {
            continue;
        }

        // Process the file sequentially
        process_file(filename);
    }
    closedir(dir);
}

// Define a function to handle multiple input files and generate reports for each processed file
void batchProcessFilesAndGenerateReports(const char *directory) {
    // Reset the internal state between calls
    reset_state();

    // Process the files sequentially or in parallel, depending on the configuration
    if (parallel) {
        pthread_t thread;
        int rc = pthread_create(&thread, NULL, process_files_parallel, directory);
        if (rc != 0) {
            perror("pthread_create");
            return;
        }
    } else {
        process_files_sequential(directory);
    }
}
