// Function to parse the JSON data and filter out whitespace-only strings
void parseJSONData(char *json_data, struct EndpointResult *result) {
    // Initialize a JSON parser
    json_parser_t *parser = json_parser_new();

    // Parse the JSON data
    json_parse_init(parser, json_data);
    json_value_t *root = json_parse_value(parser);

    // Check if the root value is an array
    if (json_is_array(root)) {
        // Get the number of elements in the array
        int num_elements = json_get_array_size(root);

        // Allocate memory for the strings
        result->num_strings = num_elements;
        result->strings = malloc(sizeof(char *) * num_elements);

        // Iterate over the array elements and filter out whitespace-only strings
        int i;
