// Function to make a GET request to an API endpoint and return the JSON response
char *makeGETRequest(char *endpoint) {
    // Initialize a CURL handle
    CURL *curl = curl_easy_init();
    if (curl == NULL) {
        fprintf(stderr, "Failed to initialize CURL\n");
        return NULL;
    }

    // Set the URL for the GET request
    curl_easy_setopt(curl, CURLOPT_URL, endpoint);

    // Set the HTTP method to GET
    curl_easy_setopt(curl, CURLOPT_HTTPGET, 1L);

    // Set the timeout for the request
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 5L);

    // Set the user agent string
    curl_easy_setopt(curl, CURLOPT_USERAGENT, "Mozilla/5.0 (Windows; U; Windows NT 6.1; en-US) AppleWebKit/534.7 (KHTML, like Gecko) Chrome/11.0.792.123 Safari/534.7");

    // Set the write callback function to handle the response data
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);

    // Perform the GET request and check for errors
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to perform GET request: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    // Get the response code and check for errors
    long http_code = 0;
    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to get response code: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    // Check the HTTP status code and handle errors
    if (http_code != 200) {
        fprintf(stderr, "HTTP status code: %ld\n", http_code);
        return NULL;
    }

    // Return the JSON response data
    return curl_easy_getinfo(curl, CURLINFO_RESPONSE_DATA);
}

// Callback function to handle the response data from a GET request
size_t writeCallback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    // Get the userdata pointer and cast it to a string buffer
    char **buffer = (char **)userdata;
    if (*buffer == NULL) {
        *buffer = malloc(size * nmemb + 1);
    } else {
        *buffer = realloc(*buffer, strlen(*buffer) + size * nmemb + 1);
    }
    memcpy(*buffer, ptr, size * nmemb);
    (*buffer)[strlen(*buffer)] = '\0';
    return size * nmemb;
}
