  time_t timestamp = time(NULL);

  // Construct the filename for the log file based on the product ID and customer ID
  char* filename = (char*)malloc(strlen(LOG_DIR) + strlen(FILENAME_FORMAT) + strlen(productID) + strlen(customerID));
  sprintf(filename, FILENAME_FORMAT, LOG_DIR, productID, customerID);

  // Open the log file for writing
  int fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
  if (fd == -1) {
    perror("open");
    exit(EXIT_FAILURE);
  }

  // Write the log entry to the file
  char* logEntry = (char*)malloc(strlen(LOG_ENTRY_FORMAT) + strlen(transactionID) + strlen(productID) + strlen(customerID) + 10);
  sprintf(logEntry, LOG_ENTRY_FORMAT, transactionID, productID, customerID, amount, timestamp);
  write(fd, logEntry, strlen(logEntry));

  // Close the file
  close(fd);

  // Free memory allocated for the log entry and filename
  free(logEntry);
  free(filename);
}

// Function to compress the log files in the archive directory
void compressLogFiles() {
  // Get the current working directory
  char* cwd = getcwd(NULL, 0);

  // Open the directory containing the log files
  DIR* dir = opendir(LOG_DIR);
  if (dir == NULL) {
    perror("opendir");
    exit(EXIT_FAILURE);
  }

  // Loop through each file in the directory and compress it using gzip
  struct dirent* entry;
  while ((entry = readdir(dir)) != NULL) {
    char* filename = (char*)malloc(strlen(LOG_DIR) + strlen(entry->d_name));
    sprintf(filename, "%s/%s", LOG_DIR, entry->d_name);

    // Check if the file is a regular file and not a directory or symlink
    struct stat sb;
    if (stat(filename, &sb) == 0 && S_ISREG(sb.st_mode)) {
      char* compressedFilename = (char*)malloc(strlen(LOG_DIR) + strlen(entry->d_name) + 5);
      sprintf(compressedFilename, "%s/%s.gz", LOG_DIR, entry->d_name);

      // Compress the file using gzip
      int ret = system(("gzip -f " + filename).c_str());
      if (ret != 0) {
        perror("gzip");
        exit(EXIT_FAILURE);
      }

      // Remove the original file
      remove(filename);
    }

    free(filename);
  }

  closedir(dir);
}

// Function to track the number of transactions in each archive
void trackTransactions() {
  // Get the current working directory
  char* cwd = getcwd(NULL, 0);

  // Open the directory containing the log files
  DIR* dir = opendir(LOG_DIR);
  if (dir == NULL) {
    perror("opendir");
    exit(EXIT_FAILURE);
  }

  // Loop through each file in the directory and count the number of transactions
  struct dirent* entry;
  while ((entry = readdir(dir)) != NULL) {
    char* filename = (char*)malloc(strlen(LOG_DIR) + strlen(entry->d_name));
    sprintf(filename, "%s/%s", LOG_DIR, entry->d_name);

    // Check if the file is a regular file and not a directory or symlink
    struct stat sb;
    if (stat(filename, &sb) == 0 && S_ISREG(sb.st_mode)) {
      int fd = open(filename, O_RDONLY);
      if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
      }

      // Read the file and count the number of transactions
      char* buffer = (char*)malloc(MAX_ARCHIVE_SIZE);
      int bytesRead = read(fd, buffer, MAX_ARCHIVE_SIZE);
      if (bytesRead == -1) {
        perror("read");
        exit(EXIT_FAILURE);
      }

      // Close the file
      close(fd);

      // Count the number of transactions in the file
      int transactionCount = 0;
      char* line = strtok(buffer, "\n");
      while (line != NULL) {
        transactionCount++;
        line = strtok(NULL, "\n");
      }

      // Print a summary report for this archive
      printf(SUMMARY_REPORT_FORMAT, entry->d_name, transactionCount);
    }

    free(filename);
  }

  closedir(dir);
}

// Function to handle directory traversal attacks
void handleDirectoryTraversalAttacks() {
  // Get the current working directory
  char* cwd = getcwd(NULL, 0);

  // Open the directory containing the log files
  DIR* dir = opendir(LOG_DIR);
  if (dir == NULL) {
    perror("opendir");
    exit(EXIT_FAILURE);
  }

  // Loop through each file in the directory and check for directory traversal attacks
  struct dirent* entry;
  while ((entry = readdir(dir)) != NULL) {
    char* filename = (char*)malloc(strlen(LOG_DIR) + strlen(entry->d_name));
    sprintf(filename, "%s/%s", LOG_DIR, entry->d_name);

    // Check if the file is a regular file and not a directory or symlink
    struct stat sb;
    if (stat(filename, &sb) == 0 && S_ISREG(sb.st_mode)) {
      int fd = open(filename, O_RDONLY);
      if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
      }

      // Read the file and check for directory traversal attacks
      char* buffer = (char*)malloc(MAX_ARCHIVE_SIZE);
      int bytesRead = read(fd, buffer, MAX_ARCHIVE_SIZE);
      if (bytesRead == -1) {
        perror("read");
        exit(EXIT_FAILURE);
      }

      // Close the file
      close(fd);

      // Check for directory traversal attacks in the file
      char* line = strtok(buffer, "\n");
      while (line != NULL) {
        if (strstr(line, "../") != NULL || strstr(line, "..\\") != NULL) {
          printf("Directory traversal attack detected in %s\n", filename);
          exit(EXIT_FAILURE);
        }

        line = strtok(NULL, "\n");
      }
    }

    free(filename);
  }

  closedir(dir);
}

