      // Check for appropriate permissions in the file
      char* line = strtok(buffer, "\n");
      while (line != NULL) {
        if (strstr(line, "..") != NULL || strstr(line, "..\\") != NULL) {
          printf("Inappropriate permissions detected in %s\n", filename);
