#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <semaphore.h>

// Define the cache structure
struct Cache {
    char* key;
    char* value;
    time_t expirationTime;
};

// Define the cache settings
struct CacheSettings {
    int maxSize;
    int expirationTime;
    int hitThreshold;
    int missThreshold;
};

// Define the cache instance
struct CacheInstance {
    struct Cache* cache;
    struct CacheSettings settings;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
};

// Initialize the cache instance
void initCache(struct CacheInstance* cache, struct CacheSettings settings) {
    // Allocate memory for the cache
    cache->cache = (struct Cache*)malloc(sizeof(struct Cache) * settings.maxSize);

    // Set the cache settings
    cache->settings = settings;

    // Initialize the mutex and semaphore
    pthread_mutex_init(&cache->mutex, NULL);
    semaphore_init(&cache->semaphore, 0, 1);
}

// Add an item to the cache
void addToCache(struct CacheInstance* cache, char* key, char* value) {
    // Acquire the mutex
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full
    if (cache->settings.maxSize == 0 || cache->settings.size < cache->settings.maxSize) {
        // Add the item to the cache
        struct Cache* newCache = (struct Cache*)malloc(sizeof(struct Cache));
        newCache->key = key;
        newCache->value = value;
        newCache->expirationTime = time(NULL) + cache->settings.expirationTime;
        cache->cache[cache->settings.size++] = *newCache;
    } else {
        // Evict the least recently used item from the cache
        struct Cache* lruItem = &cache->cache[0];
        for (int i = 1; i < cache->settings.maxSize; i++) {
            if (lruItem->expirationTime > cache->cache[i].expirationTime) {
                lruItem = &cache->cache[i];
            }
        }
        free(lruItem);
    }

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Get an item from the cache
char* getFromCache(struct CacheInstance* cache, char* key) {
    // Acquire the mutex
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is empty
    if (cache->settings.size == 0) {
        // Release the mutex and return NULL
        pthread_mutex_unlock(&cache->mutex);
        return NULL;
    }

    // Find the item in the cache
    struct Cache* foundItem = NULL;
    for (int i = 0; i < cache->settings.size; i++) {
        if (strcmp(key, cache->cache[i].key) == 0) {
            foundItem = &cache->cache[i];
            break;
        }
    }

    // Check if the item was found
    if (foundItem != NULL) {
        // Update the hit threshold
        cache->settings.hitThreshold++;

        // Release the mutex and return the value
        pthread_mutex_unlock(&cache->mutex);
        return foundItem->value;
    } else {
        // Update the miss threshold
        cache->settings.missThreshold++;

        // Release the mutex and return NULL
        pthread_mutex_unlock(&cache->mutex);
        return NULL;
    }
}

// Remove an item from the cache
void removeFromCache(struct CacheInstance* cache, char* key) {
    // Acquire the mutex
    pthread_mutex_lock(&cache->mutex);

    // Find the item in the cache
    struct Cache* foundItem = NULL;
    for (int i = 0; i < cache->settings.size; i++) {
        if (strcmp(key, cache->cache[i].key) == 0) {
            foundItem = &cache->cache[i];
            break;
        }
    }

    // Check if the item was found
    if (foundItem != NULL) {
        // Remove the item from the cache
        free(foundItem);
        cache->settings.size--;
    }

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Update the cache with new content
void updateCache(struct CacheInstance* cache, char* key, char* value) {
    // Acquire the mutex
    pthread_mutex_lock(&cache->mutex);

    // Find the item in the cache
    struct Cache* foundItem = NULL;
    for (int i = 0; i < cache->settings.size; i++) {
        if (strcmp(key, cache->cache[i].key) == 0) {
            foundItem = &cache->cache[i];
            break;
        }
    }

    // Check if the item was found
    if (foundItem != NULL) {
        // Update the value of the item
        free(foundItem->value);
        foundItem->value = value;
        foundItem->expirationTime = time(NULL) + cache->settings.expirationTime;
    } else {
        // Add the new item to the cache
        addToCache(cache, key, value);
    }

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Clear the cache
void clearCache(struct CacheInstance* cache) {
    // Acquire the mutex
    pthread_mutex_lock(&cache->mutex);

    // Free all items in the cache
    for (int i = 0; i < cache->settings.size; i++) {
        free(cache->cache[i].value);
    }

    // Reset the cache settings
    cache->settings.size = 0;

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);
}
