void dynamicArrayInit(DynamicArray* array) {
    array->data = NULL;
    array->capacity = 0;
    array->count = 0;
}

void dynamicArrayResize(DynamicArray* array, size_t newCapacity) {
    struct DataPacket** newData = (struct DataPacket**)realloc(array->data, sizeof(struct DataPacket*) * newCapacity);
    if (newData == NULL) {
        // Handle allocation failure
        return;
    }
    array->data = newData;
    array->capacity = newCapacity;
}

void dynamicArrayAdd(DynamicArray* array, struct DataPacket* packet) {
    if (array->count == array->capacity) {
        // Resize the array if it's full
        dynamicArrayResize(array, array->capacity * 2);
    }
    array->data[array->count++] = packet;
}

