// Define a function to append a transaction to the archive file
void appendTransaction(const Transaction& transaction, const std::string& directory) {
    // Create a mutex for synchronizing access to the archive file
    static std::mutex mtx;

    // Lock the mutex before accessing the archive file
    std::lock_guard<std::mutex> lock(mtx);

    // Open the archive file in append mode
    std::ofstream ofs(directory + "/transaction-archive.txt", std::ios::app);

    // Write the transaction details to the archive file
    ofs << transaction.productId << "," << transaction.customerId << "," << transaction.amount << "\n";

    // Close the archive file
    ofs.close();
}

// Define a function to compress the archive file when it reaches the compression threshold
void compressArchive(const std::string& directory) {
    // Create a mutex for synchronizing access to the archive file
    static std::mutex mtx;

    // Lock the mutex before accessing the archive file
    std::lock_guard<std::mutex> lock(mtx);

    // Open the archive file in read mode
    std::ifstream ifs(directory + "/transaction-archive.txt", std::ios::in);

    // Create a new compressed archive file with the same name as the original file
    std::ofstream ofs(directory + "/transaction-archive.txt.gz", std::ios::out | std::ios::binary);

    // Compress the contents of the original archive file to the new compressed archive file
    ifs >> ofs;

    // Close both files
    ifs.close();
    ofs.close();
}

