    // Create a mutex for synchronizing access to the archive file
    static std::mutex mtx;

    // Lock the mutex before accessing the archive file
    std::lock_guard<std::mutex> lock(mtx);

    // Append the transaction details to the archive file
    appendTransaction(transaction, directory);
}

