        segments[i].header.flags = rand() % 8;
        segments[i].header.window_size = rand() % 65536;
        segments[i].header.checksum = rand() % 65536;
        segments[i].header.urgent_pointer = rand() % 65536;

        // Initialize the payload size and contents
        int payload_size = rand() % 1024 + 1;
        char *payload = malloc(payload_size);
        for (int j = 0; j < payload_size; j++) {
            payload[j] = rand() % 256;
        }
        segments[i].payload = payload;

        // Initialize the optional TCP options field
        int num_options = rand() % 10 + 1;
        struct tcp_option *options = malloc(num_options * sizeof(struct tcp_option));
        for (int j = 0; j < num_options; j++) {
            // Generate a unique option code
            int option_code = rand() % 256;
            while (option_code == segments[i].header.flags) {
                option_code = rand() % 256;
            }

            // Generate the option length
            int option_length = rand() % 10 + 1;

            // Initialize the option field
            options[j].option_code = option_code;
            options[j].option_length = option_length;
            for (int k = 0; k < option_length; k++) {
                options[j].option_data[k] = rand() % 256;
            }
        }
        segments[i].options = options;
    }
}

// Define the function to modify a filename and ensure uniqueness
void modify_filename(char *filename, char *filetype) {
    // Get the original filename and extension
    char *original_filename = strrchr(filename, '/');
    if (original_filename == NULL) {
        original_filename = filename;
    } else {
        original_filename++;
    }
    char *extension = strrchr(original_filename, '.');
    if (extension != NULL) {
        extension++;
    }

    // Generate a random sequence of digits for the new filename
    int num_digits = strlen(original_filename);
    char *random_sequence = malloc(num_digits + 1);
    for (int i = 0; i < num_digits; i++) {
        random_sequence[i] = rand() % 10 + '0';
    }
    random_sequence[num_digits] = '\0';

    // Construct the new filename
    char *new_filename = malloc(strlen(original_filename) + strlen(random_sequence) + strlen(filetype) + 1);
    sprintf(new_filename, "%s%s%s", original_filename, random_sequence, filetype);

    // Ensure the new filename is unique
    int i = 0;
    while (access(new_filename, F_OK) == 0) {
        char *temp = malloc(strlen(original_filename) + strlen(random_sequence) + strlen(filetype) + 1);
        sprintf(temp, "%s%s%s", original_filename, random_sequence, filetype);
        free(new_filename);
        new_filename = temp;
        i++;
    }

    // Update the filename and return it
    strcpy(filename, new_filename);
    free(random_sequence);
    free(new_filename);
}

// Define the function to log operation details to a separate log file
void log_operation(char *filename, char *message) {
    // Get the current time and date
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);

    // Construct the log filename
    char *log_filename = malloc(strlen(LOG_DIR) + strlen(LOG_FILENAME) + 1);
    sprintf(log_filename, "%s%s", LOG_DIR, LOG_FILENAME);

    // Open the log file for writing
    int fd = open(log_filename, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("open");
        return;
    }

    // Write the log entry to the file
    char *log_entry = malloc(strlen(message) + 1024);
    sprintf(log_entry, "%s %s\n", asctime(timeinfo), message);
    write(fd, log_entry, strlen(log_entry));

    // Close the log file and free resources
    close(fd);
    free(log_filename);
    free(log_entry);
}

// Define the function to manage the maximum size of the log directory
void manage_log_directory() {
    // Get the current directory path
    char *dir = getcwd(NULL, 0);

    // Get the list of files in the directory
    struct dirent **files;
    int num_files = scandir(dir, &files, NULL, alphasort);

    // Check if the number of files exceeds the maximum size
    if (num_files > MAX_NUM_LOGS) {
        // Remove the oldest logs first
        for (int i = 0; i < num_files - MAX_NUM_LOGS; i++) {
            remove(files[i]->d_name);
        }
    }
}

// Define the function to handle concurrent access from multiple threads safely
void handle_concurrent_access() {
    // Use a mutex to synchronize access to shared resources
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Use a condition variable to signal when a thread is waiting for access
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Define the function to acquire access to shared resources
    void acquire_access() {
        pthread_mutex_lock(&mutex);
        while (/* condition */) {
            pthread_cond_wait(&cond, &mutex);
        }
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to release access to shared resources
    void release_access() {
        pthread_mutex_lock(&mutex);
        /* condition */ = false;
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&mutex);
    }
}
