import java.io.*;
import java.util.*;
import java.security.*;

public class FileRenamer {
    private static final int MAX_FILENAME_LENGTH = 255;
    private static final int MAX_LOG_SIZE = 1024 * 1024; // 1 MB
    private static final String DEFAULT_FILE_TYPE = ".txt";

    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println("Usage: java FileRenamer <filename>");
            return;
        }

        String filename = args[0];
        String newFilename = generateNewFilename(filename);
        System.out.println("Original filename: " + filename);
        System.out.println("New filename: " + newFilename);
    }

    private static String generateNewFilename(String filename) {
        // Generate a random sequence of digits to append to the filename
        Random rand = new Random();
        int numDigits = Math.min(10, filename.length());
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < numDigits; i++) {
            sb.append(rand.nextInt(10));
        }

        // Derive the file type from the original filename's extension, if present
        String fileType = DEFAULT_FILE_TYPE;
        int dotIndex = filename.lastIndexOf('.');
        if (dotIndex != -1) {
            fileType = filename.substring(dotIndex);
        }

        // Construct the new filename by appending the random sequence and file type
        String newFilename = filename + sb.toString() + fileType;

        // Ensure that the resulting filename is unique among all files in the current directory
        int suffix = 0;
        while (new File(newFilename).exists()) {
            newFilename = newFilename + "_" + suffix++;
        }

        // Log the operation details to a separate log file
        try {
            BufferedWriter writer = new BufferedWriter(new FileWriter("rename_log.txt", true));
            writer.write(filename + " -> " + newFilename + "\n");
            writer.close();
        } catch (IOException e) {
            System.out.println("Error writing to log file: " + e);
        }

        // Return the modified filename and its MD5 hash
        return newFilename;
    }
}
