    int retries = 0;
    while (access(new_filename, F_OK) == 0 && retries < 10) {
        sprintf(new_filename, "%s%d", file_name, rand() % 10);
        retries++;
    }
    if (retries >= 10) {
        printf("Error: Could not find a unique filename after %d retries\n", retries);
        exit(1);
    }

    return new_filename;
}
