// Handle concurrent access to the file system for thread safety when checking for filename uniqueness
void handleConcurrentAccessToFileSystem() {
    // Initialize a mutex for synchronizing access to the file system
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Lock the mutex before checking for filename uniqueness
    pthread_mutex_lock(&mutex);

    // Check for filename uniqueness within a maximum number of retries
    int num_retries = 0;
