            printf("Total filename length exceeds maximum of 255 characters\n");
            exit(1);
        }

        // Set the new filename and check for uniqueness again
        strcpy(filename, new_filename);
    }

    // Unlock the mutex after checking for filename uniqueness
    pthread_mutex_unlock(&mutex);
