// Structure to represent a configuration node in the linked list
typedef struct ConfigNode {
    int id;
    char* name;
    char* value;
    struct ConfigNode* next;
} ConfigNode;

// Function to initialize the configuration list with predefined configurations read from a YAML file
void initConfigList(const char* filename) {
    // Open the YAML file and check for errors
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening configuration file: %s\n", strerror(errno));
        return;
    }

    // Read the YAML file line by line and parse each entry as a key-value pair
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Skip empty lines and comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Parse the key-value pair and add a new configuration node to the list
        char* id = strtok(line, " ");
        char* name = strtok(NULL, " ");
        char* value = strtok(NULL, " ");
        ConfigNode* node = malloc(sizeof(ConfigNode));
        node->id = atoi(id);
        node->name = strdup(name);
        node->value = strdup(value);
        node->next = NULL;

        // Check for duplicate IDs and names, and log a warning message if necessary
        ConfigNode* current = head;
        while (current != NULL) {
            if (current->id == node->id || strcmp(current->name, node->name) == 0) {
                printf("Warning: Duplicate ID or name detected in configuration file\n");
                break;
            }
            current = current->next;
        }

        // Add the new node to the list and update the head pointer if necessary
        if (head == NULL) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;
    }

    // Close the YAML file and free any memory allocated for the line buffer
    fclose(fp);
    if (line != NULL) {
        free(line);
    }
}

// Function to add a new configuration node to the list
void addConfigNode(int id, char* name, char* value) {
    // Create a new configuration node and add it to the list
    ConfigNode* node = malloc(sizeof(ConfigNode));
    node->id = id;
    node->name = strdup(name);
    node->value = strdup(value);
    node->next = NULL;

    // Check for duplicate IDs and names, and log a warning message if necessary
    ConfigNode* current = head;
    while (current != NULL) {
        if (current->id == id || strcmp(current->name, name) == 0) {
            printf("Warning: Duplicate ID or name detected in configuration file\n");
            break;
        }
        current = current->next;
    }

    // Add the new node to the list and update the head pointer if necessary
    if (head == NULL) {
        head = node;
    } else {
        tail->next = node;
    }
    tail = node;
}

// Function to remove a configuration node from the list by its ID
void removeConfigNode(int id) {
    // Find the node with the specified ID and remove it from the list
    ConfigNode* current = head;
    while (current != NULL) {
        if (current->id == id) {
            break;
        }
        current = current->next;
    }
    if (current == NULL) {
        printf("Error: Configuration node with ID %d not found\n", id);
        return;
    }
    ConfigNode* previous = current->prev;
    if (previous != NULL) {
        previous->next = current->next;
    } else {
        head = current->next;
    }
    free(current);
}

// Function to search for a configuration node by its ID and return its value
char* getConfigValue(int id) {
    // Find the node with the specified ID and return its value
    ConfigNode* current = head;
    while (current != NULL) {
        if (current->id == id) {
            break;
        }
        current = current->next;
    }
    if (current == NULL) {
        printf("Error: Configuration node with ID %d not found\n", id);
        return NULL;
    }
    return current->value;
}

// Function to search for a configuration node by its name and return its value
char* getConfigValueByName(const char* name) {
    // Find the node with the specified name and return its value
    ConfigNode* current = head;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            break;
        }
        current = current->next;
    }
    if (current == NULL) {
        printf("Error: Configuration node with name %s not found\n", name);
        return NULL;
    }
    return current->value;
}

// Function to update the value of a configuration node by its ID
void setConfigValue(int id, char* value) {
    // Find the node with the specified ID and update its value
    ConfigNode* current = head;
    while (current != NULL) {
        if (current->id == id) {
            break;
        }
        current = current->next;
    }
    if (current == NULL) {
        printf("Error: Configuration node with ID %d not found\n", id);
        return;
    }
    free(current->value);
    current->value = strdup(value);
}

// Function to update the value of a configuration node by its name
void setConfigValueByName(const char* name, char* value) {
    // Find the node with the specified name and update its value
    ConfigNode* current = head;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            break;
        }
        current = current->next;
    }
    if (current == NULL) {
