        return;
    }
    free(current->value);
    current->value = strdup(value);
}

// Function to print the configuration list in a human-readable format
void printConfigList() {
    // Print each node in the list, starting from the head
    ConfigNode* current = head;
    while (current != NULL) {
        printf("ID: %d, Name: %s, Value: %s\n", current->id, current->name, current->value);
        current = current->next;
    }
}
