#include <errno.h>
#include <pthread.h>
#include <stdbool.h>

// Define the file type to be used for renaming files
#define FILE_TYPE ".txt"

// Define the maximum size of the log file
#define LOG_FILE_SIZE 1024 * 1024 * 5 // 5 MB

// Define the directory path where the files are located
#define DIRECTORY_PATH "/path/to/directory"

// Define the metadata service URL
#define METADATA_SERVICE_URL "http://metadata-service.com"

// Define the number of retries for the metadata service
#define NUM_RETRIES 3

// Define the retry delay in milliseconds
#define RETRY_DELAY 1000 // 1 second

// Define the maximum size of the log file before archiving
#define LOG_FILE_ARCHIVE_SIZE 1024 * 1024 * 10 // 10 MB

// Define the directory path where the logs are archived
#define ARCHIVE_DIRECTORY_PATH "/path/to/archive"

// Define the file name pattern for the log files
#define LOG_FILE_PATTERN "rename-files-%d.log"

// Define the lock for synchronizing access to the directory
pthread_mutex_t dir_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the log file name and path
char log_file_name[256];
char log_file_path[256];

// Define the metadata service client
struct http_client *metadata_service_client = NULL;

// Define the function to rename files in the directory
void rename_files(const char *directory_path) {
  // Lock the directory to prevent concurrent access
  pthread_mutex_lock(&dir_lock);

  // Open the directory and retrieve a list of files
  DIR *dir = opendir(directory_path);
  struct dirent *file;
  while ((file = readdir(dir)) != NULL) {
    // Skip hidden files and directories
    if (file->d_name[0] == '.') continue;

    // Get the file path and name
    char file_path[256];
    snprintf(file_path, sizeof(file_path), "%s/%s", directory_path, file->d_name);
    char *file_name = basename(file_path);

    // Get the file extension and check if it matches the desired type
    char *file_ext = strrchr(file_name, '.');
    if (file_ext == NULL || strcmp(file_ext, FILE_TYPE) != 0) continue;

    // Remove the existing suffix from the file name
    char *suffix = strstr(file_name, "-");
    if (suffix != NULL) {
      *suffix = '\0';
    }

    // Get the file classification data from the metadata service
    struct http_response *response = get_classification_data(file_path);
    if (response == NULL) continue;

    // Parse the response and determine the new suffix
    char *new_suffix = parse_classification_data(response->body);
    free(response);
    if (new_suffix == NULL) continue;

    // Rename the file with the new suffix
    snprintf(file_path, sizeof(file_path), "%s/%s-%s%s", directory_path, file_name, new_suffix, FILE_TYPE);
    if (rename(file_path, file_path) != 0) {
      perror("Error renaming file");
      continue;
    }

    // Log the operation result
    log_operation_result(file_name, new_suffix);
  }

  // Unlock the directory to allow other processes to access it
  pthread_mutex_unlock(&dir_lock);
}

// Define the function to get classification data from the metadata service
struct http_response *get_classification_data(const char *file_path) {
  // Create a new HTTP client if necessary
  if (metadata_service_client == NULL) {
    metadata_service_client = http_client_new();
  }

  // Set the URL for the classification data request
  char url[256];
  snprintf(url, sizeof(url), "%s/%s", METADATA_SERVICE_URL, file_path);

  // Send a GET request to the metadata service
  struct http_response *response = http_client_get(metadata_service_client, url);
  if (response == NULL) {
    perror("Error sending GET request");
    return NULL;
  }

  // Check for HTTP errors and retry if necessary
  int status_code = response->status_code;
  if (status_code != 200 && status_code != 404) {
    printf("Error: %d\n", status_code);
    free(response);
    return NULL;
  }

  // Return the response body as a string
  char *body = strdup(response->body);
  free(response);
  return body;
}

// Define the function to parse classification data and determine the new suffix
char *parse_classification_data(const char *body) {
  // Parse the response body as JSON
  json_t *root = json_loads(body, 0, NULL);
  if (root == NULL) {
    perror("Error parsing JSON");
    return NULL;
  }

  // Get the classification data from the root object
  json_t *classification_data = json_object_get(root, "classification_data");
  if (classification_data == NULL) {
    perror("Error getting classification data");
    return NULL;
  }

  // Get the new suffix from the classification data
  char *new_suffix = json_string_value(json_object_get(classification_data, "new_suffix"));
  if (new_suffix == NULL) {
    perror("Error getting new suffix");
    return NULL;
  }

  // Return the new suffix as a string
  return strdup(new_suffix);
}

// Define the function to log operation results
void log_operation_result(const char *file_name, const char *new_suffix) {
  // Create a new log file if necessary
  if (log_file_path[0] == '\0') {
    snprintf(log_file_name, sizeof(log_file_name), LOG_FILE_PATTERN, getpid());
    snprintf(log_file_path, sizeof(log_file_path), "%s/%s", DIRECTORY_PATH, log_file_name);
  }

  // Open the log file in append mode
  FILE *log_file = fopen(log_file_path, "a");
  if (log_file == NULL) {
    perror("Error opening log file");
    return;
  }

  // Write the operation result to the log file
  char *operation_result = malloc(strlen(file_name) + strlen(new_suffix) + 1);
  snprintf(operation_result, sizeof(operation_result), "%s-%s%s", file_name, new_suffix, FILE_TYPE);
  fputs(operation_result, log_file);
  free(operation_result);

  // Close the log file and check for errors
  if (fclose(log_file) != 0) {
    perror("Error closing log file");
  }

  // Archive the log file if necessary
  archive_log_file();
}

// Define the function to archive old log files
void archive_log_file() {
  // Check if the log file size exceeds the limit
  struct stat file_stats;
  if (stat(log_file_path, &file_stats) != 0 || file_stats.st_size < LOG_FILE_ARCHIVE_SIZE) {
    return;
  }

  // Create a new archive directory if necessary
  char archive_directory[256];
  snprintf(archive_directory, sizeof(archive_directory), "%s/%d", ARCHIVE_DIRECTORY_PATH, getpid());
  mkdir(archive_directory, S_IRWXU | S_IRGRP | S_IXGRP);

  // Move the log file to the archive directory
  char archive_file_path[256];
  snprintf(archive_file_path, sizeof(archive_file_path), "%s/%s", archive_directory, log_file_name);
  if (rename(log_file_path, archive_file_path) != 0) {
    perror("Error archiving log file");
  }
}
