void* manage_thread_pool(int* states, int num_states, FSA* fsa, int last_state) {
    // Initialize thread pool with maximum number of threads
    pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * MAX_THREADS);
    if (!threads) {
        return NULL;
    }

    // Create state list by finding states in FSA and storing in dynamic memory allocation
    int* state_list = (int*)malloc(sizeof(int) * num_states);
    if (!state_list) {
        free(threads);
        return NULL;
    }

    // Update 'next' pointer of last state in list to point to newly created state list
    int* next_ptr = &last_state->next;
    *next_ptr = state_list;

    // Implement cache mechanism to reuse previously allocated memory where possible
    int* cache = (int*)malloc(sizeof(int) * num_states);
    if (!cache) {
        free(threads);
        free(state_list);
        return NULL;
    }

    // Monitor memory allocations to ensure they do not exceed specified threshold
    int mem_usage = 0;
    for (int i = 0; i < num_states; i++) {
        if (mem_usage + sizeof(int) > MAX_MEMORY) {
            free(threads);
            free(state_list);
            free(cache);
            return NULL;
        }
        mem_usage += sizeof(int);
    }

    // Handle cases where FSA contains duplicate states by ensuring each state is processed only once
    int* seen = (int*)malloc(sizeof(int) * num_states);
    if (!seen) {
        free(threads);
        free(state_list);
        free(cache);
        return NULL;
    }
    for (int i = 0; i < num_states; i++) {
        seen[i] = 0;
    }

    // Execute tasks concurrently and ensure all threads are properly terminated and cleaned up upon completion
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < num_states; i++) {
        if (!seen[i]) {
            seen[i] = 1;
            int* state = &state_list[i];
            pthread_create(&threads[i], NULL, process_state, (void*)state);
        }
    }
    for (int i = 0; i < num_states; i++) {
        if (!seen[i]) {
            seen[i] = 1;
            int* state = &state_list[i];
            pthread_join(threads[i], NULL);
        }
    }

    // Log detailed execution statistics for auditing and performance analysis purposes
    long start_time = time(NULL);
    for (int i = 0; i < num_states; i++) {
        if (!seen[i]) {
            seen[i] = 1;
            int* state = &state_list[i];
            pthread_join(threads[i], NULL);
        }
    }
    long end_time = time(NULL);
    printf("Execution statistics: %d tasks executed, %d threads used, %ld seconds taken to complete all tasks\n", num_states, MAX_THREADS, end_time - start_time);

    // Clean up memory and return newly created state list or NULL if there is insufficient memory or any processing error occurs
    free(threads);
    free(state_list);
    free(cache);
    free(seen);
    return state_list;
}
