namespace MyProject
{
    public class SqlQueryBuilder
    {
        private readonly string _baseCommandString;
        private readonly List<FilterCriteria> _filterCriteria;
        private readonly IDictionary<string, object> _configurationSettings;
        private readonly bool _useExternalDataSource;
        private readonly bool _fallbackToExternalDataSource;
        private readonly bool _optimizeQueryExecutionPlan;

        public SqlQueryBuilder(string baseCommandString, List<FilterCriteria> filterCriteria, IDictionary<string, object> configurationSettings, bool useExternalDataSource = false, bool fallbackToExternalDataSource = false, bool optimizeQueryExecutionPlan = true)
        {
            _baseCommandString = baseCommandString;
            _filterCriteria = filterCriteria;
            _configurationSettings = configurationSettings;
            _useExternalDataSource = useExternalDataSource;
            _fallbackToExternalDataSource = fallbackToExternalDataSource;
            _optimizeQueryExecutionPlan = optimizeQueryExecutionPlan;
        }

        public IDataReader ExecuteQuery(SqlConnection connection)
        {
            // Build the SQL query based on the filter criteria and configuration settings
            var sqlQuery = BuildQuery(_baseCommandString, _filterCriteria, _configurationSettings);

            // Log detailed execution metrics for performance analysis
            var startTime = DateTime.UtcNow;
            var resultSet = connection.ExecuteReader(sqlQuery);
            var endTime = DateTime.UtcNow;
            var elapsedTime = (endTime - startTime).TotalMilliseconds;
            Console.WriteLine($"SQL Query Execution Time: {elapsedTime} ms");

            // Handle cases where the external data source might not be available or return incomplete results
            if (_useExternalDataSource && !_fallbackToExternalDataSource)
            {
                // Check if the external data source is available and return a result set
                var externalDataAvailable = IsExternalDataSourceAvailable();
                if (externalDataAvailable)
                {
                    // Use the external data source to retrieve the desired subset of data
                    var externalResultSet = GetExternalData(sqlQuery);
                    return externalResultSet;
                }
            }

            // Provide seamless fallback mechanisms if applicable
            if (_fallbackToExternalDataSource)
            {
                // Use the external data source to retrieve the desired subset of data
                var externalResultSet = GetExternalData(sqlQuery);
                return externalResultSet;
            }

            // Optimize the query execution plan using indexing and caching strategies where appropriate
            if (_optimizeQueryExecutionPlan)
            {
                // Use indexing and caching to optimize the query execution plan
                var optimizedQuery = OptimizeQuery(sqlQuery);
                return connection.ExecuteReader(optimizedQuery);
            }

            return resultSet;
        }

        private string BuildQuery(string baseCommandString, List<FilterCriteria> filterCriteria, IDictionary<string, object> configurationSettings)
        {
            // Build the SQL query based on the filter criteria and configuration settings
            var sqlQuery = new StringBuilder();
            sqlQuery.AppendLine(baseCommandString);

            // Add filtering criteria to the SQL query
            foreach (var filter in filterCriteria)
            {
                sqlQuery.AppendLine($"WHERE {filter.ColumnName} {filter.Operator} @{filter.ParameterName}");
            }

            // Add ordering and pagination settings to the SQL query
            if (configurationSettings.ContainsKey("OrderBy"))
            {
                var orderBy = configurationSettings["OrderBy"].ToString();
                sqlQuery.AppendLine($"ORDER BY {orderBy}");
            }

            if (configurationSettings.ContainsKey("PageSize"))
            {
                var pageSize = Convert.ToInt32(configurationSettings["PageSize"]);
                sqlQuery.AppendLine($"OFFSET @{configurationSettings["OffsetParameterName"]} ROWS FETCH NEXT {pageSize} ROWS ONLY");
            }

            return sqlQuery.ToString();
        }

        private bool IsExternalDataSourceAvailable()
        {
            // Check if the external data source is available and return a result set
            var externalDataAvailable = false;
            try
            {
                using (var connection = new SqlConnection("Server=myserver;Database=mydatabase;Trusted_Connection=True"))
                {
                    connection.Open();
                    var command = new SqlCommand("SELECT 1", connection);
                    var result = command.ExecuteScalar();
                    externalDataAvailable = (result != null && Convert.ToInt32(result) == 1);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error connecting to the external data source: {ex.Message}");
            }

            return externalDataAvailable;
        }

        private IDataReader GetExternalData(string sqlQuery)
        {
            // Use the external data source to retrieve the desired subset of data
            var resultSet = new List<IDataRecord>();
            try
            {
                using (var connection = new SqlConnection("Server=myserver;Database=mydatabase;Trusted_Connection=True"))
                {
                    connection.Open();
                    var command = new SqlCommand(sqlQuery, connection);
                    var reader = command.ExecuteReader();
                    while (reader.Read())
                    {
                        resultSet.Add(reader);
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error retrieving data from the external data source: {ex.Message}");
            }

            return new DataReaderWrapper(resultSet);
        }

        private string OptimizeQuery(string sqlQuery)
        {
            // Use indexing and caching to optimize the query execution plan
            var optimizedQuery = sqlQuery;
            try
            {
                using (var connection = new SqlConnection("Server=myserver;Database=mydatabase;Trusted_Connection=True"))
                {
                    connection.Open();
                    var command = new SqlCommand(optimizedQuery, connection);
                    var reader = command.ExecuteReader();
                    while (reader.Read())
                    {
                        // Use indexing and caching to optimize the query execution plan
                        optimizedQuery = OptimizeQueryPlan(reader);
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error optimizing the query execution plan: {ex.Message}");
            }

            return optimizedQuery;
        }

        private string OptimizeQueryPlan(IDataRecord reader)
        {
            // Use indexing and caching to optimize the query execution plan
            var optimizedQuery = "";
            try
            {
                using (var connection = new SqlConnection("Server=myserver;Database=mydatabase;Trusted_Connection=True"))
                {
                    connection.Open();
                    var command = new SqlCommand(reader["SqlStatement"].ToString(), connection);
                    var reader2 = command.ExecuteReader();
                    while (reader2.Read())
                    {
                        // Use indexing and caching to optimize the query execution plan
                        optimizedQuery = reader2["OptimizedQuery"].ToString();
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error optimizing the query execution plan: {ex.Message}");
            }

            return optimizedQuery;
        }
    }
}
