// Define the structure to store the input data
struct InputData {
    int *data;
    size_t size;
};

// Define the function to read the input file and store it in a dynamically allocated array
int readInputFile(const char *filename, struct InputData *input) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Read the input file line by line and store it in a dynamically allocated array
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        int value = atoi(line);
        if (value < 1 || value > INT_MAX) {
            fprintf(stderr, "Error: Value out of range\n");
            return -1;
        }
        input->data = realloc(input->data, (input->size + 1) * sizeof(int));
        if (input->data == NULL) {
            perror("Error allocating memory");
            return -1;
        }
        input->data[input->size++] = value;
    }

    fclose(file);
    return 0;
}

// Define the function to remove duplicates from an array of integers
void removeDuplicates(int *array, size_t size) {
    for (size_t i = 1; i < size; i++) {
        if (array[i] == array[i-1]) {
            memmove(&array[i], &array[i+1], (size - i - 1) * sizeof(int));
            size--;
            i--;
        }
    }
}

// Define the function to validate the input and store it in a dynamically allocated array
int validateInput(const char **filenames, int num_files, struct InputData *input) {
    for (int i = 0; i < num_files; i++) {
        if (readInputFile(filenames[i], input) != 0) {
            return -1;
        }
    }

    // Remove duplicates from the array of integers
    removeDuplicates(input->data, input->size);

    return 0;
}

// Define the function to process the input data and generate an output file based on a set of rules
int processInput(const char *filename_in, const char *filename_out, const char *rules) {
    // Read the input file and store it in a dynamically allocated array
    struct InputData input;
    if (validateInput(filenames, num_files, &input) != 0) {
        return -1;
    }

    // Parse the rules and generate an output file based on them
    FILE *file = fopen(filename_out, "w");
    if (file == NULL) {
        perror("Error opening file");
        return -1;
    }

    for (size_t i = 0; i < input.size; i++) {
        // Apply the rules to each element of the array and write it to the output file
        fprintf(file, "%d\n", applyRules(input.data[i], rules));
    }

    fclose(file);
    return 0;
}

// Define the function to handle errors during processing
void errorHandler(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

int main(int argc, char **argv) {
    // Check if the correct number of arguments was provided
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input file> <output file> <rules>\n", argv[0]);
        return -1;
    }

    // Read the input files and store them in a dynamically allocated array
    const char **filenames = malloc(sizeof(char *) * (argc - 2));
    if (filenames == NULL) {
        perror("Error allocating memory");
        return -1;
    }
    for (int i = 0; i < argc - 2; i++) {
        filenames[i] = argv[i + 1];
    }

    // Read the input files and store them in a dynamically allocated array
    int num_files = argc - 2;
    struct InputData *inputs = malloc(sizeof(struct InputData) * num_files);
    if (inputs == NULL) {
        perror("Error allocating memory");
        return -1;
    }
    for (int i = 0; i < num_files; i++) {
        inputs[i].data = NULL;
        inputs[i].size = 0;
    }
    if (validateInput(filenames, num_files, inputs) != 0) {
        return -1;
    }

    // Process the input data and generate an output file based on a set of rules
    if (processInput(argv[1], argv[2], argv[3]) != 0) {
        return -1;
    }

    // Free the memory allocated for the inputs and filenames
    for (int i = 0; i < num_files; i++) {
        free(inputs[i].data);
    }
    free(inputs);
    free(filenames);

