```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Function to read a list of floating-point numbers from standard input and calculate the mean and standard deviation
void read_numbers(float **numbers, int *num_numbers) {
    // Initialize variables
    float sum = 0;
    float mean = 0;
    float stddev = 0;
    int i = 0;

    // Read input from standard input
    while (fgets(buffer, sizeof(buffer), stdin)) {
        // Parse the input line and validate each number
        char *token = strtok(buffer, " ");
        while (token != NULL) {
            float num = atof(token);
            if (num <= 0) {
                printf("Error: Non-positive value found in input.\n");
                return;
            }
            sum += num;
            i++;
            token = strtok(NULL, " ");
        }
    }

    // Calculate the mean and standard deviation
    mean = sum / i;
    stddev = sqrt((sum - mean) * (sum - mean) / (i - 1));

    // Allocate memory for the array of numbers
    *numbers = malloc(sizeof(float) * i);
    if (*numbers == NULL) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    // Copy the input numbers into the array
    for (int j = 0; j < i; j++) {
        (*numbers)[j] = atof(buffer);
    }

    // Set the number of numbers in the array
    *num_numbers = i;
}
