    return numbers;
}

// Function to process a list of floating-point numbers and calculate the mean and standard deviation
void process_numbers(float **numbers, int num_numbers) {
    // Calculate the mean and standard deviation
    float sum = 0;
    for (int i = 0; i < num_numbers; i++) {
        sum += numbers[i];
    }
    float mean = sum / num_numbers;
    float stddev = sqrt((sum - mean) * (sum - mean) / (num_numbers - 1));

    // Print the results
    printf("Mean: %f\n", mean);
    printf("Standard deviation: %f\n", stddev);
}

// Function to process multiple CSV files containing space-separated floating-point numbers on a single line, using multi-threading where appropriate
void process_files(char **file_names, int num_files) {
    // Initialize variables
    float **numbers = NULL;
    int num_numbers = 0;

    // Create threads to read the input from each file
    pthread_t *threads = malloc(sizeof(pthread_t) * num_files);
    if (threads == NULL) {
        printf("Error: Could not allocate memory for threads.\n");
        return;
    }
    for (int i = 0; i < num_files; i++) {
        pthread_create(&threads[i], NULL, read_numbers, file_names[i]);
    }

    // Wait for the threads to finish and process the input
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], &numbers);
        if (numbers != NULL) {
            process_numbers(numbers, num_numbers);
        }
    }

    // Free the memory allocated for the threads and the input numbers
    free(threads);
    free(numbers);
}
```
This system uses multi-threading to read multiple CSV files containing space-separated floating-point numbers on a single line, using the `pthread` library. Each thread reads the input from a file and calculates the mean and standard deviation of the numbers in the file. The results are then printed to the console. If any errors occur during processing, such as memory allocation failures or invalid formats, they are handled gracefully and an error message is printed to the console.

