// Function to read a list of integers from a file and determine the largest integer
int largest_integer(char* file_path) {
    // Open the file for reading
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", file_path);
        return -1;
    }

    // Initialize variables to keep track of the largest integer and its index
    int largest = INT_MIN, index = 0;

    // Read each line from the file and process it
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Convert the line to an integer
        int num = atoi(line);
        if (num > largest) {
            largest = num;
            index = read / sizeof(int);
        }
    }

    // Close the file
    fclose(file);

    // Calculate and print the average of all integers in the list
    int sum = 0, count = 0;
    for (int i = 0; i < index; i++) {
        sum += atoi(line + i * sizeof(int));
        count++;
    }
    printf("Average: %f\n", (float)sum / count);

    // Free the memory allocated for the line buffer
    free(line);

    return largest;
}

// Main function to test the largest_integer function
int main() {
    char* file_path = "integers.txt";
    int largest = largest_integer(file_path);
    if (largest == -1) {
        printf("Error: unable to read from file %s\n", file_path);
        return 1;
    }
    printf("Largest integer in the list is %d\n", largest);
    return 0;
}
