// Function to perform DNS resolution for a given hostname using the specified DNS server
void resolveDNS(char* hostname, struct in6_addr* ipv6Address, struct in_addr* ipv4Address) {
    // Initialize the DNS result structure
    DNSResult dnsResult;
    memset(&dnsResult, 0, sizeof(dnsResult));

    // Get the IP address of the specified hostname using getaddrinfo()
    struct addrinfo hints, *result;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname, NULL, &hints, &result) != 0) {
        return;
    }

    // Iterate over the list of addresses and find the first IPv6 address
    struct addrinfo* current = result;
    while (current != NULL) {
        if (current->ai_family == AF_INET6) {
            memcpy(&dnsResult.ipv6Address, current->ai_addr, sizeof(struct in6_addr));
            break;
        } else if (current->ai_family == AF_INET) {
            memcpy(&dnsResult.ipv4Address, current->ai_addr, sizeof(struct in_addr));
            break;
        }
        current = current->ai_next;
    }

    // Free the memory allocated by getaddrinfo()
    freeaddrinfo(result);

