// Structure to represent a configuration node in the linked list
typedef struct ConfigNode {
    int id;
    char* name;
    char* value;
    struct ConfigNode* next;
} ConfigNode;

// Global variable to store the head of the linked list
ConfigNode* config_list = NULL;

// Lock for protecting concurrent access to the configuration list
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the configuration list with a set of predefined configurations read from a remote REST API
void init_config(const char* api_url) {
    // Retrieve the configurations from the remote API
    struct ConfigNode* configs = get_configs_from_api(api_url);

    // Initialize the configuration list with the retrieved configurations
    config_list = configs;
}

// Function to add a new configuration node to the linked list
void add_config(int id, const char* name, const char* value) {
    // Acquire the lock for protecting concurrent access to the configuration list
    pthread_mutex_lock(&config_lock);

    // Create a new configuration node with the given ID, name, and value
    ConfigNode* new_node = malloc(sizeof(ConfigNode));
    new_node->id = id;
    new_node->name = strdup(name);
    new_node->value = strdup(value);

    // Add the new node to the end of the linked list
    if (config_list == NULL) {
        config_list = new_node;
    } else {
        ConfigNode* current = config_list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Release the lock for protecting concurrent access to the configuration list
    pthread_mutex_unlock(&config_lock);
}

// Function to remove a configuration node from the linked list by its ID
void remove_config(int id) {
    // Acquire the lock for protecting concurrent access to the configuration list
    pthread_mutex_lock(&config_lock);

    // Find the configuration node with the given ID in the linked list
    ConfigNode* current = config_list;
    while (current != NULL && current->id != id) {
        current = current->next;
    }

    // If the node is found, remove it from the linked list and free its memory
    if (current != NULL) {
        ConfigNode* previous = current->prev;
        if (previous == NULL) {
            config_list = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }

    // Release the lock for protecting concurrent access to the configuration list
    pthread_mutex_unlock(&config_lock);
}

// Function to search for a configuration node in the linked list by its ID
ConfigNode* find_config(int id) {
    // Acquire the lock for protecting concurrent access to the configuration list
    pthread_mutex_lock(&config_lock);

    // Find the configuration node with the given ID in the linked list
    ConfigNode* current = config_list;
    while (current != NULL && current->id != id) {
        current = current->next;
    }

    // Release the lock for protecting concurrent access to the configuration list
    pthread_mutex_unlock(&config_lock);

    return current;
}

// Function to update a configuration node in the linked list by its ID
void update_config(int id, const char* name, const char* value) {
    // Acquire the lock for protecting concurrent access to the configuration list
    pthread_mutex_lock(&config_lock);

    // Find the configuration node with the given ID in the linked list
    ConfigNode* current = config_list;
    while (current != NULL && current->id != id) {
        current = current->next;
    }

    // If the node is found, update its name and value
    if (current != NULL) {
        free(current->name);
        current->name = strdup(name);
        free(current->value);
        current->value = strdup(value);
    }

    // Release the lock for protecting concurrent access to the configuration list
    pthread_mutex_unlock(&config_lock);
}

// Function to merge two configuration nodes with the same ID by applying a conflict resolution strategy
void merge_configs(ConfigNode* node1, ConfigNode* node2) {
    // Acquire the lock for protecting concurrent access to the configuration list
    pthread_mutex_lock(&config_lock);

    // If the nodes have different names or values, apply the conflict resolution strategy
    if (strcmp(node1->name, node2->name) != 0 || strcmp(node1->value, node2->value) != 0) {
        // Overwrite the value of node1 with the value of node2
        free(node1->value);
        node1->value = strdup(node2->value);
    }

    // Release the lock for protecting concurrent access to the configuration list
    pthread_mutex_unlock(&config_lock);
}

// Function to export the configuration list to a log aggregation service
void export_configs() {
    // Acquire the lock for protecting concurrent access to the configuration list
    pthread_mutex_lock(&config_lock);

    // Iterate over the linked list and export each configuration node to the log aggregation service
    ConfigNode* current = config_list;
    while (current != NULL) {
        // Export the configuration node to the log aggregation service
        export_config(current->id, current->name, current->value);

        // Move to the next node in the linked list
        current = current->next;
    }

    // Release the lock for protecting concurrent access to the configuration list
    pthread_mutex_unlock(&config_lock);
}
