#define DEFAULT_FILE_TYPE ".txt"
#define LOG_ROTATION_THRESHOLD 10 // in MB

typedef struct {
    char filename[MAX_FILENAME_LEN];
    int fd;
} log_file_t;

void init_log(const char *filename, const char *filetype) {
    char new_filename[MAX_FILENAME_LEN];
    struct stat st;
    int i = 0;

    // Generate a random filename with the specified file type
    sprintf(new_filename, "%s%d%s", filename, rand() % 1000000000, filetype);

    // Ensure that the new filename is unique and does not exceed 255 characters
    while (stat(new_filename, &st) == 0 || strlen(new_filename) > MAX_FILENAME_LEN) {
        sprintf(new_filename, "%s%d%s", filename, rand() % 1000000000, filetype);
    }

    // Open the log file for writing and truncate it if it already exists
    int fd = open(new_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Initialize the log file structure with the new filename and fd
    log_file_t *log = malloc(sizeof(log_file_t));
    strcpy(log->filename, new_filename);
    log->fd = fd;

    // Log the operation details to a separate log file
    char log_entry[MAX_LOG_SIZE];
    sprintf(log_entry, "Initialized log file %s\n", new_filename);
    write(log->fd, log_entry, strlen(log_entry));
}

void update_log(const char *filename, const char *filetype) {
    // Open the log file for writing and truncate it if it already exists
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Initialize the log file structure with the new filename and fd
    log_file_t *log = malloc(sizeof(log_file_t));
    strcpy(log->filename, filename);
    log->fd = fd;

    // Log the operation details to a separate log file
    char log_entry[MAX_LOG_SIZE];
    sprintf(log_entry, "Updated log file %s\n", filename);
    write(log->fd, log_entry, strlen(log_entry));
}

void close_log(const char *filename) {
    // Close the log file and free the memory allocated for it
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Initialize the log file structure with the new filename and fd
    log_file_t *log = malloc(sizeof(log_file_t));
    strcpy(log->filename, filename);
    log->fd = fd;

    // Log the operation details to a separate log file
    char log_entry[MAX_LOG_SIZE];
    sprintf(log_entry, "Closed log file %s\n", filename);
    write(log->fd, log_entry, strlen(log_entry));
}

void rotate_logs() {
    // Rotate the logs by renaming them with a timestamp and appending a random number to the filename
    char new_filename[MAX_FILENAME_LEN];
    struct stat st;
    int i = 0;

    // Iterate over all log files in the directory
    DIR *dir = opendir(".");
    if (dir == NULL) {
        perror("opendir");
        exit(1);
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip non-log files and hidden files
        if (strncmp(entry->d_name, "log", 3) != 0 || entry->d_name[0] == '.') {
            continue;
        }

        // Generate a new filename with the current timestamp and a random number
        sprintf(new_filename, "%s%d%s", entry->d_name, rand() % 1000000000, ".txt");

        // Ensure that the new filename is unique and does not exceed 255 characters
        while (stat(new_filename, &st) == 0 || strlen(new_filename) > MAX_FILENAME_LEN) {
            sprintf(new_filename, "%s%d%s", entry->d_name, rand() % 1000000000, ".txt");
        }

        // Rename the log file to the new filename
        if (rename(entry->d_name, new_filename) < 0) {
            perror("rename");
            exit(1);
        }
    }

    closedir(dir);
}

void cleanup_logs() {
    // Remove the oldest logs until the maximum size of the log directory is not exceeded
    char *oldest_log = NULL;
    struct stat st;
    int i = 0;

    // Iterate over all log files in the directory
    DIR *dir = opendir(".");
    if (dir == NULL) {
        perror("opendir");
        exit(1);
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip non-log files and hidden files
        if (strncmp(entry->d_name, "log", 3) != 0 || entry->d_name[0] == '.') {
            continue;
        }

        // Get the file size of the log file
        sprintf(new_filename, "%s%d%s", entry->d_name, rand() % 1000000000, ".txt");
        if (stat(new_filename, &st) < 0) {
            perror("stat");
            exit(1);
        }

        // Remove the oldest log file until the maximum size of the log directory is not exceeded
        if (oldest_log == NULL || st.st_mtime < oldest_log->st_mtime) {
            oldest_log = malloc(sizeof(struct stat));
            memcpy(oldest_log, &st, sizeof(struct stat));
        } else {
            free(oldest_log);
            oldest_log = NULL;
        }
    }

    closedir(dir);
}
