    uint8_t *data;
    size_t length;
} MACSDU;

// Define the structure for an IE_LIST
typedef struct {
    uint16_t ie_id;
    uint16_t ie_length;
} IE_LIST;

void initialize_mac_pdu(MAC_PDU *mac_pdu, size_t num_mac_pdus) {
