    mac_pdu->header.source[0] = 0x12;
    mac_pdu->header.source[1] = 0x34;
    mac_pdu->header.source[2] = 0x56;
    mac_pdu->header.destination[0] = 0x78;
    mac_pdu->header.destination[1] = 0x9a;
    mac_pdu->header.destination[2] = 0xbc;
    mac_pdu->header.type = 0xdeadbeef;

    // Initialize the MACSDU structure
    mac_pdu->macsdu.data = malloc(num_mac_pdus * sizeof(uint8_t));
    mac_pdu->macsdu.length = num_mac_pdus;

    // Initialize the IE_LIST structure
    mac_pdu->ie_list.ie_id = 0xcafe;
    mac_pdu->ie_list.ie_length = 10;

    // Generate random MACSDU sizes and contents
