        mac_pdu[i].macsdu.data[i] = rand() % 256;
    }

    // Validate the integrity of the MACSDU after each update to prevent buffer overflows
    for (size_t i = 0; i < num_mac_pdus; i++) {
        if (mac_pdu[i].macsdu.data[i] > mac_pdu[i].macsdu.length) {
            printf("Buffer overflow detected in MACSDU %zu\n", i);
            exit(1);
        }
    }
}
