    // Check if the MACSDU size exceeds the maximum allowed size
    if (mac_pdu->header.macsdu_size > MAX_MACSDU_SIZE) {
        printf("Error: MACSDU size exceeds maximum allowed size\n");
        return;
    }

    // Check if any IE ID is repeated within the same MAC_PDU
    for (int i = 0; i < mac_pdu->ie_list.num_ies; i++) {
        for (int j = i + 1; j < mac_pdu->ie_list.num_ies; j++) {
            if (mac_pdu->ie_list.ies[i].ie_id == mac_pdu->ie_list.ies[j].ie_id) {
                printf("Error: Repeated IE ID found in MAC_PDU\n");
                return;
            }
        }
    }
}

// Function to handle a configuration file that specifies the maximum size of the MACSDU and the minimum required number of IEs per MAC_PDU
void reload_config(char *filename) {
    // Open the configuration file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: Failed to open configuration file\n");
        return;
    }

    // Read the maximum size of the MACSDU and the minimum required number of IEs per MAC_PDU from the configuration file
    int max_macsdu_size, min_num_ies;
    if (fscanf(fp, "%d %d", &max_macsdu_size, &min_num_ies) != 2) {
        printf("Error: Failed to read maximum MACSDU size and minimum number of IEs from configuration file\n");
        fclose(fp);
        return;
    }

    // Close the configuration file
    fclose(fp);

    // Update the maximum size of the MACSDU and the minimum required number of IEs per MAC_PDU
    MAX_MACSDU_SIZE = max_macsdu_size;
    MIN_NUM_IES = min_num_ies;
}

// Function to modify a filename by appending a sequence of random digits followed by a specified file type
void modify_filename(char *filename, char *filetype) {
    // Get the length of the original filename
    int len = strlen(filename);

    // Generate a sequence of random digits to append to the filename
    srand(time(NULL));
    char rand_digits[10];
    for (int i = 0; i < 10; i++) {
        rand_digits[i] = '0' + (rand() % 10);
    }

    // Construct the new filename by appending the random digits and the file type
    char new_filename[256];
    sprintf(new_filename, "%s%s.%s", filename, rand_digits, filetype);

    // Ensure that the total length of the new filename does not exceed 255 characters
    if (strlen(new_filename) > 255) {
        printf("Error: New filename is too long\n");
        return;
    }

    // Copy the new filename to the original filename
    strcpy(filename, new_filename);
}

// Function to handle filenames with multiple dots and maintain the original directory path in the filename
void handle_multiple_dots(char *filename) {
    // Split the filename into its components using the "." character as a delimiter
    char *token = strtok(filename, ".");
    while (token != NULL) {
        if (strcmp(token, ".") == 0) {
            printf("Error: Multiple dots found in filename\n");
            return;
        }
        token = strtok(NULL, ".");
    }
}

// Function to ensure that the resulting filename is unique among all files in the current directory
void ensure_unique_filename(char *filename) {
    // Check if the filename already exists in the current directory
    DIR *dir = opendir(".");
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, filename) == 0) {
            printf("Error: Filename already exists in current directory\n");
            return;
        }
    }
}

// Function to check for uniqueness by appending a random number to the filename until no conflict is found
void append_random_number(char *filename) {
    // Generate a random number between 1 and 10
    srand(time(NULL));
    int rand_num = (rand() % 9) + 1;

    // Append the random number to the filename
    char new_filename[256];
    sprintf(new_filename, "%s%d", filename, rand_num);

    // Check if the resulting filename is unique among all files in the current directory
    ensure_unique_filename(new_filename);
}
