// Load the configuration file and extract the maximum MACSDU size and minimum number of IEs
void loadConfigurationFile(const char* filename) {
    // Open the configuration file and read the maximum MACSDU size and minimum number of IEs
    FILE* config_file = fopen(filename, "r");
    if (!config_file) {
        printf("Error: Failed to open the configuration file %s\n", filename);
        return;
    }
    while (fgets(buffer, sizeof(buffer), config_file)) {
        // Extract the maximum MACSDU size and minimum number of IEs from the configuration file
        if (strncmp(buffer, "MAX_MACSDU_SIZE", 15) == 0) {
            max_macsdu_size = atoi(buffer + 16);
        } else if (strncmp(buffer, "MIN_NUM_IES", 11) == 0) {
            min_num_ies = atoi(buffer + 12);
        }
    }
    // Close the configuration file and return
    fclose(config_file);
}

