    i = strlen(new_filename) - 1;
    while (i >= 0 && new_filename[i] != '.') {
        i--;
    }
    if (i < 0) {
        printf("Error: Failed to find the extension in the filename\n");
        return NULL;
    }
    strcat(new_filename, file_type);
    // Ensure the new filename is unique by appending a random number if necessary
    j = rand() % 1000000;
    sprintf(temp_strings, "%d", j);
    strcat(new_filename, temp_strings);
    return new_filename;
}

