// Define the function to generate a new filename based on the original filename provided
char *generate_filename(const char *original_filename) {
    // Extract the directory path and filename from the original filename
    const char *directory = strtok((char *)original_filename, "/");
    const char *filename = strchr(original_filename, '/');
    if (filename == NULL) {
        return NULL;
    }
    filename++; // Skip the first slash

