    if (new_filename == NULL) {
        printf("Error: Failed to allocate memory for new filename\n");
        return NULL;
    }
    strncpy(new_filename, filename, length);
    sprintf(new_filename + length, "%010d.txt", rand() % 1024 + 1); // Randomly generate a sequence of random digits followed by ".txt"

