};

// Define the function to perform DNS resolution
int dns_resolve(const char *hostname, struct in_addr *ipv4_address, struct in6_addr *ipv6_address) {
    // Initialize the DNS servers from the configuration file
    const char *dns_servers[] = {"8.8.8.8", "8.8.4.4"};
    size_t num_dns_servers = sizeof(dns_servers) / sizeof(dns_servers[0]);

    // Initialize the DNS query parameters
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_DGRAM;

    // Iterate over the DNS servers and perform the query
    for (size_t i = 0; i < num_dns_servers; i++) {
        int err = getaddrinfo(hostname, NULL, &hints, &res);
        if (err != EAI_NONAME) {
            break;
        }
    }

    // Check if the query was successful and return the IP address
    if (res == NULL) {
        return -1;
    } else {
        struct sockaddr_in *sa = (struct sockaddr_in *) res->ai_addr;
        *ipv4_address = sa->sin_addr;
        freeaddrinfo(res);
        return 0;
    }
}

// Define the function to generate a random sequence of digits
int rand_sequence(char *sequence, size_t length) {
    // Check if the length is valid
    if (length > MAX_RANDOM_DIGITS_LENGTH) {
        return -1;
    }

    // Generate a random sequence of digits
    for (size_t i = 0; i < length; i++) {
        sequence[i] = '0' + (rand() % 10);
    }

    return 0;
}

// Define the function to modify the extension of a filename
int modify_filename(const char *filename, const char *filetype, char *new_filename) {
    // Check if the filetype is valid
    if (strlen(filetype) > MAX_FILENAME_LENGTH - strlen(filename)) {
        return -1;
    }

    // Modify the extension of the filename
    size_t len = strlen(filename);
    char *dot = strrchr(filename, '.');
    if (dot == NULL) {
        dot = filename + len;
    }
    strncpy(new_filename, filename, dot - filename);
    strcpy(new_filename + (dot - filename), filetype);

    return 0;
}

// Define the function to generate a unique filename
int generate_unique_filename(const char *filename, const char *filetype, char *unique_filename) {
    // Check if the filename is valid
    if (strlen(filename) > MAX_FILENAME_LENGTH - strlen(filetype)) {
        return -1;
    }

    // Generate a unique filename by appending a random sequence of digits
    char sequence[MAX_RANDOM_DIGITS_LENGTH + 1];
    rand_sequence(sequence, MAX_RANDOM_DIGITS_LENGTH);
    sprintf(unique_filename, "%s%0*d", filename, MAX_RANDOM_DIGITS_LENGTH, atoi(sequence));

    return 0;
}

