    int err = dns_resolve(ie_list->header.destination, &ipv4_address, &ipv6_address);
    if (err != 0) {
        return -1;
    }

    // Update the IE list with the new IP address
    ie_list->header.destination = inet_ntoa(ipv4_address);

    // Handle the fallback mechanism by using cached results if available and retrying the DNS resolution if necessary
    struct macsdu *macsdu = ie_list->macsdus[0];
    if (macsdu != NULL && macsdu->length > 0) {
        return 0;
    } else {
        int err = dns_resolve(ie_list->header.destination, &ipv4_address, &ipv6_address);
        if (err != 0) {
            return -1;
        }
    }

    // Update the IE list with the new IP address
    ie_list->header.destination = inet_ntoa(ipv4_address);

    return 0;
}
