// Function to initialize and aggregate network logs
void initializeAndAggregateNetworkLogs(char* directory) {
    // Open the directory containing the log files
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        perror("Error opening directory");
        return;
    }

    // Loop through each file in the directory
    struct dirent *file;
    while ((file = readdir(dir)) != NULL) {
        // Skip files that are not log files
        if (strcmp(file->d_name, ".") == 0 || strcmp(file->d_name, "..") == 0) {
            continue;
        }

        // Open the log file
        char* filename = malloc(strlen(directory) + strlen(file->d_name) + 1);
        sprintf(filename, "%s/%s", directory, file->d_name);
        int fd = open(filename, O_RDONLY);
        if (fd == -1) {
            perror("Error opening log file");
            continue;
        }

        // Read the log file and process each line
        char* line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, fd)) != -1) {
            // Parse the JSON data in the line
            JSONObject* json = parseJSON(line);
            if (json == NULL) {
                continue;
            }

            // Extract the server metrics from the JSON object
            int cpu_usage = getIntValue(json, "cpu_usage");
            int memory_usage = getIntValue(json, "memory_usage");

            // Create a new NetworkFlow structure for each log entry
            NetworkFlow* flow = malloc(sizeof(NetworkFlow));
            flow->tcp_header.source_port = getIntValue(json, "source_port");
            flow->tcp_header.destination_port = getIntValue(json, "destination_port");
            flow->payload.size = getIntValue(json, "payload_size");
            flow->payload.data = malloc(flow->payload.size);
            memcpy(flow->payload.data, json->payload_data, flow->payload.size);
            flow->options.count = getIntValue(json, "option_count");
            for (int i = 0; i < flow->options.count; i++) {
                flow->options.list[i].code = getIntValue(json, "option_code");
                flow->options.list[i].length = getIntValue(json, "option_length");
                flow->options.list[i].data = malloc(flow->options.list[i].length);
                memcpy(flow->options.list[i].data, json->option_data + i * flow->options.list[i].length, flow->options.list[i].length);
            }

            // Add the new NetworkFlow structure to a dynamic list of flows
            addNetworkFlow(flow);
        }

        // Close the log file and free resources
        close(fd);
        free(line);
    }

    // Generate a new filename based on the original filename provided
    char* new_filename = generateNewFilename(directory, "csv");

    // Write the aggregated network logs to the new file
    FILE* fp = fopen(new_filename, "w");
    if (fp == NULL) {
        perror("Error opening output file");
        return;
    }
    for (int i = 0; i < flow_count; i++) {
        NetworkFlow* flow = flows[i];
        fprintf(fp, "%d,%d,%d,%s\n", flow->tcp_header.source_port, flow->tcp_header.destination_port, flow->payload.size, flow->payload.data);
    }
    fclose(fp);
}

// Function to generate a new filename based on the original filename provided
char* generateNewFilename(char* directory, char* filetype) {
    // Get the original filename and extension
    char* filename = strrchr(directory, '/');
    if (filename == NULL) {
        return NULL;
    }
    filename++;
    char* extension = strrchr(filename, '.');
    if (extension != NULL) {
        *extension = '\0';
    }

    // Generate a new filename with a random sequence of alphabetic characters and the specified file type
    int length = strlen(directory);
    char* new_filename = malloc(length + 9);
    sprintf(new_filename, "%s%s", directory, generateRandomString(8));
    if (extension != NULL) {
        *extension = '.';
    }
    strcat(new_filename, filetype);

    // Ensure the new filename is unique among all files in the current directory
    int conflict = 1;
    while (conflict) {
        struct stat st;
        if (stat(new_filename, &st) == 0) {
            char* random_string = generateRandomString(8);
            sprintf(new_filename + length - 9, "%s", random_string);
        } else {
            conflict = 0;
        }
    }

    return new_filename;
}

// Function to generate a random string of alphabetic characters with the specified length
char* generateRandomString(int length) {
    char* str = malloc(length + 1);
    for (int i = 0; i < length; i++) {
        int index = rand() % 26;
        str[i] = 'a' + index;
    }
    str[length] = '\0';
    return str;
}

// Function to add a new NetworkFlow structure to the dynamic list of flows
void addNetworkFlow(NetworkFlow* flow) {
    // Check if the dynamic array needs to be resized
    if (flow_count == flow_capacity) {
        flow_capacity *= 2;
        flows = realloc(flows, flow_capacity * sizeof(NetworkFlow));
    }

    // Add the new NetworkFlow structure to the dynamic array
    flows[flow_count++] = flow;
}
