// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of NFAPI_CRC_INDICATION_PDU_T structures
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *list = NULL;
static size_t list_size = 0;

// Function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
void create_and_populate_list(size_t num_structures, uint16_t seed, uint16_t rnti_range) {
    // Acquire lock on the list to prevent concurrent access
    pthread_mutex_lock(&list_lock);

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_list) {
        // Handle memory allocation failure gracefully
        pthread_mutex_unlock(&list_lock);
        return;
    }

    // Initialize the list of structures with random values
    for (size_t i = 0; i < num_structures; i++) {
        new_list[i].rx_ue_information_tag = rand() % rnti_range + 1;
        new_list[i].rnti = rand() % rnti_range + 1;
        new_list[i].crc_indication_rel8_tag = (rand() % 2) ? 0 : 1;
    }

    // Replace the old list with the new one
    if (list) {
        free(list);
    }
    list = new_list;
    list_size = num_structures;

    // Release lock on the list
    pthread_mutex_unlock(&list_lock);
}

// Function to clear and reset the list of NFAPI_CRC_INDICATION_PDU_T structures
void clear_and_reset_list() {
    // Acquire lock on the list to prevent concurrent access
    pthread_mutex_lock(&list_lock);

    // Free the memory allocated for the list of structures
    if (list) {
        free(list);
    }
    list = NULL;
    list_size = 0;

    // Release lock on the list
    pthread_mutex_unlock(&list_lock);
}

// Function to handle memory allocation failure gracefully
void handle_memory_allocation_failure() {
    // Acquire lock on the list to prevent concurrent access
    pthread_mutex_lock(&list_lock);

    // Log the failure and release lock on the list
    printf("Memory allocation failed\n");
    pthread_mutex_unlock(&list_lock);
}
