struct Message* create_message(int user_id, char* message_body) {
    struct Message* msg = malloc(sizeof(struct Message));
    if (!msg) {
        return NULL;
    }
    msg->timestamp = time(NULL);
    msg->user_id = user_id;
    msg->message_body = strdup(message_body);
    return msg;
}

// Function to free memory for a message structure
void destroy_message(struct Message* msg) {
    if (msg) {
        free(msg->message_body);
        free(msg);
    }
}

// Function to add a new message to the list
int add_message(struct MessageList* list, int user_id, char* message_body) {
    struct Message* msg = create_message(user_id, message_body);
    if (!msg) {
        return -1;
    }
    pthread_mutex_lock(&list->mutex);
    list->messages[list->num_messages++] = msg;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Function to remove a message from the list
int remove_message(struct MessageList* list, int index) {
    if (index < 0 || index >= list->num_messages) {
        return -1;
    }
    pthread_mutex_lock(&list->mutex);
    destroy_message(list->messages[index]);
    for (int i = index + 1; i < list->num_messages; i++) {
        list->messages[i - 1] = list->messages[i];
    }
    list->num_messages--;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Function to clear the message list
void clear_message_list(struct MessageList* list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->num_messages; i++) {
        destroy_message(list->messages[i]);
    }
    list->num_messages = 0;
    pthread_mutex_unlock(&list->mutex);
}

// Function to reset the message list
void reset_message_list(struct MessageList* list) {
    clear_message_list(list);
    list->messages = realloc(list->messages, sizeof(struct Message*) * 1000);
    if (!list->messages) {
        return;
    }
    for (int i = 0; i < 1000; i++) {
        list->messages[i] = NULL;
    }
}

