// Function to detect and handle potential synchronization issues when multiple threads attempt to access or modify the message list simultaneously
void synchronize_message_list(struct MessageList* list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->num_messages; i++) {
