// Define the function for parsing text for mentions of books in the Old Testament of the Bible using regular expressions
void parseTextForBooks(char *text) {
    // Initialize the map-like structure for storing book names and their counts
    BOOK_COUNT *bookCount = malloc(sizeof(BOOK_COUNT));
    if (bookCount == NULL) {
        printf("Error: Failed to allocate memory for the book count\n");
        return;
    }

    // Initialize the regular expressions for parsing text
    regex_t oldTestamentRegex, bookRegex;
    regcomp(&oldTestamentRegex, OLD_TESTAMENT_REGEX, REG_EXTENDED);
    regcomp(&bookRegex, BOOK_REGEX, REG_EXTENDED);

    // Iterate over the text and find matches for the regular expressions
    char *match = NULL;
    while ((match = regexec(&oldTestamentRegex, text, 1, NULL, 0)) != NULL) {
        // Get the start and end positions of the match
        int startPos = match - text;
        int endPos = startPos + strlen(match);

        // Extract the book name from the match
        char *bookName = malloc(endPos - startPos + 1);
        if (bookName == NULL) {
            printf("Error: Failed to allocate memory for the book name\n");
            return;
        }
        strncpy(bookName, text + startPos, endPos - startPos);
        bookName[endPos - startPos] = '\0';

        // Check if the book name is already in the map-like structure
        bool found = false;
        for (int i = 0; i < bookCount->count; i++) {
            if (strcmp(bookCount->books[i].bookName, bookName) == 0) {
                found = true;
                break;
            }
        }

        // If the book name is not already in the map-like structure, add it to the list of books and increment its count
        if (!found) {
            bookCount->books[bookCount->count].bookName = bookName;
            bookCount->books[bookCount->count].count++;
            bookCount->count++;
        }
    }

    // Free the memory for the regular expressions
    regfree(&oldTestamentRegex);
    regfree(&bookRegex);

    // Print the list of books and their counts
    printf("List of books and their counts:\n");
    for (int i = 0; i < bookCount->count; i++) {
        printf("%s: %d\n", bookCount->books[i].bookName, bookCount->books[i].count);
    }

    // Free the memory for the map-like structure and return
    free(bookCount);
}

// Define the function for performing DNS resolution for a given hostname
void performDNSResolution(char *hostname) {
    // Initialize the DNS resolution data
    DNS_RESOLUTION_DATA *dnsData = malloc(sizeof(DNS_RESOLUTION_DATA));
    if (dnsData == NULL) {
        printf("Error: Failed to allocate memory for the DNS resolution data\n");
        return;
    }

    // Set the hostname and port number for the DNS resolution
    strcpy(dnsData->hostname, hostname);
    dnsData->port = 53;

    // Initialize the socket family, type, and protocol
    dnsData->family = AF_INET;
    dnsData->socktype = SOCK_DGRAM;
    dnsData->protocol = IPPROTO_UDP;

    // Perform DNS resolution using the specified hostname and port number
    struct addrinfo *result, hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    hints.ai_protocol = IPPROTO_UDP;
    if (getaddrinfo(dnsData->hostname, NULL, &hints, &result) != 0) {
        printf("Error: Failed to perform DNS resolution\n");
        return;
    }

    // Print the DNS resolution results
    struct addrinfo *rp;
    for (rp = result; rp != NULL; rp = rp->ai_next) {
        void *addr;
        char *ipver;
        int portno;
        if (rp->ai_family == AF_INET) {
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)rp->ai_addr;
            addr = &ipv4->sin_addr;
            ipver = "IPv4";
            portno = ntohs(ipv4->sin_port);
        } else {
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)rp->ai_addr;
            addr = &ipv6->sin6_addr;
            ipver = "IPv6";
            portno = ntohs(ipv6->sin6_port);
        }
        char address[INET6_ADDRSTRLEN];
        inet_ntop(rp->ai_family, addr, address, sizeof(address));
        printf("DNS resolution results for %s:\n", dnsData->hostname);
        printf("\t%s: %s\n", ipver, address);
        printf("\tPort number: %d\n", portno);
    }

    // Free the memory for the DNS resolution data and return
    freeaddrinfo(result);
    free(dnsData);
}

