use std::sync::Arc;
use std::thread;
use std::time::Instant;

use tokio::runtime::Runtime;
use tokio::sync::mpsc::channel;

struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: u32,
    rnti: u32,
    crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG,
}

struct CRC_INDICATION_REL8_TAG {
    crcflag: bool,
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} <number of structures>", args[0]);
        return;
    }

    let num_structures: usize = args[1].parse().unwrap();
    let mut structures: Vec<NFAPI_CRC_INDICATION_PDU_T> = vec![];

    // Create a channel for communication between threads
    let (tx, rx) = channel::<usize>(num_structures);

    // Spawn a thread to generate the structures
    thread::spawn(move || {
        let start = Instant::now();
        for i in 0..num_structures {
            let structure = NFAPI_CRC_INDICATION_PDU_T {
                rx_ue_information_tag: i as u32,
                rnti: i as u32,
                crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG { crcflag: false },
            };
            structures.push(structure);
        }
        let duration = start.elapsed();
        println!("Generated {} structures in {:?}", num_structures, duration);
        tx.send(num_structures).unwrap();
    });

    // Spawn a thread to handle the logging mechanism
    thread::spawn(move || {
        let mut successfully_created = 0;
        let mut errors = vec![];
        while let Ok(count) = rx.recv() {
            successfully_created += count;
            if !errors.is_empty() {
                println!("Errors encountered: {:?}", errors);
            } else {
                println!(
                    "Successfully created {} structures in {:?}",
                    successfully_created,
                    Instant::now().elapsed()
                );
            }
        }
    });
}
