        if (!new_records) {
            // Handle memory allocation error
            pthread_mutex_unlock(&records_lock);
            return;
        }
        this->records = new_records;
    }

    // Add the new record to the list
    this->records[num_records].ci = ci;
    this->records[num_records].rssi = rssi;
    this->records[num_records].snr = snr;
    this->records[num_records].cqi = cqi;
    num_records++;

    // Release the lock on the records list
    pthread_mutex_unlock(&records_lock);
}

// Filter the list of LTE PHY Layer Measurement Records based on a minimum RSRP threshold
void filter_lte_phy_measurements(float min_rsrp_threshold) {
    // Acquire the lock on the records list
    pthread_mutex_lock(&records_lock);

    // Filter the list of records based on the minimum RSRP threshold
    int num_filtered_records = 0;
    for (int i = 0; i < this->num_records; i++) {
        if (this->records[i].rssi >= min_rsrp_threshold) {
            // Move the filtered record to the beginning of the list
            memmove(&this->records[num_filtered_records], &this->records[i], sizeof(lte_phy_measurement_record_t));
            num_filtered_records++;
        }
    }

    // Update the number of filtered records
    this->num_records = num_filtered_records;

    // Release the lock on the records list
    pthread_mutex_unlock(&records_lock);
}

// Free the memory allocated for the list of LTE PHY Layer Measurement Records
void free_lte_phy_measurements() {
    // Acquire the lock on the records list
    pthread_mutex_lock(&records_lock);

    // Free the memory allocated for the list of records
    if (this->records) {
        free(this->records);
        this->records = NULL;
    }

    // Release the lock on the records list
    pthread_mutex_unlock(&records_lock);
}
