}

// Insert a new LTE PHY layer measurement record into the list
void insert_lte_phy_record(lte_phy_list_t *list, int ci, float rssi, float snr, int cqi) {
    // Check if the list is full
    if (list->num_records == 10) {
        printf("Error: LTE PHY list is full\n");
        return;
    }
    // Insert the new record into the list
    list->records[list->num_records].ci = ci;
    list->records[list->num_records].rssi = rssi;
    list->records[list->num_records].snr = snr;
    list->records[list->num_records].cqi = cqi;
    // Increment the number of records in the list
    list->num_records++;
}

// Delete a LTE PHY layer measurement record from the list
void delete_lte_phy_record(lte_phy_list_t *list, int ci) {
    // Find the index of the record to be deleted
    int i;
    for (i = 0; i < list->num_records; i++) {
        if (list->records[i].ci == ci) {
            break;
        }
    }
    // Check if the record was found
    if (i == list->num_records) {
        printf("Error: LTE PHY record with CI %d not found\n", ci);
        return;
    }
    // Shift all records after the deleted record to fill the gap
    for (int j = i; j < list->num_records - 1; j++) {
        list->records[j] = list->records[j + 1];
    }
    // Decrement the number of records in the list
    list->num_records--;
}

