// Priority-based insertion strategy for records with higher SNR values
void insert_lte_phy_record_priority(lte_phy_list_t *list, int ci, float rssi, float snr, int cqi) {
    // Check if the list is full
    if (list->num_records == 10) {
        return;
    }
    // Find the index of the record to be inserted
    int i;
    for (i = 0; i < list->num_records; i++) {
        if (snr > list->records[i].snr) {
            break;
        }
