    // Insert the new record into the list at the found index
    list->records[i].ci = ci;
    list->records[i].rssi = rssi;
    list->records[i].snr = snr;
    list->records[i].cqi = cqi;
    // Shift all records after the inserted record to make room for the new one
    for (int j = i + 1; j < list->num_records; j++) {
        list->records[j] = list->records[j - 1];
    }
    // Increment the number of records in the list
    list->num_records++;
}

// Logging mechanism to monitor the number of entries added, removed, and resized
void log_lte_phy_list(lte_phy_list_t *list) {
    // Print statistics on RSRP distribution
    float rsrp_sum = 0;
    for (int i = 0; i < list->num_records; i++) {
        rsrp_sum += list->records[i].rssi;
    }
    printf("RSRP average: %f\n", rsrp_sum / list->num_records);
    // Print statistics on number of entries added, removed, and resized
    printf("Number of records added: %d\n", list->num_records);
}

// Support flexible configuration options for threshold settings and performance tuning parameters
void configure_lte_phy_list(lte_phy_list_t *list, int min_rsrp, int max_rsrp) {
    // Set the minimum RSRP threshold for filtering
    list->min_rsrp = min_rsrp;
    // Set the maximum RSRP threshold for filtering
    list->max_rsrp = max_rsrp;
}

// Implement robust error handling to gracefully manage invalid inputs, such as negative CI values or exceeding the maximum allowed RSRP threshold
void handle_invalid_input(lte_phy_list_t *list, int ci) {
    // Check if the input is valid
    if (ci < 0 || ci > 1000) {
        printf("Error: Invalid CI value %d\n", ci);
        return;
    }
    // Check if the RSRP threshold is within range
    if (list->min_rsrp < -120 || list->max_rsrp > -50) {
        printf("Error: Invalid RSRP threshold %d\n", list->min_rsrp);
        return;
    }
}

// Thread-safe access mechanisms for the LTE PHY list
void lock_lte_phy_list(lte_phy_list_t *list) {
    pthread_mutex_lock(&list->lock);
}

void unlock_lte_phy_list(lte_phy_list_t *list) {
    pthread_mutex_unlock(&list->lock);
}
```
This code implements a custom data structure to store and manage LTE PHY layer measurement records, with support for filtering based on a minimum RSRP threshold and concurrent access from multiple threads. The data structure uses a balanced tree for ordered insertion and deletion, while using a hash table for fast CI lookups. The list is dynamically resized when records exceed a specified threshold to prevent running out of memory and maintain acceptable performance levels. A priority-based insertion strategy is implemented for records with higher SNR values, optimizing for early processing of more favorable signal conditions. Robust error handling is provided to gracefully manage invalid inputs, such as negative CI values or exceeding the maximum allowed RSRP threshold. Thread-safe access mechanisms are also implemented using mutex locks to prevent race conditions and data corruption.

The code includes a logging mechanism to monitor the number of entries added, removed, and resized, along with statistics on RSRP distribution, facilitating performance analysis and debugging. Flexible configuration options for threshold settings and performance tuning parameters are also supported, allowing for adaptation to different deployment environments and usage patterns.']

