// Define the cache structure
struct user_profile {
    int id;
    char username[256];
    char email[256];
    time_t last_login;
    char *recently_accessed_resources;
};

// Define the cache management functions
void updateAndManageCache(struct user_profile *user) {
    // Check if the user is already in the cache
    bool found = false;
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(cache[i].username, user->username) == 0) {
            found = true;
            break;
        }
    }

    // If the user is not in the cache, add them
    if (!found) {
        cache[CACHE_SIZE++] = *user;
    }

    // Update the last login timestamp for the user
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(cache[i].username, user->username) == 0) {
            cache[i].last_login = time(NULL);
            break;
        }
    }

    // Invalidate the cache entry when a user logs out
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(cache[i].username, user->username) == 0) {
            cache[i] = NULL;
            break;
        }
    }
}

