int compare_cache_entries(const void *a, const void *b) {
    cache_entry_t *entry1 = (cache_entry_t *) a;
    cache_entry_t *entry2 = (cache_entry_t *) b;

    if (entry1->last_login < entry2->last_login) {
        return -1;
    } else if (entry1->last_login > entry2->last_login) {
        return 1;
    } else {
        return 0;
    }
}

