// Define the list of LTE PHY Layer Measurement Records
PhyLayerMeasurementRecord *phyLayerMeasurements = NULL;

// Define the size of the list
int phyLayerMeasurementsSize = 0;

// Define the minimum RSRP threshold for filtering
float minRSRPThreshold = -120.0f;

// Define the initialization mode (synchronous or asynchronous)
bool isAsyncInit = false;

// Define the external data source for periodic updates
FILE *dataSource = NULL;

// Define the cache for storing previously read data
char *cache = NULL;

// Define the size of the cache
int cacheSize = 0;

// Define the current position in the cache
int cachePos = 0;

// Define the buffer for reading from the external data source
char buffer[1024];

// Define the function to compute the MD5 hash of a string
unsigned char *computeMD5Hash(const char *str) {
    unsigned char *hash = NULL;
    int len = strlen(str);
    if (len > 0) {
        hash = malloc(16);
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, str, len);
        MD5_Final(hash, &ctx);
    }
    return hash;
}

// Define the function to initialize the list of LTE PHY Layer Measurement Records
void initPhyLayerMeasurements() {
    // Initialize the list of LTE PHY Layer Measurement Records
    phyLayerMeasurements = malloc(sizeof(PhyLayerMeasurementRecord) * 1024);
    if (phyLayerMeasurements == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    // Initialize the size of the list
    phyLayerMeasurementsSize = 1024;
    // Set the minimum RSRP threshold for filtering
    minRSRPThreshold = -120.0f;
    // Set the initialization mode (synchronous or asynchronous)
    isAsyncInit = false;
    // Initialize the external data source for periodic updates
    dataSource = fopen("data.txt", "r");
    if (dataSource == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    // Initialize the cache for storing previously read data
    cache = malloc(1024 * 1024);
    if (cache == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    // Set the size of the cache
    cacheSize = 1024 * 1024;
    // Set the current position in the cache
    cachePos = 0;
}

// Define the function to add a new LTE PHY Layer Measurement Record
void addPhyLayerMeasurement(int CI, float RSRP, float SNR, int CQI) {
    // Check if the list is full
    if (phyLayerMeasurementsSize == phyLayerMeasurementsCount) {
        // Increase the size of the list by 1024 elements
        phyLayerMeasurements = realloc(phyLayerMeasurements, sizeof(PhyLayerMeasurementRecord) * (phyLayerMeasurementsSize + 1024));
        if (phyLayerMeasurements == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        // Update the size of the list
        phyLayerMeasurementsSize += 1024;
    }
    // Add the new LTE PHY Layer Measurement Record to the list
    phyLayerMeasurements[phyLayerMeasurementsCount].CI = CI;
    phyLayerMeasurements[phyLayerMeasurementsCount].RSRP = RSRP;
    phyLayerMeasurements[phyLayerMeasurementsCount].SNR = SNR;
    phyLayerMeasurements[phyLayerMeasurementsCount].CQI = CQI;
    // Increment the count of LTE PHY Layer Measurement Records in the list
    phyLayerMeasurementsCount++;
}

// Define the function to filter the list of LTE PHY Layer Measurement Records based on a minimum RSRP threshold
void filterPhyLayerMeasurements(float minRSRPThreshold) {
    // Iterate over the list of LTE PHY Layer Measurement Records
    for (int i = 0; i < phyLayerMeasurementsCount; i++) {
        // Check if the RSRP value is below the minimum threshold
        if (phyLayerMeasurements[i].RSRP < minRSRPThreshold) {
            // Remove the LTE PHY Layer Measurement Record from the list
            phyLayerMeasurementsCount--;
            for (int j = i; j < phyLayerMeasurementsCount; j++) {
                phyLayerMeasurements[j] = phyLayerMeasurements[j + 1];
            }
            i--;
        }
    }
}

// Define the function to update the list of LTE PHY Layer Measurement Records from an external data source
void updatePhyLayerMeasurements() {
    // Check if the cache is full
    if (cachePos == cacheSize) {
        // Increase the size of the cache by 1024 elements
        cache = realloc(cache, sizeof(char) * (cacheSize + 1024));
        if (cache == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        // Update the size of the cache
        cacheSize += 1024;
    }
    // Read from the external data source into the buffer
    int bytesRead = fread(buffer, sizeof(char), 1024, dataSource);
    if (bytesRead == 0) {
        perror("fread");
        exit(EXIT_FAILURE);
    }
    // Update the cache with the read data
    memcpy(cache + cachePos, buffer, bytesRead);
    // Increment the position in the cache
    cachePos += bytesRead;
}

// Define the function to compute the MD5 hash of a provided string parameter
unsigned char *computeMD5Hash(const char *str) {
    unsigned char *hash = NULL;
    int len = strlen(str);
    if (len > 0) {
        hash = malloc(16);
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, str, len);
        MD5_Final(hash, &ctx);
    }
    return hash;
}
