        // Both file and standard output
        printf("Logging initialization process to both file and standard output\n");
    }

    // Initialize the verbosity level of logging
    log_verbosity = 3;

    // Initialize the checksum mechanism for validating data integrity
    if (CHECKSUM_MECHANISM == 0) {
        // MD5 hash
        printf("Using MD5 hash for data integrity validation\n");
    } else if (CHECKSUM_MECHANISM == 1) {
        // SHA-256 hash
        printf("Using SHA-256 hash for data integrity validation\n");
    }

    // Initialize the frequency of data updates in milliseconds
    update_frequency = 1000;

