#include <stdlib.h>
#include <string.h>

typedef struct FrameBufferEntry {
    uint64_t Timestamp;
    size_t PacketLength;
    void* PacketData;
} FrameBufferEntry;

void initializeFrameBuffer(FrameBufferEntry* buffer, size_t bufferSize, size_t alignment) {
    // Allocate memory for the packet data
    buffer->PacketData = malloc(bufferSize);

    // Ensure that the allocated memory is properly aligned
    if (alignment > 0) {
        void* alignedPtr = NULL;
        posix_memalign(&alignedPtr, alignment, bufferSize);
        memcpy(alignedPtr, buffer->PacketData, bufferSize);
        free(buffer->PacketData);
        buffer->PacketData = alignedPtr;
    }

    // Initialize the timestamp and packet length fields
    buffer->Timestamp = 0;
    buffer->PacketLength = bufferSize;
}
