import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class StringHasher {
    public static String hashStrings(String... strings) throws NoSuchAlgorithmException {
        if (strings == null || strings.length == 0) {
            return "";
        }

        List<String> stringList = new ArrayList<>();
        for (String s : strings) {
            if (s != null && !s.isEmpty()) {
                stringList.add(s);
            }
        }

        String concatenatedString = stringList.stream().collect(Collectors.joining());
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(concatenatedString.getBytes());
        return bytesToHex(hashBytes);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            sb.append(String.format("%02x", bytes[i]));
        }
        return sb.toString();
    }
}
```
This implementation uses the `MessageDigest` class from Java's security API to compute the MD5 hash of a concatenated string, and then converts the resulting byte array to a hexadecimal string using the `bytesToHex()` method. The `hashStrings()` method takes a variable number of string parameters and returns the computed hash as a hexadecimal string.

Here is an example usage of the `StringHasher` class:
