public class WeightedAverage {
    public static float computeWeightedAverage(List<Number> numbers, List<Double> weights) {
        if (numbers == null || weights == null || numbers.size() != weights.size()) {
            return 0f;
        }

        double sum = 0d;
        for (int i = 0; i < numbers.size(); i++) {
            sum += numbers.get(i) * weights.get(i);
