void parse_file(char* input_filename, char* output_filename, char* rules, int threshold, bool log) {
    // Open the input file and check for errors
    FILE* input = fopen(input_filename, "rb");
    if (input == NULL) {
        perror("Error opening input file");
        return;
    }

    // Get the size of the input file
    fseek(input, 0, SEEK_END);
    long input_size = ftell(input);
    rewind(input);

    // Check if the input file size exceeds the threshold
    if (input_size > threshold) {
        printf("Input file size exceeds threshold. Reading in chunks...\n");

        // Allocate memory for reading the input file in chunks
        char* buffer = malloc(threshold);
        if (buffer == NULL) {
            perror("Error allocating memory for input file");
            fclose(input);
            return;
        }

        // Read the input file in chunks and parse each chunk
        while (!feof(input)) {
            size_t bytes_read = fread(buffer, 1, threshold, input);
            if (ferror(input)) {
                perror("Error reading from input file");
                free(buffer);
                fclose(input);
                return;
            }

            // Parse the chunk and generate output
            parse_chunk(buffer, bytes_read, rules, log);
        }

        // Release memory for reading the input file in chunks
        free(buffer);
    } else {
        // Allocate memory for reading the entire input file at once
        char* buffer = malloc(input_size);
        if (buffer == NULL) {
            perror("Error allocating memory for input file");
            fclose(input);
            return;
        }

        // Read the entire input file and parse it
        size_t bytes_read = fread(buffer, 1, input_size, input);
        if (ferror(input)) {
            perror("Error reading from input file");
            free(buffer);
            fclose(input);
            return;
        }

        // Parse the entire input file and generate output
        parse_chunk(buffer, bytes_read, rules, log);

        // Release memory for reading the entire input file at once
        free(buffer);
    }

    // Close the input file
    fclose(input);
}

