// Define the maximum number of allowed domains
#define MAX_DOMAINS 10

// Define the cache size for recent DNS lookups
#define CACHE_SIZE 1024

// Define the error codes
#define ERROR_OK 0
#define ERROR_INVALID_HOSTNAME -1
#define ERROR_DNS_FAILED -2
#define ERROR_DOMAIN_NOT_ALLOWED -3
#define ERROR_CACHE_FULL -4

// Define the cache structure
typedef struct {
    char hostname[MAX_HOSTNAME_LEN];
    u_char ip_address[INET6_ADDRSTRLEN];
} dns_cache_entry;

// Define the cache array
dns_cache_entry cache[CACHE_SIZE];

// Define the allowed domains list
char *allowed_domains[MAX_DOMAINS] = { "example.com", "example2.com" };

int dns_resolve(const char *hostname, u_char *ip_address) {
    // Check if the hostname is valid
    if (!hostname || !*hostname) {
        return ERROR_INVALID_HOSTNAME;
    }

    // Check if the domain is allowed
    for (int i = 0; i < MAX_DOMAINS; i++) {
        if (strcmp(hostname, allowed_domains[i]) == 0) {
            break;
        } else if (i == MAX_DOMAINS - 1) {
            return ERROR_DOMAIN_NOT_ALLOWED;
        }
    }

    // Check if the cache is full
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (!strcmp(hostname, cache[i].hostname)) {
            memcpy(ip_address, cache[i].ip_address, INET6_ADDRSTRLEN);
            return ERROR_OK;
        }
    }

    // Perform DNS resolution
    struct addrinfo hints, *res;
    int error;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET6;
    hints.ai_socktype = SOCK_STREAM;

    if ((error = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return ERROR_DNS_FAILED;
    }

    // Get the IP address from the first result
    struct in6_addr *addr = &((struct sockaddr_in6 *) res->ai_addr)->sin6_addr;
    inet_ntop(AF_INET6, addr, ip_address, INET6_ADDRSTRLEN);

    // Add the result to the cache
    strcpy(cache[0].hostname, hostname);
    memcpy(cache[0].ip_address, ip_address, INET6_ADDRSTRLEN);

    return ERROR_OK;
}
```
