// Define the DNS resolution function
int dns_resolve(const char *hostname, struct in_addr *ip_address) {
    // Check if the hostname is allowed
    if (!is_allowed_domain(hostname)) {
        return -1;
    }

    // Check if the hostname is already cached
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (dns_cache[i] != NULL && strcmp(dns_cache[i]->hostname, hostname) == 0) {
            *ip_address = dns_cache[i]->ip_address;
            return 0;
        }
    }

    // Perform DNS resolution using the standard library functions
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return -1;
    }

    // Check if the DNS resolution result is valid
    if (res == NULL || res->ai_family != AF_INET || res->ai_addrlen != sizeof(struct sockaddr_in)) {
        freeaddrinfo(res);
        return -1;
    }

    // Extract the IP address from the DNS resolution result
    struct sockaddr_in *addr = (struct sockaddr_in *) res->ai_addr;
    inet_pton(AF_INET, hostname, &addr->sin_addr);

    // Add the DNS cache entry
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (dns_cache[i] == NULL) {
            dns_cache[i] = malloc(sizeof(struct dns_cache_entry));
            dns_cache[i]->hostname = strdup(hostname);
            dns_cache[i]->ip_address = addr->sin_addr;
            break;
        }
    }

    // Free the DNS resolution result
    freeaddrinfo(res);

    *ip_address = addr->sin_addr;
    return 0;
}

// Define the mechanism for limiting the capabilities of the process
static int is_allowed_domain(const char *hostname) {
    // Check if the hostname is in the list of allowed domains
    for (int i = 0; i < MAX_DOMAINS; i++) {
        if (strcmp(hostname, allowed_domains[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

// Define the list of allowed domains
static const char *allowed_domains[] = {"example.com", "example2.com"};
