typedef struct {
    int fd;
    int priority;
} fd_allocation_request_t;

// Define functions for file descriptor allocation and release
int allocate_fd(fd_allocation_request_t *request) {
    // Check if there are any available file descriptors in the cache
    if (request->priority == FD_PRIORITY_PERSISTENT && fd_cache.size > 0) {
        // Return the oldest cached file descriptor with highest priority
        int fd = fd_cache[0].fd;
        fd_cache.erase(fd);
        return fd;
    } else if (request->priority == FD_PRIORITY_TRANSIENT && fd_cache.size > MIN_FD_RESERVED) {
        // Return the oldest cached file descriptor with lowest priority
        int fd = fd_cache[fd_cache.size - 1].fd;
        fd_cache.erase(fd);
        return fd;
    } else if (request->priority == FD_PRIORITY_PERSISTENT && fd_cache.size < MAX_FD_ALLOCATIONS) {
        // Allocate a new file descriptor from the system
        int fd = open("/dev/null", O_RDWR);
        if (fd == -1) {
            return -errno;
        }
        return fd;
    } else {
        // Return an error code if there are no available file descriptors
        return -ENOMEM;
    }
}

void release_fd(int fd) {
    // Add the file descriptor to the cache
    fd_cache.push_back({fd, time(NULL)});
}

