void update_priority(int fd, int priority) {
    // Update the priority of the file descriptor in the cache
    for (auto it = fd_cache.begin(); it != fd_cache.end(); ++it) {
        if (it->fd == fd) {
            it->priority = priority;
            break;
        }
    }
}

int get_priority(int fd) {
    // Return the priority of the file descriptor in the cache
    for (auto it = fd_cache.begin(); it != fd_cache.end(); ++it) {
        if (it->fd == fd) {
            return it->priority;
        }
    }
    // Return an error code if the file descriptor is not in the cache
    return -ENOENT;
}

