// Structure to store TCP/IP Performance Metrics
struct tcpip_metrics {
    int version;
    time_t timestamp;
    double throughput;
};

// Function to append version number, timestamp, and CI-based identification to the log filename
void append_log_filename(char* log_filename, char* log_directory_path, int throughput_threshold) {
    // Get current directory contents
    struct dirent** files;
    int num_files = scandir(log_directory_path, &files, NULL, alphasort);
    if (num_files < 0) {
        perror("scandir");
        return;
    }

    // Initialize version number and timestamp
    int version = 1;
    time_t timestamp = time(NULL);

    // Check for existing logs in the directory
    if (num_files > 0) {
        // Iterate through files and find the latest log file
        struct dirent* file;
        for (int i = 0; i < num_files; i++) {
            file = files[i];
            if (strcmp(file->d_name, log_filename) == 0) {
                // Found the latest log file, get its version number and timestamp
                char* version_str = strtok(file->d_name, "_");
                version = atoi(version_str);
                char* timestamp_str = strtok(NULL, "_");
                timestamp = atol(timestamp_str);
                break;
            }
        }
    }

    // Increment version number if necessary
    if (throughput_threshold > 0) {
        struct tcpip_metrics metrics;
        metrics.version = version;
        metrics.timestamp = timestamp;
        metrics.throughput = throughput_threshold;
        int new_version = version + 1;
        if (new_version > version) {
            version = new_version;
        }
    }

    // Append version number, timestamp, and CI-based identification to the log filename
    char* version_str = malloc(sizeof(int));
    sprintf(version_str, "%d", version);
    char* timestamp_str = malloc(sizeof(time_t));
    sprintf(timestamp_str, "%ld", timestamp);
    char* ci_id_str = getenv("CI_ID");
    if (ci_id_str == NULL) {
        ci_id_str = "0";
    }
    char* new_log_filename = malloc(sizeof(char) * 128);
    sprintf(new_log_filename, "%s_%s_%s.log", log_filename, version_str, timestamp_str);
    strcat(new_log_filename, ci_id_str);

    // Free memory allocated for version and timestamp strings
    free(version_str);
    free(timestamp_str);

    return new_log_filename;
}

// Function to initialize and configure a list of TCP/IP Performance Metrics
void init_tcpip_metrics(char* log_directory_path, int throughput_threshold) {
    // Get current directory contents
    struct dirent** files;
    int num_files = scandir(log_directory_path, &files, NULL, alphasort);
    if (num_files < 0) {
        perror("scandir");
        return;
    }

    // Initialize list of TCP/IP Performance Metrics
    struct tcpip_metrics* metrics = malloc(sizeof(struct tcpip_metrics) * num_files);
    for (int i = 0; i < num_files; i++) {
        file = files[i];
        if (strcmp(file->d_name, log_filename) == 0) {
            // Found the latest log file, get its version number and timestamp
            char* version_str = strtok(file->d_name, "_");
            metrics[i].version = atoi(version_str);
            char* timestamp_str = strtok(NULL, "_");
            metrics[i].timestamp = atol(timestamp_str);
        }
    }

    // Filter TCP/IP Performance Metrics based on throughput threshold
    int num_metrics = 0;
    for (int i = 0; i < num_files; i++) {
        if (metrics[i].throughput > throughput_threshold) {
            num_metrics++;
        }
    }

    // Resize list of TCP/IP Performance Metrics if necessary
    struct tcpip_metrics* new_metrics = realloc(metrics, sizeof(struct tcpip_metrics) * num_metrics);
    if (new_metrics == NULL) {
        perror("realloc");
        return;
    }
    metrics = new_metrics;

    // Initialize and configure list of TCP/IP Performance Metrics
    for (int i = 0; i < num_metrics; i++) {
        metrics[i].version = version;
        metrics[i].timestamp = timestamp;
        metrics[i].throughput = throughput_threshold;
    }
}
