void transfer_file_chunk_with_priority(transfer_request_t* request, file_chunk_t** chunk) {
    // Check if the network is congested
    if (is_network_congested()) {
        // Use UDP for transfers with high priority
        request->protocol = 1;
    } else {
        // Use TCP for transfers with low priority
        request->protocol = 0;
    }
}

// Define a function to dynamically adjust its behavior based on the current network conditions, such as switching to UDP-only mode if TCP connections are consistently unstable
void transfer_file_chunk_with_adaptive_behavior(transfer_request_t* request, file_chunk_t** chunk) {
    // Check if the network is congested
    if (is_network_congested()) {
        // Switch to UDP-only mode if TCP connections are consistently unstable
        request->protocol = 1;
    } else {
        // Use TCP for transfers with low priority
        request->protocol = 0;
    }
}
