struct Cache {
    int *keys;
    void **values;
    size_t capacity;
    size_t size;
    size_t num_hits;
    size_t num_misses;
    size_t num_evictions;
};

struct Cache* createCache(int *keys, size_t num_entries, void (*callback)(void*)) {
    struct Cache *cache = malloc(sizeof(struct Cache));
    if (!cache) return NULL;

    cache->keys = malloc(num_entries * sizeof(int));
    cache->values = malloc(num_entries * sizeof(void*));
    cache->capacity = num_entries;
    cache->size = 0;
    cache->num_hits = 0;
    cache->num_misses = 0;
    cache->num_evictions = 0;

    if (!cache->keys || !cache->values) {
        free(cache);
        return NULL;
    }

    for (size_t i = 0; i < num_entries; i++) {
        cache->keys[i] = keys[i];
        cache->values[i] = NULL;
    }

    return cache;
}

void destroyCache(struct Cache *cache) {
    free(cache->keys);
    free(cache->values);
    free(cache);
}

int getCacheSize(struct Cache *cache) {
    return cache->size;
}

int getNumEntries(struct Cache *cache) {
    return cache->capacity;
}

void* getValue(struct Cache *cache, int key) {
    for (size_t i = 0; i < cache->capacity; i++) {
        if (cache->keys[i] == key) {
            return cache->values[i];
        }
    }
    return NULL;
}

void setValue(struct Cache *cache, int key, void* value) {
    for (size_t i = 0; i < cache->capacity; i++) {
        if (cache->keys[i] == key) {
            cache->values[i] = value;
            return;
        }
    }
    // Eviction policy: LRU
    int evicted_key = cache->keys[0];
    void* evicted_value = cache->values[0];
    for (size_t i = 1; i < cache->capacity; i++) {
        if (cache->keys[i] == key) {
            return;
        } else if (cache->keys[i] > evicted_key) {
            evicted_key = cache->keys[i];
            evicted_value = cache->values[i];
        }
    }
    // Log eviction for audit purposes
    printf("Evicted key: %d, value: %p\n", evicted_key, evicted_value);
    cache->num_evictions++;
}

void updateMetrics(struct Cache *cache) {
    cache->num_hits += getCacheSize(cache);
    cache->num_misses += (getNumEntries(cache) - getCacheSize(cache));
}
