void manage_book_counts(char* name, int count) {
    // Initialize the book count structure
    book_count_t* book_count = (book_count_t*)malloc(sizeof(book_count_t));
    if (!book_count) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for book count\n");
        return;
    }

    // Set the name and count in the book count structure
    book_count->name = name;
    book_count->count = count;

    // Free the memory allocated for the book count structure when it is no longer needed
    free(book_count);
}

// Define a function for parsing text data and identifying mentions of books in the Bible
void parse_text_data(char* text) {
    // Initialize the regular expressions for matching Old Testament books, New Testament books, and all books in the Bible
    regex_t old_testament_books_regex;
    regex_t new_testament_books_regex;
    regex_t bible_books_regex;

    // Compile the regular expressions for matching Old Testament books, New Testament books, and all books in the Bible
    regcomp(&old_testament_books_regex, old_testament_books[0], REG_EXTENDED);
    regcomp(&new_testament_books_regex, new_testament_books[0], REG_EXTENDED);
    regcomp(&bible_books_regex, bible_books[0], REG_EXTENDED);

    // Loop through each character in the text data and check for matches with the regular expressions
    for (int i = 0; i < strlen(text); i++) {
        char c = text[i];
        if (c == ' ') continue;
        else if (regexec(&old_testament_books_regex, &c, 1, NULL, 0) == 0) {
            // Increment the count for the Old Testament book that was matched
            manage_book_counts(old_testament_books[i], 1);
        } else if (regexec(&new_testament_books_regex, &c, 1, NULL, 0) == 0) {
            // Increment the count for the New Testament book that was matched
            manage_book_counts(new_testament_books[i], 1);
        } else if (regexec(&bible_books_regex, &c, 1, NULL, 0) == 0) {
            // Increment the count for the book in the Bible that was matched
            manage_book_counts(bible_books[i], 1);
        }
    }

    // Free the memory allocated for the regular expressions when they are no longer needed
    regfree(&old_testament_books_regex);
    regfree(&new_testament_books_regex);
    regfree(&bible_books_regex);
