// Define a function for managing DNS resolution for a given hostname
void manage_dns_resolution(char* hostname) {
    // Initialize the DNS resolution result structure
    dns_result_t* dns_result = (dns_result_t*)malloc(sizeof(dns_result_t));
    if (!dns_result) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for DNS resolution result\n");
        return;
    }

    // Set the hostname in the DNS resolution result structure
    dns_result->hostname = hostname;

    // Perform DNS resolution for the given hostname using getaddrinfo()
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        // Handle DNS resolution failure
        printf("Error: Failed to resolve hostname %s\n", hostname);
        return;
    }

    // Loop through each result in the DNS resolution results and extract the IPv4 and IPv6 addresses
    for (struct addrinfo* r = res; r != NULL; r = r->ai_next) {
        if (r->ai_family == AF_INET) {
            dns_result->ipv4_addr = ((struct sockaddr_in*)r->ai_addr)->sin_addr.s_addr;
        } else if (r->ai_family == AF_INET6) {
            dns_result->ipv6_addr = ((struct sockaddr_in6*)r->ai_addr)->sin6_addr.s6_addr;
        }
    }

    // Free the memory allocated for the DNS resolution results when they are no longer needed
    freeaddrinfo(res);
}

