#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

void* load_shared_library(const char* library_path) {
    void* handle = dlopen(library_path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to load shared library: %s\n", dlerror());
        return NULL;
    }
    return handle;
}

void* get_function_address(void* handle, const char* function_name) {
    void* address = dlsym(handle, function_name);
    if (!address) {
        fprintf(stderr, "Failed to find function %s in shared library\n", function_name);
        return NULL;
    }
    return address;
}

void unload_shared_library(void* handle) {
    dlclose(handle);
}

int execute_function(const char* library_path, const char* function_name, int argc, char** argv) {
    void* handle = load_shared_library(library_path);
    if (!handle) {
        return 1;
    }
    void (*function)(int, char**) = get_function_address(handle, function_name);
    if (!function) {
        unload_shared_library(handle);
        return 1;
    }
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    int result = (*function)(argc, argv);
    clock_gettime(CLOCK_MONOTONIC, &end);
    long elapsed = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
    printf("Execution time: %ld ms\n", elapsed);
    unload_shared_library(handle);
    return result;
}
