        for (int i = 0; i < 10; i++) {
            if (measurement_reports[i] > threshold_rsrp || measurement_reports[i] < -140.0) {
                log("Anomaly detected in cell %d, UE %d, measurement report %d: %f", cell_id, ue_id, i + 1, measurement_reports[i]);
