char* generate_random_filename(const char* filename, const char* filetype) {
    // Get the length of the original filename
    int len = strlen(filename);

    // Generate a random sequence of digits
    srand(time(NULL));
    char* rand_seq = malloc(10 * sizeof(char));
    for (int i = 0; i < 10; i++) {
        rand_seq[i] = '0' + (rand() % 10);
    }

    // Construct the new filename
    char* new_filename = malloc((len + strlen(filetype) + 10) * sizeof(char));
    sprintf(new_filename, "%s%s%s", filename, rand_seq, filetype);

    // Check for uniqueness of the new filename
    while (access(new_filename, F_OK)) {
        char* temp = malloc((len + strlen(filetype) + 10) * sizeof(char));
        sprintf(temp, "%s%s%s", filename, rand_seq, filetype);
        free(new_filename);
        new_filename = temp;
    }

    // Free the random sequence and return the new filename
    free(rand_seq);
    return new_filename;
}

// Define a function to initialize a dynamic array of MAC_PDU structures
void init_mac_pdu_array(struct MAC_PDU** mac_pdu_array, int num_elements) {
