    // Initialize each element of the array with a valid MAC_HEADER, MACSDU, and IE_LIST
    for (int i = 0; i < num_elements; i++) {
        (*mac_pdu_array)[i].header.valid = 1;
        (*mac_pdu_array)[i].macsdu.size = rand() % 100 + 1;
        (*mac_pdu_array)[i].ie_list.num_ies = rand() % 5 + 1;
        for (int j = 0; j < (*mac_pdu_array)[i].ie_list.num_ies; j++) {
            (*mac_pdu_array)[i].ie_list.ies[j].ie_id = rand() % 256;
            (*mac_pdu_array)[i].ie_list.ies[j].ie_length = rand() % 100 + 1;
        }
    }
}

// Define a function to validate the integrity of a MACSDU
void validate_macsdu(struct MAC_PDU* mac_pdu) {
    // Check that the MACSDU size is within bounds
    if (mac_pdu->macsdu.size > 1000) {
        printf("MACSDU size exceeds maximum allowed value\n");
        return;
    }

    // Check that each IE has a unique ID and length
    for (int i = 0; i < mac_pdu->ie_list.num_ies; i++) {
        for (int j = i + 1; j < mac_pdu->ie_list.num_ies; j++) {
            if ((*mac_pdu)[i].ie_list.ies[j].ie_id == (*mac_pdu)[i].ie_list.ies[j].ie_id) {
                printf("Duplicate IE ID found in MAC_PDU\n");
                return;
            }
        }
    }
}
