// Function to read integers from a file and calculate the average
int read_integers(char* filename, int** integers, int* num_integers) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return -1;
    }

    // Initialize variables
    int largest_integer = INT_MIN;
    int sum = 0;
    *num_integers = 0;

    // Read the integers from the file and calculate the average
    while (fscanf(fp, "%d", &(*integers)[*num_integers]) == 1) {
        if ((*integers)[*num_integers] > largest_integer) {
            largest_integer = (*integers)[*num_integers];
        }
        sum += (*integers)[*num_integers];
        *num_integers += 1;
    }

    // Close the file
    fclose(fp);

    // Calculate the average and return the largest integer
    int average = sum / *num_integers;
    return largest_integer;
}

// Function to read integers from multiple files and calculate the average
int read_multiple_integers(char** filenames, int num_filenames, int** integers, int* num_integers) {
    // Initialize variables
    int largest_integer = INT_MIN;
    int sum = 0;
    *num_integers = 0;

    // Read the integers from each file and calculate the average
    for (int i = 0; i < num_filenames; i++) {
        int* current_integers = NULL;
        int current_num_integers = 0;
        read_integers(filenames[i], &current_integers, &current_num_integers);
        if (current_num_integers > 0) {
            // Reallocate memory for the integers array if necessary
            if (*num_integers + current_num_integers > *num_integers) {
                int* new_integers = realloc(*integers, (*num_integers + current_num_integers) * sizeof(int));
                if (new_integers == NULL) {
                    printf("Error: unable to allocate memory for integers\n");
                    return -1;
                }
                *integers = new_integers;
            }

            // Copy the current integers into the array
            memcpy(&(*integers)[*num_integers], current_integers, current_num_integers * sizeof(int));
            *num_integers += current_num_integers;
        }
    }

    // Calculate the average and return the largest integer
    int average = sum / *num_integers;
    return largest_integer;
}
