    // Concatenate the new filename with the original extension
    char* final_filename = malloc(sizeof(char) * (new_len + orig_len));
    strcpy(final_filename, new_filename);
    if (orig_len > 0) {
        strcat(final_filename, orig_filename);
    } else {
        strcat(final_filename, filetype);
    }

    // Free memory and return the final filename
    free(rand_str);
    return final_filename;
}
