// Define the function to perform DNS resolution for a given hostname
void dns_resolve(char* hostname, int family) {
    // Check if the hostname is valid
    if (!hostname || !*hostname) {
        printf("Error: The requested hostname is invalid\n");
        return;
    }

    // Initialize the DNS query parameters
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = family;
    hints.ai_socktype = SOCK_DGRAM;

    // Perform the DNS resolution
    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        printf("Error: Failed to perform DNS resolution for %s\n", hostname);
        return;
    }

    // Print the results
    struct addrinfo* temp = res;
    while (temp) {
        char ip[INET6_ADDRSTRLEN];
        void* addr;
        if (family == AF_INET) {
            struct sockaddr_in* sin = (struct sockaddr_in*)temp->ai_addr;
            addr = &sin->sin_addr;
        } else {
            struct sockaddr_in6* sin6 = (struct sockaddr_in6*)temp->ai_addr;
            addr = &sin6->sin6_addr;
        }
        inet_ntop(family, addr, ip, sizeof(ip));
        printf("DNS resolution for %s: %s\n", hostname, ip);
        temp = temp->ai_next;
    }

    // Free the results
    freeaddrinfo(res);
}

