#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>

// Define the maximum number of records to store in the list
#define MAX_RECORDS 1000

// Define the threshold for filtering records based on RSRP
#define RSRP_THRESHOLD 30

// Define the directory path where files are stored
#define DIRECTORY_PATH "/path/to/directory"

// Define the filename pattern for matching files
#define FILENAME_PATTERN "file_%d.txt"

// Define the timestamp format for logging purposes
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

// Define the logging service URL
#define LOGGING_SERVICE_URL "http://logging-service:8080/log"

// Define the logging service timeout in seconds
#define LOGGING_SERVICE_TIMEOUT 5

// Define the maximum number of retries for logging operations
#define MAX_LOGGING_RETRIES 3

// Define the delay between logging retries
#define RETRY_DELAY 10

// Define the flag to indicate whether the function is running in synchronous or asynchronous mode
int syncMode = 0;

// Define the list of LTE PHY Layer Measurement Records
struct Record {
    int version;
    char *filename;
    double rsrp;
};

// Define the list of records to store in memory
struct Record records[MAX_RECORDS];

// Define the number of records currently stored in memory
int numRecords = 0;

// Define the function to rename a file and update the record list
void renameFile(char *filename, char *newFilename) {
    // Check if the new filename is valid
    if (newFilename == NULL || strlen(newFilename) == 0) {
        return;
    }

    // Check if the file exists and is not a directory
    struct stat buf;
    if (stat(filename, &buf) != 0 || S_ISDIR(buf.st_mode)) {
        return;
    }

    // Rename the file
    if (rename(filename, newFilename) != 0) {
        perror("Error renaming file");
        return;
    }

    // Update the record list
    for (int i = 0; i < numRecords; i++) {
        if (strcmp(records[i].filename, filename) == 0) {
            records[i].filename = newFilename;
            break;
        }
    }
}

// Define the function to filter records based on RSRP threshold
void filterRecordsByRsrp() {
    // Create a temporary list of filtered records
    struct Record filteredRecords[MAX_RECORDS];
    int numFilteredRecords = 0;

    // Iterate over the record list and filter based on RSRP threshold
    for (int i = 0; i < numRecords; i++) {
        if (records[i].rsrp >= RSRP_THRESHOLD) {
            filteredRecords[numFilteredRecords++] = records[i];
        }
    }

    // Update the record list with the filtered records
    numRecords = numFilteredRecords;
    for (int i = 0; i < numFilteredRecords; i++) {
        records[i] = filteredRecords[i];
    }
}

// Define the function to manage memory allocation for the record list
void manageMemoryAllocation() {
    // Check if the number of records exceeds the maximum threshold
    if (numRecords >= MAX_RECORDS) {
        // Resize the record list dynamically
        struct Record *newRecords = realloc(records, sizeof(struct Record) * 2 * numRecords);
        if (newRecords == NULL) {
            perror("Error resizing record list");
            return;
        }
        records = newRecords;
    }
}

// Define the function to handle network failures during logging operations
void handleNetworkFailures() {
    // Check if the logging service is available
    if (access(LOGGING_SERVICE_URL, F_OK) != 0) {
        return;
    }

    // Retry logging operations until the service becomes available again
    for (int i = 0; i < MAX_LOGGING_RETRIES; i++) {
        if (sendLog(records, numRecords)) {
            break;
        }
        sleep(RETRY_DELAY);
    }
}

// Define the function to send logs to the logging service
int sendLog(struct Record *records, int numRecords) {
    // Create a JSON object for the log message
    cJSON *json = cJSON_CreateObject();
    if (json == NULL) {
        perror("Error creating JSON object");
        return 0;
    }

    // Add metadata to the JSON object
    cJSON_AddStringToObject(json, "user", getenv("USER"));
    cJSON_AddStringToObject(json, "originalFilename", records[0].filename);
    cJSON_AddStringToObject(json, "newFilename", records[numRecords - 1].filename);
    cJSON_AddNumberToObject(json, "timestamp", time(NULL));

    // Convert the JSON object to a string
    char *jsonStr = cJSON_Print(json);
    if (jsonStr == NULL) {
        perror("Error converting JSON object to string");
        return 0;
    }

    // Send the log message to the logging service
    int ret = sendPostRequest(LOGGING_SERVICE_URL, jsonStr);
    free(jsonStr);
    cJSON_Delete(json);
    return ret;
}

// Define the function to send a POST request to the logging service
int sendPostRequest(char *url, char *data) {
    // Create a new HTTP client instance
    struct httplib_client_t *client = httplib_new();
    if (client == NULL) {
        perror("Error creating HTTP client");
        return 0;
    }

    // Set the URL and data for the POST request
    httplib_set_url(client, url);
    httplib_set_data(client, data);

    // Send the POST request to the logging service
    int ret = httplib_post(client);
    if (ret != 0) {
        perror("Error sending POST request");
    }

    // Free the HTTP client instance
    httplib_free(client);
    return ret;
}

// Define the main function for the program
int main() {
    // Initialize the record list and set the synchronous mode flag
    numRecords = 0;
    syncMode = 1;

    // Loop indefinitely to handle file renaming operations
    while (1) {
        // Check if a file needs to be renamed
        char *filename = NULL;
        if (syncMode) {
            filename = getNextFileToRename();
        } else {
            filename = getNextFileToRenameAsync();
        }

        // Rename the file and update the record list
        if (filename != NULL) {
            char newFilename[256];
            sprintf(newFilename, FILENAME_PATTERN, numRecords);
            renameFile(filename, newFilename);
            manageMemoryAllocation();
            filterRecordsByRsrp();
        }

        // Handle network failures during logging operations
        handleNetworkFailures();
    }
}

// Define the function to get the next file to be renamed synchronously
char *getNextFileToRename() {
    // Check if there are any files in the directory
    struct dirent **files;
    int numFiles = scandir(DIRECTORY_PATH, &files, NULL, alphasort);
    if (numFiles == 0) {
        return NULL;
    }

    // Iterate over the files and find the next file to be renamed
    for (int i = 0; i < numFiles; i++) {
        char *filename = files[i]->d_name;
        if (strcmp(filename, ".") != 0 && strcmp(filename, "..") != 0) {
            return filename;
        }
    }

    // No more files to be renamed
    return NULL;
}

// Define the function to get the next file to be renamed asynchronously
char *getNextFileToRenameAsync() {
    // Check if there are any files in the directory
    struct dirent **files;
    int numFiles = scandir(DIRECTORY_PATH, &files, NULL, alphasort);
    if (numFiles == 0) {
        return NULL;
    }

    // Iterate over the files and find the next file to be renamed
    for (int i = 0; i < numFiles; i++) {
        char *filename = files[i]->d_name;
        if (strcmp(filename, ".") != 0 && strcmp(filename, "..") != 0) {
            return filename;
        }
    }

    // No more files to be renamed
    return NULL;
}
