    int rand_digits = rand() % 10;
    char* rand_str = (char*)malloc(rand_digits + 1);
    for (int i = 0; i < rand_digits; i++) {
        rand_str[i] = '0' + (rand() % 10);
    }
    rand_str[rand_digits] = '\0';

    // Derive the file type from the original filename's extension if present, otherwise default to ".txt"
    char* filetype = orig_extension ? orig_extension : FILETYPE;

    // Construct the new filename by appending the random digits and file type
    int new_filename_len = strlen(orig_filename) + rand_digits + strlen(filetype);
    char* new_filename = (char*)malloc(new_filename_len + 1);
    sprintf(new_filename, "%s%s%s", orig_filename, rand_str, filetype);

    // Ensure the resulting filename is unique by appending a random number until no conflict is found
    int new_filename_index = 0;
    while (1) {
        if (!access(new_filename, F_OK)) {
            break;
        } else {
            sprintf(new_filename + new_filename_index, "%d", rand() % 10);
            new_filename_index++;
        }
    }

    // Free the memory allocated for the random string and return the new filename
    free(rand_str);
    return new_filename;
}
