public class MAC_PDU {
    private MAC_HEADER header;
    private MACSDU macsdu;
    private List<IE_LIST> ieList;

    public MAC_PDU(MAC_HEADER header, MACSDU macsdu, List<IE_LIST> ieList) {
        this.header = header;
        this.macsdu = macsdu;
        this.ieList = ieList;
    }

    public static String processMACPDUsAndComputeHash(String... jsonLogs) throws Exception {
        // Initialize a dynamic array of MAC_PDU structures
        List<MAC_PDU> macPdus = new ArrayList<>();

        // Iterate over the JSON logs and parse them into MAC_PDU structures
        for (String jsonLog : jsonLogs) {
            JSONObject jsonObj = new JSONObject(jsonLog);
            MAC_HEADER header = new MAC_HEADER(jsonObj.getString("header"));
            MACSDU macsdu = new MACSDU(jsonObj.getString("macsdu"));
            List<IE_LIST> ieList = new ArrayList<>();

            // Parse the IEs in the JSON log and add them to the IE list
            JSONArray ieArray = jsonObj.getJSONArray("ieList");
            for (int i = 0; i < ieArray.length(); i++) {
                JSONObject ieObj = ieArray.getJSONObject(i);
                int ieId = ieObj.getInt("id");
                int ieLength = ieObj.getInt("length");
                IE_LIST ieListEntry = new IE_LIST(ieId, ieLength);
                ieList.add(ieListEntry);
            }

            // Add the parsed MAC_PDU structure to the list of MAC_PDUs
            macPdus.add(new MAC_PDU(header, macsdu, ieList));
        }

        // Initialize a dynamic array of integers for storing the hash values
        List<Integer> hashValues = new ArrayList<>();

        // Iterate over the MAC_PDUs and compute the hash value for each one
        for (MAC_PDU macPdu : macPdus) {
            String hashValue = computeHash(macPdu);
            hashValues.add(Integer.parseInt(hashValue));
        }

        // Return the concatenated MD5 hash of all the hash values
        return concatHashes(hashValues);
    }

    private static String computeHash(MAC_PDU macPdu) throws Exception {
        // Initialize a dynamic array for storing the MAC_HEADER and MACSDU bytes
        List<Byte> macBytes = new ArrayList<>();

        // Add the MAC_HEADER bytes to the array
        byte[] headerBytes = macPdu.header.getBytes();
        for (byte b : headerBytes) {
            macBytes.add(b);
        }

        // Add the MACSDU bytes to the array
        byte[] macsduBytes = macPdu.macsdu.getBytes();
        for (byte b : macsduBytes) {
            macBytes.add(b);
        }

        // Initialize a dynamic array for storing the IE_LIST bytes
        List<Byte> ieListBytes = new ArrayList<>();

        // Iterate over the IEs in the MAC_PDU and add their bytes to the array
        for (IE_LIST ieListEntry : macPdu.ieList) {
            byte[] ieBytes = ieListEntry.getBytes();
            for (byte b : ieBytes) {
                ieListBytes.add(b);
            }
        }

        // Concatenate the MAC_HEADER, MACSDU, and IE_LIST bytes into a single array
        byte[] concatenatedBytes = new byte[macBytes.size() + ieListBytes.size()];
        int i = 0;
        for (Byte b : macBytes) {
            concatenatedBytes[i++] = b;
        }
        for (Byte b : ieListBytes) {
            concatenatedBytes[i++] = b;
        }

        // Compute the MD5 hash of the concatenated bytes and return it as a string
        Mac mac = Mac.getInstance("MD5");
        SecretKeySpec secretKeySpec = new SecretKeySpec(concatenatedBytes, "MD5");
        mac.init(secretKeySpec);
        byte[] hashBytes = mac.doFinal();
        return bytesToHexString(hashBytes);
    }

    private static String concatHashes(List<Integer> hashValues) {
        // Initialize a dynamic array for storing the concatenated hash values
        List<Byte> concatenatedHashes = new ArrayList<>();

        // Iterate over the hash values and add them to the array
        for (int i = 0; i < hashValues.size(); i++) {
            int hashValue = hashValues.get(i);
            byte[] hashBytes = intToByteArray(hashValue);
            for (byte b : hashBytes) {
                concatenatedHashes.add(b);
            }
        }

        // Concatenate the hash values into a single array
        byte[] concatenatedBytes = new byte[concatenatedHashes.size()];
        int i = 0;
        for (Byte b : concatenatedHashes) {
            concatenatedBytes[i++] = b;
        }

        // Compute the MD5 hash of the concatenated bytes and return it as a string
        Mac mac = Mac.getInstance("MD5");
        SecretKeySpec secretKeySpec = new SecretKeySpec(concatenatedBytes, "MD5");
        mac.init(secretKeySpec);
        byte[] hashBytes = mac.doFinal();
        return bytesToHexString(hashBytes);
    }

    private static String bytesToHexString(byte[] bytes) {
        // Initialize a dynamic array for storing the hexadecimal string
        List<Byte> hexBytes = new ArrayList<>();

        // Iterate over the bytes and convert them to their corresponding hexadecimal values
        for (byte b : bytes) {
            String hexValue = Integer.toHexString(b);
            if (hexValue.length() == 1) {
                hexBytes.add((byte) '0');
            }
            hexBytes.add((byte) hexValue.charAt(0));
        }

        // Concatenate the hexadecimal values into a single string
        byte[] concatenatedHexBytes = new byte[hexBytes.size()];
        int i = 0;
        for (Byte b : hexBytes) {
            concatenatedHexBytes[i++] = b;
        }

        // Return the hexadecimal string
        return new String(concatenatedHexBytes);
    }

    private static byte[] intToByteArray(int value) {
        // Initialize a dynamic array for storing the bytes of the integer
        List<Byte> byteList = new ArrayList<>();

        // Iterate over the bytes of the integer and add them to the array
        while (value > 0) {
            byte b = (byte) (value & 0xFF);
            byteList.add(b);
            value >>= 8;
        }

        // Return the reversed byte array
        int length = byteList.size();
        byte[] bytes = new byte[length];
        for (int i = 0; i < length; i++) {
            bytes[i] = byteList.get(length - i - 1);
        }
        return bytes;
    }
}
