import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

public class NetworkLogProcessor {
    private static final int MAX_MEMORY_SIZE = 2 * 1024 * 1024; // 2 GB
    private static final Pattern JSON_PATTERN = Pattern.compile("^\\s*\\{.*\\}\\s*$");

    public static String processNetworkLogsAndComputeHash(List<String> logs) {
        if (logs == null || logs.isEmpty()) {
            return "";
        }

        // Initialize a dynamic array of NetworkLog structures
        List<NetworkLog> networkLogs = new ArrayList<>();

        // Parse and validate each log entry
        for (String log : logs) {
            if (!JSON_PATTERN.matcher(log).matches()) {
                continue;
            }

            NetworkLog networkLog = parseNetworkLog(log);
            if (networkLog != null) {
                networkLogs.add(networkLog);
            }
        }

        // Compute the concatenated SHA-256 hash of the log entries
        String hash = computeHash(networkLogs);

        return hash;
    }

    private static NetworkLog parseNetworkLog(String log) {
        try {
            JSONObject jsonObject = new JSONObject(log);
            NetworkLog networkLog = new NetworkLog();
            networkLog.setHeader(jsonObject.getString("header"));
            networkLog.setPayload(jsonObject.getJSONObject("payload"));
            networkLog.setCustomAttributes(jsonObject.getJSONArray("customAttributes"));
            return networkLog;
        } catch (JSONException e) {
            // Handle parsing errors gracefully
            return null;
        }
    }

    private static String computeHash(List<NetworkLog> networkLogs) {
        try {
            JSONArray jsonArray = new JSONArray();
            for (NetworkLog networkLog : networkLogs) {
                jsonArray.put(networkLog.toJSONObject());
            }
            return SHA256.hash(jsonArray.toString()).toString();
        } catch (NoSuchAlgorithmException e) {
            // Handle hashing errors gracefully
            return "";
        }
    }
}
