// Define constants for maximum buffer size and alignment requirements
#define MAX_BUFFER_SIZE 1024 * 1024 // 1 MB
#define ALIGNMENT 64

// Define a structure to represent a frame buffer entry
typedef struct FrameBufferEntry {
    uint64_t timestamp;
    size_t packetLength;
    void* packetData;
} FrameBufferEntry;

// Define a function to initialize the frame buffers
int initialize_frame_buffers(size_t numEntries, size_t entrySize, bool padToAlignment) {
    // Check if the input parameters are valid
    if (numEntries == 0 || entrySize == 0 || entrySize > MAX_PACKET_LENGTH) {
        return -1;
    }

    // Calculate the total buffer size based on the number of entries and entry size
    size_t totalBufferSize = numEntries * entrySize;

    // Check if the total buffer size exceeds the maximum allowed value
    if (totalBufferSize > MAX_BUFFER_SIZE) {
        return -2;
    }

    // Allocate memory for the frame buffers
    FrameBufferEntry* buffers = malloc(totalBufferSize);
    if (!buffers) {
        return -3;
    }

    // Initialize each buffer entry with a timestamp, packet length, and dynamically allocated packet data
    for (size_t i = 0; i < numEntries; ++i) {
        FrameBufferEntry* entry = &buffers[i];
        entry->timestamp = getCurrentTimestamp();
        entry->packetLength = entrySize;
        entry->packetData = malloc(entrySize);
        if (!entry->packetData) {
            return -4;
        }
    }

    // If requested, pad each packet data buffer to the specified alignment boundary using zero bytes
    if (padToAlignment) {
        for (size_t i = 0; i < numEntries; ++i) {
            FrameBufferEntry* entry = &buffers[i];
            size_t paddingSize = ALIGNMENT - ((uintptr_t)entry->packetData % ALIGNMENT);
            memset(entry->packetData, 0, paddingSize);
        }
    }

    // Return the initialized frame buffers
    return buffers;
}

// Define a function to free the allocated memory for the frame buffers
void free_frame_buffers(FrameBufferEntry* buffers) {
    // Check if the input parameter is valid
    if (!buffers) {
        return;
    }

    // Free each buffer entry's packet data and the overall buffer
    for (size_t i = 0; i < numEntries; ++i) {
        FrameBufferEntry* entry = &buffers[i];
        free(entry->packetData);
    }
    free(buffers);
}
