// Custom data structure optimized for ordered insertion and deletion
struct FrequencyBand {
    uint64_t fi; // Unique frequency identifier
    float bw; // Bandwidth
    float centerFreq; // Center frequency
    int ssi; // Signal strength indicator
};

// Priority-based insertion strategy for bands with higher signal strengths
struct FrequencyBandPriority {
    uint64_t fi; // Unique frequency identifier
    float bw; // Bandwidth
    float centerFreq; // Center frequency
    int ssi; // Signal strength indicator
    int priority; // Priority based on signal strength
};

// Thread-safe registry of software-defined radio (SDR) frequency bands
class FrequencyBandRegistry {
private:
    std::vector<FrequencyBand> bands; // Vector of frequency bands
    std::mutex mutex; // Mutex for thread safety
public:
    FrequencyBandRegistry() {}

    // Add a new frequency band to the registry
    void add(uint64_t fi, float bw, float centerFreq, int ssi) {
        std::lock_guard<std::mutex> lock(mutex);
        bands.push_back({fi, bw, centerFreq, ssi});
    }

    // Remove a frequency band from the registry
    void remove(uint64_t fi) {
        std::lock_guard<std::mutex> lock(mutex);
        bands.erase(std::remove_if(bands.begin(), bands.end(), [fi](const FrequencyBand& band) { return band.fi == fi; }), bands.end());
    }

    // Get the frequency band with the highest signal strength above a minimum threshold
    FrequencyBand getHighestSignalStrength(int minThreshold) {
        std::lock_guard<std::mutex> lock(mutex);
        return *std::max_element(bands.begin(), bands.end(), [minThreshold](const FrequencyBand& band1, const FrequencyBand& band2) {
            return (band1.ssi > minThreshold && band2.ssi <= minThreshold);
        });
    }

    // Get the frequency band with the lowest signal strength above a minimum threshold
    FrequencyBand getLowestSignalStrength(int minThreshold) {
        std::lock_guard<std::mutex> lock(mutex);
        return *std::min_element(bands.begin(), bands.end(), [minThreshold](const FrequencyBand& band1, const FrequencyBand& band2) {
            return (band1.ssi > minThreshold && band2.ssi <= minThreshold);
        });
    }

    // Get the frequency band with a specific FI
    FrequencyBand get(uint64_t fi) {
        std::lock_guard<std::mutex> lock(mutex);
        return *std::find_if(bands.begin(), bands.end(), [fi](const FrequencyBand& band) { return band.fi == fi; });
    }

    // Get the number of frequency bands in the registry
    size_t size() {
        std::lock_guard<std::mutex> lock(mutex);
        return bands.size();
    }
};

// Logging mechanism to track entry additions, removals, and registry resizing
class FrequencyBandLogger {
private:
    std::ofstream logFile; // File for logging
public:
    FrequencyBandLogger(const char* filename) : logFile(filename, std::ios_base::app) {}

    // Log an entry addition to the registry
    void logAddition(uint64_t fi, float bw, float centerFreq, int ssi) {
        logFile << "Added frequency band with FI: " << fi << ", BW: " << bw << ", Center Freq: " << centerFreq << ", SSI: " << ssi << std::endl;
    }

    // Log an entry removal from the registry
    void logRemoval(uint64_t fi) {
        logFile << "Removed frequency band with FI: " << fi << std::endl;
    }

    // Log a registry resize event
    void logResize() {
        logFile << "Registry resized" << std::endl;
    }
};

// Main function for testing the FrequencyBandRegistry class
int main() {
    FrequencyBandRegistry registry;
    FrequencyBandLogger logger("frequency_band_registry.log");

    // Add some frequency bands to the registry
    registry.add(1, 20, 100, 5);
    registry.add(2, 30, 150, 7);
    registry.add(3, 40, 200, 9);

    // Get the highest signal strength frequency band above a minimum threshold
    FrequencyBand highest = registry.getHighestSignalStrength(8);
    logger.logAddition(highest.fi, highest.bw, highest.centerFreq, highest.ssi);

    // Remove a frequency band from the registry
    registry.remove(2);
    logger.logRemoval(2);

    // Get the lowest signal strength frequency band above a minimum threshold
    FrequencyBand lowest = registry.getLowestSignalStrength(8);
    logger.logAddition(lowest.fi, lowest.bw, lowest.centerFreq, lowest.ssi);

    // Get the frequency band with a specific FI
    FrequencyBand band = registry.get(1);
    logger.logAddition(band.fi, band.bw, band.centerFreq, band.ssi);

    // Print the number of frequency bands in the registry
    std::cout << "Number of frequency bands: " << registry.size() << std::endl;

    return 0;
}']

