            }
            if (server_metrics[j].network_throughput > network_throughput_peak) {
                network_throughput_peak = server_metrics[j].network_throughput;
            }
        }
        printf("Server %s: CPU usage average = %.2f, peak = %.2f\n", server_metric->server_id, cpu_usage_avg, cpu_usage_peak);
        printf("Server %s: Memory usage average = %.2f, peak = %.2f\n", server_metric->server_id, memory_usage_avg, memory_usage_peak);
        printf("Server %s: Disk I/O peak = %ld\n", server_metric->server_id, disk_io_peak);
        printf("Server %s: Network throughput peak = %ld\n", server_metric->server_id, network_throughput_peak);
    }

    // Export aggregated metrics to CSV file
    char *output_filename = malloc(MAX_FILENAME_LEN + 1);
    strcpy(output_filename, log_dir);
    strcat(output_filename, "/");
    strcat(output_filename, filename);
    int len = strlen(output_filename);
    if (len > MAX_FILENAME_LEN - MIN_RANDOM_CHARS) {
        output_filename[MAX_FILENAME_LEN - MIN_RANDOM_CHARS] = '\0';
    } else {
        len = MAX_FILENAME_LEN - MIN_RANDOM_CHARS;
    }
    for (i = 0; i < len; i++) {
        output_filename[len + i] = 'a' + rand() % ('z' - 'a');
    }
    strcat(output_filename, ".csv");
    FILE *output_file = fopen(output_filename, "w");
    if (output_file == NULL) {
        perror("Error opening output file");
        exit(EXIT_FAILURE);
    }
    for (i = 0; i < num_server_metrics; i++) {
        server_metrics_t *server_metric = &server_metrics[i];
        fprintf(output_file, "%s,%f,%f,%ld,%ld\n", server_metric->server_id, cpu_usage_avg, memory_usage_avg, disk_io_peak, network_throughput_peak);
    }
    fclose(output_file);
}
