#include <errno.h>

// Define the structure to hold a connection request
typedef struct {
    int client_id;
    char* source_ip;
    char* destination_ip;
    int priority_level;
} ConnectionRequest;

// Define the list data structure to hold the connection requests
typedef struct {
    ConnectionRequest** requests;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} ConnectionRequestList;

// Initialize a new connection request list with a given capacity
ConnectionRequestList* init_connection_request_list(size_t capacity) {
    ConnectionRequestList* list = malloc(sizeof(ConnectionRequestList));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for connection request list: %s\n", strerror(errno));
        return NULL;
    }
    list->requests = calloc(capacity, sizeof(ConnectionRequest*));
    if (!list->requests) {
        fprintf(stderr, "Failed to allocate memory for connection requests: %s\n", strerror(errno));
        free(list);
        return NULL;
    }
    list->capacity = capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Add a new connection request to the list
int add_connection_request(ConnectionRequestList* list, int client_id, char* source_ip, char* destination_ip, int priority_level) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        // Resize the list if it's full
        ConnectionRequest** new_requests = realloc(list->requests, 2 * list->capacity * sizeof(ConnectionRequest*));
        if (!new_requests) {
            fprintf(stderr, "Failed to resize connection request list: %s\n", strerror(errno));
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->requests = new_requests;
        list->capacity *= 2;
    }
    ConnectionRequest* request = malloc(sizeof(ConnectionRequest));
    if (!request) {
        fprintf(stderr, "Failed to allocate memory for connection request: %s\n", strerror(errno));
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    request->client_id = client_id;
    request->source_ip = source_ip;
    request->destination_ip = destination_ip;
    request->priority_level = priority_level;
    list->requests[list->count++] = request;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Remove a connection request from the list by its index
int remove_connection_request(ConnectionRequestList* list, size_t index) {
    if (index >= list->count) {
        fprintf(stderr, "Invalid index for connection request removal\n");
        return -1;
    }
    ConnectionRequest* request = list->requests[index];
    free(request);
    memmove(&list->requests[index], &list->requests[index + 1], (list->count - index - 1) * sizeof(ConnectionRequest*));
    list->count--;
    return 0;
}

// Reset the connection request list to its initial state
void reset_connection_request_list(ConnectionRequestList* list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        free(list->requests[i]);
    }
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
}

// Release the memory allocated for the connection request list
void destroy_connection_request_list(ConnectionRequestList* list) {
    if (list) {
        pthread_mutex_destroy(&list->mutex);
        free(list->requests);
        free(list);
    }
}
