#include <pthread.h>

#define MAX_LOG_FILES 100
#define MAX_SERVERS 100
#define MAX_METRICS 50
#define METRIC_NAME_LEN 32
#define SERVER_ID_LEN 64
#define LOG_FILE_EXTENSION ".json"
#define CSV_FILE_EXTENSION ".csv"
#define MAX_CSV_FILENAME_LEN 255
#define MIN_RANDOM_CHARS 8
#define MAX_RANDOM_CHARS 16

typedef struct {
    char name[METRIC_NAME_LEN];
    double value;
} Metric;

typedef struct {
    char id[SERVER_ID_LEN];
    int num_metrics;
    Metric metrics[MAX_METRICS];
} ServerMetrics;

typedef struct {
    char filename[MAX_CSV_FILENAME_LEN];
    FILE *file;
} CSVFile;

void processAndAggregateServerMetrics(char *log_dir, int num_files) {
    // Initialize variables
    ServerMetrics *server_metrics = malloc(sizeof(ServerMetrics) * MAX_SERVERS);
    memset(server_metrics, 0, sizeof(ServerMetrics) * MAX_SERVERS);
    CSVFile *csv_files = malloc(sizeof(CSVFile) * num_files);
    memset(csv_files, 0, sizeof(CSVFile) * num_files);
    int num_servers = 0;
    int num_metrics = 0;
    time_t start_time = time(NULL);

    // Iterate over log files and process metrics
    for (int i = 0; i < num_files; i++) {
        char *filename = malloc(strlen(log_dir) + strlen(LOG_FILE_EXTENSION) + 1);
        sprintf(filename, "%s%s", log_dir, LOG_FILE_EXTENSION);
        FILE *file = fopen(filename, "r");
        if (file == NULL) {
            perror("fopen");
            continue;
        }

        // Read metrics from file and add to server metrics
        char line[1024];
        while (fgets(line, sizeof(line), file)) {
            JSONObject *json = json_parse(line);
            if (json == NULL) {
                continue;
            }

            // Get server ID and metric name
            char *server_id = json_get_string(json, "server_id");
            char *metric_name = json_get_string(json, "metric_name");

            // Check if server exists in array
            int server_index = -1;
            for (int j = 0; j < num_servers; j++) {
                if (strcmp(server_id, server_metrics[j].id) == 0) {
                    server_index = j;
                    break;
                }
            }

            // Add new server to array if not found
            if (server_index == -1) {
                server_index = num_servers++;
                strcpy(server_metrics[server_index].id, server_id);
            }

            // Get metric value and add to array
            double value = json_get_double(json, "value");
            int metric_index = -1;
            for (int j = 0; j < server_metrics[server_index].num_metrics; j++) {
                if (strcmp(metric_name, server_metrics[server_index].metrics[j].name) == 0) {
                    metric_index = j;
                    break;
                }
            }

            // Add new metric to array if not found
            if (metric_index == -1) {
                metric_index = server_metrics[server_index].num_metrics++;
                strcpy(server_metrics[server_index].metrics[metric_index].name, metric_name);
            }

            // Update metric value
            server_metrics[server_index].metrics[metric_index].value = value;
        }

        fclose(file);
    }

    // Calculate average and peak values for each metric across all servers
    for (int i = 0; i < num_servers; i++) {
        for (int j = 0; j < server_metrics[i].num_metrics; j++) {
            double sum = 0.0;
            int count = 0;
            for (int k = 0; k < num_files; k++) {
                if (strcmp(server_metrics[i].id, csv_files[k].filename) == 0) {
                    sum += server_metrics[i].metrics[j].value;
                    count++;
                }
            }
            double average = sum / count;
            double peak = 0.0;
            for (int k = 0; k < num_files; k++) {
                if (strcmp(server_metrics[i].id, csv_files[k].filename) == 0) {
                    if (server_metrics[i].metrics[j].value > peak) {
                        peak = server_metrics[i].metrics[j].value;
                    }
                }
            }
            printf("Server %s, Metric %s: Average = %.2f, Peak = %.2f\n", server_metrics[i].id, server_metrics[i].metrics[j].name, average, peak);
        }
    }

    // Export aggregated metrics to CSV files
    for (int i = 0; i < num_servers; i++) {
        char *filename = malloc(strlen(log_dir) + strlen(CSV_FILE_EXTENSION) + 1);
        sprintf(filename, "%s%s", log_dir, CSV_FILE_EXTENSION);
        FILE *file = fopen(filename, "w");
        if (file == NULL) {
            perror("fopen");
            continue;
        }

        // Write header row
        fprintf(file, "Server ID,Metric Name,Average Value,Peak Value\n");

        // Write data rows
        for (int j = 0; j < server_metrics[i].num_metrics; j++) {
            fprintf(file, "%s,%s,%.2f,%.2f\n", server_metrics[i].id, server_metrics[i].metrics[j].name, average, peak);
        }

        fclose(file);
    }

    // Clean up resources
    free(server_metrics);
    for (int i = 0; i < num_files; i++) {
        if (csv_files[i].file != NULL) {
            fclose(csv_files[i].file);
        }
    }
}
