        return false;
    }

    // Check if the list has reached its capacity limit
    if (list->size == list->capacity) {
        // Dynamically resize the list by 50%
        size_t new_capacity = list->capacity * 1.5;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            printf("Error: Failed to resize CRC indication list\n");
            return false;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    // Insert the new structure into the list
    NFAPI_CRC_INDICATION_PDU_T *new_entry = &list->data[list->size++];
    new_entry->rx_ue_information_tag = rx_ue_information_tag;
    new_entry->rnti = rnti;
    new_entry->crc_indication_rel8_tag = rand() % 256; // Randomly set CRCFLAG

    return true;
}

// Define the function to validate that the RNTI values fall within a specified valid range
bool validate_rnti(uint16_t rnti) {
    if (rnti < 0 || rnti > 65535) {
        printf("Error: Invalid RNTI value %d\n", rnti);
        return false;
    }
    return true;
}

// Define the function to handle error logging for cases where the RNTI validation fails
void log_error(const char *message) {
    printf("Error: %s\n", message);
}

// Define the function to ensure that the list can dynamically resize if it reaches a predefined capacity limit
void resize_list(NFAPI_CRC_INDICATION_LIST_T *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        printf("Error: Failed to resize CRC indication list\n");
        return;
    }
    list->data = new_data;
    list->capacity = new_capacity;
