// Define the function to handle concurrent access from multiple threads without data corruption
void thread_safe_add_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, uint16_t rx_ue_information_tag, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);
    bool success = add_crc_indication(list, rx_ue_information_tag, rnti);
    if (!success) {
        log_error("Failed to add CRC indication");
    }
    pthread_mutex_unlock(&list->mutex);
}
