#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include "nfapi_crc_indication_pdu.h"
#include "ue_information_manager.h"
#include "logging.h"

// Define the maximum capacity of the list
#define MAX_CAPACITY 1024

// Define the predefined valid range for RNTIs
#define MIN_RNTI 0
#define MAX_RNTI 65535

// Define the structure to hold the CRC indication data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
} CRC_INDICATION_DATA_T;

// Define the list of CRC indications
static pthread_mutex_t crc_indication_list_lock = PTHREAD_MUTEX_INITIALIZER;
static CRC_INDICATION_DATA_T *crc_indication_list = NULL;
static size_t crc_indication_list_size = 0;

// Define the function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int create_and_populate_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T *crc_indications, size_t num_crc_indications) {
    // Validate the input parameters
    if (crc_indications == NULL || num_crc_indications == 0) {
        return -1;
    }

    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&crc_indication_list_lock);

    // Iterate over each CRC indication and validate its RNTI value
    for (size_t i = 0; i < num_crc_indications; i++) {
        NFAPI_CRC_INDICATION_PDU_T *crc_indication = &crc_indications[i];

        // Validate the RNTI value falls within the valid range
        if (crc_indication->rnti < MIN_RNTI || crc_indication->rnti > MAX_RNTI) {
            pthread_mutex_unlock(&crc_indication_list_lock);
            return -2;
        }

        // Check if the RNTI value already exists in the list
        for (size_t j = 0; j < crc_indication_list_size; j++) {
            CRC_INDICATION_DATA_T *data = &crc_indication_list[j];
            if (data->crc_indication.rnti == crc_indication->rnti) {
                pthread_mutex_unlock(&crc_indication_list_lock);
                return -3;
            }
        }
    }

    // Dynamically resize the list if necessary
    size_t new_size = crc_indication_list_size + num_crc_indications;
    if (new_size > MAX_CAPACITY) {
        pthread_mutex_unlock(&crc_indication_list_lock);
        return -4;
    }

    // Allocate memory for the new list elements
    CRC_INDICATION_DATA_T *new_elements = malloc(sizeof(CRC_INDICATION_DATA_T) * num_crc_indications);
    if (new_elements == NULL) {
        pthread_mutex_unlock(&crc_indication_list_lock);
        return -5;
    }

    // Populate the new list elements with the CRC indication data
    for (size_t i = 0; i < num_crc_indications; i++) {
        NFAPI_CRC_INDICATION_PDU_T *crc_indication = &crc_indications[i];
        CRC_INDICATION_DATA_T *data = &new_elements[i];
        data->crc_indication.rx_ue_information_tag = crc_indication->rx_ue_information_tag;
        data->crc_indication.rnti = crc_indication->rnti;
        data->crc_indication.crc_indication_rel8_tag.crflag = rand() % 2;
    }

    // Insert the new list elements into the existing list
    for (size_t i = 0; i < num_crc_indications; i++) {
        CRC_INDICATION_DATA_T *data = &new_elements[i];
        crc_indication_list[crc_indication_list_size++] = data;
    }

    // Free the memory allocated for the new list elements
    free(new_elements);

    // Unlock the list and return success
    pthread_mutex_unlock(&crc_indication_list_lock);
    return 0;
}

// Define the function to retrieve a CRC indication from the list by RNTI value
NFAPI_CRC_INDICATION_PDU_T *get_crc_indication_by_rnti(uint16_t rnti) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&crc_indication_list_lock);

    // Iterate over each element in the list and check if the RNTI value matches
    for (size_t i = 0; i < crc_indication_list_size; i++) {
        CRC_INDICATION_DATA_T *data = &crc_indication_list[i];
        if (data->crc_indication.rnti == rnti) {
            // Unlock the list and return the matching element
            pthread_mutex_unlock(&crc_indication_list_lock);
            return &data->crc_indication;
        }
    }

    // If no match is found, unlock the list and return NULL
    pthread_mutex_unlock(&crc_indication_list_lock);
    return NULL;
}

// Define the function to remove a CRC indication from the list by RNTI value
int remove_crc_indication_by_rnti(uint16_t rnti) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&crc_indication_list_lock);

    // Iterate over each element in the list and check if the RNTI value matches
    for (size_t i = 0; i < crc_indication_list_size; i++) {
        CRC_INDICATION_DATA_T *data = &crc_indication_list[i];
        if (data->crc_indication.rnti == rnti) {
            // Remove the matching element from the list and decrement the size
            memmove(&crc_indication_list[i], &crc_indication_list[i + 1], sizeof(CRC_INDICATION_DATA_T) * (crc_indication_list_size - i));
            crc_indication_list_size--;

            // Unlock the list and return success
            pthread_mutex_unlock(&crc_indication_list_lock);
            return 0;
