// Define the function to add a NFAPI_CRC_INDICATION_PDU_T structure to the list
int nfapi_crc_indication_pdu_list_add(struct nfapi_crc_indication_pdu_list *list, struct nfapi_crc_indication_pdu_s *pdu) {
    // Check if the list is NULL or the PDU is NULL
    if (list == NULL || pdu == NULL) {
        return -1;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Check if the list has reached its capacity
    if (list->count >= list->capacity) {
        // Reallocate memory for the data array
        size_t new_capacity = list->capacity * 2;
        struct nfapi_crc_indication_pdu_s **new_data = realloc(list->data, sizeof(struct nfapi_crc_indication_pdu_s *) * new_capacity);
        if (new_data == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return -2;
        }

        // Update the list structure with the new data array and capacity
        list->data = new_data;
        list->capacity = new_capacity;
    }

    // Check if the RNTI value falls within a specified valid range
    uint16_t rnti = pdu->rx_ue_information.rnti;
    if (rnti < MIN_RNTI || rnti > MAX_RNTI) {
        // Log the error and unlock the mutex
        logging("Invalid RNTI value: %d\n", rnti);
        pthread_mutex_unlock(&list->mutex);
        return -3;
    }

    // Check if the RNTI already exists in the list
    for (size_t i = 0; i < list->count; i++) {
        if (list->data[i]->rx_ue_information.rnti == rnti) {
            // Log the error and unlock the mutex
            logging("Duplicate RNTI value: %d\n", rnti);
            pthread_mutex_unlock(&list->mutex);
            return -4;
        }
    }

    // Set a random CRC flag for the PDU
    uint8_t crcflag = rand() & 0x1;
    pdu->crc_indication_rel8.crc_flag = crcflag;

    // Add the PDU to the list
    list->data[list->count++] = pdu;

    // Unlock the mutex and return
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Define the function to remove a NFAPI_CRC_INDICATION_PDU_T structure from the list
int nfapi_crc_indication_pdu_list_remove(struct nfapi_crc_indication_pdu_list *list, struct nfapi_crc_indication_pdu_s *pdu) {
    // Check if the list is NULL or the PDU is NULL
    if (list == NULL || pdu == NULL) {
        return -1;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Find the index of the PDU in the list
    size_t i = 0;
    for (i = 0; i < list->count; i++) {
        if (list->data[i] == pdu) {
            break;
        }
    }

    // Check if the PDU was found in the list
    if (i >= list->count) {
        // Log the error and unlock the mutex
        logging("PDU not found in list\n");
        pthread_mutex_unlock(&list->mutex);
        return -2;
    }

    // Remove the PDU from the list
    for (size_t j = i; j < list->count - 1; j++) {
        list->data[j] = list->data[j + 1];
    }
    list->count--;

    // Unlock the mutex and return
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Define the function to clear the list of NFAPI_CRC_INDICATION_PDU_T structures
int nfapi_crc_indication_pdu_list_clear(struct nfapi_crc_indication_pdu_list *list) {
    // Check if the list is NULL
    if (list == NULL) {
        return -1;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Clear the data array and reset the count
    free(list->data);
    list->data = NULL;
    list->count = 0;

    // Unlock the mutex and return
    pthread_mutex_unlock(&list->mutex);
    return 0;
