// Define the mutex for protecting the list of cell status PDUs
static pthread_mutex_t cell_status_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the semaphore for signaling when a new cell status PDU is available
static sem_t cell_status_available_sem;

// Define the function to handle incoming cell status updates from the MME server
void handle_cell_status_update(int cell_id, int pci, int rssi) {
    // Acquire the mutex for protecting the list of cell status PDUs
    pthread_mutex_lock(&cell_status_list_mutex);

    // Check if the list of cell status PDUs is NULL
    if (cell_status_list == NULL) {
        // If the list is NULL, allocate memory for it
        cell_status_list = malloc(sizeof(NR_CELL_STATUS_PDU_T));
        if (cell_status_list == NULL) {
            perror("Failed to allocate memory for cell status list");
            return;
