    } else {
        // If the list is not NULL, reallocate memory for it with a new size
        cell_status_list = realloc(cell_status_list, (num_cells + 1) * sizeof(NR_CELL_STATUS_PDU_T));
        if (cell_status_list == NULL) {
            perror("Failed to reallocate memory for cell status list");
            return;
        }
    }

    // Update the new cell status PDU in the list
    cell_status_list[num_cells].cell_id = cell_id;
    cell_status_list[num_cells].pci = pci;
    cell_status_list[num_cells].rssi = rssi;
    cell_status_list[num_cells].sinr = calculate_sinr(cell_id, pci, rssi);
    cell_status_list[num_cells].rsrp = calculate_rsrp(cell_id, pci, rssi);

    // Increment the number of cells in the list
    num_cells++;

    // Release the mutex for protecting the list of cell status PDUs
    pthread_mutex_unlock(&cell_status_list_mutex);

    // Signal the semaphore to indicate that a new cell status PDU is available
    sem_post(&cell_status_available_sem);
}

// Define the function to calculate SINR for a given cell
float calculate_sinr(int cell_id, int pci, int rssi) {
    // Calculate the SINR using the formula: SINR = RSSI - 10 * log10(PCI / 2.5)
    return (float)(rssi - 10 * log10(pci / 2.5));
}

// Define the function to calculate RSRP for a given cell
float calculate_rsrp(int cell_id, int pci, int rssi) {
    // Calculate the RSRP using the formula: RSRP = RSSI - 10 * log10(PCI / 2.5)
    return (float)(rssi - 10 * log10(pci / 2.5));
}

