    // Acquire the mutex for protecting the list of cell status PDUs
    pthread_mutex_lock(&cell_status_list_mutex);

    // Check if the list of cell status PDUs is NULL
    if (cell_status_list == NULL) {
        // If the list is NULL, return immediately
        pthread_mutex_unlock(&cell_status_list_mutex);
        return;
    }

    // Iterate over the frames in the signaling stream
    for (int i = 0; i < num_frames; i++) {
        // Calculate the SINR and RSRP for each cell in the list
        for (int j = 0; j < num_cells; j++) {
            cell_status_list[j].sinr = calculate_sinr(cell_status_list[j].cell_id, cell_status_list[j].pci, cell_status_list[j].rssi);
