            DataPacket* packet = malloc(sizeof(DataPacket));
            if (packet == NULL) {
                fprintf(stderr, "Error: failed to allocate memory for data packet\n");
                free(packets);
                free(lists);
                return;
            }
            packet->id = id;
            packet->timestamp = timestamp;
            packet->payload_length = payload_length;

            // Verify the integrity of the packet using a checksum algorithm
            uint32_t checksum = calculate_checksum(packet);
            if (checksum != packet->id) {
                fprintf(stderr, "Error: checksum verification failed for data packet\n");
                free(packet);
                free(packets);
                free(lists);
                return;
            }

            // Add the packet to the array
            packets[i] = packet;
        }

        // Read the input from the file and populate the corresponding integer list
        while (fgets(line, sizeof(line), file)) {
            // Parse the input line and extract the integer value
            int integer;
            sscanf(line, "%d", &integer);

            // Check if the integer is positive
            if (integer <= 0) {
                fprintf(stderr, "Error: non-positive integer encountered\n");
                free(packets);
                free(lists);
                return;
            }

            // Add the integer to the array
            lists[i].integers = realloc(lists[i].integers, sizeof(int) * (lists[i].num_integers + 1));
            if (lists[i].integers == NULL) {
                fprintf(stderr, "Error: failed to allocate memory for integer list\n");
                free(packets);
                free(lists);
                return;
            }
            lists[i].integers[lists[i].num_integers++] = integer;
        }
    }

    // Find and print the largest integer in each integer list
    for (int i = 0; i < num_files; i++) {
        printf("Largest integer in file %s: %d\n", file_names[i], lists[i].integers[lists[i].num_integers - 1]);
    }

    // Free the memory allocated for the data packets and integer lists
    free(packets);
    free(lists);
}
