        (*packets)[i].timestamp = time(NULL);
        (*packets)[i].payload_length = 0;
        (*packets)[i].payload = NULL;
    }
}

// Function to verify the integrity of each packet using a checksum algorithm
void verify_checksum(struct DataPacket *packet) {
    // Compute the checksum for the packet
    unsigned int checksum = 0;
    for (int i = 0; i < packet->payload_length; i++) {
        checksum += packet->payload[i];
    }

    // If the computed checksum does not match the expected value, attempt to recompute using an alternative hashing method and retry the insertion
    if (checksum != packet->id) {
        printf("Checksum verification failed for packet %d\n", packet->id);
        // Compute the checksum using an alternative hashing method
        unsigned int alt_checksum = 0;
        for (int i = 0; i < packet->payload_length; i++) {
            alt_checksum += packet->payload[i];
        }
        if (alt_checksum != packet->id) {
            printf("Failed to verify checksum using alternative hashing method\n");
            exit(1);
        } else {
            printf("Checksum verified using alternative hashing method for packet %d\n", packet->id);
        }
    }
}

