void verify_packet(DataPacket* packet) {
    // Compute the checksum for the packet
    int checksum = 0;
    for (int i = 0; i < packet->payload_length; i++) {
        checksum += packet->payload[i];
    }

    // If the computed checksum does not match the stored checksum, attempt to recompute using an alternative hashing method
    if (checksum != packet->checksum) {
