// Define the structure to hold the received RRC message information
typedef struct {
    uint32_t pduSessionId;
    SNSSAI snssai;
    char* rrcMessage;
} NFAPI_RX_INDICATION_PDU_T;

// Define a linked list node to store the received RRC messages
typedef struct {
    NFAPI_RX_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

// Define the collection of received RRC messages
Node* head = NULL;

// Define a mutex to ensure thread safety when accessing the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to add a new received RRC message to the collection
void addPdu(NFAPI_RX_INDICATION_PDU_T pdu) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Create a new node for the received RRC message
    Node* newNode = malloc(sizeof(Node));
    newNode->pdu = pdu;
    newNode->next = NULL;

    // If the linked list is empty, set the head to point to the new node
    if (head == NULL) {
        head = newNode;
    } else {
        // Otherwise, add the new node to the end of the linked list
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Define a function to export the collected PDUs to an XML file
void exportPdusToXml(char* filename) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error: unable to open output file\n");
        return;
    }

    // Write the XML header and root element
    fprintf(fp, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    fprintf(fp, "<pdus>\n");

    // Iterate through the linked list and write each PDU to the output file
    Node* current = head;
    while (current != NULL) {
        NFAPI_RX_INDICATION_PDU_T pdu = current->pdu;
        fprintf(fp, "<pdu>\n");
        fprintf(fp, "  <pduSessionId>%u</pduSessionId>\n", pdu.pduSessionId);
        fprintf(fp, "  <snssai>%s</snssai>\n", pdu.snssai);
        fprintf(fp, "  <rrcMessage>%s</rrcMessage>\n", pdu.rrcMessage);
        fprintf(fp, "</pdu>\n");
        current = current->next;
    }

    // Write the XML footer and close the output file
    fprintf(fp, "</pdus>\n");
    fclose(fp);

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Define a function to filter PDUs based on SNSSAI and PDU Session ID
void filterPdus(SNSSAI snssai, uint32_t pduSessionId) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Create a new linked list for the filtered PDUs
    Node* head = NULL;

    // Iterate through the original linked list and add each PDU that matches the filter criteria to the new linked list
    Node* current = head;
    while (current != NULL) {
        NFAPI_RX_INDICATION_PDU_T pdu = current->pdu;
        if ((snssai == NULL || strcmp(pdu.snssai, snssai) == 0) && (pduSessionId == 0 || pdu.pduSessionId == pduSessionId)) {
            // Create a new node for the filtered PDU and add it to the end of the linked list
            Node* newNode = malloc(sizeof(Node));
            newNode->pdu = pdu;
            newNode->next = NULL;
            if (head == NULL) {
                head = newNode;
            } else {
                Node* current = head;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = newNode;
            }
        }
        current = current->next;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}
