        return;
    }

    // Initialize each DataPacket structure and populate the array
    for (int i = 0; i < num_packets; i++) {
        (*packets)[i] = (DataPacket*)malloc(sizeof(DataPacket));
        if ((*packets)[i] == NULL) {
            printf("Memory allocation failed\n");
            return;
        }

