// Function to calculate the checksum for a DataPacket structure using a specified hashing method
int calculate_checksum(DataPacket* packet) {
    // Calculate the checksum for the packet based on its payload and identifier
    int checksum = 0;
    for (int i = 0; i < packet->payload_len; i++) {
        checksum += packet->payload[i] * (i + 1);
