}

// Function to calculate the checksum for a DataPacket structure using an alternative hashing method
int calculate_alt_checksum(DataPacket* packet) {
    // Calculate the checksum for the packet based on its payload and identifier using an alternative hashing method
    int alt_checksum = 0;
    for (int i = 0; i < packet->payload_len; i++) {
