}

// Define a function to add a resource node to the linked list
void add_resource_node(ResourceNode** head, int id, long timestamp, int usage_count, bool active) {
    // Create a new node with the given parameters
    ResourceNode* node = create_resource_node(id, timestamp, usage_count, active);
    if (node == NULL) {
        printf("Failed to create resource node\n");
        return;
    }

    // Add the new node to the linked list
    node->next = *head;
    *head = node;
}

// Define a function to remove a resource node from the linked list
void remove_resource_node(ResourceNode** head, int id) {
    // Find the node with the given ID in the linked list
    ResourceNode* current = *head;
    while (current != NULL && current->id != id) {
        current = current->next;
    }

    // If the node is found, remove it from the linked list
    if (current != NULL) {
        // Update the next pointer of the previous node to skip the removed node
        (*head)->next = current->next;

        // Free the memory of the removed node
        free(current);
    } else {
        printf("Resource node with ID %d not found\n", id);
    }
}

