    while (current != NULL && current->id != id) {
        current = current->next;
    }

    // If the node is found, update its usage count
    if (current != NULL) {
        current->usage_count = usage_count;
    } else {
        printf("Resource node with ID %d not found\n", id);
    }
}

// Define a function to check for duplicate resource IDs in the linked list
void check_duplicate_ids(ResourceNode** head) {
    // Create a hash table to store the unique resource IDs
    int* ids = malloc(sizeof(int) * 100);
    if (ids == NULL) {
        printf("Failed to allocate memory for hash table\n");
        return;
