    // Iterate through the linked list and check for duplicate IDs
    ResourceNode* current = *head;
    while (current != NULL) {
        if (ids[current->id] != -1) {
            printf("Duplicate resource ID %d found\n", current->id);
            break;
        } else {
            ids[current->id] = 1;
        }
        current = current->next;
    }

