void reallocate_resources(ResourceNode** head) {
    // Calculate the total usage count of all nodes in the linked list
    int total_usage_count = 0;
    ResourceNode* current = *head;
    while (current != NULL) {
        total_usage_count += current->usage_count;
        current = current->next;
    }

    // If the total usage count exceeds a predefined threshold, reallocate resources among existing nodes
    if (total_usage_count > 1000) {
        // Calculate the average usage count per node
        int average_usage_count = total_usage_count / (*head)->next->id;

        // Reallocate resources by updating the usage count of each node based on its ID
        current = *head;
        while (current != NULL) {
            if (current->id % 2 == 0) {
                current->usage_count += average_usage_count / 2;
            } else {
                current->usage_count -= average_usage_count / 2;
            }
            current = current->next;
        }
    }
}

