    if (memory) {
        memory_pool.size += size;
    } else {
        fprintf(stderr, "Error: Failed to allocate memory\n");
    }
    pthread_mutex_unlock(&memory_pool.mutex);
    return memory;
}

void deallocate_memory(void* memory) {
    pthread_mutex_lock(&memory_pool.mutex);
    free(memory);
    memory_pool.size -= size;
    pthread_mutex_unlock(&memory_pool.mutex);
}

