#include <fcntl.h>
#include <errno.h>
#include <pthread.h>

#define MAX_FILENAME_LENGTH 255
#define MAX_RANDOM_DIGITS 10
#define DEFAULT_FILETYPE ".txt"
#define MAX_NFAPI_CREDIT 1024
#define MAX_SEQUENCE_LENGTH 20

typedef struct {
    char *filename;
    int filetype;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_random_sequence(char *filename, int length) {
    srand(time(NULL));
    for (int i = 0; i < length; i++) {
        filename[i] = '0' + rand() % 10;
    }
}

void generate_new_filename(char *original_filename, char *new_filename) {
    int original_length = strlen(original_filename);
    int new_length = original_length + MAX_RANDOM_DIGITS + 1;
    if (new_length > MAX_FILENAME_LENGTH) {
        new_length = MAX_FILENAME_LENGTH;
    }
    strncpy(new_filename, original_filename, original_length);
    generate_random_sequence(new_filename + original_length, MAX_RANDOM_DIGITS);
    new_filename[original_length + MAX_RANDOM_DIGITS] = '\0';
}

void append_filetype(char *filename, int filetype) {
    char *dot = strrchr(filename, '.');
    if (dot != NULL) {
        dot++;
    } else {
        dot = filename;
    }
    sprintf(dot, "%s", filetype);
}

void check_for_conflict(char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd != -1) {
        close(fd);
        generate_new_filename(filename, filename);
        check_for_conflict(filename);
    }
}

void create_file(char *filename, int filetype) {
    char new_filename[MAX_FILENAME_LENGTH];
    generate_new_filename(filename, new_filename);
    append_filetype(new_filename, filetype);
    check_for_conflict(new_filename);
    int fd = open(new_filename, O_CREAT | O_EXCL | O_WRONLY, 0644);
    if (fd == -1) {
        perror("Error creating file");
        exit(1);
    }
    close(fd);
}

void handle_file(char *filename, int filetype) {
    char new_filename[MAX_FILENAME_LENGTH];
    generate_new_filename(filename, new_filename);
    append_filetype(new_filename, filetype);
    check_for_conflict(new_filename);
    int fd = open(new_filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        exit(1);
    }
    close(fd);
}

void handle_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int N) {
    if (N > MAX_NFAPI_CREDIT) {
        printf("Error: N (%d) exceeds maximum value of %d\n", N, MAX_NFAPI_CREDIT);
        exit(1);
    }
    char filename[MAX_FILENAME_LENGTH];
    generate_new_filename(pdu->filename, filename);
    append_filetype(filename, pdu->filetype);
    check_for_conflict(filename);
    int fd = open(filename, O_CREAT | O_EXCL | O_WRONLY, 0644);
    if (fd == -1) {
        perror("Error creating file");
        exit(1);
    }
    for (int i = 0; i < N; i++) {
        write(fd, &pdu->RX_UE_INFORMATION_TAG, sizeof(pdu->RX_UE_INFORMATION_TAG));
        write(fd, &pdu->RNTI, sizeof(pdu->RNTI));
        write(fd, &pdu->CRC_INDICATION_REL8_TAG, sizeof(pdu->CRC_INDICATION_REL8_TAG));
    }
    close(fd);
}

void handle_command_line_arguments(int argc, char **argv) {
    if (argc == 1) {
        printf("Usage: %s [options]\n", argv[0]);
        exit(1);
    }
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            printf("Manual page for %s\n", argv[0]);
            exit(0);
        } else if (strcmp(argv[i], "-cs") == 0) {
            i++;
            if (i < argc) {
                char *filename = argv[i];
                handle_file(filename, DEFAULT_FILETYPE);
            } else {
                printf("Error: -cs option requires a filename argument\n");
                exit(1);
            }
        } else if (strcmp(argv[i], "-o") == 0) {
            i++;
            if (i < argc) {
                char *filename = argv[i];
                handle_file(filename, DEFAULT_FILETYPE);
            } else {
                printf("Error: -o option requires a filename argument\n");
                exit(1);
            }
        } else {
            printf("Error: Unknown option %s\n", argv[i]);
            exit(1);
        }
    }
}

int main(int argc, char **argv) {
    handle_command_line_arguments(argc, argv);
    return 0;
}
