            // Print man page and exit
            printf("Manual page for %s\n", argv[0]);
            return 0;
        } else if (!strcmp(option, OPTION_CS)) {
            // Set log level to DEBUG
            log_level = LOG_LEVEL_DEBUG;
        } else if (!strcmp(option, OPTION_O)) {
            // Set output file
            char* output_file = argv[i + 1];
            FILE* fp = fopen(output_file, "w");
            if (fp == NULL) {
                log_message(LOG_LEVEL_ERROR, "Failed to open output file %s", output_file);
                return 1;
            }
        } else {
            // Set input file
            char* input_file = option;
            FILE* fp = fopen(input_file, "r");
            if (fp == NULL) {
                log_message(LOG_LEVEL_ERROR, "Failed to open input file %s", input_file);
                return 1;
            }
        }
    }

    // Initialize memory pool and cache
    memory_pool = MEMORY_POOL_T();
    cache = (CACHE_ENTRY_T*)malloc(sizeof(CACHE_ENTRY_T) * MAX_NFAPI_CREDIT);
    if (cache == NULL) {
        log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for cache");
        return 1;
    }
    cache_size = 0;

    // Initialize mutex and semaphore
    pthread_mutex_init(&mutex, NULL);
    semaphore_init(&semaphore, 0, 0);

    // Start periodic cleanup thread
    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, &periodic_cleanup, NULL) != 0) {
        log_message(LOG_LEVEL_ERROR, "Failed to create cleanup thread");
        return 1;
    }

    // Read input file line by line and process each line
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Parse line and extract RNTI and CRC indication PDU
        char* rnti = strtok(line, " ");
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for CRC indication PDU");
            return 1;
        }
        // Fill in RNTI and CRC indication PDU
        strcpy(pdu->rx_ue_information_tag, rnti);
        pdu->rnti = atoi(rnti);
        pdu->crc_indication_rel8_tag[0] = 'C';
        pdu->crc_indication_rel8_tag[1] = 'R';
        pdu->crc_indication_rel8_tag[2] = 'C';
        // Insert into cache and update statistics
        int index = cache_lookup(rnti);
        if (index == -1) {
            cache_insert(rnti, pdu);
            log_message(LOG_LEVEL_INFO, "Inserted RNTI %s into cache", rnti);
        } else {
            cache[index].pdu = pdu;
            log_message(LOG_LEVEL_INFO, "Updated CRC indication PDU for RNTI %s in cache", rnti);
        }
    }

    // Close input file and free memory
    fclose(fp);
    free(line);
    memory_pool_free(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Print statistics and exit
    log_message(LOG_LEVEL_INFO, "Processed %d lines from input file", line_count);
    return 0;
}

// Memory pool functions
void* memory_pool_alloc(size_t size) {
    void* data = NULL;
    pthread_mutex_lock(&mutex);
    if (memory_pool.data != NULL && memory_pool.size >= size) {
        // Allocate from existing pool
        data = memory_pool.data;
        memory_pool.data += size;
        memory_pool.size -= size;
    } else {
        // Allocate new block
        data = malloc(size);
        if (data == NULL) {
            log_message(LOG_LEVEL_ERROR, "Failed to allocate %d bytes from memory pool", size);
        }
    }
    pthread_mutex_unlock(&mutex);
    return data;
}

void memory_pool_free(void* data, size_t size) {
    pthread_mutex_lock(&mutex);
    if (data != NULL && memory_pool.size + size <= MAX_MEMORY_POOL_SIZE) {
        // Free to existing pool
        memory_pool.data = (char*)data + size;
        memory_pool.size += size;
    } else {
        // Free new block
        free(data);
    }
    pthread_mutex_unlock(&mutex);
}

// Cache functions
int cache_lookup(char* rnti) {
    int index = -1;
    for (int i = 0; i < cache_size; i++) {
        if (!strcmp(cache[i].rnti, rnti)) {
            index = i;
            break;
        }
    }
    return index;
}

void cache_insert(char* rnti, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (cache_size >= MAX_NFAPI_CREDIT) {
        log_message(LOG_LEVEL_WARN, "Cache is full, cannot insert new entry");
        return;
    }
    cache[cache_size].rnti = rnti;
    cache[cache_size].pdu = pdu;
    cache_size++;
}

void cache_delete(char* rnti) {
    int index = cache_lookup(rnti);
    if (index == -1) {
        log_message(LOG_LEVEL_WARN, "RNTI %s not found in cache", rnti);
        return;
    }
    for (int i = index; i < cache_size - 1; i++) {
        cache[i] = cache[i + 1];
    }
    cache_size--;
}

void cache_clear() {
    for (int i = 0; i < cache_size; i++) {
        memory_pool_free(cache[i].pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    cache_size = 0;
}

// Logging functions
void log_message(int level, char* message) {
    if (level <= log_level) {
        printf("%s\n", message);
    }
}

void periodic_cleanup() {
    while (1) {
        // Sleep for a certain amount of time before checking cache size
        sleep(60);
        pthread_mutex_lock(&mutex);
        if (cache_size > MAX_NFAPI_CREDIT / 2) {
            log_message(LOG_LEVEL_INFO, "Cache is over half full, starting cleanup");
            cache_clear();
        } else {
            log_message(LOG_LEVEL_DEBUG, "Cache size %d is within bounds", cache_size);
        }
        pthread_mutex_unlock(&mutex);
    }
}
