#define LOG_LEVEL_ERROR 3

typedef struct {
    int N;
    int *RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

struct cache_entry {
    int RNTI;
    int count;
};

struct cache_pool {
    struct cache_entry *entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

struct logging_context {
    FILE *file;
    int level;
};

void init_cache(struct cache_pool *cache) {
    cache->entries = malloc(sizeof(struct cache_entry) * CACHE_SIZE);
    cache->capacity = CACHE_SIZE;
    cache->size = 0;
    pthread_mutex_init(&cache->mutex, NULL);
}

void destroy_cache(struct cache_pool *cache) {
    free(cache->entries);
    pthread_mutex_destroy(&cache->mutex);
}

int add_to_cache(struct cache_pool *cache, int RNTI) {
    pthread_mutex_lock(&cache->mutex);
    if (cache->size == cache->capacity) {
        // Evict the least recently used entry from the cache
        struct cache_entry *least_recently_used = NULL;
        for (int i = 0; i < cache->size; i++) {
            if (!least_recently_used || cache->entries[i].count < least_recently_used->count) {
                least_recently_used = &cache->entries[i];
            }
        }
        // Remove the least recently used entry from the cache
        for (int i = 0; i < cache->size - 1; i++) {
            if (&cache->entries[i] == least_recently_used) {
                memmove(&cache->entries[i], &cache->entries[i + 1], sizeof(struct cache_entry) * (cache->size - i - 1));
                break;
            }
        }
        cache->size--;
    }
    // Add the new entry to the cache
    struct cache_entry *new_entry = &cache->entries[cache->size++];
    new_entry->RNTI = RNTI;
    new_entry->count = 0;
    pthread_mutex_unlock(&cache->mutex);
}

int get_from_cache(struct cache_pool *cache, int RNTI) {
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i].RNTI == RNTI) {
            // Increment the count of the found entry
            cache->entries[i].count++;
            pthread_mutex_unlock(&cache->mutex);
            return 1;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return 0;
}

void init_logging(struct logging_context *ctx, const char *file, int level) {
    ctx->file = fopen(file, "a");
    ctx->level = level;
}

void destroy_logging(struct logging_context *ctx) {
    fclose(ctx->file);
}

void log(struct logging_context *ctx, int level, const char *fmt, ...) {
    if (level <= ctx->level) {
        va_list args;
        va_start(args, fmt);
        vfprintf(ctx->file, fmt, args);
        va_end(args);
    }
}

void parse_command_line_arguments(int argc, char **argv) {
    // Parse command line arguments and provide usage information if no input file is specified
    if (argc < 2) {
        printf("Usage: %s [options] input_file\n", argv[0]);
        exit(1);
    }
}

void read_input_file(const char *filename, struct cache_pool *cache) {
    // Read the input file line by line and print the number of lines
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("fopen");
        exit(1);
    }
    int N;
    while (fscanf(fp, "%d", &N) == 1) {
        // Validate the input against the maximum value and log errors if allocation fails or N exceeds the threshold
        if (N > MAX_NFAPI_CREDIT) {
            fprintf(stderr, "Error: Input value %d exceeds maximum allowed value %d\n", N, MAX_NFAPI_CREDIT);
            exit(1);
        }
        // Add the RNTI to the cache and increment its count
        add_to_cache(cache, N);
    }
    fclose(fp);
}

void process_input(const char *filename) {
    // Initialize a custom memory pool for efficient allocation and deallocation of `NFAPI_CRC_INDICATION_PDU_T` structures
    struct cache_pool cache;
    init_cache(&cache);
    // Read the input file line by line and print the number of lines
    read_input_file(filename, &cache);
    // Destroy the custom memory pool
    destroy_cache(&cache);
}

int main(int argc, char **argv) {
    struct logging_context ctx;
    init_logging(&ctx, "log.txt", LOG_LEVEL_INFO);
    parse_command_line_arguments(argc, argv);
    process_input(argv[1]);
    destroy_logging(&ctx);
    return 0;
}
