// Define the structure for a LTE packet
typedef struct {
    int Packet_ID;
    char Source_IP[16];
    char Destination_IP[16];
    char Payload[256];
} LTE_Packet_T;

// Define the maximum number of packets to be generated
#define MAX_PACKETS 10000

// Define the probability distribution for network congestion delays
#define CONGESTION_PROBABILITY 0.5

// Define the minimum and maximum delay values for network congestion delays
#define MIN_DELAY 100
#define MAX_DELAY 200

// Define the rolling average window size for transmission delays
#define ROLLING_AVERAGE_WINDOW 5

// Define the maximum size of the log directory
#define LOG_DIRECTORY_MAX_SIZE 10485760

// Define the default file type if none is provided in the original filename
#define DEFAULT_FILE_TYPE ".log"

// Define the environment variable for the default file type
#define ENVIRONMENT_VARIABLE "DEFAULT_FILE_TYPE"

// Function to dynamically create and manage a list of LTE packets
void generatePackets(int N, int congestionProbability, int minDelay, int maxDelay) {
    // Initialize the list of packets
    LTE_Packet_T *packets = (LTE_Packet_T *)malloc(N * sizeof(LTE_Packet_T));

    // Initialize the rolling average for transmission delays
    double rollingAverage[ROLLING_AVERAGE_WINDOW];
    for (int i = 0; i < ROLLING_AVERAGE_WINDOW; i++) {
        rollingAverage[i] = 0;
    }

    // Generate up to N packets
    for (int i = 0; i < N; i++) {
        // Simulate network congestion by introducing a probabilistic delay
        int delay = rand() % (maxDelay - minDelay + 1) + minDelay;
        if (congestionProbability > 0 && rand() % 100 < congestionProbability) {
            delay *= 2;
        }

        // Simulate network routing behavior by modifying the destination IP address
        char *destinationIP = modifyDestinationIP(packets[i].Source_IP, packets[i].Destination_IP);

        // Allocate memory for the packet payload
        int payloadSize = rand() % 256 + 1;
        char *payload = (char *)malloc(payloadSize * sizeof(char));
        memset(payload, 'a', payloadSize);

        // Assign values to the packet structure
        packets[i].Packet_ID = i;
        strcpy(packets[i].Source_IP, "192.168.0.1");
        strcpy(packets[i].Destination_IP, destinationIP);
        memcpy(packets[i].Payload, payload, payloadSize);

        // Update the rolling average for transmission delays
        rollingAverage[i % ROLLING_AVERAGE_WINDOW] = delay;
    }

    // Free memory for the list of packets
    free(packets);
}

// Function to simulate network routing behavior by modifying the destination IP address
char *modifyDestinationIP(char *sourceIP, char *destinationIP) {
    // Calculate the distance between the source and destination IP addresses
    int distance = calculateDistance(sourceIP, destinationIP);

    // Simulate network congestion by introducing a probabilistic delay
    int delay = rand() % (MAX_DELAY - MIN_DELAY + 1) + MIN_DELAY;
    if (distance > 0 && rand() % 100 < CONGESTION_PROBABILITY) {
        delay *= 2;
    }

    // Simulate network routing behavior by modifying the destination IP address
    char *modifiedDestinationIP = (char *)malloc(16);
    strcpy(modifiedDestinationIP, destinationIP);
    if (distance > 0) {
        int nodeIndex = rand() % distance;
        char *nodeIP = getNodeIP(sourceIP, nodeIndex);
        strcpy(modifiedDestinationIP, nodeIP);
    }

    // Free memory for the modified destination IP address
    free(destinationIP);

    return modifiedDestinationIP;
}

// Function to calculate the distance between two IP addresses
int calculateDistance(char *sourceIP, char *destinationIP) {
    int source[4];
    int destination[4];
    sscanf(sourceIP, "%d.%d.%d.%d", &source[0], &source[1], &source[2], &source[3]);
    sscanf(destinationIP, "%d.%d.%d.%d", &destination[0], &destination[1], &destination[2], &destination[3]);
    int distance = abs(source[0] - destination[0]) + abs(source[1] - destination[1]) + abs(source[2] - destination[2]) + abs(source[3] - destination[3]);
    return distance;
}

// Function to get the IP address of a node in the network based on its index
char *getNodeIP(char *sourceIP, int nodeIndex) {
    char *nodeIP = (char *)malloc(16);
    strcpy(nodeIP, sourceIP);
    if (nodeIndex > 0) {
        int octet[4];
        sscanf(nodeIP, "%d.%d.%d.%d", &octet[0], &octet[1], &octet[2], &octet[3]);
        nodeIP[octet[3] + 1] = (char)((int)'0' + nodeIndex);
    }
    return nodeIP;
}

// Function to derive the filename of a log file from the current timestamp
char *getLogFilename(void) {
    // Get the current timestamp
