    fprintf(logfile, "%s %d %s %s\n", filename, N, filetype, directory);
    fclose(logfile);

    // Manage the maximum size of the log directory to prevent excessive disk usage by removing the oldest logs when the threshold is exceeded
    struct stat st;
    if (stat(directory, &st) == 0 && st.st_size > MAX_LOG_DIRECTORY_SIZE) {
        char *oldest_filename = (char *)malloc(256);
        oldest_filename = find_oldest_file(directory);
        remove(oldest_filename);
    }
}

// Function to find the oldest file in a directory
char *find_oldest_file(const char *directory) {
    DIR *dir;
    struct dirent *entry;
    char *oldest_filename = NULL;
    time_t oldest_timestamp = 0;

    // Open the directory
    if ((dir = opendir(directory)) == NULL) {
        perror("opendir");
        exit(1);
    }

    // Iterate over all files in the directory
    while ((entry = readdir(dir)) != NULL) {
        char *filename = entry->d_name;
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
            continue;
        }

        // Get the timestamp of the file
        struct stat st;
        if (stat(filename, &st) == 0) {
            time_t timestamp = st.st_mtime;

            // Check if this is the oldest file so far
            if (oldest_timestamp == 0 || timestamp < oldest_timestamp) {
                oldest_filename = filename;
                oldest_timestamp = timestamp;
            }
        }
    }

    // Close the directory
    closedir(dir);

    return oldest_filename;
}
