void createAndManageLTEPacketList(int N, double delayProbability, int defaultFileType) {
    // Initialize the list of LTE packets
    LTE_Packet_T *packetList = (LTE_Packet_T *)malloc(N * sizeof(LTE_Packet_T));
    if (!packetList) {
        printf("Error: Failed to allocate memory for packet list\n");
        return;
    }

    // Initialize the list of NetworkFlows
    NetworkFlow *flowList = (NetworkFlow *)malloc(N * sizeof(NetworkFlow));
    if (!flowList) {
        printf("Error: Failed to allocate memory for flow list\n");
        free(packetList);
        return;
    }

    // Initialize the log file name and directory path
    char logFileName[256];
    char logFileDirectory[256];
    getLogFileInfo(logFileName, logFileDirectory);

    // Loop through each packet in the list
    for (int i = 0; i < N; i++) {
        // Generate a random delay before adding the packet to the list
        double delay = generateDelay(delayProbability);
        sleep(delay);

        // Create a new LTE packet and add it to the list
        LTE_Packet_T *packet = (LTE_Packet_T *)malloc(sizeof(LTE_Packet_T));
        if (!packet) {
            printf("Error: Failed to allocate memory for packet\n");
            free(flowList);
            free(packetList);
            return;
        }
        packet->Packet_ID = i + 1;
        generateIPAddress(&packet->Source_IP, &packet->Destination_IP);
        generatePayload(&packet->Payload);
        addPacketToList(packetList, packet);

        // Create a new NetworkFlow and add it to the list
        NetworkFlow *flow = (NetworkFlow *)malloc(sizeof(NetworkFlow));
        if (!flow) {
            printf("Error: Failed to allocate memory for flow\n");
            free(packetList);
            free(flowList);
            return;
        }
        generateTCPHeader(&flow->TCP_Header);
        generatePayload(&flow->Payload);
        addFlowToList(flowList, flow);
    }

    // Log the operation details to the respective log file
    logOperationDetails(logFileName, logFileDirectory, packetList, flowList);

    // Free the memory allocated for the list of LTE packets and NetworkFlows
    free(packetList);
    free(flowList);
}

// Define the function to generate a random delay based on a probability distribution
double generateDelay(double delayProbability) {
    double delay = 0;
    if (delayProbability > 0) {
        delay = rand() / (RAND_MAX + 1.0) * delayProbability;
    }
    return delay;
}

// Define the function to generate a random IP address
void generateIPAddress(char *sourceIP, char *destinationIP) {
    // Generate a random IPv4 address
    int sourceIPv4 = rand() % 256 + (rand() % 256 << 8);
    int destinationIPv4 = rand() % 256 + (rand() % 256 << 8);
    sprintf(sourceIP, "%d.%d.%d.%d", sourceIPv4 >> 24, (sourceIPv4 >> 16) & 0xFF, (sourceIPv4 >> 8) & 0xFF, sourceIPv4 & 0xFF);
    sprintf(destinationIP, "%d.%d.%d.%d", destinationIPv4 >> 24, (destinationIPv4 >> 16) & 0xFF, (destinationIPv4 >> 8) & 0xFF, destinationIPv4 & 0xFF);
}

// Define the function to generate a random payload
void generatePayload(char *payload) {
    // Generate a random payload of up to 256 bytes
    int payloadSize = rand() % 256 + 1;
    for (int i = 0; i < payloadSize; i++) {
        payload[i] = 'a' + rand() % 26;
    }
}

// Define the function to add a packet to the list
void addPacketToList(LTE_Packet_T *packetList, LTE_Packet_T *packet) {
    // Add the packet to the end of the list
    packetList[packet->Packet_ID - 1] = *packet;
}

// Define the function to add a flow to the list
void addFlowToList(NetworkFlow *flowList, NetworkFlow *flow) {
    // Add the flow to the end of the list
    flowList[flow->TCP_Header.sourcePort - 1] = *flow;
}

// Define the function to log operation details to a file
void logOperationDetails(char *logFileName, char *logFileDirectory, LTE_Packet_T *packetList, NetworkFlow *flowList) {
    // Open the log file for writing
    FILE *logFile = fopen(logFileName, "a");
    if (!logFile) {
        printf("Error: Failed to open log file\n");
        return;
    }

    // Write the operation details to the log file
    fprintf(logFile, "Operation Details:\n");
    for (int i = 0; i < packetList->Packet_ID - 1; i++) {
        LTE_Packet_T *packet = &packetList[i];
        fprintf(logFile, "\tPacket %d: Source IP %s, Destination IP %s, Payload %s\n", packet->Packet_ID, packet->Source_IP, packet->Destination_IP, packet->Payload);
    }
    for (int i = 0; i < flowList->TCP_Header.sourcePort - 1; i++) {
        NetworkFlow *flow = &flowList[i];
        fprintf(logFile, "\tFlow %d: Source Port %d, Destination Port %d, Payload %s\n", flow->TCP_Header.sourcePort, flow->TCP_Header.destinationPort, flow->Payload);
    }

    // Close the log file
    fclose(logFile);
}
