    char *timestamp = asctime(tm);

    // Remove the newline character from the timestamp string
    int len = strlen(timestamp);
    if (timestamp[len - 1] == '\n') {
        timestamp[len - 1] = '\0';
    }

    // Generate a random filename based on the current time
    char *filename = (char *)malloc(256);
    sprintf(filename, "%s_%d.log", timestamp, rand() % 1000000);

