    if (log_file == NULL) {
        return -3;
    }
    for (int i = 0; i < num_packets; i++) {
        fprintf(log_file, "%d %s %s %s\n", lte_packets[i].packet_id, lte_packets[i].source_ip, lte_packets[i].destination_ip, lte_packets[i].payload);
    }
    fclose(log_file);

    // Rotate the log file daily with each log entry limited to 1024 bytes
    struct stat st;
    if (stat(filename, &st) == 0 && st.st_size > 1024 * 1024) {
        char* new_filename = malloc(sizeof(char) * 256);
        sprintf(new_filename, "%s.%d", filename, (int)(time(NULL) / 86400));
        rename(filename, new_filename);
    }

    // Manage the maximum size of the log directory to prevent excessive disk usage by removing the oldest logs when the threshold is exceeded
    DIR* dir = opendir(".");
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, "log", 3) == 0) {
            char* filename = malloc(sizeof(char) * 256);
            sprintf(filename, "%s/%s", dir->d_name, entry->d_name);
            struct stat st;
            if (stat(filename, &st) == 0 && st.st_size > 1024 * 1024) {
                remove(filename);
            }
        }
    }
    closedir(dir);

    // Free the memory allocated for the list of LTE packets and return success
    free(lte_packets);
    return 0;
}
