// Define the maximum number of NFAPI_CRC_INDICATION_PDU_T structures that can be allocated
#define MAX_NFAPI_CREDIT 1024

// Define the structure for storing RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the cache for storing frequently accessed RNTIs
typedef struct {
    int *RNTIs;
    int size;
} RNTI_CACHE;

// Define the memory pool for allocating and deallocating NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures;
    int size;
} MEMORY_POOL;

// Define the function for dynamically managing an array of NFAPI_CRC_INDICATION_PDU_T structures
void manage_array(int N, RNTI_CACHE *cache, MEMORY_POOL *pool) {
    // Check if the input value N exceeds the maximum allowed value
    if (N > MAX_NFAPI_CREDIT) {
        printf("Error: Input value N exceeds the maximum allowed value\n");
        return;
    }

    // Allocate memory for the array of structures
    pool->structures = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (pool->structures == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize the array of structures with random values for CRCFLAG
    for (int i = 0; i < N; i++) {
        pool->structures[i].CRCFLAG = rand() % 2;
    }

    // Add the RNTIs to the cache
    for (int i = 0; i < N; i++) {
        int RNTI = pool->structures[i].RNTI;
        if (!cache_contains(cache, RNTI)) {
            add_to_cache(cache, RNTI);
        }
    }

    // Reuse previously allocated memory where possible
    for (int i = 0; i < N; i++) {
        int RNTI = pool->structures[i].RNTI;
        if (cache_contains(cache, RNTI)) {
            reuse_memory(pool, cache, RNTI);
        }
    }

    // Synchronize shared resources properly for concurrent access from multiple threads
    pthread_mutex_lock(&pool->mutex);
    pool->size = N;
    pthread_mutex_unlock(&pool->mutex);
}

// Check if the cache contains a specific RNTI value
int cache_contains(RNTI_CACHE *cache, int RNTI) {
    for (int i = 0; i < cache->size; i++) {
        if (cache->RNTIs[i] == RNTI) {
            return 1;
        }
    }
    return 0;
}

// Add a new RNTI value to the cache
void add_to_cache(RNTI_CACHE *cache, int RNTI) {
    if (cache->size == MAX_NFAPI_CREDIT) {
        printf("Error: Cache is full\n");
        return;
    }
    cache->RNTIs[cache->size++] = RNTI;
}

// Reuse previously allocated memory for a specific RNTI value
void reuse_memory(MEMORY_POOL *pool, RNTI_CACHE *cache, int RNTI) {
    // Find the index of the structure with the specified RNTI value
    int index = -1;
    for (int i = 0; i < pool->size; i++) {
        if (pool->structures[i].RNTI == RNTI) {
            index = i;
            break;
        }
    }

    // If the structure is found, reuse its memory
    if (index != -1) {
        pool->structures[index] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pool->structures[index] == NULL) {
            printf("Error: Memory allocation failed\n");
            return;
        }
    }
}

// Periodically check and clean up unused memory to maintain optimal performance
void cleanup_memory(MEMORY_POOL *pool, RNTI_CACHE *cache) {
    // Check if any structures are no longer needed
    for (int i = 0; i < pool->size; i++) {
        int RNTI = pool->structures[i].RNTI;
        if (!cache_contains(cache, RNTI)) {
            free(pool->structures[i]);
            pool->structures[i] = NULL;
        }
    }
}
