// Generate a DNS resolution mechanism with support for IPv4 and IPv6 addresses, prioritize IPv6, and support DNS over TLS (DoT) and DNS over HTTPS (DoH) for secure communication channels
DNS_RESOLVER_T *generate_dns_resolver(char **domain_list, int num_domains, int protocol) {
    DNS_RESOLVER_T *resolver = (DNS_RESOLVER_T *)malloc(num_domains * sizeof(DNS_RESOLVER_T));
    for (int i = 0; i < num_domains; i++) {
