}

// Initialize an AES-256-CBC cipher with a given password, generating a cryptographically secure initialization vector (IV) using OpenSSL's secure random number generator
AES_CBC_CTX_T *initialize_aes_cbc(const unsigned char *password, int key_len, int iv_len) {
    AES_CBC_CTX_T *ctx = (AES_CBC_CTX_T *)malloc(sizeof(AES_CBC_CTX_T));
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        handle_error("Failed to initialize AES-256-CBC cipher context");
    }
    unsigned char salt[16];
    RAND_bytes(salt, 16);
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, password, strlen(password), key_len, ctx->key, NULL);
    if (!ctx->key) {
        handle_error("Failed to generate AES-256-CBC encryption key");
    }
    RAND_bytes(ctx->iv, 16);
    if (!ctx->iv) {
        handle_error("Failed to generate AES-256-CBC initialization vector");
    }
    return ctx;
