    if (rnti > UINT_MAX) {
        printf("Error: RNTI value exceeds maximum limit\n");
        return NULL;
    }

    // Allocate memory for the list of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdus);
    if (!pdus) {
        printf("Error: Failed to allocate memory for CRC indication PDUs\n");
        return NULL;
    }

    // Populate the list of CRC indication PDUs
    for (uint16_t i = 0; i < num_pdus; i++) {
        pdus[i].rx_ue_information_tag = 0x0001;
        pdus[i].rnti = rnti + i;
        pdus[i].crc_indication_rel8_tag = (pdus[i].rnti % 5 == 0) ? 1 : 0;
    }

    return pdus;
}

