    session_list_t *new_session = malloc(sizeof(session_list_t));
    if (!new_session) {
        printf("Error: Failed to allocate memory for new session\n");
        return;
    }

    // Initialize the list of CRC indication PDUs for the new session
    new_session->pdu = create_crc_indication_pdus(0, 1);
    if (!new_session->pdu) {
        printf("Error: Failed to initialize CRC indication PDUs for new session\n");
        free(new_session);
        return;
    }

    // Add the new session to the list of active sessions
    new_session->next = NULL;
    if (active_sessions == NULL) {
        active_sessions = new_session;
    } else {
        session_list_t *current = active_sessions;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_session;
    }
}

void destroy_session(uint32_t rnti) {
    // Find the session with the specified RNTI value
    session_list_t *current = active_sessions;
    while (current != NULL && current->pdu->rnti != rnti) {
        current = current->next;
    }

    // If the session was found, destroy it and remove it from the list of active sessions
    if (current != NULL) {
        destroy_crc_indication_pdus(current->pdu);
        free(current);
        current = NULL;
    }
}

// Function to track the number of active sessions and limit the total number of sessions to a configurable maximum
void manage_active_sessions() {
    // Check if the number of active sessions exceeds the maximum limit
    if (active_sessions != NULL && num_active_sessions > MAX_SESSIONS) {
        printf("Error: Maximum number of active sessions exceeded\n");
        return;
    }

    // Increment the number of active sessions
    num_active_sessions++;
