// Define the maximum number of threads to be used in the pool
#define MAX_THREADS 16

// Define the structure for holding packet metadata
typedef struct {
    int packet_id;
    size_t data_size;
    char* destination_address;
} TX_PACKET;

// Define the queue structure for holding packets to be processed
typedef struct {
    TX_PACKET* packets[MAX_THREADS];
    int head;
    int tail;
