    sem_t empty;
} PACKET_QUEUE;

// Define the thread pool structure for managing worker threads
typedef struct {
    pthread_t* threads[MAX_THREADS];
    int num_threads;
    sem_t mutex;
    sem_t full;
} THREAD_POOL;

// Function to allocate and populate a TX_PACKET structure
TX_PACKET* alloc_packet(int packet_id, size_t data_size, char* destination_address) {
    // Allocate memory for the TX_PACKET structure
    TX_PACKET* packet = malloc(sizeof(TX_PACKET));
    if (!packet) {
        return NULL;
    }

    // Populate the TX_PACKET structure with the given metadata
    packet->packet_id = packet_id;
    packet->data_size = data_size;
    packet->destination_address = destination_address;

    return packet;
}

// Function to validate the data size against the maximum limit
int validate_data_size(size_t data_size) {
    if (data_size > MAX_DATA_SIZE) {
        return -1;
    }
    return 0;
}

// Function to handle errors gracefully by rejecting the packet and logging a warning message
void handle_error(TX_PACKET* packet, char* error_message) {
    printf("Error: %s\n", error_message);
    free(packet);
}

// Function to ensure thread safety by using semaphores for mutual exclusion and synchronization
void acquire_mutex(sem_t* mutex) {
    sem_wait(mutex);
}

void release_mutex(sem_t* mutex) {
    sem_post(mutex);
}

// Function to ensure thread safety by using semaphores for mutual exclusion and synchronization
void acquire_full(sem_t* full) {
    sem_wait(full);
}

void release_full(sem_t* full) {
    sem_post(full);
}

// Function to track the number of active threads and limit the total number of threads to a configurable maximum
int get_num_threads() {
    return num_threads;
}

void set_num_threads(int num_threads) {
    this->num_threads = num_threads;
}

// Function to implement a mechanism for logging detailed information about each processed packet, including processing start and end times
void log_packet(TX_PACKET* packet) {
    // Log the packet metadata
    printf("Packet ID: %d\n", packet->packet_id);
    printf("Data Size: %zu\n", packet->data_size);
    printf("Destination Address: %s\n", packet->destination_address);

    // Log the processing start and end times
    struct timeval start, end;
    gettimeofday(&start, NULL);
    process_packet(packet);
    gettimeofday(&end, NULL);
    printf("Processing Time: %ld ms\n", (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec - start.tv_usec) / 1000);
}

// Function to implement a mechanism for logging detailed information about each processed packet, including processing start and end times
void log_error(char* error_message) {
    printf("Error: %s\n", error_message);
}

// Function to handle asynchronous logging by using a separate thread for logging
void async_log(TX_PACKET* packet, char* error_message) {
    // Create a new thread for logging the packet metadata and processing time
    pthread_t log_thread;
    pthread_create(&log_thread, NULL, log_packet, packet);

    // If an error occurred, create a new thread for logging the error message
    if (error_message) {
        pthread_t error_thread;
        pthread_create(&error_thread, NULL, log_error, error_message);
    }
}

// Function to integrate the function into a larger network communication framework that supports multiple concurrent sessions, each with its own thread pool and queue
void process_packet(TX_PACKET* packet) {
    // Acquire the mutex for the session's queue
    acquire_mutex(&queue->mutex);

    // Add the packet to the end of the queue
    queue->packets[queue->tail] = packet;
    queue->tail = (queue->tail + 1) % MAX_THREADS;

    // Release the mutex for the session's queue
    release_mutex(&queue->mutex);

    // Acquire the full semaphore to signal that a new packet has been added to the queue
    acquire_full(&queue->full);

    // If there are no active threads, create a new thread for processing the packet
    if (get_num_threads() == 0) {
        pthread_t thread;
        pthread_create(&thread, NULL, process_packet, queue);
    }
}

// Function to manage a pool of worker threads to process a queue of TX_PACKET structures
void* thread_pool(void* arg) {
    // Cast the argument to the correct type
    PACKET_QUEUE* queue = (PACKET_QUEUE*)arg;

    // Loop indefinitely until the program is terminated
    while (1) {
        // Acquire the full semaphore to wait for a new packet to be added to the queue
        acquire_full(&queue->full);

        // If there are no packets in the queue, release the full semaphore and continue
        if (queue->head == queue->tail) {
            release_full(&queue->full);
            continue;
        }

        // Acquire the mutex for the session's queue
        acquire_mutex(&queue->mutex);

        // Get the next packet from the head of the queue
        TX_PACKET* packet = queue->packets[queue->head];
        queue->head = (queue->head + 1) % MAX_THREADS;

        // Release the mutex for the session's queue
        release_mutex(&queue->mutex);

        // Validate the data size of the packet against the maximum limit
        if (validate_data_size(packet->data_size) == -1) {
            handle_error(packet, "Data size exceeds maximum limit");
            continue;
        }

        // Process the packet and log detailed information about it
        process_packet(packet);
    }
}
