// Define the connection struct to hold essential information for each connection
typedef struct {
    int socket_descriptor;
    enum { CONNECTED, LISTENING } state;
    unsigned long timeout;
} connection_t;

// Define a pool of connections to handle multiple concurrent TCP connections efficiently
static connection_t *connections = NULL;
static size_t num_connections = 0;
static size_t max_connections = 10000;

// Function to initialize and configure the network interface for handling multiple concurrent TCP connections
void init_network_interface(void) {
    // Allocate memory for the pool of connections
    connections = (connection_t *)malloc(max_connections * sizeof(connection_t));
    if (!connections) {
        perror("Failed to allocate memory for connection pool");
        exit(1);
    }

    // Initialize each connection struct with default values
    for (size_t i = 0; i < max_connections; i++) {
        connections[i].socket_descriptor = -1;
        connections[i].state = CONNECTED;
        connections[i].timeout = 5000; // 5 seconds
    }

    // Set up the network interface for handling multiple concurrent TCP connections
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        exit(1);
    }

    // Set the maximum number of concurrent connections
    int max_conn = setsockopt(sockfd, SOL_SOCKET, SO_MAXCONN, &max_connections, sizeof(max_connections));
    if (max_conn < 0) {
        perror("Failed to set maximum number of concurrent connections");
        exit(1);
    }

    // Set the socket options for reuse address and port
    int reuse = 1;
    int ret = setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse));
    if (ret < 0) {
        perror("Failed to set socket options");
        exit(1);
    }

    // Bind the socket to a specific IP address and port
    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_address.sin_addr);
    ret = bind(sockfd, (struct sockaddr *)&server_address, sizeof(server_address));
    if (ret < 0) {
        perror("Failed to bind socket");
        exit(1);
    }

    // Listen for incoming connections
    ret = listen(sockfd, max_connections);
    if (ret < 0) {
        perror("Failed to listen for incoming connections");
        exit(1);
    }
}

// Function to handle a single connection and process its requests
void *handle_connection(void *arg) {
    // Get the socket descriptor from the argument
    int sockfd = (int)(long)arg;

    // Set up the buffer for reading data from the client
    char buffer[1024];
    memset(buffer, 0, sizeof(buffer));

    // Read data from the client until the end of the request is reached
    ssize_t num_bytes = read(sockfd, buffer, sizeof(buffer) - 1);
    if (num_bytes < 0) {
        perror("Failed to read data from client");
        return NULL;
    }

    // Process the request and send a response back to the client
    char *response = "Hello, world!";
    ssize_t num_sent = write(sockfd, response, strlen(response));
    if (num_sent < 0) {
        perror("Failed to send data to client");
        return NULL;
    }

    // Close the socket and free the memory for the connection struct
    close(sockfd);
    free((void *)arg);

    return NULL;
}

// Function to handle multiple concurrent connections and process their requests
void *handle_connections(void *arg) {
    // Get the number of connections from the argument
    int num_connections = (int)(long)arg;

    // Create a pool of threads for handling each connection
    pthread_t *threads = (pthread_t *)malloc(num_connections * sizeof(pthread_t));
    if (!threads) {
        perror("Failed to allocate memory for thread pool");
        exit(1);
    }

    // Create a connection struct for each thread and set its socket descriptor
    for (int i = 0; i < num_connections; i++) {
        connections[i].socket_descriptor = accept(sockfd, NULL, NULL);
        if (connections[i].socket_descriptor < 0) {
            perror("Failed to accept connection");
            exit(1);
        }
    }

    // Create a thread for each connection and start handling its requests
    for (int i = 0; i < num_connections; i++) {
        pthread_create(&threads[i], NULL, handle_connection, (void *)&connections[i]);
    }

    // Wait for all threads to finish before freeing the memory for the connection structs
    for (int i = 0; i < num_connections; i++) {
        pthread_join(threads[i], NULL);
    }

    free((void *)arg);

    return NULL;
}

// Function to dynamically resize the pool of connections based on system resource availability and application demand
void resize_connection_pool(size_t new_max_connections) {
    // Check if the new maximum number of connections is greater than the current maximum
    if (new_max_connections > max_connections) {
        // Allocate memory for the additional connection structs
        size_t num_additional = new_max_connections - max_connections;
        connection_t *additional = (connection_t *)malloc(num_additional * sizeof(connection_t));
        if (!additional) {
            perror("Failed to allocate memory for additional connections");
            exit(1);
        }

        // Initialize each additional connection struct with default values
        for (size_t i = 0; i < num_additional; i++) {
            additional[i].socket_descriptor = -1;
            additional[i].state = CONNECTED;
            additional[i].timeout = 5000; // 5 seconds
        }

        // Add the additional connection structs to the pool of connections
        for (size_t i = max_connections; i < new_max_connections; i++) {
            connections[i] = additional[i - max_connections];
        }

        // Free the memory for the additional connection structs
        free((void *)additional);
    } else if (new_max_connections < max_connections) {
        // Check if the new maximum number of connections is less than the current maximum
        size_t num_removed = max_connections - new_max_connections;

        // Remove the last connection structs from the pool of connections
        for (size_t i = 0; i < num_removed; i++) {
            close(connections[new_max_connections + i].socket_descriptor);
            connections[new_max_connections + i] = NULL;
        }
    }

    // Update the maximum number of connections
    max_connections = new_max_connections;
}

// Function to monitor memory usage and prevent leaks, ensuring optimal performance under varying loads
void monitor_memory(void) {
    // Check if the current memory usage is greater than the maximum allowed
    if (get_memory_usage() > max_memory_usage) {
        // Resize the pool of connections to reduce memory usage
        resize_connection_pool(max_connections - 100);
    }
}

