        // Implement error handling for malformed lines or missing credentials
        if (strncmp(line, "username=", 9) == 0) {
            creds.username = strdup(line + 9);
        } else if (strncmp(line, "password=", 9) == 0) {
            creds.password = strdup(line + 9);
