#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <json-c/json.h>
#include <pthread.h>
#include <time.h>

// Define the maximum number of concurrent HTTP requests
#define MAX_CONCURRENT_REQUESTS 5

// Define the maximum number of HTTP requests per minute
#define MAX_HTTP_REQUESTS_PER_MINUTE 20

// Define the cache timeout in seconds
#define CACHE_TIMEOUT 3600

// Define the rate limiter interval in milliseconds
#define RATE_LIMITER_INTERVAL 1000

// Define the logging framework
#include "logging.h"

// Define the cache structure
struct cache {
    char *url;
    json_object *metadata;
    time_t timestamp;
};

// Define the rate limiter structure
struct rate_limiter {
    int requests;
    time_t last_request;
};

// Function to fetch resource metadata
char *fetchResourceMetadata(const char *url) {
    // Initialize the cache and rate limiter structures
    static struct cache cache[MAX_CONCURRENT_REQUESTS];
    static struct rate_limiter rate_limiter;

    // Check if the URL is already in the cache
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        if (cache[i].url == url) {
            return json_object_get_string(cache[i].metadata);
        }
    }

    // Check if the rate limiter allows a new request
    time_t current_time = time(NULL);
    if ((current_time - rate_limiter.last_request) * 1000 < RATE_LIMITER_INTERVAL) {
        return "";
    }

    // Increment the rate limiter requests counter
    rate_limiter.requests++;

    // Initialize the CURL handle and set the URL
    CURL *curl = curl_easy_init();
    curl_easy_setopt(curl, CURLOPT_URL, url);

    // Set the HTTP headers
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Accept: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Perform the HTTP request and check for errors
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        return "";
    }

    // Get the response code and check for success
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code != 200) {
        return "";
    }

    // Get the response body as a JSON object
    json_object *response = NULL;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_BODY, &response);

    // Check if the response is valid JSON
    if (!json_object_is_type(response, json_type_object)) {
        return "";
    }

    // Parse the JSON object and extract the metadata
    json_object *metadata = NULL;
    json_object_object_get_ex(response, "metadata", &metadata);

    // Check if the metadata is valid JSON
    if (!json_object_is_type(metadata, json_type_object)) {
        return "";
    }

    // Create a new cache entry and add it to the cache
    struct cache *new_cache = malloc(sizeof(struct cache));
    new_cache->url = strdup(url);
    new_cache->metadata = json_object_get(metadata);
    new_cache->timestamp = time(NULL);
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        if (cache[i].url == NULL) {
            cache[i] = *new_cache;
            break;
        }
    }

    // Clean up the CURL handle and return the metadata
    curl_easy_cleanup(curl);
    free(new_cache);
    return json_object_get_string(metadata);
}

// Function to update the cache with new metadata
void updateCache(const char *url, json_object *metadata) {
    // Check if the URL is already in the cache
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        if (cache[i].url == url) {
            cache[i].metadata = json_object_get(metadata);
            cache[i].timestamp = time(NULL);
            return;
        }
    }

    // Create a new cache entry and add it to the cache
    struct cache *new_cache = malloc(sizeof(struct cache));
    new_cache->url = strdup(url);
    new_cache->metadata = json_object_get(metadata);
    new_cache->timestamp = time(NULL);
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        if (cache[i].url == NULL) {
            cache[i] = *new_cache;
            break;
        }
    }
}

// Function to check the cache for metadata
json_object *checkCache(const char *url) {
    // Check if the URL is already in the cache
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        if (cache[i].url == url) {
            return json_object_get(cache[i].metadata);
        }
    }

    // Return an empty JSON object if the URL is not in the cache
    json_object *empty = json_object_new_object();
    return empty;
}

// Function to handle rate limiting
void rateLimiter(const char *url) {
    // Check if the rate limiter allows a new request
    time_t current_time = time(NULL);
    if ((current_time - rate_limiter.last_request) * 1000 < RATE_LIMITER_INTERVAL) {
        return;
    }

    // Increment the rate limiter requests counter and update the last request timestamp
    rate_limiter.requests++;
    rate_limiter.last_request = current_time;
}

// Function to handle logging
void logRequest(const char *url, json_object *metadata) {
    // Log the request attempt and outcome
    LOG("Request: %s\n", url);
    if (json_object_is_type(metadata, json_type_object)) {
        LOG("Metadata: %s\n", json_object_get_string(metadata));
    } else {
        LOG("No metadata found for URL\n");
    }
}
```
This code implements the `fetchResourceMetadata` function that retrieves metadata for a given resource URL using HTTP/HTTPS requests. The function uses the `curl` library to perform the HTTP requests and the `json-c` library to parse the JSON responses. It also includes a cache mechanism to reduce redundant requests and a rate limiter to prevent overwhelming external services.

The cache is implemented as an array of `struct cache` structures, where each structure contains the URL, metadata, and timestamp for a given resource. The cache is updated with new metadata using the `updateCache` function, which checks if the URL is already in the cache before adding a new entry. The `checkCache` function is used to check if the URL is already in the cache before performing an HTTP request.

The rate limiter is implemented as a `struct rate_limiter` structure that tracks the number of requests and the last request timestamp. The `rateLimiter` function checks if the rate limiter allows a new request based on the current time and the last request timestamp.

The logging framework is used to log every request attempt along with its outcome using the `logRequest` function. This function logs the URL and metadata for each request, or indicates that no metadata was found for the URL if the response is not valid JSON.']

