    packet->payload = (char*)malloc(payload_len + 1);
    if (!packet->payload) {
        fprintf(stderr, "Failed to allocate memory for payload\n");
        return;
    }

    // Copy the payload data into the packet
    memcpy(packet->payload, payload, payload_len + 1);
}

// Function to verify the integrity of a data packet using a checksum algorithm
bool verify_data_packet(DataPacket* packet) {
    // Calculate the checksum for the packet
