        # Replace the placeholder with the actual value in the configuration file
        subprocess.run(["sed", "-i", f"s/{key}/{value}/g", filepath])

# Function to add a new line with an encrypted password and create a new file with the modifications
def add_password(filepath):
    # Read the contents of the configuration file
    with open(filepath, "r") as f:
        contents = f.read()

    # Add a new line with the encrypted password to the end of the file
    new_contents = f"{contents}\npassword={encrypt_password('actual_value')}"

    # Write the modified contents back to the configuration file
    with open(filepath, "w") as f:
        f.write(new_contents)
