        strcpy(packets[i].Payload, payload);

        // Log the operation details to a log file
        char filename[256];
        sprintf(filename, "%s/%s-%d.log", log_directory, source_ip, i + 1);
        FILE* fp = fopen(filename, "a");
        if (fp == NULL) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
        fprintf(fp, "%d %s %s %s\n", packets[i].Packet_ID, source_ip, destination_ip, payload);
        fclose(fp);
    }

    // Free the memory allocated for the list of packets
    free(packets);
}

// Function to generate a random IP address
char* generate_random_ip() {
    char* ip = (char*)malloc(16 * sizeof(char));
    sprintf(ip, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    return ip;
}

// Function to generate a random payload of a given size
char* generate_random_payload(int size) {
    char* payload = (char*)malloc(size * sizeof(char));
    for (int i = 0; i < size; i++) {
        payload[i] = rand() % 256;
    }
    return payload;
}

// Function to derive the filename of a log file from the current timestamp
char* get_log_filename(char* directory, char* extension) {
    // Get the current time and date
    struct tm* timeinfo = localtime(&time);
    int year = timeinfo->tm_year + 1900;
    int month = timeinfo->tm_mon + 1;
    int day = timeinfo->tm_mday;

    // Generate a random filename with the current date and time
    char* filename = (char*)malloc(256 * sizeof(char));
    sprintf(filename, "%s/%d-%02d-%02d-%s", directory, year, month, day, extension);

    // Ensure the filename is unique among all files in the current directory
    int i = 1;
    while (access(filename, F_OK) == 0) {
        sprintf(filename, "%s/%d-%02d-%02d-%s-%d", directory, year, month, day, extension, i);
        i++;
    }

    // Return the generated filename
    return filename;
}
