        newStruct->crcIndicationRel8.tag = CRC_INDICATION_REL8_TAG;
        newStruct->crcIndicationRel8.length = 0;
        newStruct->crcIndicationRel8.crcFlag = rand() % 2;

        // Add the structure to the list
        if (list->head == NULL) {
            list->head = newStruct;
            list->tail = newStruct;
        } else {
            list->tail->next = newStruct;
            list->tail = newStruct;
        }
    }

    // Validate the integrity of the list at regular intervals
    validateList(list);

    return list;
}

// Define a function to validate the integrity of the linked list
void validateList(NFAPI_CRC_INDICATION_LIST_T *list) {
