        while (temp != NULL) {
            if (temp->rnti == current->rnti) {
                printf("Duplicate RNTI found in list. Removing offending structure.\n");
                temp = removeStruct(current);
            } else {
                temp = temp->next;
            }
        }
        current = current->next;
    }
}

// Define a function to remove a structure from the linked list
NFAPI_CRC_INDICATION_PDU_T* removeStruct(NFAPI_CRC_INDICATION_PDU_T *structToRemove) {
    NFAPI_CRC_INDICATION_PDU_T *temp = structToRemove->next;
    free(structToRemove);
    return temp;
}

// Define a function to serialize the linked list to a file in binary format
void serializeList(NFAPI_CRC_INDICATION_LIST_T *list, char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error opening file for serialization\n");
        return;
    }

    // Write the number of structures in the list to the file
    int numStructs = 0;
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        numStructs++;
        current = current->next;
    }
    fwrite(&numStructs, sizeof(int), 1, file);

    // Write each structure in the list to the file
    current = list->head;
    while (current != NULL) {
        fwrite(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

