void read_text_file(char *filename) {
    // Open the input file for reading
    FILE *input = fopen(filename, "r");
    if (input == NULL) {
        printf("Error: Failed to open input file\n");
        return;
    }

    // Read each line of the file and print its contents
    char line[1024];
    while (fgets(line, 1024, input)) {
        // Split the line into fields using a comma delimiter
        char *fields = strtok(line, ",");
        while (fields != NULL) {
            printf("%s\n", fields);
            fields = strtok(NULL, ",");
        }
    }

    // Close the input file
    fclose(input);
}
