#include <string>
#include <vector>

using namespace boost::asio;
using namespace std;

// Define a custom round-robin algorithm for load balancing
class RoundRobinLoadBalancer {
public:
    // Constructor
    RoundRobinLoadBalancer(const vector<string>& servers) : servers_(servers), current_server_index_(0) {}

    // Get the next server to send a request to
    string getNextServer() {
        boost::lock_guard<boost::mutex> lock(mutex_);
        if (current_server_index_ >= servers_.size()) {
            current_server_index_ = 0;
        }
        return servers_[current_server_index_++];
    }

private:
    vector<string> servers_;
    size_t current_server_index_;
    boost::mutex mutex_;
};

// Define a configuration file for managing server addresses dynamically
class ServerConfig {
public:
    // Constructor
    ServerConfig(const string& config_file) : config_file_(config_file) {}

    // Load the configuration file and initialize the server list
    void load() {
        ifstream config_file(config_file_);
        if (!config_file.is_open()) {
            throw runtime_error("Failed to open configuration file");
        }
        string line;
        while (getline(config_file, line)) {
            servers_.insert(line);
        }
    }

    // Add a new server to the list
    void addServer(const string& server) {
        boost::lock_guard<boost::mutex> lock(mutex_);
        servers_.insert(server);
    }

    // Remove a server from the list
    void removeServer(const string& server) {
        boost::lock_guard<boost::mutex> lock(mutex_);
        servers_.erase(server);
    }

    // Get the current list of servers
    const set<string>& getServers() const {
        return servers_;
    }

private:
    string config_file_;
    set<string> servers_;
    boost::mutex mutex_;
};

// Define a class for handling GET requests to the server
class SandeshClient {
public:
    // Constructor
    SandeshClient(const string& config_file) : config_(config_file), load_balancer_(new RoundRobinLoadBalancer(config_.getServers())) {}

    // Send a GET request to the server and return the response
    string sendRequest(const string& url, const string& headers = "") {
        string server = load_balancer_->getNextServer();
        io_service io;
        ip::tcp::resolver resolver(io);
        auto endpoint_iterator = resolver.resolve(server, "http");
        boost::asio::connect(socket_, endpoint_iterator);
        http::request<http::string_body> request;
        request.set(http::field::host, server);
        request.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
        request.set(http::field::accept, "*/*");
        request.set(http::field::content_type, "application/json");
        request.method(http::verb::get);
        request.target(url);
        request.body() = headers;
        request.prepare();
        http::write(socket_, request);
        boost::beast::flat_buffer buffer;
        http::response<http::string_body> response;
        http::read(socket_, buffer, response);
        return response.body();
    }

private:
    ServerConfig config_;
    io_service io;
    ip::tcp::socket socket_;
    unique_ptr<RoundRobinLoadBalancer> load_balancer_;
};

