// Define a class for managing proxy sessions and handling server unavailability gracefully
class ProxySessionManager {
public:
    // Constructor
    ProxySessionManager(const string& config_file) : config_(config_file), interface_table_(new TestDoubleInterfaceTable()) {}

    // Send a GET request to the server and handle server unavailability gracefully
    string sendRequest(const string& url, const string& headers = "") {
        string vm_uuid;
        if (!interface_table_->FindVmUuidFromMetadataIp(url, vm_uuid)) {
            // Server is unavailable, retry with exponential backoff
            boost::this_thread::sleep_for(boost::chrono::seconds(1 << retry_count_));
            if (retry_count_ < 5) {
                retry_count_++;
                return sendRequest(url, headers);
            } else {
                // Server is still unavailable after retries, circuit breaker pattern
                return "";
            }
        }
        string server = config_.getServers().find(vm_uuid)->second;
        io_service io;
        ip::tcp::resolver resolver(io);
        auto endpoint_iterator = resolver.resolve(server, "http");
        boost::asio::connect(socket_, endpoint_iterator);
        http::request<http::string_body> request;
        request.set(http::field::host, server);
        request.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
        request.set(http::field::accept, "*/*");
        request.set(http::field::content_type, "application/json");
        request.method(http::verb::get);
        request.target(url);
        request.body() = headers;
        request.prepare();
        http::write(socket_, request);
        boost::beast::flat_buffer buffer;
        http::response<http::string_body> response;
        http::read(socket_, buffer, response);
        return response.body();
    }

private:
    ServerConfig config_;
    io_service io;
    ip::tcp::socket socket_;
    unique_ptr<TestDoubleInterfaceTable> interface_table_;
    int retry_count_ = 0;
};

// Define a class for maintaining rolling statistics of the last 100 requests
class RequestStatistics {
public:
    // Constructor
    RequestStatistics() : request_count_(0), successful_requests_(0), failed_requests_(0) {}

    // Increment the number of requests and update the statistics accordingly
    void incrementRequestCount(bool success) {
        boost::lock_guard<boost::mutex> lock(mutex_);
        request_count_++;
        if (success) {
            successful_requests_++;
        } else {
            failed_requests_++;
        }
    }

    // Get the current statistics
    const pair<int, int>& getStatistics() const {
        return make_pair(request_count_, successful_requests_);
    }

private:
    boost::mutex mutex_;
    int request_count_;
    int successful_requests_;
    int failed_requests_;
};

