    LoggingManager() : log_(new Logger()) {}

    // Record a request and response metric in the logging system
    void recordMetric(const string& url, const string& headers, const string& body) {
        boost::lock_guard<boost::mutex> lock(mutex_);
        log_->log("Request: " + url + "\n" + headers + "\n" + body);
    }

private:
    unique_ptr<Logger> log_;
};

