        private readonly Dictionary<string, string> _defaultNamespaceMappings = new Dictionary<string, string>();
        private readonly Dictionary<string, string> _queryParameters = new Dictionary<string, string>();
        private readonly object _syncRoot = new object();

        public XmlDocumentManager() { }

        public void AddDocument(string documentName, XDocument document)
        {
            lock (_syncRoot)
            {
                if (!_documents.ContainsKey(documentName))
                {
                    _documents.Add(documentName, document);
                }
            }
        }

        public void RemoveDocument(string documentName)
        {
            lock (_syncRoot)
            {
                if (_documents.ContainsKey(documentName))
                {
                    _documents.Remove(documentName);
                }
            }
        }

        public XDocument GetDocument(string documentName)
        {
            lock (_syncRoot)
            {
                return _documents[documentName];
            }
        }

        public IEnumerable<XElement> QueryElements(string query, string documentName = null)
        {
            lock (_syncRoot)
            {
                var elements = new List<XElement>();

                if (documentName == null)
                {
                    foreach (var doc in _documents.Values)
                    {
                        elements.AddRange(QueryElements(query, doc));
                    }
                }
                else
                {
                    var doc = GetDocument(documentName);
                    if (doc != null)
                    {
                        elements.AddRange(QueryElements(query, doc));
                    }
                }

                return elements;
            }
        }

        private IEnumerable<XElement> QueryElements(string query, XDocument document)
        {
            var nsManager = new XmlNamespaceManager(new NameTable());
            foreach (var prefix in _defaultNamespaceMappings.Keys)
