                    var schemaSet = new XmlSchemaSet();
                    schemaSet.Add("http://www.w3.org/2001/XMLSchema", "XMLSchema.xsd");
                    doc.Validate(schemaSet, (o, e) => Console.WriteLine($"{e.Severity} - {e.Message}"));
                }
            }
        }

        public void SerializeState()
        {
            lock (_syncRoot)
            {
                var serializer = new XmlSerializer(typeof(Dictionary<string, XDocument>));
                using (var stream = new FileStream("state.xml", FileMode.Create))
                {
                    serializer.Serialize(stream, _documents);
                }
            }
        }

        public void DeserializeState()
        {
            lock (_syncRoot)
            {
                if (File.Exists("state.xml"))
                {
                    var serializer = new XmlSerializer(typeof(Dictionary<string, XDocument>));
                    using (var stream = new FileStream("state.xml", FileMode.Open))
                    {
                        _documents = (Dictionary<string, XDocument>)serializer.Deserialize(stream);
                    }
                }
            }
        }

        public void AddDefaultNamespaceMapping(string prefix, string namespaceUri)
        {
            lock (_syncRoot)
            {
                _defaultNamespaceMappings[prefix] = namespaceUri;
            }
        }

        public void RemoveDefaultNamespaceMapping(string prefix)
        {
            lock (_syncRoot)
            {
                if (_defaultNamespaceMappings.ContainsKey(prefix))
                {
                    _defaultNamespaceMappings.Remove(prefix);
                }
            }
        }

