        private readonly ISessionService _sessionService;
        private readonly IElementService _elementService;

        public HttpPostController(IHttpClientFactory httpClientFactory, ILogger<HttpPostController> logger, ISessionService sessionService, IElementService elementService)
        {
            _httpClientFactory = httpClientFactory;
            _logger = logger;
            _sessionService = sessionService;
            _elementService = elementService;
        }

        [HttpPost]
        public async Task<IActionResult> UpdateElement(string userId, string sessionToken, int pageSectionId, int elementId, string htmlContent)
        {
            try
            {
                // Validate the session token for authentication and authorization
                var session = await _sessionService.GetSessionAsync(sessionToken);
                if (session == null || !session.UserId.Equals(userId))
                {
                    return Unauthorized();
                }

                // Ensure that the user has the necessary permissions to update the specified element
                var element = await _elementService.GetElementAsync(pageSectionId, elementId);
                if (element == null || !element.UserId.Equals(userId))
                {
                    return Forbid();
                }

                // Update the element's HTML content
                var updatedContent = await _elementService.UpdateElementHtmlAsync(pageSectionId, elementId, htmlContent);
                if (updatedContent == null)
                {
                    return BadRequest("Failed to update element");
                }

                // Log the request details for auditing purposes
                var logEntry = new HttpPostLogEntry()
                {
                    UserId = userId,
                    SessionToken = sessionToken,
                    PageSectionId = pageSectionId,
                    ElementId = elementId,
                    HtmlContent = htmlContent,
                    UpdatedContent = updatedContent
                };
                await _logger.LogAsync(logEntry);

                // Construct a response indicating whether the update was successful and whether the page should be refreshed
                return Ok(new { Success = true, RefreshPage = false });
            }
            catch (Exception ex)
            {
                // Handle transient errors by retrying up to three times with random intervals between 100ms and 500ms
                if (ex is HttpRequestException || ex is DbConnectionException)
                {
                    var retryCount = 3;
                    while (retryCount > 0)
                    {
                        try
                        {
                            return await UpdateElement(userId, sessionToken, pageSectionId, elementId, htmlContent);
                        }
                        catch (Exception innerEx) when (innerEx is HttpRequestException || innerEx is DbConnectionException)
                        {
                            retryCount--;
                            if (retryCount == 0)
                            {
                                throw;
                            }
                            await Task.Delay(new Random().Next(100, 500));
                        }
                    }
                }

                // Handle all other errors by returning a detailed error response
                return BadRequest(new { Success = false, ErrorMessage = ex.Message });
            }
        }
    }
}
