        public HttpPostHandler(ISessionService sessionService, IElementService elementService, ILogger<HttpPostHandler> logger)
        {
            _sessionService = sessionService;
            _elementService = elementService;
            _logger = logger;
        }

        public async Task<IActionResult> HandleAsync(string userId, string sessionToken, int pageSectionId, List<int> elementIds, string htmlContent)
        {
            // Validate the session token for authentication and authorization
            if (!await _sessionService.IsValidSessionTokenAsync(userId, sessionToken))
            {
                return Unauthorized();
            }

            // Ensure that the user has the necessary permissions to update the specified elements
            var elementPermissions = await _elementService.GetElementPermissionsAsync(userId, elementIds);
            if (!elementPermissions.All(p => p.CanUpdate))
            {
                return Forbid();
            }

            // Call a service class to update the elements' HTML content in a batch
            var batch = new Batch<ElementUpdate>
            {
                ElementIds = elementIds,
                HtmlContent = htmlContent
            };

            try
            {
                await _elementService.UpdateElementsAsync(batch);
            }
            catch (Exception ex)
            {
                // Log the error asynchronously to avoid blocking the main thread
                _logger.LogError(ex, "Failed to update elements in batch");

                // Retry the operation with exponential backoff starting from 100ms and doubling the interval for each retry
                var retryCount = 5;
                while (retryCount > 0)
                {
                    try
                    {
                        await _elementService.UpdateElementsAsync(batch);
                        break;
                    }
                    catch (Exception ex)
                    {
                        // Log the error asynchronously to avoid blocking the main thread
                        _logger.LogError(ex, "Failed to update elements in batch");

                        retryCount--;
                        if (retryCount == 0)
                        {
                            return StatusCode(500);
                        }

                        // Exponential backoff with jitter
                        var delay = Math.Pow(2, retryCount - 1) * 100;
                        await Task.Delay(delay + (new Random().Next(0, delay / 2)));
                    }
                }
            }

            // Construct a response indicating whether the batch update was successful and whether the page should be refreshed
            var response = new BatchUpdateResponse
            {
                Success = true,
                RefreshPage = false
            };

            return Ok(response);
        }
    }
}
