            _elementService = elementService;
            _logger = logger;
        }

        public async Task<HttpResponseMessage> HandleAsync(string userId, string sessionToken, int pageSectionId, List<int> elementIds, string htmlContent)
        {
            // Validate the session token for authentication and authorization
            if (!await _sessionService.ValidateSessionTokenAsync(userId, sessionToken))
            {
                return new HttpResponseMessage(HttpStatusCode.Unauthorized);
            }

            // Ensure that the user has the necessary permissions to update the specified elements
            var elementPermissions = await _elementService.GetElementPermissionsAsync(userId, elementIds);
            if (!elementPermissions.All(p => p.CanUpdate))
            {
                return new HttpResponseMessage(HttpStatusCode.Forbidden);
            }

            // Call the service class to update the elements' HTML content in a batch
            var batchResult = await _elementService.UpdateElementsAsync(userId, elementIds, htmlContent);

            // Handle partial updates by constructing a response indicating whether the batch update was successful and whether the page should be refreshed
            if (batchResult.Any(r => !r.Success))
            {
                return new HttpResponseMessage(HttpStatusCode.BadRequest)
                {
                    Content = new StringContent(JsonConvert.SerializeObject(batchResult), Encoding.UTF8, "application/json")
                };
            }

            // Handle concurrent updates gracefully by implementing a retry mechanism that allows up to five retries in case of transient errors
            var retryCount = 0;
            while (retryCount < 5)
            {
                try
                {
                    await _elementService.UpdateElementsAsync(userId, elementIds, htmlContent);
                    break;
                }
                catch (Exception ex) when (ex is HttpRequestException || ex is DbConnectionException)
                {
                    retryCount++;
                    await Task.Delay(retryCount * 100);
                }
            }

            // Log each retry asynchronously to avoid blocking the main thread
            _logger.LogInformation($"Retrying batch update for user {userId} with session token {sessionToken} and element IDs {string.Join(", ", elementIds)}");

            // Construct a response indicating whether the batch update was successful and whether the page should be refreshed
            return new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("Batch update successful", Encoding.UTF8, "text/plain")
            };
        }
    }
}
