#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

// Define the structure for a LTE PHY Layer Measurement Record
typedef struct {
    int ci;
    float rssi;
    float snr;
    int cqi;
} measurement_record_t;

// Define the dynamic list of measurement records
measurement_record_t *records = NULL;
int num_records = 0;

// Define the minimum RSRP threshold for filtering
float min_rsrp = -120.0f;

// Define the lock for protecting critical sections
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the measurement records list
void init_records(int num_records) {
    // Allocate memory for the measurement records list
    records = (measurement_record_t *)malloc(num_records * sizeof(measurement_record_t));
    if (!records) {
        printf("Error: Failed to allocate memory for measurement records\n");
        exit(1);
    }
}

// Function to add a new measurement record to the list
void add_record(int ci, float rssi, float snr, int cqi) {
    // Lock the critical section
    pthread_mutex_lock(&lock);

    // Check if the list is full
    if (num_records >= MAX_RECORDS) {
        printf("Error: Measurement records list is full\n");
        exit(1);
    }

    // Add the new record to the list
    records[num_records].ci = ci;
    records[num_records].rssi = rssi;
    records[num_records].snr = snr;
    records[num_records].cqi = cqi;

    // Increment the number of records
    num_records++;

    // Unlock the critical section
    pthread_mutex_unlock(&lock);
}

// Function to filter the measurement records based on RSRP threshold
void filter_records(float min_rsrp) {
    // Lock the critical section
    pthread_mutex_lock(&lock);

    // Iterate over the records and filter out those with RSRP below the threshold
    for (int i = 0; i < num_records; i++) {
        if (records[i].rssi < min_rsrp) {
            // Remove the record from the list
            memmove(&records[i], &records[i + 1], sizeof(measurement_record_t) * (num_records - i));
            num_records--;
        }
    }

    // Unlock the critical section
    pthread_mutex_unlock(&lock);
}

// Function to update the measurement records with new UE information
void update_records(int ci, float rssi, float snr, int cqi) {
    // Lock the critical section
    pthread_mutex_lock(&lock);

    // Iterate over the records and update those with matching CI
    for (int i = 0; i < num_records; i++) {
        if (records[i].ci == ci) {
            // Update the record with new information
            records[i].rssi = rssi;
            records[i].snr = snr;
            records[i].cqi = cqi;

            // Break out of the loop
            break;
        }
    }

    // Unlock the critical section
    pthread_mutex_unlock(&lock);
}

// Function to retrieve the measurement records list
measurement_record_t *get_records() {
    return records;
}

// Function to get the number of measurement records in the list
int get_num_records() {
    return num_records;
}
