    int data_points[MAX_DATA_POINTS];
    int num_data_points;
    int current_data_point;
    bool initialized;
} device_t;

typedef struct {
    char *device_name;
    int device_id;
    int threshold;
    bool enabled;
} filtering_config_t;

typedef struct {
    char *device_name;
    int device_id;
    int data_point;
    bool motion_detected;
} device_data_t;

// Global variables
int num_devices = 0;
device_t devices[MAX_DEVICES];
filtering_config_t filtering_config;
bool initialized = false;
sem_t *semaphore;
pthread_mutex_t mutex;

// Function prototypes
void handleSensorDataStreams(char *data);
void initializeDevices();
void updateDeviceHealth();
void filterDataPoints();
void processDataPoints();
void sendNotification(device_data_t *device_data);
void logError(const char *message);

int main() {
    // Initialize global variables and semaphore
    semaphore = sem_open("/sensor_data_streams", O_CREAT, 0644, 1);
    if (semaphore == SEM_FAILED) {
        logError("Failed to create semaphore");
        return -1;
    }
    pthread_mutex_init(&mutex, NULL);

    // Initialize devices and filtering configuration
    initializeDevices();
    filtering_config.threshold = MIN_THRESHOLD;
    filtering_config.enabled = true;

    // Start data processing loop
    while (1) {
        sem_wait(semaphore);
        handleSensorDataStreams("");
        sem_post(semaphore);
    }

    return 0;
}

void handleSensorDataStreams(char *data) {
    // Parse data and update device data points
    if (data != NULL) {
        device_data_t *device_data = parseData(data);
        if (device_data != NULL) {
            int device_id = getDeviceId(device_data->device_name);
            if (device_id >= 0) {
                updateDeviceDataPoint(device_id, device_data->data_point);
            } else {
                logError("Invalid device name");
            }
        } else {
            logError("Failed to parse data");
        }
    }

    // Update device health and filter data points if necessary
    updateDeviceHealth();
    if (filtering_config.enabled) {
        filterDataPoints();
    }

    // Process data points and send notifications if necessary
    processDataPoints();
}

void initializeDevices() {
    for (int i = 0; i < MAX_DEVICES; i++) {
        devices[i].device_name = NULL;
        devices[i].device_id = -1;
        devices[i].num_data_points = 0;
        devices[i].current_data_point = 0;
        devices[i].initialized = false;
    }
}

void updateDeviceHealth() {
    for (int i = 0; i < num_devices; i++) {
        if (!devices[i].initialized) {
            int device_id = getDeviceId(devices[i].device_name);
            if (device_id >= 0) {
                devices[i].device_id = device_id;
                devices[i].initialized = true;
            } else {
                logError("Invalid device name");
            }
        }
    }
}

void filterDataPoints() {
    for (int i = 0; i < num_devices; i++) {
        if (devices[i].initialized) {
            int data_point = devices[i].data_points[devices[i].current_data_point];
            if (data_point >= filtering_config.threshold) {
                sendNotification(&devices[i]);
            }
        }
    }
}

void processDataPoints() {
    for (int i = 0; i < num_devices; i++) {
        if (devices[i].initialized) {
            int data_point = devices[i].data_points[devices[i].current_data_point];
            if (data_point >= filtering_config.threshold) {
                sendNotification(&devices[i]);
            }
        }
    }
}

void sendNotification(device_data_t *device_data) {
    // Send notification to external API
}

void logError(const char *message) {
    printf("ERROR: %s\n", message);
}
