// Define the maximum buffer size for each frame buffer entry
#define MAX_BUFFER_SIZE 1024 * 1024

// Define the maximum packet length for each frame buffer entry
#define MAX_PACKET_LENGTH 1500

// Define the alignment requirement for PacketData buffers
#define ALIGNMENT 64

// Define the padding strategy for PacketData buffers
#define PADDING_STRATEGY ZERO_BYTES

// Define the maximum number of frame buffer entries
#define MAX_ENTRIES 1024

// Define the structure to hold information about each frame buffer entry
typedef struct FrameBufferEntry {
    uint64_t Timestamp;
    size_t PacketLength;
    void* PacketData;
} FrameBufferEntry;

// Define the function to initialize a frame buffer with flexible number of entries and individual entry sizes
int initialize_frame_buffers(FrameBufferEntry** entries, size_t num_entries, size_t entry_size) {
    // Check if the input parameters are valid
    if (entries == NULL || num_entries <= 0 || entry_size <= 0) {
        return -1;
    }

    // Calculate the total buffer size required for all entries
    size_t total_buffer_size = num_entries * entry_size;

    // Ensure that the total buffer size does not exceed the maximum allowed value
    if (total_buffer_size > MAX_BUFFER_SIZE) {
        return -2;
    }

    // Allocate memory for all entries in one go to minimize the risk of partial allocations and potential memory leaks
    void* buffer = malloc(total_buffer_size);
    if (buffer == NULL) {
        return -3;
    }

    // Initialize each entry with the appropriate size and alignment requirements
    for (size_t i = 0; i < num_entries; ++i) {
        FrameBufferEntry* entry = entries[i];
        entry->Timestamp = 0;
        entry->PacketLength = entry_size;
        entry->PacketData = buffer + i * entry_size;
    }

    // Pad each PacketData buffer to the specified alignment boundary using zero bytes
    if (PADDING_STRATEGY == ZERO_BYTES) {
        for (size_t i = 0; i < num_entries; ++i) {
            FrameBufferEntry* entry = entries[i];
            size_t padding_bytes = ALIGNMENT - ((uintptr_t)entry->PacketData % ALIGNMENT);
            memset(entry->PacketData + entry->PacketLength, 0, padding_bytes);
        }
    }

    // Validate the integrity of the allocated memory after initialization
    for (size_t i = 0; i < num_entries; ++i) {
        FrameBufferEntry* entry = entries[i];
        assert(entry->Timestamp == 0);
        assert(entry->PacketLength == entry_size);
        assert((uintptr_t)entry->PacketData % ALIGNMENT == 0);
    }

    // Return the initialized frame buffer entries
    return num_entries;
}
