// Define the function to generate and process NFAPI_CRC_INDICATION_PDU_T structures
void generateAndProcessNFALogReports(char* logFilePath) {
    // Open the log file for reading
    FILE* logFile = fopen(logFilePath, "r");
    if (logFile == NULL) {
        printf("Error: unable to open log file %s\n", logFilePath);
        return;
    }

    // Define a temporary buffer for storing parsed log entries
    char* tempBuffer = malloc(1024 * 1024);
    if (tempBuffer == NULL) {
        printf("Error: unable to allocate memory for temporary buffer\n");
        fclose(logFile);
        return;
    }

    // Define a list of NFAPI_CRC_INDICATION_PDU_T structures for storing parsed logs
    List* logList = createList();

    // Read the log file line by line and parse each entry into an NFAPI_CRC_INDICATION_PDU_T structure
    while (fgets(tempBuffer, 1024 * 1024, logFile) != NULL) {
        // Parse the current line of the log file into an NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T* pdu = parseLogEntry(tempBuffer);
        if (pdu == NULL) {
            // If the current line is not a valid log entry, skip it and continue reading the next line
            continue;
        }

        // Add the parsed NFAPI_CRC_INDICATION_PDU_T structure to the list of logs
        addToList(logList, pdu);
    }

    // Close the log file
    fclose(logFile);

    // Aggregate metrics across different time intervals and generate summary reports for each interval
    int numIntervals = 10;
    for (int i = 0; i < numIntervals; i++) {
        // Define a temporary list of NFAPI_CRC_INDICATION_PDU_T structures for storing logs within the current time interval
        List* intervalList = createList();

        // Iterate over all logs in the main list and add those that fall within the current time interval to the temporary list
        for (int j = 0; j < logList->size; j++) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = getFromList(logList, j);
            if (pdu->RX_UE_INFORMATION_TAG >= i * numIntervals && pdu->RX_UE_INFORMATION_TAG < (i + 1) * numIntervals) {
                addToList(intervalList, pdu);
            }
        }

        // Process the logs within the current time interval and generate a summary report
        processLogs(intervalList);
    }

    // Free the memory allocated for the temporary buffer and the list of logs
    free(tempBuffer);
    destroyList(logList);
}

// Define a function to parse a log entry into an NFAPI_CRC_INDICATION_PDU_T structure
NFAPI_CRC_INDICATION_PDU_T* parseLogEntry(char* logEntry) {
    // Initialize the NFAPI_CRC_INDICATION_PDU_T structure with default values
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        printf("Error: unable to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure\n");
        return NULL;
    }

    // Parse the current line of the log file into an NFAPI_CRC_INDICATION_PDU_T structure
    char* token = strtok(logEntry, ",");
    while (token != NULL) {
        if (strcmp(token, "RX_UE_INFORMATION_TAG") == 0) {
            pdu->RX_UE_INFORMATION_TAG = atoi(strtok(NULL, ","));
        } else if (strcmp(token, "RNTI") == 0) {
            pdu->RNTI = atoi(strtok(NULL, ","));
        } else if (strcmp(token, "CRC_INDICATION_REL8_TAG") == 0) {
            pdu->CRC_INDICATION_REL8_TAG = atoi(strtok(NULL, ","));
        }
        token = strtok(NULL, ",");
    }

    // Return the parsed NFAPI_CRC_INDICATION_PDU_T structure
    return pdu;
}

// Define a function to process logs within a time interval and generate a summary report
void processLogs(List* logList) {
    // Initialize variables for aggregating metrics across the current time interval
    int numRX_UE_INFORMATION_TAGS = 0;
    int numRNTIs = 0;
    int numCRC_INDICATION_REL8_TAGS = 0;

    // Iterate over all logs in the temporary list and aggregate metrics across the current time interval
    for (int i = 0; i < logList->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = getFromList(logList, i);
        numRX_UE_INFORMATION_TAGS += pdu->RX_UE_INFORMATION_TAG;
        numRNTIs += pdu->RNTI;
        numCRC_INDICATION_REL8_TAGS += pdu->CRC_INDICATION_REL8_TAG;
    }

    // Generate a summary report for the current time interval
    printf("Summary Report for Time Interval %d\n", numIntervals);
    printf("Number of RX_UE_INFORMATION_TAGS: %d\n", numRX_UE_INFORMATION_TAGS);
    printf("Number of RNTIs: %d\n", numRNTIs);
    printf("Number of CRC_INDICATION_REL8_TAGS: %d\n", numCRC_INDICATION_REL8_TAGS);
}
