    for (int i = 0; i < log_file->num_entries; i++) {
        nfapi_crc_indication_pdu_t *entry = &log_file->entries[i];
        uint32_t timestamp = entry->rx_ue_information_tag / aggregation_interval;
        if (timestamp >= aggregated_log->num_entries) {
            aggregated_log->num_entries++;
        }
    }

    // Write aggregated entries to output file
    for (int i = 0; i < aggregated_log->num_entries; i++) {
        nfapi_crc_indication_pdu_t *entry = &aggregated_log->entries[i];
        entry->rx_ue_information_tag = timestamp * aggregation_interval;
    }
}

