      stream.pause();
    }

    // process data and store in persistent array
    const processedData = processData(data);
    addToPersistentArray(processedData);

    if (memoryUsageOptimization) {
      optimizeMemoryUsage();
    }

    if (pauseResume && stream.isPaused()) {
      stream.resume();
    }
