import java.util.*;
import java.util.concurrent.TimeUnit;

public class RequestProcessor {
    private static final int MAX_PRIORITY = 10;
    private static final long PROCESSING_TIMEOUT = TimeUnit.MILLISECONDS.convert(50, TimeUnit.NANOSECONDS);

    public static List<RequestInterval> processRequests(List<Request> requests) {
        // Create an interval tree to efficiently manage and query the request intervals
        IntervalTree<RequestInterval> intervalTree = new IntervalTree<>();

        // Iterate over each request in the list
        for (Request request : requests) {
            // Add the request interval to the interval tree
            intervalTree.add(new RequestInterval(request.getTimestamp(), request.getPriority()));

            // Check if the total priority level of the intervals in the tree exceeds the threshold
            int totalPriority = 0;
            for (RequestInterval interval : intervalTree) {
                totalPriority += interval.getPriority();
                if (totalPriority > MAX_PRIORITY) {
                    // If it does, remove the oldest interval from the tree to make room for new requests
                    intervalTree.remove(interval);
                    break;
                }
            }
        }

        // Return the non-overlapping request intervals that do not exceed the threshold
        return intervalTree.getIntervals();
    }
}

class Request {
    private long timestamp;
    private int priority;
    private String uniqueId;

    public Request(long timestamp, int priority, String uniqueId) {
        this.timestamp = timestamp;
        this.priority = priority;
        this.uniqueId = uniqueId;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public int getPriority() {
        return priority;
    }

    public String getUniqueId() {
        return uniqueId;
    }
}

class RequestInterval implements Interval<RequestInterval> {
    private long start;
    private long end;
    private int priority;

    public RequestInterval(long start, long end, int priority) {
        this.start = start;
        this.end = end;
        this.priority = priority;
    }

    @Override
    public long getStart() {
        return start;
    }

    @Override
    public long getEnd() {
        return end;
    }

    public int getPriority() {
        return priority;
    }
}
