<?php

namespace EnvironmentVariables;

use Psr\Log\LoggerInterface;
use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\Response;
use Symfony\Component\Serializer\Encoder\JsonEncoder;
use Symfony\Component\Serializer\Normalizer\ObjectNormalizer;
use Symfony\Component\Serializer\Serializer;

class EnvironmentVariablesManager {
    private $logger;
    private $serviceDiscovery;
    private $configService;

    public function __construct(LoggerInterface $logger, ServiceDiscovery $serviceDiscovery, ConfigService $configService) {
        $this->logger = $logger;
        $this->serviceDiscovery = $serviceDiscovery;
        $this->configService = $configService;
    }

    public function updateResource(string $resourceId, Request $request): Response {
        try {
            $resource = $this->serviceDiscovery->getResource($resourceId);
            if (!$resource) {
                throw new \Exception("Resource not found");
            }

            $data = json_decode($request->getContent(), true);
            $updatedData = array_merge($resource, $data);

            $this->serviceDiscovery->updateResource($resourceId, $updatedData);
            $this->configService->updateConfig($resourceId, $updatedData);

            return new Response(json_encode($updatedData), 200, ['Content-Type' => 'application/json']);
        } catch (\Exception $e) {
            $this->logger->error("Error updating resource: {$e->getMessage()}");
            return new Response('', 500);
        }
    }

    public function deleteResource(string $resourceId): Response {
        try {
            $resource = $this->serviceDiscovery->getResource($resourceId);
            if (!$resource) {
                throw new \Exception("Resource not found");
            }

            $this->serviceDiscovery->deleteResource($resourceId);
            $this->configService->deleteConfig($resourceId);

            return new Response('', 204);
        } catch (\Exception $e) {
            $this->logger->error("Error deleting resource: {$e->getMessage()}");
            return new Response('', 500);
        }
    }
}
