        match command.status() {
            Ok(_) => break,
            Err(error) => {
                println!("Compilation failed with error: {}", error);
                retries += 1;
            }
        }
    }

    // Log detailed metrics about each compilation attempt, including success/failure status, elapsed time, and resource usage
    if retries == 3 {
        println!("Compilation failed after {} retries", retries);
    } else {
        println!("Compilation succeeded in {} seconds", elapsed.as_secs());
    }

    // Return the exit code of the subprocess
    command.wait().unwrap().code().unwrap()
}
