        return NULL;
    }

    // Initialize each packet with a unique identifier and timestamp
    for (size_t i = 0; i < num_packets; i++) {
        packets[i].id = i + 1;
        packets[i].timestamp = time(NULL);
    }

    return packets;
}

// Function to read a list of integers from a file and process it
void* process_file(void* arg) {
    // Cast the argument to a string pointer
    char* filename = (char*)arg;

    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open file %s\n", filename);
        return NULL;
    }

    // Read the list of integers from the file
    int* arr = NULL;
    size_t size = 0;
    while (fscanf(fp, "%d", &arr[size]) == 1) {
