    printf("The largest integer in file %s is %d\n", filename, max);

    return NULL;
}

// Function to read multiple lists of integers from different files and process each list independently
void* process_files(void* arg) {
    // Cast the argument to a string pointer
    char** filenames = (char**)arg;

    // Create a thread for each file
    pthread_t threads[num_files];
    for (size_t i = 0; i < num_files; i++) {
        if (pthread_create(&threads[i], NULL, process_file, filenames[i]) != 0) {
            fprintf(stderr, "Failed to create thread for file %s\n", filenames[i]);
            return NULL;
        }
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < num_files; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread for file %s\n", filenames[i]);
            return NULL;
        }
    }

    return NULL;
}
