        fprintf(stderr, "Failed to connect socket\n");
        return NULL;
    }

    // Read the list of integers from the network socket
    int* arr = NULL;
    size_t size = 0;
    while (recv(sock, &arr[size], sizeof(int), MSG_WAITALL) == sizeof(int)) {
        size++;
        arr = realloc(arr, size * sizeof(int));
        if (!arr) {
            fprintf(stderr, "Failed to allocate memory for integer array\n");
            return NULL;
        }
    }

    // Find the largest integer in the array
    int max = INT_MIN;
    for (size_t i = 0; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    // Print the largest integer in the array
    printf("The largest integer in file %s is %d\n", filename, max);

    return NULL;
}

// Function to read multiple lists of integers from different network sources and process each list independently
void* process_sockets(void* arg) {
    // Cast the argument to a string pointer
    char** filenames = (char**)arg;

    // Create a thread for each file
    pthread_t threads[num_files];
    for (size_t i = 0; i < num_files; i++) {
        if (pthread_create(&threads[i], NULL, process_socket, filenames[i]) != 0) {
            fprintf(stderr, "Failed to create thread for file %s\n", filenames[i]);
            return NULL;
        }
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < num_files; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread for file %s\n", filenames[i]);
            return NULL;
        }
    }

    return NULL;
}
```
