void read_integers(DataPacket **packets, int num_packets) {
    // Allocate memory for the array of integers
    *packets = (int *)malloc(num_packets * sizeof(int));
    if (*packets == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for integer list\n");
        exit(1);
    }

    // Read the integers from standard input and store them in the array
    int i = 0;
    while (scanf("%d", &(*packets)[i]) == 1) {
        if ((*packets)[i] < 0) {
            fprintf(stderr, "Error: negative integer encountered\n");
            exit(1);
        }
        i++;
    }

    // Find the largest integer in the array and print it
    int largest = -1;
    for (int j = 0; j < num_packets; j++) {
        if ((*packets)[j] > largest) {
            largest = (*packets)[j];
        }
    }
    printf("Largest integer: %d\n", largest);
}
