int process_file(const char *file_name, int *total_integers, double *average_time);
void* file_processor(void *arg);

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return 1;
    }

    int total_files = argc - 1;
    int total_integers = 0;
    double start_time = 0.0, end_time = 0.0;
    double total_average_time = 0.0;

    // Initialize threads
    pthread_t threads[total_files];
    for (int i = 0; i < total_files; ++i) {
        int ret = pthread_create(&threads[i], NULL, file_processor, (void*)argv[i+1]);
        if (ret != 0) {
            perror("Failed to create thread");
            return ret;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < total_files; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Calculate total average time
    end_time = get_current_time();
    total_average_time = end_time - start_time;
    printf("Total files processed: %d\n", total_files);
    printf("Total integers read: %d\n", total_integers);
    printf("Average processing time per file: %.2f seconds\n", total_average_time / total_files);

    return 0;
}

double get_current_time() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return tv.tv_sec + (tv.tv_usec / 1000000.0);
}

