void generatePackets(int N, int congestionProbability, char* logFile) {
    // Initialize the list of packets
    LTE_Packet_T* packets = (LTE_Packet_T*)malloc(sizeof(LTE_Packet_T) * N);
    if (!packets) {
        printf("Error: Failed to allocate memory for packet list\n");
        return;
    }

    // Initialize the rolling average of transmission delays
    double rollingAverage = 0.0;

