    char* fileType = (char*)malloc(5 + 1);
    strcpy(fileType, DEFAULT_FILE_TYPE);
    int dotIndex = strrchr(filename, '.');
    if (dotIndex != NULL) {
        fileType = filename + dotIndex;
    }

    // Build the full path for the log file
    char* logFile = (char*)malloc(256);
    sprintf(logFile, "%s/%d%02d%02d-%s.%s", getenv("LOG_DIR"), now->tm_year + 1900, now->tm_mon + 1, now->tm_mday, filename, fileType);

    // Ensure the resulting filename is unique among all files in the current directory by appending a random number until no conflict is found
    int conflict = 1;
    while (conflict) {
        FILE* fp = fopen(logFile, "r");
        if (!fp) {
            conflict = 0;
        } else {
            free(logFile);
            logFile = (char*)malloc(256);
            sprintf(logFile, "%s/%d%02d%02d-%s.%s", getenv("LOG_DIR"), now->tm_year + 1900, now->tm_mon + 1, now->tm_mday, filename, fileType);
        }
    }

    // Log the operation details to the respective log file
    FILE* fp = fopen(logFile, "a");
    if (!fp) {
        printf("Error: Failed to open log file %s\n", logFile);
        return NULL;
    }
    fprintf(fp, "Logging packets with congestion probability %d%%\n", congestionProbability * 100);
    fclose(fp);

    // Return the full path for the log file
    return logFile;
}

// Function to manage the maximum size of the log directory to prevent excessive disk usage by removing the oldest logs when the threshold is exceeded
void manageLogDirectory(char* logDir) {
    // Get the current time and date
    struct tm* now = localtime(&now);

    // Build the full path for the log file
