// Structure to represent network interface status
typedef struct NetworkInterfaceStatus {
    NetworkDeviceIdentifier id;
    IPConfiguration config;
    TrafficStatistics stats;
} NetworkInterfaceStatus;

// Function to initialize and manage the dynamic array of NetworkInterfaceStatus structures
NetworkInterfaceStatus* init_network_interface_status(int size) {
    // Allocate memory for the dynamic array
    NetworkInterfaceStatus* status = (NetworkInterfaceStatus*)malloc(size * sizeof(NetworkInterfaceStatus));
    if (!status) {
        fprintf(stderr, "Error: Failed to allocate memory for network interface status\n");
        return NULL;
    }

    // Initialize the dynamic array with default values
    for (int i = 0; i < size; i++) {
        status[i].id = -1;
        status[i].config.ip_address = "0.0.0.0";
        status[i].config.subnet_mask = "0.0.0.0";
        status[i].stats.rx_bytes = 0;
        status[i].stats.tx_bytes = 0;
    }

    return status;
}

// Function to add a new entry to the dynamic array of NetworkInterfaceStatus structures
int add_network_interface_status(NetworkInterfaceStatus* status, int size, NetworkDeviceIdentifier id, IPConfiguration config) {
    // Check if the dynamic array is full
    if (size == 0) {
        fprintf(stderr, "Error: Dynamic array of network interface status is full\n");
        return -1;
    }

    // Find an empty slot in the dynamic array
    int i = 0;
    while (i < size && status[i].id != -1) {
        i++;
    }

    // Add the new entry to the dynamic array
    status[i].id = id;
    strcpy(status[i].config.ip_address, config.ip_address);
    strcpy(status[i].config.subnet_mask, config.subnet_mask);

    return i;
}

// Function to update an existing entry in the dynamic array of NetworkInterfaceStatus structures
int update_network_interface_status(NetworkInterfaceStatus* status, int size, NetworkDeviceIdentifier id, TrafficStatistics stats) {
    // Find the index of the entry to be updated
    int i = 0;
    while (i < size && status[i].id != id) {
        i++;
    }

    // Check if the entry was found
    if (i == size || status[i].id == -1) {
        fprintf(stderr, "Error: Network interface status not found\n");
        return -1;
    }

    // Update the traffic statistics for the entry
    status[i].stats = stats;

    return i;
}

// Function to retrieve the traffic statistics for a specific network device
TrafficStatistics get_network_interface_status(NetworkInterfaceStatus* status, int size, NetworkDeviceIdentifier id) {
    // Find the index of the entry corresponding to the specified network device
    int i = 0;
    while (i < size && status[i].id != id) {
        i++;
    }

    // Check if the entry was found
    if (i == size || status[i].id == -1) {
        fprintf(stderr, "Error: Network interface status not found\n");
        return (TrafficStatistics){0};
    }

    // Return the traffic statistics for the specified network device
    return status[i].stats;
}
