class UserSessionManager {
public:
    // Constructor
    UserSessionManager(int idleTimeout = 30) : idleTimeout_(idleTimeout) {}

    // Add a new session to the manager
    void addSession(const std::string& sessionID, const std::string& userID) {
        sessions_.emplace(sessionID, UserSession{sessionID, userID});
    }

    // Update an existing session in the manager
    void updateSession(const std::string& sessionID, const std::string& userID) {
        auto it = sessions_.find(sessionID);
        if (it != sessions_.end()) {
            it->second.userID = userID;
            it->second.lastActivityTimestamp = std::chrono::system_clock::now();
        }
    }

    // Expire inactive sessions based on the idle timeout period
    void expireInactiveSessions() {
        auto now = std::chrono::system_clock::now();
        for (auto it = sessions_.begin(); it != sessions_.end();) {
            if (it->second.lastActivityTimestamp + std::chrono::seconds(idleTimeout_) < now) {
                it = sessions_.erase(it);
            } else {
                ++it;
            }
        }
    }

    // Get the number of active sessions
    int getActiveSessionCount() const {
        return sessions_.size();
    }

    // Check if a session is active
    bool isSessionActive(const std::string& sessionID) const {
        auto it = sessions_.find(sessionID);
        return it != sessions_.end() && it->second.lastActivityTimestamp + std::chrono::seconds(idleTimeout_) > std::chrono::system_clock::now();
    }

private:
    // Struct to represent a user session
    struct UserSession {
        std::string sessionID;
        std::string userID;
        std::chrono::time_point<std::chrono::system_clock> lastActivityTimestamp;
        std::vector<std::string> activeDeviceList;
    };

    // Map to store all the sessions
    std::unordered_map<std::string, UserSession> sessions_;

    // Idle timeout period in seconds
    int idleTimeout_;
};
```
