    public class ResourceMonitor
    {
        private readonly Dictionary<string, Process> _processes = new Dictionary<string, Process>();
        private readonly Dictionary<string, ServiceController> _services = new Dictionary<string, ServiceController>();
        private readonly object _lock = new object();

        public void AddProcess(string processId)
        {
            lock (_lock)
            {
                if (!_processes.ContainsKey(processId))
                {
                    try
                    {
                        var process = Process.GetProcessById(int.Parse(processId));
                        _processes.Add(processId, process);
                    }
                    catch (Exception ex)
                    {
                        throw new ArgumentException($"Invalid process ID: {processId}", ex);
                    }
                }
            }
        }

        public void AddService(string serviceName)
        {
            lock (_lock)
            {
                if (!_services.ContainsKey(serviceName))
                {
                    try
                    {
                        var service = new ServiceController(serviceName);
                        _services.Add(serviceName, service);
                    }
                    catch (Exception ex)
                    {
                        throw new ArgumentException($"Invalid service name: {serviceName}", ex);
                    }
                }
            }
        }

        public void RemoveProcess(string processId)
        {
            lock (_lock)
            {
                if (_processes.ContainsKey(processId))
                {
                    _processes.Remove(processId);
                }
            }
        }

        public void RemoveService(string serviceName)
        {
            lock (_lock)
            {
                if (_services.ContainsKey(serviceName))
                {
                    _services.Remove(serviceName);
                }
            }
        }

        public void UpdateProcess(string processId, int cpuThreshold, long memoryThreshold, long diskThreshold)
        {
            lock (_lock)
            {
                if (!_processes.ContainsKey(processId))
                {
                    throw new ArgumentException($"Invalid process ID: {processId}");
                }

                var process = _processes[processId];
                process.CpuThreshold = cpuThreshold;
                process.MemoryThreshold = memoryThreshold;
                process.DiskThreshold = diskThreshold;
            }
        }

        public void UpdateService(string serviceName, int cpuThreshold, long memoryThreshold, long diskThreshold)
        {
            lock (_lock)
            {
                if (!_services.ContainsKey(serviceName))
                {
                    throw new ArgumentException($"Invalid service name: {serviceName}");
                }

                var service = _services[serviceName];
                service.CpuThreshold = cpuThreshold;
                service.MemoryThreshold = memoryThreshold;
                service.DiskThreshold = diskThreshold;
            }
        }

        public void GenerateMetrics()
        {
            lock (_lock)
            {
                foreach (var process in _processes.Values)
