                    var memoryUsage = service.WorkingSet64;
                    var diskUsage = 0L; // TODO: Implement disk usage calculation

                    if (cpuUsage > service.CpuThreshold || memoryUsage > service.MemoryThreshold || diskUsage > service.DiskThreshold)
                    {
                        // TODO: Notify users of critical threshold exceedance
                    }
                }
            }
        }

        public override string ToString()
        {
            lock (_lock)
            {
                var sb = new StringBuilder();

                foreach (var process in _processes.Values)
