#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <zlib.h>

int move_files(const char* src, const char* dst, int retention) {
    // Check if source and destination directories exist
    struct stat st;
    if (stat(src, &st) == -1 || !S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Error: Source directory does not exist or is not a directory\n");
        return 1;
    }
    if (stat(dst, &st) == -1 || !S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Error: Destination directory does not exist or is not a directory\n");
        return 1;
    }

    // Get the current time in seconds since epoch
    time_t now = time(NULL);

    // Open the source directory and iterate over its contents
    DIR* dir = opendir(src);
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (entry->d_name[0] == '.') continue;

        // Get the file path and check its age
        char src_path[PATH_MAX];
        snprintf(src_path, PATH_MAX, "%s/%s", src, entry->d_name);
        struct stat st;
        if (stat(src_path, &st) == -1) {
            fprintf(stderr, "Error: Failed to get file status for %s\n", src_path);
            continue;
        }
        time_t age = now - st.st_mtime;

        // Move the file if it is older than the retention policy
        if (age > retention) {
            char dst_path[PATH_MAX];
            snprintf(dst_path, PATH_MAX, "%s/%s", dst, entry->d_name);
            int fd = open(src_path, O_RDONLY);
            if (fd == -1) {
                fprintf(stderr, "Error: Failed to open file %s for reading\n", src_path);
                continue;
            }
            // Compress the file using zlib library
            int compress_ratio = 9; // adjust this value as needed
            uLongf destLen = compressBound(st.st_size) * compress_ratio;
            Bytef* dest = (Bytef*)malloc(destLen);
            if (!dest) {
                fprintf(stderr, "Error: Failed to allocate memory for compressed file\n");
                close(fd);
                continue;
            }
            int err = compress2(dest, &destLen, (Bytef*)src_path, st.st_size, compress_ratio);
            if (err != Z_OK) {
                fprintf(stderr, "Error: Failed to compress file %s\n", src_path);
                free(dest);
                close(fd);
                continue;
            }
            // Move the compressed file to the destination directory
            int ret = move_file(src_path, dst_path);
            if (ret != 0) {
                fprintf(stderr, "Error: Failed to move file %s to %s\n", src_path, dst_path);
                free(dest);
                close(fd);
                continue;
            }
            // Close the source file and delete the compressed file
            close(fd);
            free(dest);
        }
    }
    closedir(dir);

    return 0;
}

int move_file(const char* src, const char* dst) {
    // Check if source and destination files exist
    struct stat st;
    if (stat(src, &st) == -1 || !S_ISREG(st.st_mode)) {
        fprintf(stderr, "Error: Source file does not exist or is not a regular file\n");
        return 1;
    }
    if (stat(dst, &st) != -1 && S_ISREG(st.st_mode)) {
        fprintf(stderr, "Error: Destination file already exists and is a regular file\n");
        return 1;
    }

    // Open the source file and create the destination file
    int src_fd = open(src, O_RDONLY);
    if (src_fd == -1) {
        fprintf(stderr, "Error: Failed to open file %s for reading\n", src);
        return 1;
    }
    int dst_fd = creat(dst, st.st_mode);
    if (dst_fd == -1) {
        fprintf(stderr, "Error: Failed to create file %s\n", dst);
        close(src_fd);
        return 1;
    }

    // Copy the contents of the source file to the destination file
    char buf[4096];
    ssize_t nread, nwritten;
    while ((nread = read(src_fd, buf, sizeof(buf))) > 0) {
        if (write(dst_fd, buf, nread) != nread) {
            fprintf(stderr, "Error: Failed to write to file %s\n", dst);
            close(src_fd);
            close(dst_fd);
            return 1;
        }
    }
    if (nread == -1) {
        fprintf(stderr, "Error: Failed to read from file %s\n", src);
        close(src_fd);
        close(dst_fd);
        return 1;
    }

    // Close the files and delete the source file
    close(src_fd);
    close(dst_fd);
    unlink(src);

    return 0;
}
