import java.util.logging.Logger;

public class FileProcessor {
    private static final Logger LOGGER = Logger.getLogger(FileProcessor.class.getName());

    public void processFiles(String directoryPath, long threshold) throws Exception {
        // Clear the directory of all files older than the given threshold
        clearDirectory(directoryPath, threshold);

        // Process each file in the directory
        List<File> files = Files.walk(new File(directoryPath).toPath())
                .filter(file -> file.lastModified() > System.currentTimeMillis() - threshold)
                .collect(Collectors.toList());

        for (File file : files) {
            try {
                // Process the file using an external API service
                processFile(file);
            } catch (Exception e) {
                LOGGER.log(Level.WARNING, "Error processing file: " + file.getName(), e);
            }
        }
    }

    private void clearDirectory(String directoryPath, long threshold) throws Exception {
        File directory = new File(directoryPath);
        if (!directory.exists()) {
            throw new IllegalArgumentException("Directory does not exist: " + directoryPath);
        }

        List<File> files = Files.walk(directory.toPath())
                .filter(file -> file.lastModified() < System.currentTimeMillis() - threshold)
                .collect(Collectors.toList());

        for (File file : files) {
            try {
                File.delete(file);
            } catch (Exception e) {
                LOGGER.log(Level.WARNING, "Error deleting file: " + file.getName(), e);
            }
        }
    }

    private void processFile(File file) throws Exception {
        // Implement API call to process the file here
    }
}
