        var tasks = new List<Task>();
        foreach (var batch in complexObjects.Batch(BATCH_SIZE))
        {
            tasks.Add(InsertDataAsync(batch));
        }

        await Task.WhenAll(tasks);

        // Return summary report
        return summaryReport;
