public class LoggingService
{
    private readonly ILogger _logger;
    private readonly DistributedLoggingSystem _distributedLoggingSystem;

    public LoggingService(ILogger<LoggingService> logger, DistributedLoggingSystem distributedLoggingSystem)
    {
        _logger = logger;
        _distributedLoggingSystem = distributedLoggingSystem;
    }

    public async Task ProcessUserInputAsync(string userInput)
    {
        if (userInput == null)
        {
            throw new ArgumentNullException(nameof(userInput));
        }

        var hashedInput = ComputeHash(userInput);
        await _distributedLoggingSystem.StoreHashAsync(hashedInput);
    }

    private string ComputeHash(string input)
    {
        using (var md5 = MD5.Create())
        {
            var hash = md5.ComputeHash(Encoding.UTF8.GetBytes(input));
            return Convert.ToBase64String(hash);
        }
    }
}
