use std::env;
use std::process::Command;
use std::fs::File;
use std::io::prelude::*;
use std::path::PathBuf;
use tokio::runtime::Runtime;
use tokio::task::spawn_blocking;
use serde::Deserialize;

#[derive(Deserialize)]
struct Config {
    api_url: String,
    cache_size: usize,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} [command]", args[0]);
        return Ok(());
    }

    // Load configuration from external API
    let config_url = format!("{}/config", args[1]);
    let config: Config = fetch_config(&config_url)?;

    // Initialize caching mechanism with configured size
    let cache = Cache::new(config.cache_size);

    // Spawn Tokio runtime to handle asynchronous operations
    let mut rt = Runtime::new()?;

    // Handle incoming requests and execute corresponding functionalities
    while let Some(request) = rt.block_on(spawn_blocking(|| {
        let request = read_request(&args[2]);
        match request {
            "fetch" => fetch_data(&config),
            "process" => process_data(&config),
            _ => println!("Invalid command: {}", request),
        }
    }))? {
        // Handle response and update cache if necessary
        let response = handle_response(request);
        cache.update(response);
    }

    Ok(())
}

fn fetch_config(url: &str) -> Result<Config, Box<dyn std::error::Error>> {
    let mut resp = reqwest::get(url)?;
    if !resp.status().is_success() {
        return Err("Failed to fetch configuration".into());
    }
    let config: Config = resp.json()?;
    Ok(config)
}

fn fetch_data(config: &Config) -> Result<(), Box<dyn std::error::Error>> {
    // Fetch data from external API using Tokio runtime
    let mut rt = Runtime::new()?;
    let response = rt.block_on(spawn_blocking(|| {
        reqwest::get(&config.api_url)?.json()
    }))?;
    println!("Fetched data: {:?}", response);
    Ok(())
}

fn process_data(config: &Config) -> Result<(), Box<dyn std::error::Error>> {
    // Process data using Tokio runtime
    let mut rt = Runtime::new()?;
    let response = rt.block_on(spawn_blocking(|| {
        reqwest::get(&config.api_url)?.json()
    }))?;
    println!("Processed data: {:?}", response);
    Ok(())
}

fn handle_response(response: &str) -> Result<(), Box<dyn std::error::Error>> {
    // Handle response and update cache if necessary
    let mut rt = Runtime::new()?;
    let response = rt.block_on(spawn_blocking(|| {
        reqwest::get(&config.api_url)?.json()
    }))?;
    println!("Handled response: {:?}", response);
    Ok(())
}
