MAC_PDU* init_mac_pdu(int size) {
    // Allocate memory for the array
    MAC_PDU* mac_pdu = (MAC_PDU*)malloc(size * sizeof(MAC_PDU));
    if (!mac_pdu) {
        return NULL;
    }

    // Initialize each structure in the array
    for (int i = 0; i < size; i++) {
        mac_pdu[i].header.valid = false;
        mac_pdu[i].macsdu.size = rand() % 1024 + 1024;
        mac_pdu[i].macsdu.data = (char*)malloc(mac_pdu[i].macsdu.size);
        if (!mac_pdu[i].macsdu.data) {
            free(mac_pdu);
            return NULL;
        }
        mac_pdu[i].ie_list.count = 0;
    }

    // Return the initialized array
    return mac_pdu;
}

// Free memory allocated for MAC_PDU structures
void free_mac_pdu(MAC_PDU* mac_pdu, int size) {
    if (!mac_pdu) {
        return;
    }

    // Free each structure in the array
    for (int i = 0; i < size; i++) {
        free(mac_pdu[i].macsdu.data);
    }

    // Free the array itself
    free(mac_pdu);
}

// Update MAC_PDU structures with new data
void update_mac_pdu(MAC_PDU* mac_pdu, int size) {
    if (!mac_pdu) {
        return;
    }

    // Generate random data for each structure in the array
    for (int i = 0; i < size; i++) {
        mac_pdu[i].header.valid = true;
        mac_pdu[i].macsdu.size = rand() % 1024 + 1024;
        mac_pdu[i].macsdu.data = (char*)malloc(mac_pdu[i].macsdu.size);
        if (!mac_pdu[i].macsdu.data) {
            free(mac_pdu);
            return NULL;
        }
        mac_pdu[i].ie_list.count = 0;
    }
}

// Validate MAC_PDU structures for buffer overflows
bool validate_mac_pdu(MAC_PDU* mac_pdu, int size) {
    if (!mac_pdu) {
        return false;
    }

    // Check each structure in the array for buffer overflows
    for (int i = 0; i < size; i++) {
        if (mac_pdu[i].header.valid && mac_pdu[i].macsdu.size > 1024) {
            return false;
        }
    }

    // Return true if no buffer overflows found
    return true;
}
