    uint32_t tcp_header;
    uint8_t tcp_options;
} TCP_segment;

// Define the function to dynamically generate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_crc_indication_pdu(int n, char *filename) {
    // Initialize the dynamic array of TCP_segments
    TCP_segment *tcp_segments = (TCP_segment *)malloc(n * sizeof(TCP_segment));

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Generate a random number for the filename
    srand(time(NULL));
    int rand_num = rand() % 10000;

    // Derive the file type from the original filename's extension if present, otherwise use ".bin" as the default
    char *filetype = strrchr(filename, '.');
    if (filetype == NULL) {
        filetype = ".bin";
    } else {
        filetype++; // Skip the dot
    }

    // Handle filenames with multiple dots and maintain the original directory path
    char *dirpath = strrchr(filename, '/');
    if (dirpath == NULL) {
        dirpath = ".";
    } else {
        dirpath++; // Skip the slash
    }

    // Ensure the resulting filename is unique among all files in the current directory by appending a random number until no conflict is found
    char *new_filename = (char *)malloc(256);
    while (1) {
        snprintf(new_filename, 256, "%s%d%s", dirpath, rand_num, filetype);
        if (access(new_filename, F_OK) == -1) {
            break;
        }
        rand_num++;
    }

    // Log the operation details to a separate log file
    char *logfile = "crc_indication_pdu.log";
    FILE *fp = fopen(logfile, "a");
    if (fp == NULL) {
        perror("fopen");
        exit(1);
    }
    fprintf(fp, "%s\n", new_filename);
    fclose(fp);

    // Rotate the log file daily with each log entry limited to 1024 bytes
    struct stat st;
    if (stat(logfile, &st) == 0 && st.st_size > 1024 * 1024) {
        char *new_logfile = (char *)malloc(256);
        snprintf(new_logfile, 256, "%s.%d", logfile, time(NULL));
        rename(logfile, new_logfile);
    }

    // Manage the maximum size of the log directory to prevent excessive disk usage by removing the oldest logs when the threshold is exceeded
    struct dirent **namelist;
    int nitems = scandir(".", &namelist, NULL, alphasort);
    if (nitems > 1024) {
        for (int i = 0; i < nitems - 1024; i++) {
            remove(namelist[i]->d_name);
        }
    }

    // Initialize the dynamic array of TCP_segments with valid TCP headers and payloads
    for (int i = 0; i < n; i++) {
        tcp_segments[i].tcp_header = htonl(i + 1);
        snprintf(tcp_segments[i].payload, 1024, "Hello World %d", i + 1);
    }

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures with random CRC flags
    for (int i = 0; i < n; i++) {
        crc_indication_pdu[i].RX_UE_INFORMATION_TAG = htons(i + 1);
        crc_indication_pdu[i].RNTI = htonl(rand() % 10000);
        crc_indication_pdu[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    // Validate the integrity of the payload after each update to prevent buffer overflows
    for (int i = 0; i < n; i++) {
        if (strlen(tcp_segments[i].payload) > 1024) {
            printf("Buffer overflow detected in TCP segment %d\n", i + 1);
            exit(1);
        }
    }

    // Write the list of NFAPI_CRC_INDICATION_PDU_T structures to a file
    FILE *fp = fopen(new_filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        exit(1);
    }
    for (int i = 0; i < n; i++) {
        fwrite(&crc_indication_pdu[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
    }
    fclose(fp);

    // Write the list of TCP_segments to a file
    FILE *fp = fopen(new_filename, "ab");
    if (fp == NULL) {
        perror("fopen");
        exit(1);
    }
    for (int i = 0; i < n; i++) {
        fwrite(&tcp_segments[i], sizeof(TCP_segment), 1, fp);
    }
    fclose(fp);

    // Free the memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures and TCP_segments
    free(crc_indication_pdu);
    free(tcp_segments);
}
