    // open the files for writing and initialize the fd field of each segment
    for (int i = 0; i < n; i++) {
        segments[i].fd = open(segments[i].filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
        if (segments[i].fd == -1) {
