#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the function for generating a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T* generate_crc_indication_list(int N, int num_threads) {
    // Initialize the list with an initial capacity of 1024 elements
    NFAPI_CRC_INDICATION_LIST_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->size = 0;
    list->capacity = 1024;
    list->data = malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the semaphore for synchronizing access to the list
    sem_t* sem = malloc(sizeof(sem_t));
    sem_init(sem, 0, 1);

    // Define the thread function for generating CRC indications
    void* generate_crc_indication(void* arg) {
        int i;
        for (i = 0; i < N; i++) {
            // Acquire the semaphore to access the list
            sem_wait(sem);

            // Check if the list has enough capacity to store another element
            if (list->size == list->capacity) {
                // Double the capacity of the list if it is full
                list->capacity *= 2;
                list->data = realloc(list->data, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }

            // Generate a new CRC indication element
            NFAPI_CRC_INDICATION_PDU_T* crc_indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            crc_indication->RX_UE_INFORMATION_TAG = i;
            crc_indication->RNTI = rand();
            crc_indication->CRC_INDICATION_REL8_TAG = rand() % 256;

            // Add the new element to the list
            list->data[list->size++] = *crc_indication;

            // Release the semaphore
            sem_post(sem);
        }
    }

    // Create a pool of threads for generating CRC indications
    pthread_t* threads = malloc(num_threads * sizeof(pthread_t));
    int i;
    for (i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, generate_crc_indication, NULL);
    }

    // Wait for all threads to finish generating CRC indications
    for (i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the pool of threads and the semaphore
    free(threads);
    sem_destroy(sem);

    return list;
}

// Define the function for freeing a list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    int i;
    for (i = 0; i < list->size; i++) {
        free(&list->data[i]);
    }
    free(list->data);
    free(list);
}

// Define the function for printing a list of NFAPI_CRC_INDICATION_PDU_T structures
void print_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    int i;
    for (i = 0; i < list->size; i++) {
        printf("RX_UE_INFORMATION_TAG: %d\n", list->data[i].RX_UE_INFORMATION_TAG);
        printf("RNTI: %u\n", list->data[i].RNTI);
        printf("CRC_INDICATION_REL8_TAG: %u\n", list->data[i].CRC_INDICATION_REL8_TAG);
    }
}']

