    char *filetype = ".log";
    if (strchr(filename, '.') != NULL) {
        filetype = "";
    }

    // Append random number until unique filename is found
    int i = 0;
    while (i < MAX_LOG_FILES) {
        sprintf(filename + size - 10, "%d%s", rand() % 1000000000, filetype);
        if (access(filename, F_OK) != 0) {
            break;
        }
        i++;
