void manage_log_files(LOG_FILE_T *log_file, int max_size) {
    // Check if allocation failed
    if (log_file == NULL) {
        printf("Error: Failed to allocate memory for log file\n");
        return;
    }

    // Initialize log file name and size
    generate_log_filename(log_file->filename, sizeof(log_file->filename));
    log_file->size = 0;

    // Open log file
    log_file->file = fopen(log_file->filename, "a");
    if (log_file->file == NULL) {
        printf("Error: Failed to open log file %s\n", log_file->filename);
        return;
    }
