// Define function to write to log file
void write_to_log(LOG_FILE_T *log_file, char *message) {
    // Check if log file is not open
    if (log_file == NULL || log_file->file == NULL) {
        printf("Error: Log file is not open\n");
        return;
    }

    // Write to log file
    fprintf(log_file->file, "%s", message);

    // Update size and check for rotation
    log_file->size += strlen(message);
    if (log_file->size >= MAX_LOG_SIZE) {
        fclose(log_file->file);
        sprintf(log_file->filename, "%s.%d", log_file->filename, time(NULL));
        log_file->file = fopen(log_file->filename, "a");
        if (log_file->file == NULL) {
            printf("Error: Failed to open log file %s\n", log_file->filename);
