// Define the structure to hold the UE context information
typedef struct {
    int UE_ID;
    int RRC_STATE;
    SRB1_CONFIG *SRB1_CONFIG;
} NR_UE_CONTEXT;

// Define a dynamic array to store the UE contexts
NR_UE_CONTEXT **ue_contexts = NULL;
size_t ue_contexts_count = 0;
pthread_mutex_t ue_contexts_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new UE context
void add_ue_context(int UE_ID, int RRC_STATE, SRB1_CONFIG *SRB1_CONFIG) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ue_contexts_lock);

    // Allocate memory for the new UE context
    NR_UE_CONTEXT *new_ue_context = malloc(sizeof(NR_UE_CONTEXT));
    if (new_ue_context == NULL) {
        perror("Failed to allocate memory for new UE context");
        return;
    }

    // Initialize the new UE context
    new_ue_context->UE_ID = UE_ID;
    new_ue_context->RRC_STATE = RRC_STATE;
    new_ue_context->SRB1_CONFIG = SRB1_CONFIG;

    // Add the new UE context to the dynamic array
    ue_contexts = realloc(ue_contexts, (ue_contexts_count + 1) * sizeof(NR_UE_CONTEXT));
    if (ue_contexts == NULL) {
        perror("Failed to allocate memory for new UE context");
        return;
    }
    ue_contexts[ue_contexts_count] = new_ue_context;
    ue_contexts_count++;

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_lock);
}

// Function to update an existing UE context based on UE ID
void update_ue_context(int UE_ID, int RRC_STATE, SRB1_CONFIG *SRB1_CONFIG) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ue_contexts_lock);

    // Find the index of the UE context with the given UE ID
    size_t ue_index = 0;
    for (size_t i = 0; i < ue_contexts_count; i++) {
        if (ue_contexts[i]->UE_ID == UE_ID) {
            ue_index = i;
            break;
        }
    }

    // If the UE context was found, update its RRC state and SRB1 configuration
    if (ue_index != 0) {
        ue_contexts[ue_index]->RRC_STATE = RRC_STATE;
        ue_contexts[ue_index]->SRB1_CONFIG = SRB1_CONFIG;
    } else {
        // If the UE context was not found, add a new one
        add_ue_context(UE_ID, RRC_STATE, SRB1_CONFIG);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_lock);
}

// Function to efficiently manage memory when the function exits
void cleanup() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ue_contexts_lock);

    // Free the dynamic array of UE contexts
    for (size_t i = 0; i < ue_contexts_count; i++) {
        free(ue_contexts[i]);
    }
    free(ue_contexts);

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_lock);
}
