    fn deallocate(&mut self, index: usize) -> Result<(), &str> {
        if index >= self.array.len() {
            return Err("Invalid index");
        }
        let element = self.array.remove(index);
        self.available_space += 1;
        Ok(())
    }

    fn resize(&mut self) -> Result<(), &str> {
        if self.available_space == self.max_size {
            return Err("No available space in the array");
        }
        let new_size = (self.array.len() as f32 * self.resize_threshold) as usize;
        if new_size > self.max_size {
            return Err("New size exceeds maximum size");
        }
        let mut new_array = VecDeque::with_capacity(new_size);
        for element in &self.array {
            new_array.push_back(*element);
        }
        self.array = new_array;
        self.max_size = new_size;
        Ok(())
    }

    fn cleanup(&mut self) -> Result<(), &str> {
        if self.available_space == 0 {
            return Err("No available space in the array");
        }
        let mut unused_elements = Vec::new();
        for (index, element) in self.array.iter().enumerate() {
            if !element.crcflag {
                unused_elements.push(index);
            }
        }
        for index in unused_elements {
            let _ = self.deallocate(index);
        }
        Ok(())
    }

    fn iterate(&self) -> Iter<'_, NFAPI_CRC_INDICATION_PDU> {
        self.array.iter()
    }

    fn monitor_usage(&self) -> (usize, usize, usize) {
        (self.available_space, self.max_size, self.total_size)
    }
}

struct CrcIndicationArrayHandle {
    array: Arc<Mutex<CrcIndicationArray>>,
}

impl CrcIndicationArrayHandle {
    fn new(array: Arc<Mutex<CrcIndicationArray>>) -> Self {
        Self { array }
    }

    fn allocate(&self) -> Result<&mut NFAPI_CRC_INDICATION_PDU, &str> {
        self.array.lock().unwrap().allocate()
    }

    fn deallocate(&self, index: usize) -> Result<(), &str> {
        self.array.lock().unwrap().deallocate(index)
    }

    fn resize(&self) -> Result<(), &str> {
        self.array.lock().unwrap().resize()
    }

    fn cleanup(&self) -> Result<(), &str> {
        self.array.lock().unwrap().cleanup()
    }

    fn iterate(&self) -> Iter<'_, NFAPI_CRC_INDICATION_PDU> {
        self.array.lock().unwrap().iterate()
    }

    fn monitor_usage(&self) -> (usize, usize, usize) {
        self.array.lock().unwrap().monitor_usage()
    }
}

fn create_crc_indication_array(max_size: usize, resize_threshold: f32, cleanup_interval: Duration) -> CrcIndicationArrayHandle {
    let array = Arc::new(Mutex::new(CrcIndicationArray::new(max_size, resize_threshold, cleanup_interval)));
    for _ in 0..cleanup_interval.as_secs() {
        let handle = CrcIndicationArrayHandle::new(array.clone());
        let thread = thread::spawn(move || {
            loop {
                handle.cleanup().unwrap();
                thread::sleep(Duration::from_secs(1));
            }
        });
        array.lock().unwrap().cleanup_threads.push(thread);
    }
    CrcIndicationArrayHandle::new(array)
}

