using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;

public static List<object> GetObjectsWithPropertyValue(string jsonString, string propertyName, object propertyValue)
{
    var objects = JsonConvert.DeserializeObject<List<object>>(jsonString);
    if (objects == null || !objects.Any())
    {
        throw new ArgumentException("Invalid JSON document");
    }

    var matchingObjects = objects.Where(obj => obj.GetType().GetProperty(propertyName).GetValue(obj, null) == propertyValue);
    if (!matchingObjects.Any())
    {
        throw new Exception($"No elements match the value of '{propertyName}'");
    }
    else if (matchingObjects.Count() > 1)
    {
        throw new Exception($"Multiple elements match the value of '{propertyName}'");
    }

    return matchingObjects.ToList();
}
