#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_NFAPI_CREDIT 1000000
#define MEMORY_POOL_SIZE 1000000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    size_t allocated_size;
    size_t used_size;
    void* memory_pool[MEMORY_POOL_SIZE];
} MemoryPool;

MemoryPool* create_memory_pool() {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) {
        printf("Error: Failed to allocate memory for memory pool\n");
        return NULL;
    }
    pthread_mutex_init(&pool->mutex, NULL);
    pool->allocated_size = 0;
    pool->used_size = 0;
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    if (pool == NULL) {
        return;
    }
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

bool allocate_memory(MemoryPool* pool, size_t size) {
    if (pool == NULL || size == 0) {
        return false;
    }
    pthread_mutex_lock(&pool->mutex);
    bool success = false;
    for (size_t i = 0; i < pool->allocated_size; i++) {
        if (pool->memory_pool[i] == NULL) {
            pool->memory_pool[i] = malloc(size);
            if (pool->memory_pool[i] != NULL) {
                success = true;
                break;
            }
        }
    }
    if (!success) {
        pool->allocated_size++;
        pool->memory_pool[pool->allocated_size - 1] = malloc(size);
        if (pool->memory_pool[pool->allocated_size - 1] != NULL) {
            success = true;
        } else {
            printf("Error: Failed to allocate memory for new block\n");
        }
    }
    pool->used_size += size;
    pthread_mutex_unlock(&pool->mutex);
    return success;
}

void deallocate_memory(MemoryPool* pool, void* ptr) {
    if (pool == NULL || ptr == NULL) {
        return;
    }
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->allocated_size; i++) {
        if (pool->memory_pool[i] == ptr) {
            free(ptr);
            pool->used_size -= size;
            break;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
}

void* allocate_array(MemoryPool* pool, size_t count, size_t size) {
    if (pool == NULL || count == 0 || size == 0) {
        return NULL;
    }
    size_t total_size = count * size;
    void* ptr = allocate_memory(pool, total_size);
    if (ptr != NULL) {
        memset(ptr, 0, total_size);
    }
    return ptr;
}

void deallocate_array(MemoryPool* pool, void* ptr, size_t count, size_t size) {
    if (pool == NULL || ptr == NULL || count == 0 || size == 0) {
        return;
    }
    size_t total_size = count * size;
    deallocate_memory(pool, ptr);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(MemoryPool* pool, uint32_t N) {
    if (pool == NULL || N > MAX_NFAPI_CREDIT) {
        return NULL;
    }
    size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    void* ptr = allocate_array(pool, N, size);
    if (ptr != NULL) {
        for (size_t i = 0; i < N; i++) {
            ((NFAPI_CRC_INDICATION_PDU_T*)ptr)[i].RX_UE_INFORMATION_TAG = rand();
            ((NFAPI_CRC_INDICATION_PDU_T*)ptr)[i].RNTI = rand();
            ((NFAPI_CRC_INDICATION_PDU_T*)ptr)[i].CRC_INDICATION_REL8_TAG = rand();
        }
    }
    return ptr;
}

void deallocate_crc_indication_pdu(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pool == NULL || pdu == NULL) {
