    int IE_LIST[10]; // fixed number of IEs per MAC_PDU
} MAC_PDU;

// cache for frequently accessed RNTIs
struct rnti_cache {
    int *rntis;
    size_t count;
};

// custom memory pool for allocation and deallocation
struct mempool {
    void **blocks;
    size_t block_size;
    size_t block_count;
};

// logging framework with asynchronous logging support
struct logger {
    FILE *file;
    char *filename;
    int log_level;
    struct mempool *mempool;
};

void init_logger(struct logger *logger, const char *filename) {
    // initialize the logger with a custom memory pool for allocation and deallocation
    logger->file = fopen(filename, "a");
    if (logger->file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    logger->filename = strdup(filename);
    logger->log_level = 0; // default log level is 0 (info)
    logger->mempool = create_mempool();
}

void destroy_logger(struct logger *logger) {
    fclose(logger->file);
    free(logger->filename);
    destroy_mempool(logger->mempool);
}

void log_message(struct logger *logger, int level, const char *format, ...) {
    // check if the log level is high enough to be logged
    if (level > logger->log_level) {
        return;
    }

    // allocate a new line in the memory pool for the message
    size_t len = strlen(format);
    char *message = malloc(len + 1);
    va_list args;
    va_start(args, format);
    vsnprintf(message, len + 1, format, args);
    va_end(args);

    // write the message to the log file
    fputs(message, logger->file);
    free(message);
}

void *create_mempool() {
    struct mempool *mempool = malloc(sizeof(struct mempool));
    if (mempool == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    mempool->blocks = calloc(10, sizeof(void*)); // allocate 10 blocks initially
    mempool->block_size = 0;
    mempool->block_count = 0;
    return mempool;
}

void destroy_mempool(struct mempool *mempool) {
    free(mempool->blocks);
    free(mempool);
}

void *allocate_memory(struct mempool *mempool, size_t size) {
    // check if the memory pool has enough space for the allocation
    if (size > mempool->block_size) {
        return NULL;
    }

    // find a free block in the memory pool
    void **block = NULL;
    for (int i = 0; i < mempool->block_count; i++) {
        if (mempool->blocks[i] == NULL) {
            block = &mempool->blocks[i];
            break;
        }
    }

    // allocate a new block if no free blocks were found
    if (block == NULL) {
        mempool->block_count++;
        mempool->blocks = realloc(mempool->blocks, mempool->block_count * sizeof(void*));
        if (mempool->blocks == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        block = &mempool->blocks[mempool->block_count - 1];
    }

    // allocate memory for the block
    *block = malloc(size);
    if (*block == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    return *block;
}

void deallocate_memory(struct mempool *mempool, void *ptr) {
    // find the block that contains the pointer
    for (int i = 0; i < mempool->block_count; i++) {
        if (mempool->blocks[i] == ptr) {
            free(mempool->blocks[i]);
            mempool->blocks[i] = NULL;
            break;
        }
    }
}

