#define MAX_NFAPI_CREDIT 10000
#define CACHE_SIZE 1024

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
} NFAPI_CRC_INDICATION_PDU_ARRAY;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int RNTI;
    int count;
} RNTI_CACHE;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_ARRAY *array = NULL;
static size_t array_size = 0;
static RNTI_CACHE cache[CACHE_SIZE];

void init_cache() {
    for (int i = 0; i < CACHE_SIZE; i++) {
        cache[i].RNTI = -1;
        cache[i].count = 0;
    }
}

NFAPI_CRC_INDICATION_PDU_T *allocate_crc_indication(int N) {
    if (N > MAX_NFAPI_CREDIT) {
        printf("Error: N exceeds maximum value of %d\n", MAX_NFAPI_CREDIT);
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    // Check if the cache has a matching RNTI
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].RNTI == N) {
            cache[i].count++;
            pthread_mutex_unlock(&mutex);
            return &array->data[i];
        }
    }

    // If no matching RNTI is found, allocate a new structure
    if (array == NULL || array->size < N) {
        size_t new_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        NFAPI_CRC_INDICATION_PDU_ARRAY *new_array = realloc(array, new_size);
        if (new_array == NULL) {
            printf("Error: Failed to allocate memory for CRC indication\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        array = new_array;
        array->size = N;
    }

    // Initialize the structure and add it to the cache
    int index = array->size - N;
    for (int i = 0; i < N; i++) {
        array->data[index + i].RX_UE_INFORMATION_TAG = 1;
        array->data[index + i].RNTI = N;
        array->data[index + i].CRC_INDICATION_REL8_TAG = 2;
        array->data[index + i].CRCFLAG = rand() % 2;
    }
    cache[index].RNTI = N;
    cache[index].count++;

    pthread_mutex_unlock(&mutex);
    return &array->data[index];
}

void deallocate_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu == NULL) {
        return;
    }

    pthread_mutex_lock(&mutex);

    // Find the index of the structure in the cache
    int index = 0;
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].RNTI == pdu->RNTI) {
            index = i;
            break;
        }
    }

    // Decrement the count of the structure in the cache
    cache[index].count--;

    // If the count is 0, remove the structure from the cache and free its memory
    if (cache[index].count == 0) {
        for (int i = index; i < CACHE_SIZE - 1; i++) {
            cache[i] = cache[i + 1];
        }
        cache[CACHE_SIZE - 1].RNTI = -1;
        cache[CACHE_SIZE - 1].count = 0;
    }

    pthread_mutex_unlock(&mutex);
}
