// Define the structure for packet data
typedef struct {
    int Packet_ID;
    char Source_Address[16];
    char Destination_Address[16];
    void* Payload;
} PACKET_DATA_T;

// Define the structure for data streams
typedef struct {
    int Stream_ID;
    time_t Start_Time;
    time_t End_Time;
    double Data_Transfer_Rate;
} DATA_STREAM_T;

// Function to process and transmit data packets over a network interface
void process_and_transmit_data_packets(PACKET_DATA_T* packet_data, int num_packets, int M) {
    // Initialize the list of data streams
    DATA_STREAM_T* data_streams = (DATA_STREAM_T*)malloc(M * sizeof(DATA_STREAM_T));
    if (!data_streams) {
        printf("Error: Failed to allocate memory for data streams\n");
        return;
    }

    // Initialize the list of packet IDs
    int* packet_ids = (int*)malloc(num_packets * sizeof(int));
    if (!packet_ids) {
        printf("Error: Failed to allocate memory for packet IDs\n");
        free(data_streams);
        return;
    }

    // Initialize the list of data transfer rates
    double* data_transfer_rates = (double*)malloc(M * sizeof(double));
    if (!data_transfer_rates) {
        printf("Error: Failed to allocate memory for data transfer rates\n");
        free(packet_ids);
        free(data_streams);
        return;
    }

    // Initialize the list of stream IDs
    int* stream_ids = (int*)malloc(M * sizeof(int));
    if (!stream_ids) {
        printf("Error: Failed to allocate memory for stream IDs\n");
        free(data_transfer_rates);
        free(packet_ids);
        free(data_streams);
        return;
    }

    // Initialize the list of start times
    time_t* start_times = (time_t*)malloc(M * sizeof(time_t));
    if (!start_times) {
        printf("Error: Failed to allocate memory for start times\n");
        free(stream_ids);
        free(data_transfer_rates);
        free(packet_ids);
        free(data_streams);
        return;
    }

    // Initialize the list of end times
    time_t* end_times = (time_t*)malloc(M * sizeof(time_t));
    if (!end_times) {
        printf("Error: Failed to allocate memory for end times\n");
        free(start_times);
        free(stream_ids);
        free(data_transfer_rates);
        free(packet_ids);
        free(data_streams);
        return;
    }

    // Initialize the list of packet IDs and data transfer rates
    for (int i = 0; i < num_packets; i++) {
        packet_ids[i] = packet_data[i].Packet_ID;
        data_transfer_rates[i] = packet_data[i].Payload->Data_Transfer_Rate;
    }

    // Initialize the list of stream IDs and start times
    for (int i = 0; i < M; i++) {
        stream_ids[i] = i + 1;
        start_times[i] = time(NULL);
    }

    // Initialize the list of end times
    for (int i = 0; i < M; i++) {
        end_times[i] = start_times[i] + (time_t)(data_transfer_rates[i] * 1000);
    }

    // Initialize the list of data streams
    for (int i = 0; i < M; i++) {
        data_streams[i].Stream_ID = stream_ids[i];
        data_streams[i].Start_Time = start_times[i];
        data_streams[i].End_Time = end_times[i];
        data_streams[i].Data_Transfer_Rate = data_transfer_rates[i];
    }

    // Process and transmit the packets over the network interface
    for (int i = 0; i < num_packets; i++) {
        // Simulate a probabilistic delay before each packet is transmitted
        double delay = rand() % 1000 / 1000.0;
        sleep(delay);

        // Transmit the packet over the network interface
        printf("Transmitting packet with ID %d\n", packet_ids[i]);
    }

    // Free the memory allocated for the lists
    free(data_streams);
    free(packet_ids);
    free(data_transfer_rates);
    free(stream_ids);
    free(start_times);
    free(end_times);
}
