#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

// Define the structure for packet data
typedef struct {
    int Packet_ID;
    char Source_Address[16];
    char Destination_Address[16];
    void* Payload;
} PACKET_DATA_T;

// Define the structure for data streams
typedef struct {
    int Stream_ID;
    time_t Start_Time;
    time_t End_Time;
    double Data_Transfer_Rate;
} DATA_STREAM_T;

// Function to process and transmit data packets over a network interface
void process_and_transmit_data_packets(PACKET_DATA_T* packet_data, int num_packets) {
    // Initialize the list of data streams
    DATA_STREAM_T* data_streams = (DATA_STREAM_T*)malloc(sizeof(DATA_STREAM_T) * M);
    if (!data_streams) {
        fprintf(stderr, "Error: Failed to allocate memory for data streams\n");
        return;
    }

    // Initialize the mutex for synchronizing access to shared resources
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Loop over each packet and process it accordingly
    for (int i = 0; i < num_packets; ++i) {
        // Acquire the lock on the mutex to prevent race conditions
        pthread_mutex_lock(&mutex);

        // Process the current packet
        PACKET_DATA_T* current_packet = &packet_data[i];
        int packet_id = current_packet->Packet_ID;
        char* source_address = current_packet->Source_Address;
        char* destination_address = current_packet->Destination_Address;
        void* payload = current_packet->Payload;

        // Determine the data stream for this packet and update its transfer rate
        DATA_STREAM_T* current_stream = NULL;
        for (int j = 0; j < M; ++j) {
            if (strcmp(data_streams[j].Source_Address, source_address) == 0 && strcmp(data_streams[j].Destination_Address, destination_address) == 0) {
                current_stream = &data_streams[j];
                break;
            }
        }
        if (!current_stream) {
            // Create a new data stream for this packet
            current_stream = (DATA_STREAM_T*)malloc(sizeof(DATA_STREAM_T));
            if (!current_stream) {
                fprintf(stderr, "Error: Failed to allocate memory for data stream\n");
                pthread_mutex_unlock(&mutex);
                return;
            }
            current_stream->Stream_ID = i;
            strcpy(current_stream->Source_Address, source_address);
            strcpy(current_stream->Destination_Address, destination_address);
            current_stream->Start_Time = time(NULL);
            current_stream->End_Time = 0;
            current_stream->Data_Transfer_Rate = 0.0;
        }

        // Update the data transfer rate for this stream
        double packet_size = (double)strlen(payload) + sizeof(PACKET_DATA_T);
        current_stream->Data_Transfer_Rate += packet_size / ((double)(current_stream->End_Time - current_stream->Start_Time));

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }

    // Clean up the data streams and free the memory allocated for them
    for (int i = 0; i < M; ++i) {
        DATA_STREAM_T* current_stream = &data_streams[i];
        if (current_stream->End_Time == 0) {
            // This stream has not been used yet, so we can safely free its memory
            free(current_stream);
        } else {
            // This stream has been used, so we need to update its end time and data transfer rate
            current_stream->End_Time = time(NULL);
            double packet_size = (double)strlen(payload) + sizeof(PACKET_DATA_T);
            current_stream->Data_Transfer_Rate += packet_size / ((double)(current_stream->End_Time - current_stream->Start_Time));
        }
    }
    free(data_streams);
}
