    if (pool == NULL) {
        return NULL;
    }
    pool->memory = malloc(size);
    if (pool->memory == NULL) {
        free(pool);
        return NULL;
    }
    pool->size = size;
    pool->num_allocated = 0;
    return pool;
}

void destroy_memory_pool(MEMORY_POOL_T* pool) {
    if (pool == NULL) {
        return;
    }
    free(pool->memory);
    free(pool);
}

void* allocate_memory(MEMORY_POOL_T* pool, size_t size) {
    if (pool == NULL || size > pool->size) {
        return NULL;
    }
    void* memory = pool->memory + pool->num_allocated * size;
    pool->num_allocated++;
    return memory;
}

void deallocate_memory(MEMORY_POOL_T* pool, void* memory) {
    if (pool == NULL || memory < pool->memory || memory > pool->memory + pool->size) {
        return;
    }
    size_t index = (uint8_t*)memory - (uint8_t*)pool->memory;
    index /= pool->size;
    pool->num_allocated--;
}

