            packet->crc_indication_pdu.crc_indication_rel8_tag.checksum = alt_checksum;
        } else {
            // If the alternative checksum does not match the expected checksum, log an error and discard the packet
            printf("Error: Checksum verification failed for packet %d\n", packet->id);
        }
    }
}

// Define the function to efficiently manage memory usage
void efficientMemoryUsage(DataPacket* packet) {
    // If the payload length is greater than a certain threshold, dynamically allocate the payload
    if (packet->payload_len > 1024) {
        packet->payload = (char*)malloc(packet->payload_len * sizeof(char));
    } else {
        // If the payload length is less than or equal to a certain threshold, use a fixed-size buffer for the payload
        char* fixed_buffer = (char*)malloc(1024 * sizeof(char));
        memcpy(fixed_buffer, packet->payload, packet->payload_len);
        packet->payload = fixed_buffer;
    }
}

