void readInputFilesConcurrently(int num_files, char** file_names) {
    // Create an array of threads for reading the input files
    pthread_t* thread_array = (pthread_t*)malloc(num_files * sizeof(pthread_t));

    // Initialize the threads for reading the input files
    for (int i = 0; i < num_files; i++) {
