    if (list == NULL) {
        return NULL;
    }

    // Initialize the count and data members of the list
    list->count = n;
    list->data = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        free(list);
