            if (json_object_is_type(val, json_type_object)) {
                // Parse the current entry as a SERVER_METRICS_T structure
                SERVER_METRICS_T server_metrics;
                json_object_object_foreach(val, field, value) {
                    if (strcmp(field, "cpu_usage") == 0) {
                        server_metrics.cpu_usage = json_object_get_int(value);
                    } else if (strcmp(field, "memory_consumption") == 0) {
                        server_metrics.memory_consumption = json_object_get_int(value);
                    } else if (strcmp(field, "network_io") == 0) {
                        server_metrics.network_io = json_object_get_int(value);
                    } else if (strcmp(field, "error_rates") == 0) {
                        server_metrics.error_rates = json_object_get_int(value);
                    }
                }

                // Add the current entry to the output file
                json_object_object_add(output, "crc_indication_pdu", json_object_new_string(crc_indication_pdu.rx_ue_information_tag));
                json_object_object_add(output, "rnti", json_object_new_string(crc_indication_pdu.rnti));
                json_object_object_add(output, "crc_indication_rel8_tag", json_object_new_string(crc_indication_pdu.crc_indication_rel8_tag));
                json_object_object_add(output, "cpu_usage", json_object_new_string(server_metrics.cpu_usage));
                json_object_object_add(output, "memory_consumption", json_object_new_string(server_metrics.memory_consumption));
                json_object_object_add(output, "network_io", json_object_new_string(server_metrics.network_io));
                json_object_object_add(output, "error_rates", json_object_new_string(server_metrics.error_rates));
            }
        }
    }

    // Close the log file
    close(fd);

    // Write the output to a new file
    int out_fd = open(output_file, O_WRONLY | O_CREAT, 0644);
    if (out_fd == -1) {
        perror("Error opening output file");
        return;
    }
    json_object_to_file(out_fd, output);
    close(out_fd);
}
