    outputfile_t* outputfiles = malloc(sizeof(outputfile_t) * MAX_CONNECTIONS);
    if (outputfiles == NULL) {
        printf("Error allocating memory for output files\n");
        return;
    }
    memset(outputfiles, 0, sizeof(outputfile_t) * MAX_CONNECTIONS);

    // Initialize counters and timestamps for performance monitoring and debugging
    int num_connections = 0;
    int num_bytes_read = 0;
    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Read log file and process logs concurrently using multiple threads
    pthread_t thread[MAX_CONNECTIONS];
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (fork() == 0) {
            // Child process reads log file and processes logs
            while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, logfile)) > 0) {
                num_bytes_read += bytes_read;
