#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for the configurations of the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_CONFIG_T;

// Define the shared buffer for appending the structures to
static NFAPI_CRC_INDICATION_PDU_T *shared_buffer = NULL;

// Define the mutex for thread-safe access to the shared buffer
static pthread_mutex_t shared_buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the total number of structures created and the total RNTI values used across all configurations
static int num_structures = 0;
static int total_rnti_values = 0;

// Define the predefined threshold for the number of used RNTI values
#define USED_RNTI_VALUES_THRESHOLD 1000

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu_list(int n, NFAPI_CRC_INDICATION_CONFIG_T *configs) {
    // Check if the input parameter 'n' is valid
    if (n < 0) {
        printf("Invalid value for 'n': %d\n", n);
        return NULL;
    }

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (list == NULL) {
        printf("Failed to allocate memory for the list of structures\n");
        return NULL;
    }

    // Initialize the running checksum of RNTI values
    uint32_t rnti_checksum = 0;

    // Iterate over each structure in the list and populate it with valid data
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list[i];

        // Set the RX_UE_INFORMATION_TAG and RNTI values based on the configuration
        pdu->rx_ue_information_tag = configs[i].rx_ue_information_tag;
        pdu->rnti = configs[i].rnti;

        // Set the CRCFLAG value randomly
        pdu->crc_indication_rel8_tag = rand() % 2;

        // Update the running checksum of RNTI values
        rnti_checksum += pdu->rnti;
    }

    // Check if the total number of structures created exceeds the predefined threshold
    if (num_structures + n > USED_RNTI_VALUES_THRESHOLD) {
        printf("Total number of structures created exceeds the predefined threshold\n");
        return NULL;
    }

    // Increment the total number of structures created and the total RNTI values used across all configurations
    num_structures += n;
    total_rnti_values += rnti_checksum;

    // Append the list of structures to the shared buffer in a thread-safe manner
    pthread_mutex_lock(&shared_buffer_mutex);
    if (shared_buffer == NULL) {
        shared_buffer = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
        if (shared_buffer == NULL) {
            printf("Failed to allocate memory for the shared buffer\n");
            pthread_mutex_unlock(&shared_buffer_mutex);
            return NULL;
        }
    }
    memcpy(shared_buffer + num_structures, list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    pthread_mutex_unlock(&shared_buffer_mutex);

    // Return the list of structures
    return list;
}

// Function to handle errors in the shared buffer operations
void handle_shared_buffer_error(const char *message) {
    printf("Error: %s\n", message);
    pthread_mutex_lock(&shared_buffer_mutex);
    if (shared_buffer != NULL) {
        free(shared_buffer);
        shared_buffer = NULL;
    }
    pthread_mutex_unlock(&shared_buffer_mutex);
}
```
