    int cache_size;
    CRCIndicationPdu* cache[];
} CacheLayer;

// Define the function for generating a list of CRC indication PDUs
void generateCRCIndications(int N, ConfigurationOptions options, LoggingMechanism logging) {
    // Initialize the running checksum and RNTI values
    int checksum = 0;
    int rnti_values[N];

    // Generate a random number for each RNTI value
    for (int i = 0; i < N; i++) {
        rnti_values[i] = generateRandomNumber();
        checksum += rnti_values[i];
