        pdu_list[i].crc_indication.rnti = rnti_values[i];

        // Generate a random CRC indication REL8 tag
        pdu_list[i].crc_indication.crc_indication_rel8_tag = generateRandomNumber();

        // Set the CRCFLAG to a randomly set value
        pdu_list[i].crc_indication.crcflag = generateRandomNumber() % 2;
    }

    // Maintain the running checksum of all RNTI values
    logging.log_file = fopen("crc_indications.log", "a");
    if (logging.enable_logging) {
        fprintf(logging.log_file, "Checksum: %d\n", checksum);
    }

    // Optimize the list for memory usage and access patterns
    optimizeListForMemoryUsageAndAccessPatterns(pdu_list, N);

    // Return the generated list of CRC indication PDUs
    return pdu_list;
}

// Generate a random number using an external library
int generateRandomNumber() {
    // Use the rand() function from the standard library to generate a random number
    int random_number = rand();

    // Handle potential integration issues and version mismatches gracefully
    if (random_number == 0) {
        return generateRandomNumber();
    } else {
        return random_number;
    }
}

