#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t num_pdus;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T *create_crc_indication_list(size_t n) {
    // Check if the input value is valid
    if (n == 0 || n > 10000) {
        return NULL;
    }

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (list == NULL) {
        return NULL;
    }

    // Initialize the list and allocate memory for the structures
    list->pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->pdu_list == NULL) {
        free(list);
        return NULL;
    }

    // Initialize the number of structures in the list
    list->num_pdus = n;

    // Set the RX_UE_INFORMATION_TAG and RNTI for each structure
    for (size_t i = 0; i < n; i++) {
        list->pdu_list[i].rx_ue_information_tag = i + 1;
        list->pdu_list[i].rnti = i * 23 + 17;
    }

    // Set the CRCFLAG for each structure randomly
    for (size_t i = 0; i < n; i++) {
        list->pdu_list[i].crc_indication_rel8_tag = rand() % 2;
    }

    // Calculate the running checksum of all RNTI values included in the list
    uint32_t checksum = 0;
    for (size_t i = 0; i < n; i++) {
        checksum += list->pdu_list[i].rnti;
    }

    // Log a warning message if the number of structures exceeds the available system memory
    if (n > 10000) {
        printf("Warning: The number of structures (%zu) exceeds the available system memory\n", n);
    }

    // Return the list of NFAPI_CRC_INDICATION_PDU_T structures
    return list;
}

// Define the function to update the list with new structures and recalculate the checksum
void update_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list, size_t n) {
    // Check if the input value is valid
    if (n == 0 || n > 10000) {
        return;
    }

    // Allocate memory for the new structures
    NFAPI_CRC_INDICATION_PDU_T *new_pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu_list == NULL) {
        return;
    }

    // Set the RX_UE_INFORMATION_TAG and RNTI for each new structure
    for (size_t i = 0; i < n; i++) {
        new_pdu_list[i].rx_ue_information_tag = list->num_pdus + i + 1;
        new_pdu_list[i].rnti = list->num_pdus * 23 + i * 17;
    }

    // Set the CRCFLAG for each new structure randomly
    for (size_t i = 0; i < n; i++) {
        new_pdu_list[i].crc_indication_rel8_tag = rand() % 2;
    }

    // Append the new structures to the existing list and recalculate the checksum
    for (size_t i = 0; i < n; i++) {
        list->pdu_list[i + list->num_pdus] = new_pdu_list[i];
    }
    free(new_pdu_list);

    // Calculate the running checksum of all RNTI values included in the list
    uint32_t checksum = 0;
    for (size_t i = 0; i < list->num_pdus + n; i++) {
        checksum += list->pdu_list[i].rnti;
    }
}

// Define the function to free the memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    if (list == NULL) {
        return;
    }
    free(list->pdu_list);
    free(list);
}
