// Function to initialize and populate a dynamic array of FrameStatistics structures
FrameStatistics* initAndPopulateFrameStats(int numFrames, int numChannels, float signalThreshold) {
    // Allocate memory for the array of FrameStatistics structures
    FrameStatistics* frameStats = (FrameStatistics*)malloc(numFrames * sizeof(FrameStatistics));
    if (!frameStats) {
        printf("Error: Failed to allocate memory for frame statistics\n");
        return NULL;
    }

    // Initialize the timestamp and sequence number for each FrameStatistics structure
    for (int i = 0; i < numFrames; i++) {
        frameStats[i].timestamp = 0;
        frameStats[i].sequenceNumber = i + 1;
    }

    // Populate the measurements for each FrameStatistics structure based on signal strength thresholds
    for (int i = 0; i < numFrames; i++) {
        for (int j = 0; j < numChannels; j++) {
            ChannelMeasurement measurement = {0};
            measurement.frequency = j + 1;
            measurement.signalStrength = rand() % 100;
            measurement.noiseLevel = rand() % 100;
            if (measurement.signalStrength >= signalThreshold) {
                frameStats[i].measurements[j] = measurement;
            }
        }
    }

    // Log the creation and deletion of FrameStatistics structures for debugging purposes
    printf("Created %d FrameStatistics structures\n", numFrames);
    return frameStats;
}

// Function to deallocate memory for a dynamic array of FrameStatistics structures
void freeFrameStats(FrameStatistics* frameStats, int numFrames) {
    if (frameStats) {
        printf("Deleted %d FrameStatistics structures\n", numFrames);
        free(frameStats);
    }
}
