#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for FrameStatistics
typedef struct {
    long timestamp;
    int sequence_number;
    ChannelMeasurement *measurements;
} FrameStatistics;

// Define the structure for ChannelMeasurement
typedef struct {
    float frequency;
    float signal_strength;
    float noise_level;
} ChannelMeasurement;

// Define the dynamic array of FrameStatistics structures
FrameStatistics *frame_statistics = NULL;
size_t frame_statistics_capacity = 0;
size_t frame_statistics_count = 0;
pthread_mutex_t frame_statistics_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the function to initialize and populate the dynamic array of FrameStatistics structures
void init_frame_statistics(size_t capacity) {
    // Allocate memory for the dynamic array of FrameStatistics structures
    frame_statistics = (FrameStatistics *)malloc(capacity * sizeof(FrameStatistics));
    if (!frame_statistics) {
        fprintf(stderr, "Failed to allocate memory for frame statistics\n");
        exit(1);
    }
    // Initialize the capacity of the dynamic array
    frame_statistics_capacity = capacity;
    // Set the count of the dynamic array to 0
    frame_statistics_count = 0;
}

// Define the function to add a new FrameStatistics structure to the dynamic array
void add_frame_statistics(long timestamp, int sequence_number, ChannelMeasurement *measurements) {
    // Acquire the lock on the frame statistics
    pthread_mutex_lock(&frame_statistics_lock);
    // Check if the capacity of the dynamic array has been reached
    if (frame_statistics_count == frame_statistics_capacity) {
        // Dynamically resize the dynamic array to prevent performance degradation
        size_t new_capacity = frame_statistics_capacity * 2;
        FrameStatistics *new_frame_statistics = (FrameStatistics *)realloc(frame_statistics, new_capacity * sizeof(FrameStatistics));
        if (!new_frame_statistics) {
            fprintf(stderr, "Failed to resize frame statistics\n");
            exit(1);
        }
        // Update the capacity of the dynamic array and the pointer to it
        frame_statistics = new_frame_statistics;
        frame_statistics_capacity = new_capacity;
    }
    // Add a new FrameStatistics structure to the dynamic array
    frame_statistics[frame_statistics_count].timestamp = timestamp;
    frame_statistics[frame_statistics_count].sequence_number = sequence_number;
    frame_statistics[frame_statistics_count].measurements = measurements;
    // Increment the count of the dynamic array
    frame_statistics_count++;
    // Release the lock on the frame statistics
    pthread_mutex_unlock(&frame_statistics_lock);
}

// Define the function to delete a FrameStatistics structure from the dynamic array
void delete_frame_statistics(size_t index) {
    // Acquire the lock on the frame statistics
    pthread_mutex_lock(&frame_statistics_lock);
    // Check if the index is valid
    if (index >= frame_statistics_count) {
        fprintf(stderr, "Invalid index for deleting frame statistics\n");
        exit(1);
    }
    // Decrement the count of the dynamic array
    frame_statistics_count--;
    // Shift all the elements after the deleted element to the left
    memmove(&frame_statistics[index], &frame_statistics[index + 1], (frame_statistics_count - index) * sizeof(FrameStatistics));
    // Release the lock on the frame statistics
    pthread_mutex_unlock(&frame_statistics_lock);
}

// Define the function to filter FrameStatistics structures based on signal strength thresholds
void filter_frame_statistics(float threshold) {
    // Acquire the lock on the frame statistics
    pthread_mutex_lock(&frame_statistics_lock);
    // Iterate over all the FrameStatistics structures in the dynamic array
    for (size_t i = 0; i < frame_statistics_count; i++) {
        // Check if the signal strength of the current ChannelMeasurement structure is below the threshold
        if (frame_statistics[i].measurements->signal_strength < threshold) {
            // Delete the FrameStatistics structure from the dynamic array
            delete_frame_statistics(i);
            // Decrement the count of the dynamic array and continue to the next element
            i--;
        }
    }
    // Release the lock on the frame statistics
    pthread_mutex_unlock(&frame_statistics_lock);
}

// Define the function to log the creation and deletion of FrameStatistics structures for debugging purposes
void log_frame_statistics(int enable) {
    // Acquire the lock on the frame statistics
    pthread_mutex_lock(&frame_statistics_lock);
    // Check if logging is enabled
    if (enable) {
        // Log the creation of each FrameStatistics structure
        for (size_t i = 0; i < frame_statistics_count; i++) {
            printf("Created FrameStatistics with timestamp %ld and sequence number %d\n", frame_statistics[i].timestamp, frame_statistics[i].sequence_number);
        }
    } else {
        // Log the deletion of each FrameStatistics structure
        for (size_t i = 0; i < frame_statistics_count; i++) {
            printf("Deleted FrameStatistics with timestamp %ld and sequence number %d\n", frame_statistics[i].timestamp, frame_statistics[i].sequence_number);
        }
    }
    // Release the lock on the frame statistics
    pthread_mutex_unlock(&frame_statistics_lock);
}

// Define the function to handle concurrent access from multiple threads
void handle_concurrent_access(FrameStatistics *frame_statistics, size_t index) {
    // Acquire the lock on the frame statistics
    pthread_mutex_lock(&frame_statistics_lock);
    // Check if the index is valid
    if (index >= frame_statistics_count) {
        fprintf(stderr, "Invalid index for concurrent access\n");
        exit(1);
    }
    // Release the lock on the frame statistics
    pthread_mutex_unlock(&frame_statistics_lock);
}

// Define the function to optimize memory usage during peak load periods
void optimize_memory_usage() {
    // Acquire the lock on the frame statistics
    pthread_mutex_lock(&frame_statistics_lock);
    // Check if the capacity of the dynamic array has been reached
    if (frame_statistics_count == frame_statistics_capacity) {
        // Dynamically resize the dynamic array to prevent performance degradation
        size_t new_capacity = frame_statistics_capacity * 2;
        FrameStatistics *new_frame_statistics = (FrameStatistics *)realloc(frame_statistics, new_capacity * sizeof(FrameStatistics));
        if (!new_frame_statistics) {
            fprintf(stderr, "Failed to resize frame statistics\n");
            exit(1);
        }
        // Update the capacity of the dynamic array and the pointer to it
        frame_statistics = new_frame_statistics;
        frame_statistics_capacity = new_capacity;
    }
    // Release the lock on the frame statistics
    pthread_mutex_unlock(&frame_statistics_lock);
}
