// Define the function to initialize and populate a dynamic array of FrameStatistics structures
void init_frame_statistics(FrameStatistics **frames, int *num_frames, char *filename, char *directory_path, float rsrp_threshold) {
    // Initialize the dynamic array of FrameStatistics structures
    *frames = (FrameStatistics *)malloc(sizeof(FrameStatistics));
    if (*frames == NULL) {
        printf("Error: Failed to allocate memory for frames\n");
        return;
    }
    *num_frames = 0;

    // Open the file and read its contents
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: Failed to open file %s\n", filename);
        return;
    }
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Parse the line and extract the timestamp, sequence number, and channel measurements
        time_t timestamp = strtol(line, NULL, 10);
        int sequence_number = strtol(line + 10, NULL, 10);
        ChannelMeasurement *channel_measurements = (ChannelMeasurement *)malloc(sizeof(ChannelMeasurement));
        if (channel_measurements == NULL) {
            printf("Error: Failed to allocate memory for channel measurements\n");
            return;
        }
        // Fill in the ChannelMeasurement structure with the extracted values
        channel_measurements->frequency = strtof(line + 20, NULL);
        channel_measurements->signal_strength = strtof(line + 30, NULL);
        channel_measurements->noise_level = strtof(line + 40, NULL);

        // Add the ChannelMeasurement structure to the FrameStatistics structure
        (*frames)[*num_frames].timestamp = timestamp;
        (*frames)[*num_frames].sequence_number = sequence_number;
        (*frames)[*num_frames].channel_measurements = channel_measurements;
        (*num_frames)++;
    }
    fclose(file);

    // Filter the FrameStatistics structures based on the RSRP threshold
    int filtered_num_frames = 0;
    for (int i = 0; i < *num_frames; i++) {
        if ((*frames)[i].channel_measurements->signal_strength >= rsrp_threshold) {
            (*frames)[filtered_num_frames] = (*frames)[i];
            filtered_num_frames++;
        }
    }
    *num_frames = filtered_num_frames;

    // Rename the file with a version number and timestamp
    char new_filename[1024];
    sprintf(new_filename, "%s/%s_v%d_%s", directory_path, filename, (*frames)[0].timestamp, (*frames)[0].sequence_number);
    if (rename(filename, new_filename) != 0) {
        printf("Error: Failed to rename file %s\n", filename);
        return;
    }

    // Log the renaming operation with detailed metadata
    log_renaming_operation(new_filename, (*frames)[0].timestamp, (*frames)[0].sequence_number);
}

// Define the function to handle network failures and persist logs locally until the logging service is available again
void handle_network_failure() {
    // Implement mechanisms for graceful degradation in case of resource exhaustion or unexpected errors
}

// Define the function to implement efficient memory management and prevent leaks and proper resource freeing upon completion or error conditions
void cleanup(FrameStatistics **frames, int *num_frames) {
    // Free the dynamically allocated memory for the FrameStatistics structures
    for (int i = 0; i < *num_frames; i++) {
        free((*frames)[i].channel_measurements);
    }
    free(*frames);
