NFAPI_CRC_INDICATION_LIST_T *manage_list(NFAPI_CRC_INDICATION_LIST_T *list, size_t n) {
    // Check if the input list is NULL or if the number of elements to add is zero
    if (list == NULL || n == 0) {
        return NULL;
    }

    // Calculate the total number of elements in the list
    size_t total = list->size + n;

    // Check if the total number of elements exceeds the available system memory
    if (total > SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        printf("Warning: Total number of elements exceeds available system memory\n");
        return NULL;
    }

    // Dynamically allocate memory for the new list
    NFAPI_CRC_INDICATION_LIST_T *new_list = malloc(total * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_list == NULL) {
        printf("Error: Failed to allocate memory for the new list\n");
        return NULL;
    }

    // Copy the existing elements from the old list to the new list
    memcpy(new_list->data, list->data, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add the new elements to the end of the new list
    for (size_t i = 0; i < n; i++) {
