void checksum_verification(DataPacket* data_packet) {
    // Calculate the checksum of the payload using a hashing method
    uint32_t checksum = hash(data_packet->payload, data_packet->payload_length);

    // If the calculated checksum does not match the expected checksum, attempt to recompute the checksum using an alternative hashing method
    if (checksum != data_packet->checksum) {
        uint32_t alt_checksum = hash(data_packet->payload, data_packet->payload_length);
        if (alt_checksum == data_packet->checksum) {
            // If the alternative checksum matches the expected checksum, update the payload with the new checksum and continue processing
            data_packet->checksum = alt_checksum;
        } else {
            // If the alternative checksum does not match the expected checksum, log an error and discard the packet
            printf("Error: Checksum verification failed for packet %d\n", data_packet->id);
            free(data_packet->payload);
        }
    }
