// Define structure for TPS data record
typedef struct {
    time_t timestamp;
    int sensor_id;
    bool status_flag;
} TPS_DATA_RECORD;

// Define structure for initialization parameters
typedef struct {
    int num_sensor_configs;
    int *allowed_sensor_ids;
    int *status_flags;
} INIT_PARAMS;

// Define shared buffer for storing TPS data records
#define BUFFER_SIZE 1024
static TPS_DATA_RECORD *buffer = NULL;
static pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;

// Define function to populate list of TPS data records based on sensor readings
void populate_list(int num_sensor_configs, int *allowed_sensor_ids, int *status_flags) {
    // Initialize list of TPS data records
    TPS_DATA_RECORD *list = NULL;

    // Iterate over each sensor configuration
    for (int i = 0; i < num_sensor_configs; i++) {
        // Get current sensor ID and status flag
        int sensor_id = allowed_sensor_ids[i];
        bool status_flag = status_flags[i];

        // Check if sensor ID is already in use
        bool id_in_use = false;
        for (int j = 0; j < i; j++) {
            if (allowed_sensor_ids[j] == sensor_id) {
                id_in_use = true;
                break;
            }
        }

        // If sensor ID is not in use, create new record and append to list
        if (!id_in_use) {
            TPS_DATA_RECORD *record = malloc(sizeof(TPS_DATA_RECORD));
            record->timestamp = time(NULL);
            record->sensor_id = sensor_id;
            record->status_flag = status_flag;
            list = realloc(list, (i + 1) * sizeof(TPS_DATA_RECORD));
            list[i] = record;
        }
    }

    // Add records to shared buffer for further processing
    pthread_mutex_lock(&buffer_lock);
    while (buffer != NULL && BUFFER_SIZE <= buffer->size) {
        sleep(1);  // Wait until buffer is available
    }
    if (buffer == NULL) {
        buffer = malloc(sizeof(TPS_DATA_RECORD));
        buffer->size = 0;
    }
    for (int i = 0; i < list->size; i++) {
        TPS_DATA_RECORD *record = list[i];
        buffer = realloc(buffer, (buffer->size + 1) * sizeof(TPS_DATA_RECORD));
        buffer[buffer->size] = record;
        buffer->size++;
    }
    pthread_mutex_unlock(&buffer_lock);
}

// Define function to maintain rolling average of timestamps for each sensor over a specified window size
void maintain_rolling_average(int num_sensor_configs, int *allowed_sensor_ids, int *status_flags) {
    // Initialize rolling average for each sensor
    int *rolling_averages = malloc(num_sensor_configs * sizeof(int));
    for (int i = 0; i < num_sensor_configs; i++) {
        rolling_averages[i] = 0;
    }

    // Iterate over each sensor configuration
    for (int i = 0; i < num_sensor_configs; i++) {
        // Get current sensor ID and status flag
        int sensor_id = allowed_sensor_ids[i];
        bool status_flag = status_flags[i];

        // Check if sensor ID is in use
        bool id_in_use = false;
        for (int j = 0; j < i; j++) {
            if (allowed_sensor_ids[j] == sensor_id) {
                id_in_use = true;
                break;
            }
        }

        // If sensor ID is in use, update rolling average
        if (id_in_use) {
            TPS_DATA_RECORD *record = malloc(sizeof(TPS_DATA_RECORD));
            record->timestamp = time(NULL);
            record->sensor_id = sensor_id;
            record->status_flag = status_flag;
            rolling_averages[i] += record->timestamp;
        }
    }

    // Calculate average timestamp for each sensor over window size
    int window_size = 10;  // Specify desired window size
    for (int i = 0; i < num_sensor_configs; i++) {
        rolling_averages[i] /= window_size;
    }
}

