                id_in_use = true;
                break;
            }
        }

        // If sensor ID is in use, increment counters
        if (id_in_use) {
            total_records++;
            unique_sensor_ids++;
        }
    }

    // Print resource usage information to console
    printf("Total records created: %d\n", total_records);
    printf("Unique sensor IDs used: %d\n", unique_sensor_ids);
}

// Define function to handle errors during shared buffer operations
void handle_error(const char *message) {
    // Log error message and attempt to recover gracefully
    fprintf(stderr, "Error: %s\n", message);
    pthread_mutex_unlock(&buffer_lock);
}
