struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
};

class AttackSequenceManager {
private:
    vector<NFAPI_CRC_INDICATION_PDU_T> attackSequences;
    mutex sharedBufferMutex;
    condition_variable sharedBufferCondition;
    uint32_t totalStructuresCreated = 0;
    uint32_t totalRNTIValuesUsed = 0;
    bool isPaused = false;
    uint32_t maxAllowedRNTIValues = 1000;
    uint32_t cooldownPeriod = 4; // seconds
    uint32_t activeCombatModeCooldownPeriod = 1; // seconds
    bool isActiveCombatModeEnabled = false;
    uint32_t currentRNTIValue = 0;
    uint32_t totalAttackChoicesLogged = 0;

public:
    AttackSequenceManager() {
        attackSequences.reserve(100); // preallocate memory for 100 structures
    }

    void createAndExecuteAttackSequence(uint32_t N) {
        if (N == 0) {
            return;
        }

        vector<NFAPI_CRC_INDICATION_PDU_T> newAttackSequences;
        newAttackSequences.reserve(N);

        for (uint32_t i = 0; i < N; ++i) {
            NFAPI_CRC_INDICATION_PDU_T attackSequence;
            attackSequence.RX_UE_INFORMATION_TAG = rand() % 1000;
            attackSequence.RNTI = currentRNTIValue++;
            attackSequence.CRCFLAG = rand() % 2;
            newAttackSequences.push_back(attackSequence);
        }

        {
            lock_guard<mutex> lock(sharedBufferMutex);
            totalStructuresCreated += N;
            totalRNTIValuesUsed += currentRNTIValue - 1;
            if (totalRNTIValuesUsed >= maxAllowedRNTIValues) {
                isPaused = true;
            }
        }

        sharedBufferCondition.notify_all();
    }

    void selectAndExecuteAttack() {
        if (!isActiveCombatModeEnabled) {
            return;
        }

        lock_guard<mutex> lock(sharedBufferMutex);
        if (totalStructuresCreated == 0 || isPaused) {
            return;
        }

        // select and execute an attack pattern
        NFAPI_CRC_INDICATION_PDU_T* attackSequence = &attackSequences[rand() % totalStructuresCreated];
        cout << "Executing attack sequence with RNTI value: " << attackSequence->RNTI << endl;
        // log the attack choice for debugging purposes
        ++totalAttackChoicesLogged;
        if (totalAttackChoicesLogged % 100 == 0) {
            cout << "Total number of attack choices logged: " << totalAttackChoicesLogged << endl;
        }
    }

    void pauseCreation() {
        lock_guard<mutex> lock(sharedBufferMutex);
        isPaused = true;
    }

    void resumeCreation() {
        lock_guard<mutex> lock(sharedBufferMutex);
        isPaused = false;
    }

    bool isCreationPaused() {
        lock_guard<mutex> lock(sharedBufferMutex);
        return isPaused;
    }

    void setActiveCombatModeEnabled(bool enabled) {
        lock_guard<mutex> lock(sharedBufferMutex);
        isActiveCombatModeEnabled = enabled;
    }

    bool isActiveCombatModeEnabled() {
        lock_guard<mutex> lock(sharedBufferMutex);
        return isActiveCombatModeEnabled;
    }

    void setCooldownPeriod(uint32_t period) {
        lock_guard<mutex> lock(sharedBufferMutex);
        cooldownPeriod = period;
    }

    uint32_t getCooldownPeriod() {
        lock_guard<mutex> lock(sharedBufferMutex);
        return cooldownPeriod;
    }

    void setActiveCombatModeCooldownPeriod(uint32_t period) {
        lock_guard<mutex> lock(sharedBufferMutex);
        activeCombatModeCooldownPeriod = period;
    }

    uint32_t getActiveCombatModeCooldownPeriod() {
        lock_guard<mutex> lock(sharedBufferMutex);
        return activeCombatModeCooldownPeriod;
    }
};
