DataStorageLayer *create_data_storage_layer(int id, long timestamp, int source_id, int dest_id, size_t payload_len, char *payload, ComplexSignalTrace *trace) {
    DataStorageLayer *layer = malloc(sizeof(DataStorageLayer));
    layer->id = id;
    layer->timestamp = timestamp;
    layer->source_id = source_id;
    layer->dest_id = dest_id;
    layer->payload_len = payload_len;
    layer->payload = malloc(payload_len);
    memcpy(layer->payload, payload, payload_len);
    layer->trace = trace;
    return layer;
}

