    free(layer->payload);
    free(layer);
}

// Define the function to add a data packet to the data storage layer
void add_data_packet(DataStorageLayer *layer, DataPacket *packet) {
    // Check if the queue is full
    if (layer->size == layer->capacity) {
        // Double the capacity of the queue
        layer->capacity *= 2;
        layer->data = realloc(layer->data, layer->capacity * sizeof(DataPacket *));
    }
    // Add the packet to the end of the queue
    layer->data[layer->tail] = packet;
    layer->tail = (layer->tail + 1) % layer->capacity;
    layer->size++;
}

// Define the function to remove a data packet from the data storage layer
DataPacket *remove_data_packet(DataStorageLayer *layer) {
    // Check if the queue is empty
    if (layer->size == 0) {
        return NULL;
    }
    // Remove the packet from the head of the queue
    DataPacket *packet = layer->data[layer->head];
    layer->head = (layer->head + 1) % layer->capacity;
    layer->size--;
    return packet;
}

