    // Allocate memory for the serialized data
    *buffer = malloc(len);
    // Serialize the length of the signal trace
    memcpy(*buffer, &trace->length, sizeof(size_t));
    // Serialize the signal trace
    memcpy(*buffer + sizeof(size_t), trace->data, trace->length);
}

// Define the function to deserialize a complex cellular signal trace
ComplexSignalTrace *deserialize_complex_signal_trace(char **buffer) {
    // Calculate the length of the serialized data
    size_t len = sizeof(size_t) + (*buffer)[sizeof(size_t)];
    // Allocate memory for the deserialized signal trace
    ComplexSignalTrace *trace = malloc(len);
    // Deserialize the length of the signal trace
    memcpy(&trace->length, *buffer, sizeof(size_t));
    // Deserialize the signal trace
    memcpy(trace->data, *buffer + sizeof(size_t), trace->length);
    return trace;
}

