    // Calculate the average processing time for both synchronous and asynchronous data flows
    double sync_time = 0;
    double async_time = 0;
    // Measure the processing time for a large number of data packets using both synchronous and asynchronous data flows
    for (int i = 0; i < 1000; i++) {
        sync_time += process_data(create_data_packet(i, i * 2, i * 3, "Hello World!"));
        async_time += process_data_async(create_data_packet(i, i * 2, i * 3, "Hello World!"));
    }
