#include <string.h>
#include <time.h>
#include <math.h>

// Structure to store sequence data
typedef struct SequenceData {
    int id;
    time_t timestamp;
    double value;
} SequenceData;

// Function to generate a list of sequence data with the given number N
SequenceData* generateSequenceIndications(int N) {
    // Check if N is valid
    if (N <= 0) {
        return NULL;
    }

    // Allocate memory for the list of sequences
    SequenceData* sequences = malloc(sizeof(SequenceData) * N);
    if (!sequences) {
        printf("Error: Failed to allocate memory for sequence data\n");
        return NULL;
    }

    // Initialize the running average and sequence identifier counter
    double avg = 0.0;
    int id_counter = 1;

    // Loop through each sequence in the list
    for (int i = 0; i < N; i++) {
        // Generate a random timestamp
        time_t timestamp = generateRandomTimestamp();

        // Calculate the sequence value using the running average and the current timestamp
        double value = avg + (timestamp - avg) / (i + 1);

        // Store the sequence data in the list
        sequences[i].id = id_counter++;
        sequences[i].timestamp = timestamp;
        sequences[i].value = value;

        // Update the running average
        avg = value;
    }

    // Return the generated list of sequences
    return sequences;
}

// Function to generate a random timestamp
time_t generateRandomTimestamp() {
    // Generate a random number between 0 and 1
    double rand_num = (double)rand() / RAND_MAX;

    // Convert the random number to a timestamp
    time_t timestamp = (time_t)(rand_num * TIMESTAMP_RANGE);

    return timestamp;
}

// Function to calculate the average of a list of sequence values
double calculateAverage(SequenceData* sequences, int N) {
    // Check if N is valid
    if (N <= 0) {
        return 0.0;
    }

    // Initialize the sum and count variables
    double sum = 0.0;
    int count = 0;

    // Loop through each sequence in the list
    for (int i = 0; i < N; i++) {
        // Add the sequence value to the sum and increment the count
        sum += sequences[i].value;
        count++;
    }

    // Return the average of the list
    return sum / count;
}
