// Define the function to manage multiple lists of sensor data records
void manage_sensor_data(SENSOR_CONFIGURATION *configurations, int num_configurations) {
    // Initialize the semaphore for synchronizing access to the shared buffer
    sem_t *sem = sem_open("shared_buffer", O_CREAT, 0644, 1);

    // Loop over each sensor configuration
    for (int i = 0; i < num_configurations; ++i) {
