using namespace std;

struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
};

class AttackSequenceManager {
private:
    vector<NFAPI_CRC_INDICATION_PDU_T> attackSequences;
    mutex sharedBufferMutex;
    condition_variable sharedBufferCondition;
    uint32_t totalStructuresCreated = 0;
    uint32_t totalRNTIValuesUsed = 0;
    uint32_t maxAllowedRNTIValues = 1000;
    uint32_t cooldownPeriod = 4000; // in milliseconds
    bool activeCombatMode = false;
    bool paused = false;
    bool shutdownRequested = false;

public:
    AttackSequenceManager() {
        attackSequences.reserve(100);
    }

    void createAndExecuteAttackSequence(uint32_t N) {
        if (N == 0) {
            return;
        }

        // Check if the system has reached the predefined threshold of used RNTI values
        if (totalRNTIValuesUsed >= maxAllowedRNTIValues) {
            paused = true;
            while (paused) {
                this_thread::sleep_for(chrono::milliseconds(10));
            }
        }

        // Populate the list of attack sequences with randomly set CRCFLAG values
        for (uint32_t i = 0; i < N; ++i) {
            NFAPI_CRC_INDICATION_PDU_T sequence;
            sequence.RX_UE_INFORMATION_TAG = rand() % 1000;
            sequence.RNTI = rand() % 1000;
            sequence.CRCFLAG = rand() % 2;
            attackSequences.push_back(sequence);
        }

        // Increment the total number of structures created and RNTI values used
        totalStructuresCreated += N;
        totalRNTIValuesUsed += N;

