        cout << "Attack chosen: RX_UE_INFORMATION_TAG=" << sequence.RX_UE_INFORMATION_TAG << ", RNTI=" << sequence.RNTI << ", CRCFLAG=" << sequence.CRCFLAG << endl;

        // Execute the attack pattern with a cooldown period to prevent overwhelming the system
        this_thread::sleep_for(chrono::milliseconds(cooldownPeriod));
