    int rnti_checksum;
} RNTIChecksum;

// Function to process a list of FinancialTransaction structures
void processFinancialTransactions(TransactionList* transaction_list, ConfigurationOptions* config) {
    // Initialize the running checksum of all RNTI values included in the list
    RNTIChecksum rnti_checksum = {0};

    // Iterate over each transaction in the list
    for (size_t i = 0; i < transaction_list->num_transactions; i++) {
        FinancialTransaction* transaction = &transaction_list->transactions[i];

        // Check if the customer ID is valid according to the configuration options
        bool is_customer_id_valid = true;
        if (config->customer_id_pattern != NULL) {
            is_customer_id_valid = strcmp(transaction->customer_id, config->customer_id_pattern) == 0;
        }

        // Check if the transaction amount meets the minimum and maximum thresholds
        bool is_amount_valid = true;
        if (config->min_transaction_amount > 0 || config->max_transaction_amount > 0) {
            is_amount_valid = transaction->amount >= config->min_transaction_amount && transaction->amount <= config->max_transaction_amount;
        }

        // If the customer ID and amount are both valid, add the transaction to the list of NFAPI_CRC_INDICATION_PDU_T structures
        if (is_customer_id_valid && is_amount_valid) {
            // Allocate memory for a new NFAPI_CRC_INDICATION_PDU_T structure
            NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (pdu == NULL) {
                printf("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure\n");
                continue;
            }

            // Set the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields of the new structure
            pdu->rx_ue_information_tag = 0x1234;
            pdu->rnti = transaction->customer_id;
            pdu->crc_indication_rel8_tag = 0x5678;

            // Set the CRCFLAG field of the new structure to a randomly set value
            pdu->crcflag = rand() % 2 == 0 ? true : false;

            // Add the new structure to the list of NFAPI_CRC_INDICATION_PDU_T structures
            transaction_list->pdu_list = realloc(transaction_list->pdu_list, (transaction_list->num_pdus + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (transaction_list->pdu_list == NULL) {
                printf("Error: Failed to reallocate memory for NFAPI_CRC_INDICATION_PDU_T structure\n");
                continue;
            }
            transaction_list->pdu_list[transaction_list->num_pdus++] = *pdu;

            // Update the running checksum of all RNTI values included in the list
            rnti_checksum.rnti_checksum += pdu->rnti;
        }
    }

    // Calculate the total transaction volume, average transaction amount, and identify the highest and lowest transaction amounts
    int total_transaction_volume = 0;
    float average_transaction_amount = 0.0f;
    int highest_transaction_amount = INT_MIN;
    int lowest_transaction_amount = INT_MAX;
    for (size_t i = 0; i < transaction_list->num_transactions; i++) {
        FinancialTransaction* transaction = &transaction_list->transactions[i];
        total_transaction_volume += transaction->amount;
        average_transaction_amount += transaction->amount;
        if (transaction->amount > highest_transaction_amount) {
            highest_transaction_amount = transaction->amount;
        }
        if (transaction->amount < lowest_transaction_amount) {
            lowest_transaction_amount = transaction->amount;
        }
    }
    average_transaction_amount /= transaction_list->num_transactions;

    // Serialize the processed transactions for storage and return the running checksum of all RNTI values included in the list
    char* serialized_transactions = malloc(sizeof(FinancialTransaction) * transaction_list->num_transactions);
    if (serialized_transactions == NULL) {
        printf("Error: Failed to allocate memory for serialized transactions\n");
        return;
    }
    memcpy(serialized_transactions, transaction_list->transactions, sizeof(FinancialTransaction) * transaction_list->num_transactions);
    free(transaction_list->transactions);
    transaction_list->transactions = serialized_transactions;
    return rnti_checksum.rnti_checksum;
}
