        for (int i = 0; i < N; i++) {
            NFAPI_CRC_INDICATION_PDU_T newStructure;
            newStructure.RX_UE_INFORMATION_TAG = rand() % 10000;
            newStructure.RNTI = rand() % maxAllowedRNTIValues;
            newStructure.CRCFLAG = rand() % 2;
            attackSequences.push_back(newStructure);
        }

        // Increment the total number of structures created and RNTI values used
        totalStructuresCreated += N;
        totalRNTIValuesUsed += N;

        // Check if the buffer is full and pause creation if necessary
        if (totalRNTIValuesUsed >= predefinedThreshold) {
            isBufferFull = true;
            while (isBufferFull) {
                this_thread::sleep_for(chrono::seconds(1));
            }
        }

        // Append the new structures to the shared buffer in a thread-safe manner
        bufferMutex.lock();
        for (int i = 0; i < N; i++) {
            attackSequences[i].RX_UE_INFORMATION_TAG = rand() % 10000;
            attackSequences[i].RNTI = rand() % maxAllowedRNTIValues;
            attackSequences[i].CRCFLAG = rand() % 2;
        }
        bufferCondition.notify_all();
        bufferMutex.unlock();
    }

