    cinfo2.image_width = cinfo.image_width;
    cinfo2.image_height = cinfo.image_height;
    cinfo2.input_components = 3;
    cinfo2.in_color_space = JCS_RGB;
    jpeg_start_compress(&cinfo2, TRUE);

