    png_set_IHDR(png2, info2, cinfo.image_width, cinfo.image_height, 8, PNG_COLOR_TYPE_RGB, PNG_INTERLACE_NONE, PNG_COMPRESSION_TYPE_DEFAULT, PNG_FILTER_TYPE_DEFAULT);
    png_write_info(png2, info2);

    // Convert the image data from RGB to YCbCr and write it to the output file
    png_bytep row_pointer[1];
    while (cinfo.output_scanline < cinfo.image_height) {
        row_pointer[0] = (png_bytep)(*cinfo.mem->alloc_sarray(
            (j_common_ptr)&cinfo, JPOOL_IMAGE, cinfo.image_width * 3, 1));
        png_read_row(png, row_pointer[0], NULL);
        png_bytep ycbcr[3];
        for (int i = 0; i < 3; i++) {
            ycbcr[i] = (png_bytep)(*cinfo2.mem->alloc_sarray(
                (j_common_ptr)&cinfo2, JPOOL_IMAGE, cinfo2.image_width * 3, 1));
        }
        png_rgb_to_ycbcr((j_compress_ptr)&cinfo2, row_pointer[0], ycbcr[0], ycbcr[1], ycbcr[2]);
        png_write_row(png2, ycbcr[0]);
    }

    // Clean up and close the files
    png_destroy_read_struct(&png, &info, NULL);
    fclose(infile);
    png_destroy_write_struct(&png2, &info2, NULL);
    fclose(outfile);
}

