    // Initialize the OpenSSL library
    EVP_Encryptor* encryptor = EVP_get_cipherbyname("aes-256-cbc");
    if (encryptor == NULL) {
        printf("Error initializing OpenSSL\n");
        return NULL;
    }

    // Create a buffer to store the encrypted password
    char* encrypted_password = (char*)malloc(sizeof(char) * 1024);

    // Encrypt the password using the AES-256-CBC algorithm
    EVP_EncryptInit_ex(encryptor, NULL, NULL, NULL, NULL);
    EVP_EncryptUpdate(encryptor, encrypted_password, 1024, password, strlen(password));
    EVP_EncryptFinal_ex(encryptor, encrypted_password, 1024);

    // Free the memory allocated for the encryptor and return the encrypted password
    EVP_CIPHER_CTX_free(encryptor);
    return encrypted_password;
