    uint16_t ie_length[MAX_RANDOM_DIGITS];
};

void init_mac_pdu(struct MAC_PDU *mac_pdu) {
    // Initialize the MAC header
    mac_pdu->header.protocol_discriminator = 0x10;
    mac_pdu->header.message_type = 0x00;
    mac_pdu->header.message_length = 0x00;

    // Initialize the MAC SDU
    mac_pdu->macsdu.sdu_size = 0x00;
    mac_pdu->macsdu.sdu_buffer = NULL;

    // Initialize the IE list
