    sprintf(new_filename, "%s%d%s", filename, mac_pdu->ie_list.ie_id[0], filetype);

    // Check for uniqueness of the new filename
    int fd = open(new_filename, O_RDONLY);
    if (fd != -1) {
        close(fd);
        generate_random_filename(filename, filetype);
    } else {
        strcpy(filename, new_filename);
    }
}

