// Function to generate a unique filename based on the original filename and a random sequence of digits
char* generateUniqueFilename(const char* filename, const char* filetype) {
    // Get the directory path from the original filename
    char *directory = strdup(filename);
    char *filepath = strrchr(directory, '/');
    if (filepath != NULL) {
        *filepath = '\0';
    }

    // Generate a random sequence of digits to append to the original filename
    int rand_digits[MAX_RAND_DIGITS];
    for (int i = 0; i < MAX_RAND_DIGITS; i++) {
        rand_digits[i] = rand() % 10;
    }

    // Construct the new filename by appending the random digits and filetype to the original filename
    char *newfilename = malloc(strlen(directory) + strlen(filetype) + MAX_RAND_DIGITS + 1);
    sprintf(newfilename, "%s%0*d%s", directory, MAX_RAND_DIGITS, rand_digits[i], filetype);

    // Ensure the resulting filename is unique among all files in the current directory
    int retries = 0;
    while (access(newfilename, F_OK) == 0 && retries < MAX_RETRIES) {
        rand_digits[i]++;
        sprintf(newfilename, "%s%0*d%s", directory, MAX_RAND_DIGITS, rand_digits[i], filetype);
        retries++;
    }

    // Clean up memory and return the new filename
    free(directory);
    return newfilename;
}

