    if (config_file == NULL) {
        perror("Error opening configuration file");
        return NULL;
    }

    // Create a JSON parser to parse the configuration file
    json_object *json = json_object_from_file(filename);
    if (json == NULL) {
        fclose(config_file);
        perror("Error parsing configuration file");
        return NULL;
    }

    // Get the root object of the JSON tree
    json_object *root = json_object_get_object(json);
    if (root == NULL) {
        fclose(config_file);
        perror("Error getting root object");
        return NULL;
    }

    // Get the array of device IDs and corresponding network settings from the configuration file
    json_object *device_ids = json_object_get_array(root, "device_ids");
    if (device_ids == NULL) {
        fclose(config_file);
        perror("Error getting device IDs array");
        return NULL;
    }

    // Get the number of devices in the configuration file
    int num_devices = json_object_array_length(device_ids);

    // Create an array to hold the network interface configurations for each device
    NetworkInterfaceConfiguration *nic_configs = malloc(num_devices * sizeof(NetworkInterfaceConfiguration));

    // Iterate over each device in the configuration file and parse its corresponding network settings
    for (int i = 0; i < num_devices; i++) {
        json_object *device_id = json_object_array_get_idx(device_ids, i);
        if (device_id == NULL) {
