            perror("Error getting IP address");
            return NULL;
        }
        json_object *subnet_mask = json_object_get_string(device_id, "subnet_mask");
        if (subnet_mask == NULL) {
            fclose(config_file);
            perror("Error getting subnet mask");
            return NULL;
        }
        json_object *gateway = json_object_get_string(device_id, "gateway");
        if (gateway == NULL) {
            fclose(config_file);
            perror("Error getting gateway");
            return NULL;
        }
        json_object *dns_server = json_object_get_string(device_id, "dns_server");
        if (dns_server == NULL) {
            fclose(config_file);
            perror("Error getting DNS server");
            return NULL;
        }

        // Create a new network interface configuration for this device
        NetworkInterfaceConfiguration *nic_config = malloc(sizeof(NetworkInterfaceConfiguration));
        nic_config->id = strdup(json_object_get_string(device_id, "id"));
        nic_config->ip_address = strdup(ip_address);
        nic_config->subnet_mask = strdup(subnet_mask);
        nic_config->gateway = strdup(gateway);
        nic_config->dns_server = strdup(dns_server);

        // Add the new network interface configuration to the array of configurations for this device
        nic_configs[i] = nic_config;
    }

    // Close the configuration file and return the array of network interface configurations
    fclose(config_file);
    return nic_configs;
}
