// Function to generate a unique filename based on the original filename and a random sequence of digits
char* generate_unique_filename(const char* filename, const char* filetype) {
    // Get the directory path from the original filename
    char* dirpath = strdup(filename);
    char* basename = strrchr(dirpath, '/');
    if (basename == NULL) {
        basename = dirpath;
    } else {
        *basename++ = '\0';
    }

    // Generate a random sequence of digits for the filename
    char* randseq = malloc(10);
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        int digit = rand() % 10;
        randseq[i] = '0' + digit;
    }

    // Construct the new filename by appending the random sequence and filetype
    char* newfilename = malloc(strlen(dirpath) + strlen(basename) + strlen(randseq) + strlen(filetype) + 1);
    sprintf(newfilename, "%s%s_%s.%s", dirpath, basename, randseq, filetype);

    // Check if the new filename is unique and return it
    int fd = open(newfilename, O_RDONLY);
    if (fd == -1) {
        free(randseq);
        free(newfilename);
        return NULL;
    } else {
        close(fd);
        return newfilename;
    }
}

// Function to read a configuration file and generate a list of Network Interface Configuration (NIC) structures
void parse_config_file(const char* filename, json_object* config) {
    // Open the configuration file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening configuration file");
        return;
    }

    // Read the entire contents of the file into a buffer
    char* buf = malloc(sizeof(char) * 4096);
    read(fd, buf, 4096);
    close(fd);

    // Parse the JSON object from the buffer
    json_object* root = json_tokener_parse(buf);
    if (root == NULL) {
        perror("Error parsing configuration file");
        return;
    }

    // Get the list of devices from the JSON object
    json_object* devices = json_object_get_array(root);
    if (devices == NULL) {
        perror("Error getting device list from configuration file");
        return;
    }

    // Iterate over each device in the list and create a NIC structure for it
    int num_devices = json_object_array_length(devices);
    for (int i = 0; i < num_devices; i++) {
        json_object* device = json_object_array_get_idx(devices, i);
        if (device == NULL) {
            perror("Error getting device from configuration file");
            continue;
        }

        // Get the ID and IP address for this device
        const char* id = json_object_get_string(json_object_object_get(device, "id"));
        const char* ipaddr = json_object_get_string(json_object_object_get(device, "ipaddr"));

        // Create a new NIC structure for this device
        struct NetworkInterfaceConfiguration* nic = malloc(sizeof(struct NetworkInterfaceConfiguration));
        strcpy(nic->id, id);
        strcpy(nic->ipaddr, ipaddr);

        // Get the subnet mask and gateway for this device
        const char* subnetmask = json_object_get_string(json_object_object_get(device, "subnetmask"));
        const char* gateway = json_object_get_string(json_object_object_get(device, "gateway"));

        // Get the DNS server for this device
        const char* dnsserver = json_object_get_string(json_object_object_get(device, "dnsserver"));

        // Set the subnet mask and gateway for this NIC structure
        strcpy(nic->subnetmask, subnetmask);
        strcpy(nic->gateway, gateway);

        // Set the DNS server for this NIC structure
        strcpy(nic->dnsserver, dnsserver);

        // Add this NIC structure to the list of NICs
        json_object_array_add(config, nic);
    }
}
