    strcpy(new_filename, filename);
    int len = strlen(new_filename);
    if (len > MAX_FILENAME_LENGTH - DEFAULT_FILE_TYPE) {
        len = MAX_FILENAME_LENGTH - DEFAULT_FILE_TYPE;
    }
    for (int i = 0; i < len; i++) {
        new_filename[i] = filename[i];
    }
    strcat(new_filename, DEFAULT_FILE_TYPE);

    // Generate a random sequence of digits to append to the filename
    int rand_digits[MAX_RANDOM_DIGITS];
    for (int i = 0; i < MAX_RANDOM_DIGITS; i++) {
        rand_digits[i] = rand() % 10;
    }
    char rand_str[MAX_RANDOM_DIGITS + 1];
    sprintf(rand_str, "%d", rand_digits);
    strcat(new_filename, rand_str);

    // Ensure the filename is unique among all files in the current directory
    int retries = 0;
    while (retries < MAX_RETRIES) {
        struct stat st;
        if (stat(new_filename, &st) == -1) {
            break;
        }
        new_filename[len]++;
        retries++;
    }
    if (retries >= MAX_RETRIES) {
        printf("Error: could not find a unique filename\n");
        exit(EXIT_FAILURE);
    }

    // Open the file for writing
    int fd = open(new_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        printf("Error: could not open file %s\n", new_filename);
        exit(EXIT_FAILURE);
    }

    // Write the MAC_PDU structure to the file
    size_t written = write(fd, pdu, sizeof(*pdu));
    if (written != sizeof(*pdu)) {
        printf("Error: could not write to file %s\n", new_filename);
        exit(EXIT_FAILURE);
    }

    // Close the file
    close(fd);
}

void init_mac_pdus(const char *filename, int num_pdu) {
