        // Skip empty lines or comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Parse the JSON object and add a new NetworkInterfaceConfig structure to the list
        json_object* obj = json_tokener_parse(line);
        if (!obj) {
            fprintf(stderr, "Error parsing JSON object: %s\n", line);
            continue;
        }

        // Get the device ID and network settings from the JSON object
        const char* id = json_object_get_string(json_object_object_get(obj, "id"));
        const char* ip = json_object_get_string(json_object_object_get(obj, "ip"));
        const char* subnet = json_object_get_string(json_object_object_get(obj, "subnet"));
        const char* gateway = json_object_get_string(json_object_object_get(obj, "gateway"));
        const char* dns = json_object_get_string(json_object_object_get(obj, "dns"));

        // Validate the device ID and network settings
        if (!id || !ip || !subnet || !gateway || !dns) {
            fprintf(stderr, "Invalid JSON object: %s\n", line);
            continue;
        }

        // Add a new NetworkInterfaceConfig structure to the list and increment the number of devices
        nic_list = realloc(nic_list, (*num_devices + 1) * sizeof(NetworkInterfaceConfig));
        if (!nic_list) {
            perror("realloc");
            fclose(fp);
            return NULL;
        }
        NetworkInterfaceConfig* nic = &nic_list[*num_devices];
        strcpy(nic->id, id);
        strcpy(nic->ip, ip);
        strcpy(nic->subnet, subnet);
        strcpy(nic->gateway, gateway);
        strcpy(nic->dns, dns);
        (*num_devices)++;
    }

    // Close the configuration file and return the list of network interface configurations
    fclose(fp);
    return nic_list;
}
