// Structure for a Network Interface Configuration (NIC)
typedef struct {
    int id;
    char *ip_address;
    char *subnet_mask;
    char *gateway;
    char *dns_server;
} NIC;

// Function to read a configuration file containing a list of device identifiers (IDs) and corresponding network settings
void read_config(char *filename, int num_devices, NIC **nic_list) {
    // Open the configuration file for reading
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error: unable to open configuration file %s\n", filename);
        return;
    }

    // Allocate memory for the dynamic array of NIC structures
    *nic_list = (NIC *)malloc(num_devices * sizeof(NIC));

    // Read each line from the configuration file and parse it into a NIC structure
    char line[256];
    while (fgets(line, 256, file)) {
        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\n') continue;

        // Parse the device ID and corresponding network settings from the line
        int id = atoi(strtok(line, " "));
        char *ip_address = strtok(NULL, " ");
        char *subnet_mask = strtok(NULL, " ");
        char *gateway = strtok(NULL, " ");
        char *dns_server = strtok(NULL, "\n");

        // Validate the device ID and corresponding network settings
        if (id < 0 || id > num_devices) {
            printf("Error: invalid device ID %d\n", id);
            continue;
        }
        if (!ip_address || !subnet_mask || !gateway || !dns_server) {
            printf("Error: missing network settings for device ID %d\n", id);
            continue;
        }

        // Add the NIC structure to the dynamic array of NIC structures
        (*nic_list)[id].id = id;
        (*nic_list)[id].ip_address = ip_address;
        (*nic_list)[id].subnet_mask = subnet_mask;
        (*nic_list)[id].gateway = gateway;
        (*nic_list)[id].dns_server = dns_server;
    }

    // Close the configuration file
    fclose(file);
}
