    // Allocate memory for the array of HTTP responses
    HTTP_RESPONSE **responses = malloc(count * sizeof(HTTP_RESPONSE));
    if (!responses) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    // Initialize each HTTP response structure
    for (size_t i = 0; i < count; i++) {
        responses[i] = malloc(sizeof(HTTP_RESPONSE));
        if (!responses[i]) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        responses[i]->url = NULL;
        responses[i]->method = NULL;
        responses[i]->body_size = 0;
        responses[i]->body = NULL;
        responses[i]->metadata_count = 0;
        responses[i]->metadata = NULL;
    }

    return responses;
}

// Function to generate a random filename with a specified file type
char *generate_random_filename(const char *filename, const char *filetype) {
    // Get the original filename and directory path
    char *original_filename = strdup(filename);
    char *directory_path = dirname(original_filename);

    // Generate a random sequence of alphanumeric characters
    char rand_seq[MAX_RAND_LEN + 1];
    for (size_t i = 0; i < MAX_RAND_LEN; i++) {
        rand_seq[i] = 'a' + (rand() % ('z' - 'a'));
    }
    rand_seq[MAX_RAND_LEN] = '\0';

    // Construct the new filename by appending the random sequence and file type
    char *new_filename = malloc(strlen(directory_path) + strlen(original_filename) + strlen(filetype) + MAX_RAND_LEN + 1);
    if (!new_filename) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    sprintf(new_filename, "%s/%s%s", directory_path, original_filename, rand_seq);

    // Ensure the new filename is unique among all files in the current directory
    int retries = 0;
    while (access(new_filename, F_OK) == 0 && retries < MAX_RETRIES) {
        sprintf(new_filename + strlen(directory_path) + strlen(original_filename), "%s%d", rand_seq, retries);
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to generate a unique filename after %d retries\n", MAX_RETRIES);
        exit(EXIT_FAILURE);
    }

    // Free the original filename and return the new filename
    free(original_filename);
    return new_filename;
}

// Function to populate an HTTP response structure with a valid URL, HTTP method, and request payload size
HTTP_RESPONSE *populate_http_response(const char *url, const char *method, size_t body_size) {
    // Allocate memory for the HTTP response structure
    HTTP_RESPONSE *response = malloc(sizeof(HTTP_RESPONSE));
    if (!response) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    // Initialize the URL, method, and request payload size
    response->url = strdup(url);
    response->method = strdup(method);
    response->body_size = body_size;

    // Allocate memory for the request payload
    response->body = malloc(response->body_size);
    if (!response->body) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    return response;
}

// Function to initialize an HTTP response structure with a valid HTTP header, HTTP body, and optional metadata list
HTTP_RESPONSE *init_http_response(const char *url, const char *method, size_t body_size, size_t metadata_count) {
    // Populate the HTTP response structure with a valid URL, method, and request payload size
    HTTP_RESPONSE *response = populate_http_response(url, method, body_size);

    // Allocate memory for the metadata list
    response->metadata_count = metadata_count;
    response->metadata = malloc(metadata_count * sizeof(struct { char *key; char *value; }));
    if (!response->metadata) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    // Initialize each metadata entry with a unique key and variable value
    for (size_t i = 0; i < metadata_count; i++) {
        response->metadata[i].key = malloc(16);
        if (!response->metadata[i].key) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        sprintf(response->metadata[i].key, "key%d", i);
        response->metadata[i].value = malloc(16);
        if (!response->metadata[i].value) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        sprintf(response->metadata[i].value, "value%d", i);
    }

    return response;
}

// Function to validate the integrity of an HTTP body after each update
void validate_http_body(HTTP_RESPONSE *response) {
    // Check for buffer overflows by comparing the size of the request payload with the maximum allowed size
    if (response->body_size > MAX_BODY_SIZE) {
        fprintf(stderr, "Buffer overflow detected in HTTP body\n");
        exit(EXIT_FAILURE);
    }
}
