    char *random_method = generateRandomHTTPMethod();
    int random_payload_size = generateRandomPayloadSize();

    // Initialize the HTTP request structure with the generated values
    response->request->url = malloc(strlen(filename) + 1);
    strcpy(response->request->url, filename);
    response->request->method = random_method;
    response->request->request_payload_size = random_payload_size;

    // Close the file descriptor and free the memory allocated for the HTTP request structure
    close(fd);
    free(response->request);
