    // Wait for the DNS resolution and data collection threads to complete
    pthread_join(dns_thread, NULL);
    pthread_join(data_thread, NULL);

    // Clean up resources
    sem_close(dns_semaphore);
    sem_unlink("dns_semaphore");
    sem_close(data_semaphore);
    sem_unlink("data_semaphore");

    // Free the memory allocated for the dynamic arrays of DataPacket and SensorDataConfig structures
    free(data_packets);
    free(sensor_configs);
