        while (true) {
            if (persistSensorDataToDatabase(sensor_data)) {
                break;
            } else {
                printf("Retrying persistence operation due to database connection error.\n");
                sleep(pow(2, i)); // Exponential backoff with increasing delay times
            }
        }
    }
}

// Define function to persist LTE packet data to database
void persistLTEPacketData(LTE_PACKET_T** lte_packet_list, int num_packets) {
    // Persist LTE packet data to database using thread-safe and scalable implementation
    for (int i = 0; i < num_packets; i++) {
