int verify_payload(char* payload, size_t length) {
    // Calculate the checksum of the payload using a hash function
    unsigned long checksum = 0;
    for (int i = 0; i < length; i++) {
        checksum += payload[i];
    }

    // Return the result of the checksum verification
    return checksum % 10 == 0;
}

