        pthread_t thread;
        if (pthread_create(&thread, NULL, process_files, filename_array) != 0) {
            printf("Error: unable to create thread for processing input files\n");
            return NULL;
        }

        // Join the current thread with the main thread
        if (pthread_join(thread, NULL) != 0) {
            printf("Error: unable to join thread for processing input files\n");
            return NULL;
        }
    } else {
        // Print usage information and exit
        printf("Usage: %s <input file 1> [<input file 2> ...]\n", argv_ptr[0]);
        return NULL;
    }
}

// Define a function to integrate a Python script that modifies a configuration file using the subprocess module
void* modify_configuration(void* filename) {
    // Cast the void pointer to a string
    char* filename_str = (char*)filename;

    // Create a new process to execute the Python script
    FILE* fp = popen("python3 modify_config.py", "r");
    if (fp == NULL) {
        printf("Error: unable to execute Python script\n");
        return NULL;
    }

    // Read the output of the Python script into a buffer
    char* buffer = malloc(sizeof(char) * 1024);
    size_t bytes_read = fread(buffer, sizeof(char), 1024, fp);
    if (bytes_read == 0) {
        printf("Error: unable to read output of Python script\n");
        return NULL;
    }

    // Close the process and free the memory allocated for the buffer
    pclose(fp);
    free(buffer);
}
