// Define the function to initialize and manage the dynamic queue of JobRequests
void init_job_queue(JobQueue *queue) {
    // Allocate memory for the queue
    queue->jobs = malloc(sizeof(JobRequest *) * INITIAL_QUEUE_SIZE);
    if (queue->jobs == NULL) {
        perror("Failed to allocate memory for job queue");
        exit(1);
    }
    // Initialize the queue size and head/tail pointers
    queue->size = INITIAL_QUEUE_SIZE;
    queue->head = 0;
    queue->tail = 0;
}

// Define the function to add a JobRequest to the queue
void enqueue(JobQueue *queue, JobRequest *job) {
    // Check if the queue is full
    if (queue->size == MAX_QUEUE_SIZE) {
        perror("Job queue is full");
        exit(1);
    }
    // Add the job to the tail of the queue
    queue->jobs[queue->tail] = job;
    queue->tail = (queue->tail + 1) % queue->size;
}

// Define the function to remove a JobRequest from the queue
JobRequest *dequeue(JobQueue *queue) {
    // Check if the queue is empty
    if (queue->head == queue->tail) {
        perror("Job queue is empty");
        exit(1);
    }
    // Remove the job from the head of the queue
    JobRequest *job = queue->jobs[queue->head];
    queue->head = (queue->head + 1) % queue->size;
    return job;
}

