    // Initialize the priority queue for task scheduling within the thread pool
    PriorityQueue *queue = (PriorityQueue *)malloc(sizeof(PriorityQueue));
    init_priority_queue(queue);

    // Loop until all tasks are completed or an error occurs
    while (!is_all_tasks_completed(queue)) {
        // Get the next task from the priority queue
        Task *task = get_next_task(queue);

        // Execute the task concurrently within a thread pool
        pthread_create(&thread_pool[i], NULL, task_handler, (void *)task);
    }

    // Terminate all threads properly upon completion
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(thread_pool[i], NULL);
    }

    // Free the memory allocated for the thread pool and priority queue
    free(thread_pool);
    free(queue);

    return NULL;
}

// Define the function to handle tasks concurrently within a thread pool
void *task_handler(void *args) {
    // Cast the arguments to the correct types
    Task *task = (Task *)args;

    // Create a new state list by finding states in the given FSM
    DeviceState *new_state_list = find_states_in_fsm(task->fsm);

    // Update the 'next' pointer of the last state in the list to point to the newly created state list
    task->last_state->next = new_state_list;

    // Return a pointer to the newly created state list or NULL if there is insufficient memory or if no valid states are found
    return (new_state_list != NULL) ? new_state_list : NULL;
}

// Define the function to find states in an FSM
DeviceState *find_states_in_fsm(FSM *fsm) {
    // Initialize a list of DeviceStates
    DeviceState *device_states = (DeviceState *)malloc(sizeof(DeviceState));

    // Loop through the states in the FSM and add them to the list if they meet the power consumption threshold
    for (int i = 0; i < fsm->num_states; i++) {
        State *state = &fsm->states[i];
        if (state->power_consumption >= POWER_CONSUMPTION_THRESHOLD) {
            DeviceState *device_state = (DeviceState *)malloc(sizeof(DeviceState));
            device_state->status = state->status;
            device_state->power_consumption = state->power_consumption;
            device_state->temperature = state->temperature;
            device_states = add_device_state(device_states, device_state);
        }
    }

    // Return the list of DeviceStates or NULL if there are no valid states found
    return (device_states != NULL) ? device_states : NULL;
}

// Define the function to add a DeviceState to a list
DeviceState *add_device_state(DeviceState *device_states, DeviceState *device_state) {
    // Check if there is enough memory to allocate for the new DeviceState
    if (device_states == NULL) {
        return NULL;
    }

    // Allocate memory for the new DeviceState and copy the values from the given DeviceState
    DeviceState *new_device_state = (DeviceState *)malloc(sizeof(DeviceState));
    memcpy(new_device_state, device_state, sizeof(DeviceState));

    // Add the new DeviceState to the list
    device_states->next = new_device_state;

    return device_states;
}
