    sprintf(new_filename, "%s%s%s", filename, rand_digits, FILE_TYPE);

    // Check if the total filename length exceeds 255 characters
    int len = strlen(new_filename);
    if (len > 255) {
        printf("Error: The generated filename is too long\n");
        return;
    }

    // Ensure the new filename is unique within the directory by appending a random number until no conflict is found
    int conflict = 1;
    while (conflict) {
        // Generate a random number between 0 and 9999
        int rand_num = rand() % 10000;

        // Construct the new filename with the random number appended to the original filename
        char new_filename[256];
        sprintf(new_filename, "%s%d", filename, rand_num);

        // Check if the new filename is unique within the directory
        conflict = access(new_filename, F_OK) == 0;
    }
}
