    for (int i = 0; i < list->size; i++) {
        NetworkTrafficLog log = list->logs[i];
        // Check if the TrafficData is valid and has a valid CRC flag
        if (log.data.valid && log.crc_indication_rel8_tag.crc_flag) {
            // If it is, check if the CRC value matches the expected value
            int expected_crc = calculate_crc(log.header.rnti, log.data.payload);
            if (expected_crc != log.crc_indication_rel8_tag.crc) {
                // If it doesn't, print an error message and continue to the next log
                printf("Error: CRC value does not match expected value\n");
                continue;
            }
        }
    }
}

// Define a function to calculate the CRC value for a given RNTI and payload
int calculate_crc(RNTI rnti, TrafficData data) {
    // Calculate the CRC value using a random seed and threshold values
    int crc = 0;
    srand(time(NULL));
    for (int i = 0; i < THRESHOLD_VALUE; i++) {
        crc += rand() % MAX_CRC_VALUE;
    }
    return crc;
}

// Define a function to generate a unique filename based on the original filename and file type
char *generate_filename(const char *original_filename, const char *file_type) {
    // Get the length of the original filename
    int original_length = strlen(original_filename);
    // Generate a random sequence of digits for the new filename
    int random_sequence[10];
    for (int i = 0; i < 10; i++) {
        random_sequence[i] = rand() % 10;
    }
    // Create a string buffer to hold the new filename
    char *new_filename = malloc(256);
    if (new_filename == NULL) {
        printf("Error: failed to allocate memory for new filename\n");
        exit(1);
    }
    // Copy the original filename into the string buffer
    strcpy(new_filename, original_filename);
    // Append the random sequence of digits to the end of the filename
    int new_length = original_length + 10;
    for (int i = 0; i < 10; i++) {
        new_filename[new_length++] = '0' + random_sequence[i];
    }
    // Append the file type to the end of the filename
    strcpy(new_filename + new_length, file_type);
    return new_filename;
}

// Define a function to handle real-time data ingestion and buffering
void handle_real_time_data(LogList *list) {
    // Create a buffer for incoming data
    NetworkTrafficLog *buffer = malloc(MAX_BUFFER_SIZE * sizeof(NetworkTrafficLog));
    if (buffer == NULL) {
        printf("Error: failed to allocate memory for buffer\n");
        exit(1);
    }
    // Set the buffer size and index to 0
    int buffer_size = MAX_BUFFER_SIZE;
    int buffer_index = 0;
    // Loop until the main thread is blocked or the buffer is full
    while (true) {
        // Check if there are any incoming logs
        NetworkTrafficLog log = get_next_log();
        if (log.header.rnti == -1) {
            // If not, wait for a short time before checking again
            usleep(1000);
            continue;
        }
        // Add the incoming log to the buffer
        buffer[buffer_index++] = log;
        // Check if the buffer is full
        if (buffer_index == buffer_size) {
            // If it is, flush the buffer and reset the index
            flush_buffer(list, buffer);
            buffer_index = 0;
        }
    }
}

// Define a function to flush the buffer of incoming logs to the list
void flush_buffer(LogList *list, NetworkTrafficLog *buffer) {
    // Iterate over each log in the buffer
    for (int i = 0; i < buffer_size; i++) {
        NetworkTrafficLog log = buffer[i];
        // Add the log to the end of the list
        add_log(list, log);
    }
}
