// Structure to store network device configuration parameters
typedef struct NetworkDeviceConfig {
    char* ip_address;
    char* subnet_mask;
    char* gateway_address;
    int device_identifier;
} NetworkDeviceConfig;

// Function to read a CSV file containing network device configuration parameters and populate a list of NetworkDeviceConfig structs
NetworkDeviceConfig* readCSVFile(const char* filename, int N) {
    // Check if the input parameter N is valid
    if (N <= 0) {
        return NULL;
    }

    // Open the CSV file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return NULL;
    }

    // Allocate memory for the list of NetworkDeviceConfig structs
    NetworkDeviceConfig* config_list = malloc(N * sizeof(NetworkDeviceConfig));
    if (config_list == NULL) {
        printf("Error: unable to allocate memory for list\n");
        fclose(fp);
        return NULL;
    }

    // Initialize the running checksum of device identifiers
    int checksum = 0;

    // Read each line from the CSV file and process it
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Skip empty lines or lines with fewer than 4 fields
        if (strlen(line) < 4) {
            continue;
        }

        // Split the line into fields using "," as the delimiter
        char* fields[4];
        int num_fields = 0;
        for (int i = 0; i < 4; i++) {
            fields[i] = strtok(line, ",");
            if (fields[i] == NULL) {
                break;
            }
            num_fields++;
        }

        // Check if the line has the correct number of fields
        if (num_fields != 4) {
            printf("Error: malformed input line %d\n", read);
            continue;
        }

        // Allocate memory for the NetworkDeviceConfig struct
        NetworkDeviceConfig* config = malloc(sizeof(NetworkDeviceConfig));
        if (config == NULL) {
            printf("Error: unable to allocate memory for NetworkDeviceConfig\n");
            fclose(fp);
            return NULL;
        }

        // Populate the NetworkDeviceConfig struct with the fields from the line
        config->ip_address = strdup(fields[0]);
        config->subnet_mask = strdup(fields[1]);
        config->gateway_address = strdup(fields[2]);
        config->device_identifier = atoi(fields[3]);

        // Add the NetworkDeviceConfig struct to the list
        config_list[N - read] = *config;

        // Update the running checksum of device identifiers
        checksum += config->device_identifier;
    }

    // Close the CSV file
    fclose(fp);

    // Return the list of NetworkDeviceConfig structs and the running checksum
    return config_list;
}
