    // Check if the file was opened successfully
    if (fp == NULL) {
        printf("Error: unable to open network stream\n");
        return;
    }

    // Read data from the network stream
    while (!feof(fp)) {
        // Allocate memory for a new DataPacket structure
        DataPacket* packet = malloc(sizeof(DataPacket));

        // Read the timestamp and source from the network stream
        fscanf(fp, "%d %s", &packet->timestamp, &packet->source);

        // Allocate memory for the data field in the DataPacket structure
        packet->data = malloc(sizeof(char) * MAX_RANDOM_DIGITS);

        // Read the data from the network stream
        fscanf(fp, "%s", packet->data);

        // Add the new DataPacket to the dynamic array of data packets
        addDataPacket(&data, &packet);
    }

    // Close the network stream
    fclose(fp);
}

// Perform DNS resolution for the given hostname
void performDNSResolution(char* hostname, SensorDataPacket*** sensor_data, DataPacket*** data) {
    // Check if the hostname is valid
    if (hostname != NULL) {
        // Open the DNS server file for reading
        FILE* fp = fopen("dns_servers", "r");

        // Check if the file was opened successfully
        if (fp == NULL) {
            printf("Error: unable to open DNS server file\n");
            return;
        }

        // Read the DNS servers from the file
        char* dns_servers[MAX_DNS_QUERIES];
        for (int i = 0; i < MAX_DNS_QUERIES; i++) {
            fscanf(fp, "%s", &dns_servers[i]);
        }

        // Close the DNS server file
        fclose(fp);

        // Perform DNS resolution for the given hostname using the DNS servers
        performDNSResolutionUsingDNSServers(hostname, dns_servers, &sensor_data, &data);
    }
}

