void populate_ack(transaction_t *transaction, size_t index) {
    int sequence_number = generate_unique_id();
    bool acknowledged = (rand() % 2 == 0);
    time_t timestamp = time(NULL);
    ack_t *ack = &transaction->acks[index];
    ack->sequence_number = sequence_number;
    ack->acknowledged = acknowledged;
    ack->timestamp = timestamp;
