// Function to add a new transaction structure to the dynamic array
void add_transaction(transaction_t **transactions, size_t *size, size_t max_size) {
    if (*size >= max_size) {
        perror("Maximum number of transactions reached");
        exit(EXIT_FAILURE);
    }
    transaction_t *new_transaction = (transaction_t *)malloc(sizeof(transaction_t));
    if (new_transaction == NULL) {
        perror("Failed to allocate memory for new transaction");
        exit(EXIT_FAILURE);
    }
    (*transactions)[*size] = *new_transaction;
    populate_ack(&(*transactions)[*size], 0);
    ++(*size);
}

// Function to validate the integrity of the payload
void validate_payload(char *payload, size_t length) {
    if (length > MAX_PAYLOAD_LENGTH) {
        perror("Payload exceeds maximum length");
        exit(EXIT_FAILURE);
    }
}

// Function to write transaction logs to a specified directory
void write_transaction_logs(transaction_t *transactions, size_t size, char *directory) {
    for (size_t i = 0; i < size; ++i) {
        char filename[MAX_FILENAME_LENGTH];
        sprintf(filename, "%s/%d-%d.log", directory, transactions[i].sequence_number, generate_unique_id());
        int fd = open(filename, O_WRONLY | O_CREAT, 0644);
        if (fd == -1) {
            perror("Failed to create file");
            exit(EXIT_FAILURE);
        }
        write(fd, transactions[i].payload, strlen(transactions[i].payload));
        close(fd);
    }
}

// Function to read a configuration file and set the maximum length of the random sequence for generating unique IDs
void read_config_file(char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Failed to open config file");
        exit(EXIT_FAILURE);
    }
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, fp) != NULL) {
        if (strncmp(line, "max_id=", 7) == 0) {
            sscanf(line + 7, "%d", &MAX_ID);
        } else if (strncmp(line, "max_payload_length=", 18) == 0) {
            sscanf(line + 18, "%d", &MAX_PAYLOAD_LENGTH);
        } else if (strncmp(line, "max_metadata_length=", 20) == 0) {
            sscanf(line + 20, "%d", &MAX_METADATA_LENGTH);
        }
    }
    fclose(fp);
}

// Function to handle errors gracefully and log them without interruption
void handle_error(char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

