#include <fcntl.h>
#include <errno.h>
#include <json-c/json.h>

#define MAX_FILENAME_LENGTH 255
#define DEFAULT_FILE_TYPE ".txt"
#define MAX_RANDOM_DIGITS 10
#define MAX_RETRIES 100

typedef struct {
    MAC_HEADER header;
    MACSDU macsdu;
    IE_LIST ie_list;
} MAC_PDU;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int num_pdu;
    MAC_PDU *pdu_list;
} PDU_LIST;

void init_mac_pdu(MAC_PDU *pdu) {
    // Initialize the MAC_HEADER, MACSDU, and IE_LIST fields of the pdu structure
    memset(&pdu->header, 0, sizeof(MAC_HEADER));
    memset(&pdu->macsdu, 0, sizeof(MACSDU));
    memset(&pdu->ie_list, 0, sizeof(IE_LIST));
}

void init_nfapi_crc_indication_pdu_t(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Initialize the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields of the pdu structure
    memset(&pdu->rx_ue_information_tag, 0, sizeof(RX_UE_INFORMATION_TAG));
    memset(&pdu->rnti, 0, sizeof(RNTI));
    memset(&pdu->crc_indication_rel8_tag, 0, sizeof(CRC_INDICATION_REL8_TAG));
}

void init_pdu_list(PDU_LIST *list) {
    // Initialize the num_pdu and pdu_list fields of the list structure
    list->num_pdu = 0;
    list->pdu_list = NULL;
}

int generate_random_digits(char *filename, int length) {
    // Generate a random sequence of digits based on the length of the filename
    srand(time(NULL));
    for (int i = 0; i < length; i++) {
        char digit = rand() % 10 + '0';
        strcat(filename, &digit);
    }
    return 0;
}

char *generate_unique_filename(char *filename) {
    // Generate a unique filename by appending a random number to the original filename
    char *new_filename = malloc(MAX_FILENAME_LENGTH + 1);
    strcpy(new_filename, filename);
    int retries = 0;
    while (retries < MAX_RETRIES) {
        generate_random_digits(new_filename, MAX_RANDOM_DIGITS);
        if (access(new_filename, F_OK) != 0) {
            break;
        }
        retries++;
    }
    if (retries == MAX_RETRIES) {
        printf("Error: Could not generate a unique filename after %d retries\n", MAX_RETRIES);
        return NULL;
    }
    return new_filename;
}

int read_config_file(char *filename, char **filetype, int *max_random_digits) {
    // Read the configuration file and parse it with a simple JSON parser
    json_object *root = json_object_from_file(filename);
    if (root == NULL) {
        printf("Error: Could not read configuration file %s\n", filename);
        return -1;
    }
    json_object *filetype_obj = json_object_object_get(root, "filetype");
    if (filetype_obj == NULL) {
        printf("Error: Could not find 'filetype' field in configuration file %s\n", filename);
        return -1;
    }
    *filetype = json_object_get_string(filetype_obj);
    json_object *max_random_digits_obj = json_object_object_get(root, "max_random_digits");
    if (max_random_digits_obj == NULL) {
        printf("Error: Could not find 'max_random_digits' field in configuration file %s\n", filename);
        return -1;
    }
    *max_random_digits = json_object_get_int(max_random_digits_obj);
    return 0;
}

void init_mac_pdu_list(PDU_LIST *list, char *filename) {
    // Initialize the PDU_LIST structure and populate it with randomly generated MAC_PDU structures
    list->num_pdu = 0;
    list->pdu_list = malloc(sizeof(MAC_PDU) * MAX_NUM_PDU);
    for (int i = 0; i < MAX_NUM_PDU; i++) {
        init_mac_pdu(&list->pdu_list[i]);
    }
    // Generate a unique filename based on the original filename and append it to the list structure
    char *new_filename = generate_unique_filename(filename);
    if (new_filename == NULL) {
        printf("Error: Could not generate a unique filename for %s\n", filename);
        return;
    }
    strcat(list->pdu_list[i].header.filename, new_filename);
}

void init_nfapi_crc_indication_pdu_t_list(PDU_LIST *list) {
    // Initialize the NFAPI_CRC_INDICATION_PDU_T structures and populate them with randomly generated RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields
    for (int i = 0; i < list->num_pdu; i++) {
        init_nfapi_crc_indication_pdu_t(&list->pdu_list[i].header.rx_ue_information_tag);
        list->pdu_list[i].header.rnti = rand() % MAX_RNTI;
