void initMacPdu(MAC_PDU *pdu, const char *filename) {
    // Initialize the MAC_PDU structure with random values
    pdu->header.rxUeInformationTag = rand() % 65535;
    pdu->header.rnti = rand() % 65535;
    pdu->header.crcIndicationRel8.crcFlag = rand() % 2;
    pdu->macSdu.macSduSize = rand() % 1000;
