    for (int i = 0; i < pdu->macSdu.macSduSize; i++) {
        pdu->macSdu.macSdu[i] = rand() % 256;
    }
    // Initialize the IE_LIST structure with random values
    int numIes = rand() % 10 + 1;
    pdu->ieList = malloc(sizeof(IE_LIST) * numIes);
    for (int i = 0; i < numIes; i++) {
        pdu->ieList[i].ieId = rand() % 65535;
        pdu->ieList[i].ieLength = rand() % 1000;
    }
}

void generateRandomFilename(const char *filename, const char *fileType) {
    // Generate a random filename with the specified file type
    int len = strlen(filename);
    char *newFilename = malloc(MAX_FILENAME_LENGTH + 1);
    memcpy(newFilename, filename, len);
    newFilename[len] = '.';
    for (int i = 0; i < MAX_RANDOM_DIGITS; i++) {
        int digit = rand() % 10;
        newFilename[len + 1 + i] = '0' + digit;
    }
    strcat(newFilename, fileType);
    // Ensure the resulting filename is unique among all files in the current directory
    struct stat sb;
    int retries = 0;
    while (stat(newFilename, &sb) == 0 && retries < 10) {
        for (int i = 0; i < MAX_RANDOM_DIGITS; i++) {
            newFilename[len + 1 + i]++;
            if (newFilename[len + 1 + i] > '9') {
                newFilename[len + 1 + i] = '0';
            } else {
                break;
            }
        }
        retries++;
    }
    // If the filename is not unique, log an error and exit
    if (retries == 10) {
        printf("Error: Could not generate a unique filename\n");
        exit(EXIT_FAILURE);
    }
}

void readConfigurationFile(const char *filename, const char *fileType) {
    // Read the configuration file and parse it with a simple JSON parser
    json_object *root = json_object_from_file(filename);
    if (root == NULL) {
        printf("Error: Could not read configuration file\n");
        exit(EXIT_FAILURE);
    }
    // Get the default file type and maximum length of the random digit sequence from the JSON object
    const char *defaultFileType = json_object_get_string(json_object_object_get(root, "fileType"));
    int maxRandomDigits = json_object_get_int(json_object_object_get(root, "maxRandomDigits"));
    // Free the JSON object and return the default file type and maximum length of the random digit sequence
    json_object_put(root);
    return defaultFileType, maxRandomDigits;
}

