    // Initialize the MAC_PDU structure with random values using the configuration file
    int retries = 0;
    while (retries < 10) {
        generateRandomFilename(filename, DEFAULT_FILE_TYPE);
        initMacPdu(pdu, newFilename);
        // If the filename is unique, break out of the loop
        if (stat(newFilename, &sb) != 0) {
            break;
        }
        retries++;
    }
    // If the filename is not unique after 10 attempts, log an error and exit
    if (retries == 10) {
        printf("Error: Could not generate a unique filename\n");
        exit(EXIT_FAILURE);
    }
}

