uint32_t getRntiChecksum(MAC_PDU *pdu) {
    // Calculate a running checksum of all RNTIs included in the list
    uint32_t checksum = 0;
    for (int i = 0; i < pdu->ieList.numIes; i++) {
        checksum += pdu->ieList[i].rnti;
    }
    return checksum;
}
