// Define the function for initializing the encryption context
ENCRYPTION_CONTEXT* init_encryption(const char *password, const char *config_file) {
    // Allocate memory for the encryption context
    ENCRYPTION_CONTEXT *ctx = malloc(sizeof(ENCRYPTION_CONTEXT));
    if (ctx == NULL) {
        printf("Error: Failed to allocate memory for encryption context\n");
        return NULL;
    }

    // Initialize the AES-256-GCM cipher with the password and nonce
    int ret = AES_set_encrypt_key(password, 256, &ctx->aes_key);
    if (ret != 1) {
        printf("Error: Failed to initialize AES-256-GCM cipher\n");
        free(ctx);
        return NULL;
    }

    // Generate a cryptographically secure nonce using OpenSSL's secure random number generator
    if (!RAND_bytes(ctx->nonce, 16)) {
        printf("Error: Failed to generate nonce\n");
        free(ctx);
        return NULL;
    }

    // Derive the encryption key securely from the password using a salted key derivation function (KDF) with adjustable parameters for key length and iterations
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (cipher_ctx == NULL) {
        printf("Error: Failed to create cipher context\n");
        free(ctx);
        return NULL;
    }

    // Initialize the cipher with the derived key and nonce
    ret = EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_gcm(), NULL, ctx->aes_key.key, ctx->nonce);
    if (ret != 1) {
        printf("Error: Failed to initialize cipher\n");
        free(ctx);
        return NULL;
    }

    // Set the encryption context
    ctx->cipher_ctx = cipher_ctx;

    // Return the encryption context
    return ctx;
}

// Define the function for encrypting and decrypting files in the specified directory
int encrypt_decrypt_files(const char *directory, const char *password, const char *config_file) {
    // Initialize the encryption context with the password and configuration file
    ENCRYPTION_CONTEXT *ctx = init_encryption(password, config_file);
    if (ctx == NULL) {
        printf("Error: Failed to initialize encryption context\n");
        return -1;
    }

    // Iterate over the files in the directory and encrypt/decrypt them as needed
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        printf("Error: Failed to open directory %s\n", directory);
        free_encryption_context(ctx);
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip over non-files and hidden files
        if (entry->d_type != DT_REG || entry->d_name[0] == '.') {
            continue;
        }

        // Get the full file path
        char *file_path = malloc(strlen(directory) + strlen(entry->d_name) + 2);
        if (file_path == NULL) {
            printf("Error: Failed to allocate memory for file path\n");
            free_encryption_context(ctx);
            return -1;
        }
        sprintf(file_path, "%s/%s", directory, entry->d_name);

        // Encrypt/decrypt the file as needed
        int ret = encrypt_decrypt_file(file_path, ctx);
        if (ret != 0) {
            printf("Error: Failed to encrypt/decrypt file %s\n", file_path);
            free(file_path);
            free_encryption_context(ctx);
            return -1;
        }

        // Free the file path memory
        free(file_path);
    }

    // Close the directory stream
    closedir(dir);

    // Return success
    return 0;
}

// Define the function for encrypting and decrypting a single file
int encrypt_decrypt_file(const char *file_path, ENCRYPTION_CONTEXT *ctx) {
    // Open the file in binary mode
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        printf("Error: Failed to open file %s\n", file_path);
        return -1;
    }

    // Get the file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    // Allocate memory for the encrypted/decrypted data
    uint8_t *data = malloc(file_size);
    if (data == NULL) {
        printf("Error: Failed to allocate memory for file data\n");
        fclose(file);
        return -1;
    }

    // Read the file into memory
    size_t bytes_read = fread(data, 1, file_size, file);
    if (bytes_read != file_size) {
        printf("Error: Failed to read file %s\n", file_path);
        free(data);
        fclose(file);
        return -1;
    }

    // Encrypt/decrypt the data as needed
    if (ctx->cipher_ctx != NULL) {
        // Encrypt the data
        int ret = EVP_EncryptUpdate(ctx->cipher_ctx, data, &file_size, data, file_size);
        if (ret != 1) {
            printf("Error: Failed to encrypt file %s\n", file_path);
            free(data);
            fclose(file);
            return -1;
        }
    } else {
        // Decrypt the data
        int ret = EVP_DecryptUpdate(ctx->cipher_ctx, data, &file_size, data, file_size);
        if (ret != 1) {
            printf("Error: Failed to decrypt file %s\n", file_path);
            free(data);
            fclose(file);
            return -1;
        }
    }

    // Write the encrypted/decrypted data back to the file
    size_t bytes_written = fwrite(data, 1, file_size, file);
    if (bytes_written != file_size) {
        printf("Error: Failed to write file %s\n", file_path);
        free(data);
        fclose(file);
        return -1;
    }

    // Close the file
    fclose(file);

    // Free the encrypted/decrypted data memory
    free(data);

    // Return success
    return 0;
}

// Define the function for freeing the encryption context
void free_encryption_context(ENCRYPTION_CONTEXT *ctx) {
    if (ctx == NULL) {
        return;
    }

    // Free the AES key memory
    OPENSSL_cleanse(&ctx->aes_key, sizeof(AES_KEY));

    // Free the cipher context memory
    EVP_CIPHER_CTX_free(ctx->cipher_ctx);

    // Free the encryption context memory
    free(ctx);
}
