// Function to resize the pool of structures based on user input N
void resize_pool(size_t n) {
    // Validate that N is within a specified range
    if (n < 1 || n > 1000) {
        printf("Error: Invalid input value for N. Must be between 1 and 1000.\n");
        return;
    }

    // Allocate memory for the new pool of structures
    size_t new_pool_size = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* new_pool = malloc(new_pool_size);
    if (new_pool == NULL) {
        printf("Error: Failed to allocate memory for the new pool of structures.\n");
        return;
    }

    // Copy the contents of the old pool to the new pool
    memcpy(new_pool, pool, pool_size);

    // Deallocate the old pool
    deallocate_pool(pool);

    // Update the global variables with the new pool and size
    pool = new_pool;
    pool_size = new_pool_size;
}

// Function to handle memory allocation failures gracefully
