    if (N < 1 || N > 1000) {
        printf("Error: Invalid input value for N. Must be between 1 and 1000.\n");
        return NULL;
    }

    // Acquire the lock to ensure thread-safe access to the pool
    pthread_mutex_lock(&mutex);

    // Check if the pool has already been initialized
    if (pool == NULL) {
        // Allocate memory for the pool of structures
        pool = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pool == NULL) {
            printf("Error: Failed to allocate memory for the pool.\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
