            NFAPI_CRC_INDICATION_PDU_T* newPool = realloc(pool, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (newPool == NULL) {
                printf("Error: Failed to resize the pool.\n");
                pthread_mutex_unlock(&mutex);
                return NULL;
            }
            pool = newPool;
