    if (fp == NULL) {
        printf("Error: Failed to open configuration file\n");
        return NULL;
    }

    // Read the contents of the file into a buffer
    char* buffer = malloc(1024 * 1024);
    size_t bytes_read = fread(buffer, 1, 1024 * 1024, fp);
    if (bytes_read == 0) {
        printf("Error: Configuration file is empty\n");
        return NULL;
    }

    // Close the file and check for any errors
    int error = fclose(fp);
    if (error != 0) {
        printf("Error: Failed to close configuration file\n");
        return NULL;
    }

    // Extract the password from the buffer using a regular expression
    char* pattern = "password=(.*)";
    regex_t regex;
    regcomp(&regex, pattern, REG_EXTENDED);
    regmatch_t match[2];
    if (regexec(&regex, buffer, 2, match, 0) == 0) {
        // Extract the password from the regular expression match
        char* password = malloc(match[1].rm_eo - match[1].rm_so + 1);
        strncpy(password, buffer + match[1].rm_so, match[1].rm_eo - match[1].rm_so);
        return password;
    } else {
        printf("Error: Failed to extract password from configuration file\n");
        return NULL;
    }
}
