NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(int n) {
    // Validate that n is within the specified range
    if (n < 0 || n > MAX_POOL_SIZE) {
        fprintf(stderr, "Invalid input: n must be between 0 and %d\n", MAX_POOL_SIZE);
        return NULL;
    }

    // Allocate memory for the pool of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pool = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for the pool of NFAPI_CRC_INDICATION_PDU_T structures\n");
        return NULL;
