        pool[i].crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
        pool[i].crc_indication_rel8.crcflag = 1;
    }

    return pool;
}

// Define a function to deallocate the memory allocated for the pool of NFAPI_CRC_INDICATION_PDU_T structures
