#define OPT_OUTPUT_FILE 3
#define OPT_LIMIT 4
#define OPT_VERBOSE 5
#define OPT_THREADS 6
#define OPT_FORMAT 7

// Define structure for storing statistics
typedef struct {
    int num_lines;
    double avg_line_length;
    char most_frequent_word[1024];
    int longest_line;
} stats_t;

// Function to parse command-line arguments and return a pointer to the stats structure
stats_t* parse_args(int argc, char** argv) {
    // Initialize variables
    int i, j, opt;
    char c;
    stats_t* stats = NULL;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "mcs:o:l:vt:f:")) != -1) {
        switch (opt) {
            case OPT_MANPAGE:
                printf("Usage: %s [options] <input file>\n", argv[0]);
                printf("\nOptions:\n");
                printf("  -m, --manpage\tDisplay detailed usage information.\n");
                printf("  -c, --case-sensitive\tEnable case-sensitive line counting (default is case-insensitive).\n");
