                printf("  -l, --limit <number>\tLimit the number of lines processed to the specified value.\n");
                printf("  -v, --verbose\tVerbose mode, which includes line numbers, average line length, and most frequent words in the output.\n");
                printf("  -t, --threads <number>\tSpecify the number of threads to use for parallel processing of files if multiple files are provided.\n");
                printf("  -f, --format <format>\tSpecify the output format (e.g., JSON, CSV).\n");
                exit(0);
            case OPT_CASE_SENSITIVE:
                stats->case_sensitive = 1;
                break;
            case OPT_OUTPUT_FILE:
                stats->output_file = optarg;
                break;
            case OPT_LIMIT:
                stats->limit = atoi(optarg);
                break;
            case OPT_VERBOSE:
                stats->verbose = 1;
                break;
            case OPT_THREADS:
                stats->threads = atoi(optarg);
                break;
            case OPT_FORMAT:
                stats->format = optarg;
                break;
        }
    }

    // Check if input file is specified
    if (optind >= argc) {
        printf("Error: No input file specified.\n");
        exit(1);
    }

    // Initialize statistics structure
    stats = malloc(sizeof(stats_t));
    memset(stats, 0, sizeof(stats_t));

    // Set default values for options
    stats->case_sensitive = 0;
    stats->output_file = NULL;
    stats->limit = -1;
    stats->verbose = 0;
    stats->threads = 1;
    stats->format = "text";

    // Set input file path
    stats->input_file = argv[optind];

    return stats;
}

// Function to read a line from the input file and update statistics
void process_line(stats_t* stats, char* line) {
    int i, j;
    char c;

    // Increment number of lines
    stats->num_lines++;

    // Calculate average line length
    stats->avg_line_length += strlen(line);

    // Find most frequent word in the line
    for (i = 0; i < strlen(line); i++) {
        if (isalpha(line[i])) {
            j = i + 1;
            while (j < strlen(line) && isalpha(line[j])) {
                j++;
            }
            c = line[i];
            for (i = i + 1; i < j; i++) {
                if (c == line[i]) {
                    stats->most_frequent_word[i - 1]++;
                }
            }
        }
    }

    // Find longest line
    if (strlen(line) > stats->longest_line) {
        stats->longest_line = strlen(line);
    }
}

