    // Parse command-line arguments and initialize statistics structure
    stats = parse_args(argc, argv);

    // Check if input file exists and has read permission
    struct stat st;
    if (stat(stats->input_file, &st) == -1 || !(st.st_mode & S_IRUSR)) {
