            longest_line = strlen(line);
        }
        average_line_length += strlen(line);
        line_count++;
    }
    fclose(fp);
    file_stats* stats = (file_stats*)malloc(sizeof(file_stats));
    stats->file = file;
    stats->line_count = line_count;
    stats->average_line_length = average_line_length / line_count;
