    for (int i = optind; i < argc; i++) {
        if (!strcmp(argv[i], "-t") || !strcmp(argv[i], "--threads")) {
            thread_count = atoi(argv[++i]);
        } else if (!strcmp(argv[i], "-o") || !strcmp(argv[i], "--output")) {
            output_file = argv[++i];
        } else if (!strcmp(argv[i], "-f") || !strcmp(argv[i], "--format")) {
