#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <dirent.h>
#include <unistd.h>
#include <errno.h>

// Command line options
static const char* EXTENSION_OPTION = "-e";
static const char* SIZE_SORT_OPTION = "-s";
static const char* DATE_SORT_OPTION = "-d";

// Error messages
static const char* INVALID_DIRECTORY_ERROR = "Invalid directory specified.";
static const char* INVALID_EXTENSION_ERROR = "Invalid file extension specified.";
static const char* INVALID_SORT_OPTION_ERROR = "Invalid sort option specified.";

int main(int argc, char** argv) {
    // Check command line arguments
    if (argc < 2) {
        printf("%s\n", INVALID_DIRECTORY_ERROR);
        return 1;
    }

    // Get directory path from command line argument
    const char* directoryPath = argv[1];

    // Check if directory exists and is a directory
    struct stat sb;
    if (stat(directoryPath, &sb) == -1 || !S_ISDIR(sb.st_mode)) {
        printf("%s\n", INVALID_DIRECTORY_ERROR);
        return 1;
    }

    // Initialize variables for file extension filtering and sorting
    const char* extension = NULL;
    int sortOption = -1;

    // Check command line options
    for (int i = 2; i < argc; i++) {
        if (strcmp(argv[i], EXTENSION_OPTION) == 0 && i + 1 < argc) {
            extension = argv[i + 1];
        } else if (strcmp(argv[i], SIZE_SORT_OPTION) == 0 || strcmp(argv[i], DATE_SORT_OPTION) == 0) {
            sortOption = i;
        } else {
            printf("%s\n", INVALID_SORT_OPTION_ERROR);
            return 1;
        }
    }

    // Open directory and read files
    DIR* dir = opendir(directoryPath);
    if (dir == NULL) {
        printf("Error opening directory: %s\n", strerror(errno));
        return 1;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (entry->d_name[0] == '.') {
            continue;
        }

        // Check file extension filter
        if (extension != NULL && strcmp(extension, entry->d_name + strlen(entry->d_name) - strlen(extension)) != 0) {
            continue;
        }

        // Get file information
        struct stat sb;
        if (stat(entry->d_name, &sb) == -1) {
            printf("Error getting file information: %s\n", strerror(errno));
            return 1;
        }

        // Print file information
        printf("%s\t%ld\t%s\n", entry->d_name, sb.st_size, ctime(&sb.st_mtime));
    }

    // Close directory
    closedir(dir);

    // Calculate total disk space used by listed files
    off_t totalSize = 0;
    for (int i = 2; i < argc; i++) {
        if (strcmp(argv[i], SIZE_SORT_OPTION) == 0 || strcmp(argv[i], DATE_SORT_OPTION) == 0) {
            totalSize += sb.st_size;
        }
    }

    // Print total disk space used by listed files
    printf("Total disk space used: %ld\n", totalSize);

    return 0;
}
