typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_ARRAY_T;

void init_NFAPI_CRC_INDICATION_PDU_ARRAY(NFAPI_CRC_INDICATION_PDU_ARRAY_T *array) {
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void destroy_NFAPI_CRC_INDICATION_PDU_ARRAY(NFAPI_CRC_INDICATION_PDU_ARRAY_T *array) {
    free(array->array);
    pthread_mutex_destroy(&array->mutex);
}

bool add_NFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_ARRAY_T *array, uint32_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
