    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for the TCP_segment
typedef struct {
    TCP_header header;
    char* payload;
    char* options;
} TCP_segment;

// Define the function to dynamically generate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_crc_indication_pdu(int N, int max_length) {
    // Initialize the dynamic array of TCP_segments
    TCP_segment* segments = (TCP_segment*)malloc(sizeof(TCP_segment) * N);

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

    // Generate a random sequence of digits for the filename
    char* filename = (char*)malloc(max_length + 1);
    sprintf(filename, "%s", "log");

    // Initialize the file type to ".bin" if not provided in the original filename
    char* filetype = (char*)malloc(5);
    strcpy(filetype, ".bin");

    // Initialize the directory path for the log file
    char* dirpath = (char*)malloc(256);
    getcwd(dirpath, 256);

    // Initialize the log file name and directory path
    char* logfile = (char*)malloc(256);
    sprintf(logfile, "%s/%s%s", dirpath, filename, filetype);

    // Open the log file for writing
    FILE* fp = fopen(logfile, "w");

    // Initialize the thread synchronization mutex and condition variable
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    // Initialize the memory management variables
    int num_segments = 0;
    int segment_size = 1024;
    int total_size = 0;

    // Loop through each element in the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < N; i++) {
        // Generate a random RX_UE_INFORMATION_TAG and RNTI
        uint16_t RX_UE_INFORMATION_TAG = rand() % 65536;
        uint32_t RNTI = rand() % 4294967296;

        // Generate a randomly set CRCFLAG
        uint8_t CRCFLAG = rand() % 256;

        // Initialize the TCP_segment structure
        segments[i].header.source_port = rand() % 65536;
        segments[i].header.destination_port = rand() % 65536;
        segments[i].header.sequence_number = rand() % 4294967296;
        segments[i].header.acknowledgment_number = rand() % 4294967296;
        segments[i].header.data_offset = rand() % 16;
        segments[i].header.reserved = rand() % 8;
        segments[i].header.control = rand() % 32;
        segments[i].header.window = rand() % 65536;
        segments[i].header.checksum = rand() % 65536;
        segments[i].header.urgent_pointer = rand() % 65536;

        // Initialize the payload and options fields of the TCP_segment structure
        segments[i].payload = (char*)malloc(segment_size);
        memset(segments[i].payload, 0, segment_size);
        segments[i].options = (char*)malloc(1024);
        memset(segments[i].options, 0, 1024);

        // Initialize the NFAPI_CRC_INDICATION_PDU_T structure
        pdu_list[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu_list[i].RNTI = RNTI;
        pdu_list[i].CRCFLAG = CRCFLAG;

        // Increment the number of segments and total size
        num_segments++;
        total_size += segment_size;
    }

    // Close the log file
    fclose(fp);

    // Clean up the memory management variables
    free(filename);
    free(filetype);
    free(dirpath);
    free(logfile);

    // Clean up the thread synchronization mutex and condition variable
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);

    // Return the list of NFAPI_CRC_INDICATION_PDU_T structures
    return pdu_list;
}
