        .subtype = 0x00,
        .to_ds = 0x00,
        .from_ds = 0x00,
        .duration = 0x00,
        .addr1 = {0xff, 0xff, 0xff, 0xff, 0xff, 0xff},
        .addr2 = {0xff, 0xff, 0xff, 0xff, 0xff, 0xff},
        .addr3 = {0xff, 0xff, 0xff, 0xff, 0xff, 0xff},
    };

    // Initialize the MACSDU with a random size and content
    pdu->mac_sdus[0].size = rand() % 1024;
    for (int i = 0; i < pdu->mac_sdus[0].size; i++) {
