    for (int i = 0; i < num_ies; i++) {
        pdu->ie_list[i].id = rand() % 256;
        pdu->ie_list[i].length = rand() % 1024;
        for (int j = 0; j < pdu->ie_list[i].length; j++) {
            pdu->ie_list[i].data[j] = rand() & 0xff;
        }
