// Function to initialize a dynamic array of TCP_segments with valid TCP headers and payloads
void init_tcp_segment(TCP_segment *segment, int payload_size) {
    // Initialize the TCP header
    segment->header = (TCP_header){
        .source_port = rand() % 65536,
        .dest_port = rand() % 65536,
        .seq_num = rand() % 4294967296,
        .ack_num = rand() % 4294967296,
        .data_offset = 0x50,
        .flags = 0x02,
        .window_size = rand() % 65536,
        .checksum = 0x00,
        .urgent_pointer = 0x00,
    };

    // Initialize the TCP payload with a random size and content
    segment->payload.size = payload_size;
    for (int i = 0; i < segment->payload.size; i++) {
        segment->payload.data[i] = rand() & 0xff;
    }
}

// Function to generate a unique filename by appending a random sequence of digits to the original filename
char *generate_filename(const char *original_filename, int max_length) {
    // Get the file extension from the original filename
    const char *extension = strrchr(original_filename, '.');
    if (extension == NULL) {
        extension = ".bin";
    } else {
        extension++;
    }

    // Generate a random sequence of digits to append to the original filename
    int length = rand() % 10;
    char *sequence = malloc(length + 1);
    for (int i = 0; i < length; i++) {
        sequence[i] = '0' + (rand() % 10);
    }
    sequence[length] = '\0';

    // Construct the new filename by appending the random sequence to the original filename
    int total_length = strlen(original_filename) + length + strlen(extension) + 1;
    if (total_length > max_length) {
        total_length = max_length;
    }
    char *new_filename = malloc(total_length);
    snprintf(new_filename, total_length, "%s%s%s", original_filename, sequence, extension);

    // Free the memory allocated for the random sequence and return the new filename
    free(sequence);
    return new_filename;
}

// Function to manage logging to a separate log file, rotating daily with each log entry limited to 1024 bytes
void log(const char *message) {
    // Get the current time and date in ISO format
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char *timestamp = asctime(timeinfo);

    // Open the log file for writing, creating it if necessary
    FILE *log_file = fopen("log.txt", "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return;
    }

    // Write the log entry to the file, limiting the size to 1024 bytes
    int length = strlen(message);
    if (length > 1024) {
        length = 1024;
    }
    fwrite(timestamp, sizeof(char), strlen(timestamp), log_file);
    fwrite(" - ", sizeof(char), 3, log_file);
    fwrite(message, sizeof(char), length, log_file);
    fwrite("\n", sizeof(char), 1, log_file);

    // Close the log file and remove the oldest logs when the threshold is exceeded
    fclose(log_file);
    struct stat st;
    if (stat("log.txt", &st) == 0 && st.st_size > 1024 * 1024) {
        char command[1024];
        sprintf(command, "mv log.txt log-%d.txt", time(NULL));
        system(command);
    }
}']

