// Define the structure for the user connection records
typedef struct UserConnectionRecord {
    int connId;
    time_t lastActiveTime;
    char* sessionState;
} UserConnectionRecord;

// Define the linked list node for the user connection records
typedef struct UserConnectionNode {
    UserConnectionRecord record;
    struct UserConnectionNode* next;
} UserConnectionNode;

// Define the function to initialize and manage the dynamic linked list of user connection records
void initUserConnections(void) {
    // Initialize the head node of the linked list
    UserConnectionNode* head = NULL;

    // Implement a mechanism to handle concurrent updates gracefully, ensuring data integrity and performance optimization
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Define the predefined set of rules for updating the last active time and transitioning the session state
    const char* sessionStates[] = {"active", "inactive", "disconnected"};
    int numSessionStates = sizeof(sessionStates) / sizeof(sessionStates[0]);

    // Define a flexible logging framework that allows for custom logging levels and formats
    void logMessage(int level, const char* message) {
        switch (level) {
            case 1: printf("DEBUG: %s\n", message); break;
            case 2: printf("INFO: %s\n", message); break;
            case 3: printf("WARNING: %s\n", message); break;
            case 4: printf("ERROR: %s\n", message); break;
        }
    }

    // Implement a function to update the last active time and transition the session state based on the predefined rules
    void updateUserConnection(int connId, int newSessionState) {
        pthread_mutex_lock(&mutex);

        UserConnectionNode* node = head;
        while (node != NULL && node->record.connId != connId) {
            node = node->next;
        }

        if (node == NULL) {
            // If the connection ID is not found in the linked list, create a new node and add it to the end of the list
            UserConnectionNode* newNode = malloc(sizeof(UserConnectionNode));
            newNode->record.connId = connId;
            newNode->record.lastActiveTime = time(NULL);
            newNode->record.sessionState = sessionStates[newSessionState];
            newNode->next = NULL;

            if (head == NULL) {
                head = newNode;
            } else {
                UserConnectionNode* currentNode = head;
                while (currentNode->next != NULL) {
                    currentNode = currentNode->next;
                }
                currentNode->next = newNode;
            }
        } else {
            // If the connection ID is found in the linked list, update the last active time and transition the session state
            node->record.lastActiveTime = time(NULL);
            int oldSessionState = getSessionStateIndex(node->record.sessionState);
            if (newSessionState != oldSessionState) {
                logMessage(2, "Connection %d: Session state changed from %s to %s", connId, sessionStates[oldSessionState], sessionStates[newSessionState]);
            }
            node->record.sessionState = sessionStates[newSessionState];
        }

        pthread_mutex_unlock(&mutex);
    }

    // Implement a function to get the index of the current session state in the predefined set of rules
    int getSessionStateIndex(const char* sessionState) {
        for (int i = 0; i < numSessionStates; i++) {
            if (strcmp(sessionState, sessionStates[i]) == 0) {
                return i;
            }
        }
        return -1;
    }
}
