void manage_log_directory(const char *directory) {
    // Get the current time in seconds since the epoch
    time_t now = time(NULL);

    // Open the log directory for reading
    DIR *dir = opendir(directory);

    // Iterate over the files in the log directory
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Check if the file is a regular file and has a ".txt" extension
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".txt") != NULL) {
            // Get the last modification time of the file
            struct stat st;
            stat(entry->d_name, &st);

            // Check if the file is older than 1 day
            if (now - st.st_mtime > 86400) {
                // Remove the file from the log directory
                remove(entry->d_name);
            }
        }
    }

    // Close the log directory
    closedir(dir);
}
