        free(pool);
        fclose(log_file);
        free(pdu_list);
        free(segment_list);
        return;
    }
    int line_count = 0;
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, input_file)) != -1) {
        line_count++;
    }
    free(line);
    fclose(input_file);

    // Print the number of lines in the input file
    printf("Number of lines in the input file: %d\n", line_count);

    // Free memory allocated for the log file and custom memory pool
    free(pool->buffer);
    free(pool);
    fclose(log_file);

    // Free memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures and TCP_segments
    free(pdu_list);
    free(segment_list);
}
