        newNode->data.CRCFLAG = (i % 2 == 0) ? true : false;

        // Set the next pointer of the new node to NULL
        newNode->next = NULL;

        // If the head pointer is NULL, set it to point to the new node
        if (*head == NULL) {
            *head = newNode;
        } else {
            // Otherwise, add the new node to the end of the linked list
            Node* current = *head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newNode;
        }
    }

    return 0;
}

// Function to handle memory allocation failures and ensure proper linked list management
