// Define the function for inserting a CRC indication into the list
void insert_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Validate the RNTI value falls within the specified range
    if (pdu->rnti < rnti_validation_range_min || pdu->rnti > rnti_validation_range_max) {
        log_error("Invalid RNTI value: %u", pdu->rnti);
        return;
