        resize_crc_indication_list(crc_indication_list_capacity * 2);
    }

    // Insert the CRC indication into the list
    crc_indication_list[crc_indication_list_size].pdu = pdu;
    crc_indication_list[crc_indication_list_size].timestamp = get_current_timestamp();
    crc_indication_list_size++;
}

// Define the function for resizing the list of CRC indications
void resize_crc_indication_list(uint32_t new_capacity) {
    // Allocate memory for the new list
    CRC_INDICATION_LIST_ENTRY_T *new_list = malloc(sizeof(CRC_INDICATION_LIST_ENTRY_T) * new_capacity);
    if (new_list == NULL) {
        log_error("Failed to allocate memory for the CRC indication list");
        return;
    }

    // Copy the existing elements from the old list to the new list
    uint32_t i;
    for (i = 0; i < crc_indication_list_size; i++) {
        new_list[i].pdu = crc_indication_list[i].pdu;
        new_list[i].timestamp = crc_indication_list[i].timestamp;
    }

    // Free the old list and update the global variables
    free(crc_indication_list);
    crc_indication_list = new_list;
    crc_indication_list_capacity = new_capacity;
}

// Define the function for purging older entries from the list
void purge_older_entries(uint32_t threshold) {
    // Check if the list is empty or the threshold is 0
    if (crc_indication_list_size == 0 || threshold == 0) {
        return;
    }

    // Find the oldest entry that meets the purge threshold
    uint32_t i = 0;
    while (i < crc_indication_list_size && crc_indication_list[i].timestamp.tv_sec > threshold) {
        i++;
    }

    // Purge the entries before the oldest entry that meets the purge threshold
    if (i > 0) {
        crc_indication_list_size -= i;
        memmove(crc_indication_list, crc_indication_list + i, sizeof(CRC_INDICATION_LIST_ENTRY_T) * crc_indication_list_size);
    }
}

// Define the function for handling periodic purges of older entries
void handle_periodic_purges() {
    // Check if the purge threshold is set and the list is not empty
    if (purge_threshold == 0 || crc_indication_list_size == 0) {
        return;
    }

    // Purge older entries based on the purge threshold
    uint32_t threshold = get_current_timestamp().tv_sec - purge_threshold;
    purge_older_entries(threshold);
}

