// Define the function for validating the input data and updating the configuration settings if necessary
void validate_input_data(NFAPI_CRC_INDICATION_PDU_T *data, size_t count) {
    // Validate that the RNTIs fall within a specified valid range
    for (size_t i = 0; i < count; i++) {
        if (data[i].rnti < MIN_RNTI || data[i].rnti > MAX_RNTI) {
            log_error("Invalid RNTI value: %d", data[i].rnti);
            return false;
        }
    }

    // Validate that no duplicate RNTIs are inserted into the list structure
    for (size_t i = 0; i < count - 1; i++) {
        for (size_t j = i + 1; j < count; j++) {
            if (data[i].rnti == data[j].rnti) {
                log_error("Duplicate RNTI value: %d", data[i].rnti);
                return false;
            }
        }
    }

    // Update the configuration settings if necessary
    update_configuration_settings();
