// Define the function to dynamically generate a list of NFAPI_RRC_MESSAGE_PDU_T structures
void generate_rrc_message_pdu_list(int N, int default_channel_mode, int default_transmission_power) {
    // Initialize the list of NFAPI_RRC_MESSAGE_PDU_T structures
    NFAPI_RRC_MESSAGE_PDU_T *rrc_message_pdu_list = (NFAPI_RRC_MESSAGE_PDU_T *)malloc(sizeof(NFAPI_RRC_MESSAGE_PDU_T) * N);
    if (!rrc_message_pdu_list) {
        printf("Error: Failed to allocate memory for the list of RRC message PDUs\n");
        return;
    }

    // Initialize the thread pool for concurrent execution
    pthread_t *threads = (pthread_t *)malloc(sizeof(pthread_t) * N);
    if (!threads) {
        printf("Error: Failed to allocate memory for the thread pool\n");
        free(rrc_message_pdu_list);
        return;
    }

    // Initialize the configuration structure for each thread
    struct config {
        int channel_mode;
        int transmission_power;
        NFAPI_RRC_MESSAGE_PDU_T *rrc_message_pdu_list;
        int rrc_message_pdu_list_size;
        int thread_id;
    };
    struct config *configs = (struct config *)malloc(sizeof(struct config) * N);
    if (!configs) {
        printf("Error: Failed to allocate memory for the configuration structures\n");
        free(rrc_message_pdu_list);
        free(threads);
        return;
    }

    // Initialize the thread synchronization variables
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Parse the XML configuration file to determine the default channel mode and transmission power
    FILE *config_file = fopen("config.xml", "r");
    if (!config_file) {
        printf("Error: Failed to open the configuration file\n");
        free(rrc_message_pdu_list);
        free(threads);
        free(configs);
        return;
    }
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, config_file)) != -1) {
        if (strstr(line, "<channel_mode>") != NULL) {
            default_channel_mode = atoi(strstr(line, "<channel_mode>") + 13);
        } else if (strstr(line, "<transmission_power>") != NULL) {
            default_transmission_power = atoi(strstr(line, "<transmission_power>") + 20);
        }
    }
    fclose(config_file);

    // Initialize the RRC state machine and the last state in the list
    int rrc_state_machine = 0;
    int last_state = -1;

    // Loop through each thread to generate a unique configuration for each thread
    for (int i = 0; i < N; i++) {
        // Initialize the configuration structure for the current thread
        configs[i].channel_mode = default_channel_mode;
        configs[i].transmission_power = default_transmission_power;
        configs[i].rrc_message_pdu_list = rrc_message_pdu_list + i * N;
        configs[i].rrc_message_pdu_list_size = N;
        configs[i].thread_id = i;

        // Create a new thread to generate the configuration for the current thread
        pthread_create(&threads[i], NULL, generate_configuration, (void *)&configs[i]);
    }

    // Wait for all threads to complete and clean up the thread pool
    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);

    // Validate the integrity of the configuration settings after each update
    for (int i = 0; i < N; i++) {
        if (configs[i].channel_mode < 0 || configs[i].transmission_power < 0) {
            printf("Error: Invalid channel mode or transmission power\n");
            free(rrc_message_pdu_list);
            free(threads);
            free(configs);
            return;
        }
    }

    // Log the operation details to a separate log file
    FILE *log_file = fopen("operation.log", "a");
    if (!log_file) {
        printf("Error: Failed to open the log file\n");
        free(rrc_message_pdu_list);
        free(threads);
        free(configs);
        return;
    }
    fprintf(log_file, "Operation details:\n");
    for (int i = 0; i < N; i++) {
        fprintf(log_file, "\tThread %d: Channel mode = %d, Transmission power = %d\n", i, configs[i].channel_mode, configs[i].transmission_power);
    }
    fclose(log_file);

    // Manage the maximum size of the log directory to prevent excessive disk usage by removing the oldest logs when the threshold is exceeded
    struct statvfs log_dir_stats;
    if (statvfs("./logs", &log_dir_stats) == 0) {
        long free_space = log_dir_stats.f_bavail * log_dir_stats.f_frsize;
        if (free_space < 1024 * 1024 * 1024) { // 1 GB
            printf("Error: The log directory is running out of space\n");
            free(rrc_message_pdu_list);
            free(threads);
            free(configs);
            return;
        }
    }

    // Clean up the memory and resources used by the function
    free(rrc_message_pdu_list);
    free(threads);
    free(configs);
}

// Define the thread function to generate a unique configuration for each thread
void *generate_configuration(void *arg) {
    struct config *config = (struct config *)arg;

    // Initialize the RRC state machine and the last state in the list
    int rrc_state_machine = 0;
    int last_state = -1;

    // Loop through each configuration to generate a unique configuration for each thread
    for (int i = 0; i < config->rrc_message_pdu_list_size; i++) {
        // Generate a unique RRC message PDU ID and transaction ID for the current thread
        int rrc_message_pdu_id = rand() % 1000000 + 1;
        int rrc_transaction_id = rand() % 1000000 + 1;

        // Generate a unique PHY channel configuration for the current thread
        config->rrc_message_pdu_list[i].RRC_MESSAGE_ID = rrc_message_pdu_id;
        config->rrc_message_pdu_list[i].RRC_TRANSACTION_ID = rrc_transaction_id;
        config->rrc_message_pdu_list[i].phy_channel_config.CHANNEL_MODE = rand() % 10 + 1;
        config->rrc_message_pdu_list[i].phy_channel_config.TRANSMISSION_POWER = rand() % 100 + 1;

        // Update the RRC state machine and the last state in the list
        rrc_state_machine = (rrc_state_machine + 1) % 10;
        last_state = i;
    }

    // Log the operation details to a separate log file
    FILE *log_file = fopen("operation.log", "a");
    if (!log_file) {
        printf("Error: Failed to open the log file\n");
        return NULL;
    }
    fprintf(log_file, "Thread %d: Operation details:\n", config->thread_id);
    for (int i = 0; i <= last_state; i++) {
        fprintf(log_file, "\tRRC message PDU ID = %d, Transaction ID = %d\n", config->rrc_message_pdu_list[i].RRC_MESSAGE_ID, config->rrc_message_pdu_list[i].RRC_TRANSACTION_ID);
    }
    fclose(log_file);

    // Clean up the memory and resources used by the thread function
    return NULL;
}
