#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>

// Define the structure for storing MAC packet information
typedef struct {
    int id;
    char src_mac[18];
    char dest_mac[18];
} mac_packet_t;

// Define the structure for storing configuration settings
typedef struct {
    int num_configs;
    mac_packet_t *configs;
} config_t;

// Define the structure for storing state lists within the thread pool operations
typedef struct {
    int id;
    char src_mac[18];
    char dest_mac[18];
    int last_state;
} state_list_t;

// Define the function to dynamically manage a collection of MAC packet structures
void manage_mac_packets(config_t *config, mac_packet_t *packet) {
    // Check if the configuration is valid
    if (config == NULL || config->num_configs <= 0) {
        return;
    }

    // Allocate memory for the list of MAC packet structures
    mac_packet_t *mac_packets = malloc(sizeof(mac_packet_t) * config->num_configs);
    if (mac_packets == NULL) {
        return;
    }

    // Initialize the list of MAC packet structures with the default configuration
    for (int i = 0; i < config->num_configs; i++) {
        mac_packets[i].id = config->configs[i].id;
        strcpy(mac_packets[i].src_mac, config->configs[i].src_mac);
        strcpy(mac_packets[i].dest_mac, config->configs[i].dest_mac);
    }

    // Check if the packet is valid
    if (packet == NULL) {
        return;
    }

    // Update the list of MAC packet structures with the new packet information
    for (int i = 0; i < config->num_configs; i++) {
        if (mac_packets[i].id == packet->id) {
            strcpy(mac_packets[i].src_mac, packet->src_mac);
            strcpy(mac_packets[i].dest_mac, packet->dest_mac);
            break;
        }
    }

    // Validate the integrity of the MAC address configurations
    for (int i = 0; i < config->num_configs; i++) {
        if (!validate_mac_address(mac_packets[i].src_mac) || !validate_mac_address(mac_packets[i].dest_mac)) {
            return;
        }
    }

    // Log the operation details to a separate log file
    char log_file[256];
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    strftime(log_file, sizeof(log_file), "mac_packet_manager.%Y-%m-%d.log", time_info);
    FILE *log_fp = fopen(log_file, "a");
    if (log_fp == NULL) {
        return;
    }
    fprintf(log_fp, "%s: %d\n", __func__, config->num_configs);
    for (int i = 0; i < config->num_configs; i++) {
        fprintf(log_fp, "ID: %d, SRC MAC: %s, DEST MAC: %s\n", mac_packets[i].id, mac_packets[i].src_mac, mac_packets[i].dest_mac);
    }
    fclose(log_fp);
}

// Define the function to validate the integrity of a MAC address configuration
int validate_mac_address(char *mac_addr) {
    // Check if the MAC address is valid
    if (strlen(mac_addr) != 17 || mac_addr[2] != ':' || mac_addr[5] != ':' || mac_addr[8] != ':' || mac_addr[11] != ':' || mac_addr[14] != ':') {
        return 0;
    }

    // Check if the MAC address is in the correct format
    for (int i = 0; i < 17; i++) {
        if (!isxdigit(mac_addr[i]) && mac_addr[i] != ':') {
            return 0;
        }
    }

    // Check if the MAC address is unique among all configurations in the current directory
    char *config_file = "mac_packet_manager.conf";
    FILE *config_fp = fopen(config_file, "r");
    if (config_fp == NULL) {
        return 1;
    }
    while (!feof(config_fp)) {
        char line[256];
        fgets(line, sizeof(line), config_fp);
        if (strstr(line, mac_addr) != NULL) {
            fclose(config_fp);
            return 0;
        }
    }
    fclose(config_fp);
    return 1;
}

// Define the function to parse a JSON configuration file and determine default MAC address settings if no specific configuration is provided in the function call
void parse_json_config(char *filename, config_t *config) {
    // Check if the filename is valid
    if (filename == NULL || strlen(filename) == 0) {
        return;
    }

    // Open the JSON configuration file
    FILE *config_fp = fopen(filename, "r");
    if (config_fp == NULL) {
        return;
    }

    // Read the JSON configuration file and determine default MAC address settings if no specific configuration is provided in the function call
    char line[256];
    while (!feof(config_fp)) {
        fgets(line, sizeof(line), config_fp);
        if (strstr(line, "\"num_configs\":") != NULL) {
            sscanf(line, "\"num_configs\": %d", &config->num_configs);
        } else if (strstr(line, "\"src_mac\":") != NULL) {
            char src_mac[18];
            sscanf(line, "\"src_mac\": \"%s\"", src_mac);
            strcpy(config->configs[i].src_mac, src_mac);
        } else if (strstr(line, "\"dest_mac\":") != NULL) {
            char dest_mac[18];
            sscanf(line, "\"dest_mac\": \"%s\"", dest_mac);
            strcpy(config->configs[i].dest_mac, dest_mac);
        }
    }
    fclose(config_fp);
}

// Define the function to handle filenames with multiple dots and maintain the original directory path in the configuration file paths
void handle_filename_with_multiple_dots(char *filename) {
    // Check if the filename is valid
    if (filename == NULL || strlen(filename) == 0) {
        return;
    }

    // Split the filename into its directory and basename components
    char *directory = strtok(filename, "/");
    char *basename = strrchr(filename, '/');
    if (basename != NULL) {
        basename++;
    } else {
        basename = filename;
    }

    // Check if the basename contains multiple dots and handle it accordingly
    char *dot = strrchr(basename, '.');
    if (dot != NULL && dot - basename > 1) {
        // Remove the extension from the basename
        *dot = '\0';

        // Append a timestamp to the basename to ensure uniqueness among all configurations in the current directory
        char timestamp[256];
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);
        sprintf(basename + (dot - basename), ".%s", timestamp);
    }
}

// Define the function to ensure that the resulting configuration is unique among all configurations in the current directory by appending a timestamp until no conflict is found
void ensure_unique_configuration(config_t *config) {
    // Check if the configuration is valid
    if (config == NULL || config->num_configs <= 0) {
        return;
    }

    // Allocate memory for the list of MAC packet structures
    mac_packet_t *mac_packets = malloc(sizeof(mac_packet_t) * config->num_configs);
    if (mac_packets == NULL) {
        return;
    }

    // Initialize the list of MAC packet structures with the default configuration
    for (int i = 0; i < config->num_configs; i++) {
        mac_packets[i].id = config->configs[i].id;
        strcpy(mac_packets[i].src_mac, config->configs[i].src_mac);
        strcpy(mac_packets[i].dest_mac, config->configs[i].dest_mac);
    }

    // Ensure that the resulting configuration is unique among all configurations in the current directory by appending a timestamp until no conflict is found
    char *directory = ".";
    while (1) {
        for (int i = 0; i < config->num_configs; i++) {
            sprintf(mac_packets[i].src_mac, "%s/%s.%s", directory, mac_packets[i].src_mac, timestamp);
            sprintf(mac_packets[i].dest_mac, "%s/%s.%s", directory, mac_packets[i].dest_mac, timestamp);
        }
        if (!validate_unique_configuration(mac_packets)) {
            break;
        }
    }
}

// Define the function to validate that a resulting configuration is unique among all configurations in the current directory
int validate_unique_configuration(mac_packet_t *mac_packets) {
    // Check if the MAC packet structures are valid
    if (mac_packets == NULL || mac_packets->num_configs <= 0) {
        return 0;
    }

    // Open the JSON configuration file and read its contents
    char *config_file = "mac_packet_manager.conf";
    FILE *config_fp = fopen(config_file, "r");
    if (config_fp == NULL) {
        return 1;
    }
    while (!feof(config_fp)) {
        char line[256];
        fgets(line, sizeof(line), config_fp);
        if (strstr(line, mac_packets->src_mac) != NULL || strstr(line, mac_packets->dest_mac) != NULL) {
            fclose(config_fp);
            return 0;
        }
    }
    fclose(config_fp);
    return 1;
}

// Define the function to manage a thread pool with a configurable maximum number of threads, initializing the pool, executing a set of tasks concurrently, and ensuring all threads are properly terminated and cleaned up upon completion
void manage_thread_pool(int num_threads, void *(*task)(void *), void *args) {
    // Check if the number of threads is valid
    if (num_threads <= 0) {
        return;
    }

    // Allocate memory for the thread pool and initialize it
    pthread_t *threads = malloc(sizeof(pthread_t) * num_threads);
    if (threads == NULL) {
        return;
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, task, args);
    }

    // Execute the set of tasks concurrently and ensure all threads are properly terminated and cleaned up upon completion
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);
}

// Define the function to dynamically allocate memory for storing state lists within the thread pool operations
void *allocate_state_list(int id, char *src_mac, char *dest_mac, int last_state) {
    // Allocate memory for the state list structure
    state_list_t *state_list = malloc(sizeof(state_list_t));
    if (state_list == NULL) {
        return NULL;
    }

    // Initialize the state list structure with the provided parameters
    state_list->id = id;
    strcpy(state_list->src_mac, src_mac);
    strcpy(state_list->dest_mac, dest_mac);
    state_list->last_state = last_state;

    // Return the allocated memory for the state list structure
    return state_list;
}

// Define the function to track and report the throughput and latency of packet processing to facilitate performance tuning
void track_packet_processing(int num_packets, int *throughput, int *latency) {
    // Check if the number of packets is valid
    if (num_packets <= 0) {
        return;
    }

    // Calculate the throughput and latency for the packet processing operation
    *throughput = num_packets / 1000;
    *latency = 1000 / *throughput;
}
