        // Check for errors in reading the configuration file
        if (ferror(fp)) {
            printf("Error: Unable to read from configuration file %s\n", config->config_file);
            return;
        }

        // Parse each line of the configuration file and set default MAC address settings if necessary
        parse_configuration_line(line, config, packets);
    }

    // Close the configuration file
    fclose(fp);
