// Function to parse a single line from the configuration file and set default MAC address settings if necessary
void parse_configuration_line(char *line, CONFIG_T *config, MAC_PACKET_T **packets) {
    // Check for errors in parsing the configuration line
    if (strlen(line) == 0 || line[0] == '#') {
        return;
    }

    // Parse the configuration line and set default MAC address settings if necessary
    char *token = strtok(line, " ");
    while (token != NULL) {
        if (strcmp(token, "N") == 0) {
            config->N = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "default_mac_address") == 0) {
            int i;
            for (i = 0; i < 6; i++) {
                config->default_mac_address[i] = atoi(strtok(NULL, ":"));
            }
        } else if (strcmp(token, "config_file") == 0) {
            strcpy(config->config_file, strtok(NULL, "\n"));
        }
        token = strtok(NULL, " ");
    }
}

