    if (mac_state_machine->current_state < 0) {
        printf("Error: Unable to update MAC state machine\n");
        return;
    }
}

// Function to calculate the next state of the MAC state machine based on a single packet
int calculate_next_state(MAC_PACKET_T *packet, MAC_STATE_MACHINE_T *mac_state_machine) {
    // Calculate the next state of the MAC state machine based on the current packet
    int next_state = mac_state_machine->current_state + 1;

    // Check for errors in calculating the next state
    if (next_state < 0 || next_state > 256) {
