    void add_element(QUEUE_ENTRY_T *entry) {
        // Acquire the mutex lock
        pthread_mutex_lock(&mutex);

        // Check if the queue is full
        if (num_elements == max_elements) {
            printf("Error: The queue is full\n");
            exit(1);
        }

        // Add the element to the queue
        queue[num_elements++] = *entry;

        // Signal the condition variable
        pthread_cond_signal(&cond);

        // Release the mutex lock
        pthread_mutex_unlock(&mutex);
    }

    // Define a function to remove an element from the queue
    void remove_element(int index) {
        // Acquire the mutex lock
        pthread_mutex_lock(&mutex);

        // Check if the index is valid
        if (index < 0 || index >= num_elements) {
            printf("Error: The index is invalid\n");
            exit(1);
        }

        // Remove the element from the queue
        QUEUE_ENTRY_T *entry = &queue[index];
        memmove(&queue[index], &queue[index + 1], (num_elements - index - 1) * sizeof(QUEUE_ENTRY_T));
        num_elements--;

        // Signal the condition variable
        pthread_cond_signal(&cond);

        // Release the mutex lock
        pthread_mutex_unlock(&mutex);
    }

    // Define a function to get an element from the queue
