                        printf("Connection established: %s\n", connection_id);
                        printf("Message received: %s\n", message_buffer);
                    } else if (strcmp(monitoring_level, "error") == 0) {
                        printf("Connection established: %s\n", connection_id);
                        printf("Message received: %s\n", message_buffer);
                    }
                }
            }
        } else {
            printf("Invalid JSON data\n");
        }
    }
}

void generate_random_string(int length) {
    // Generate a random string of the specified length using OpenSSL's secure random number generator
    char *random_string = malloc(length + 1);
    for (int i = 0; i < length; i++) {
        int random_char = RAND_bytes(1, NULL);
        if (random_char >= 0 && random_char <= 255) {
            random_string[i] = random_char;
        } else {
            printf("Error generating random string\n");
        }
    }
    return random_string;
}

void generate_hash(char *host, char *session_id) {
    // Generate a hash of the host name and session ID using a salted hash function with adjustable parameters for security strength
    int hash_length = HASH_ITERATIONS * SALT_LENGTH;
    char *hash = malloc(hash_length + 1);
    for (int i = 0; i < HASH_ITERATIONS; i++) {
        char *salt = generate_random_string(SALT_LENGTH);
        int hash_size = SHA256_DIGEST_LENGTH;
        unsigned char hash_buffer[hash_size];
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, host, strlen(host));
        SHA256_Update(&ctx, session_id, strlen(session_id));
        SHA256_Update(&ctx, salt, strlen(salt));
        SHA256_Final(hash_buffer, &ctx);
        for (int j = 0; j < hash_size; j++) {
            hash[i * SALT_LENGTH + j] = hash_buffer[j];
        }
    }
    return hash;
}
