        if (!context_entries[i]->active) {
            context_entries[i]->active = true;
            context_entries[i]->context->id = id;
            strcpy(context_entries[i]->context->qos_flow, qos_flow);
            strcpy(context_entries[i]->context->rrc_messages, rrc_messages);
            pool.num_active_contexts++;
            break;
        }
    }
    pthread_mutex_unlock(&pool.mutex);
}

// Update an existing UE Context in the pool
