    for (int i = 0; i < MAX_CONTEXTS; i++) {
        if (context_entries[i]->active && context_entries[i]->context->id == id) {
            strcpy(context_entries[i]->context->qos_flow, qos_flow);
            strcpy(context_entries[i]->context->rrc_messages, rrc_messages);
            break;
        }
    }
    pthread_mutex_unlock(&pool.mutex);
}

// Delete an existing UE Context from the pool
void delete_context(int id) {
