            context_entries[i]->active = false;
            pool.num_inactive_contexts++;
            break;
        }
    }
    pthread_mutex_unlock(&pool.mutex);
}

// Clean up inactive UE Contexts periodically to prevent memory leaks and optimize resource usage
void cleanup() {
    pthread_mutex_lock(&pool.mutex);
    if (pool.num_inactive_contexts > 0) {
        for (int i = 0; i < MAX_CONTEXTS; i++) {
            if (!context_entries[i]->active) {
                free(context_entries[i]);
                pool.num_inactive_contexts--;
            }
        }
    }
    pthread_mutex_unlock(&pool.mutex);
}

// Log critical events such as context creation, updates, and deletions for auditing and debugging purposes
void log(char *message) {
    if (LOGGING_LEVEL > 0) {
        printf("%s\n", message);
    }
}

// Throttle cleanup operations based on system load and UE activity patterns
void throttle() {
    pthread_mutex_lock(&pool.mutex);
    if (pool.num_active_contexts > THROTTLING_FACTOR) {
        pool.cleanup_pending = true;
    } else {
        pool.cleanup_pending = false;
    }
    pthread_cond_signal(&pool.cond);
    pthread_mutex_unlock(&pool.mutex);
}

// Provide statistics API to monitor key performance metrics such as context lookup time, update latency, and cleanup efficiency
