        Transaction* transaction = &transactions[i];
        printf("Enter transaction %d details: ", i + 1);
        scanf("%d %lf %c", &transaction->id, &transaction->amount, &transaction->status);
    }

    // Set the configuration options for transaction validation and processing
    setConfigOption(&options, "min_amount", "10.0");
    setConfigOption(&options, "max_amount", "500.0");
    setConfigOption(&options, "allowed_currencies", "USD,EUR,GBP");
    setConfigOption(&options, "retry_limit", "3");

    // Process the batch of transactions using the defined function
    processBatchTransactions(&options, &transactions[0], num_transactions);

    // Print the total amount and failed count
    printf("Total amount: %.2f\n", total_amount);
    printf("Failed count: %d\n", failed_count);

    return 0;
}
