#define TIME_BASED_EVICTION_THRESHOLD 1800 // seconds

// Define the Least Recently Used (LRU) eviction policy parameters
#define LRU_EVICTION_SIZE_THRESHOLD 512 // bytes
#define LRU_EVICTION_AGE_THRESHOLD 3600 // seconds

