    if (EVICTION_POLICY == TIME_BASED_EVICTION) {
        for (int i = 1; i < CACHE_SIZE; i++) {
            if (cache[i]->last_accessed + TIME_BASED_EVICTION_THRESHOLD < time(NULL)) {
                free(cache[i]);
                cache[i] = NULL;
            }
        }
    } else if (EVICTION_POLICY == LRU) {
        for (int i = 1; i < CACHE_SIZE; i++) {
            if (cache[i]->last_accessed + LRU_EVICTION_AGE_THRESHOLD < time(NULL)) {
                free(cache[i]);
                cache[i] = NULL;
            }
        }
