    sprintf(old_filename, "%s/%s", directory, filename);
    if (rename(old_filename, new_filename) == -1) {
        perror("rename");
        return;
    }

    // Log the file movement
    char* log_message = malloc(256);
    sprintf(log_message, "%s moved to %s", old_filename, new_filename);
    if (LOGGING_ENABLED) {
        FILE* log_file = fopen(LOGGING_DIRECTORY "/" LOGGING_FILENAME, "a");
        fprintf(log_file, "%s\n", log_message);
