// Define the structure for LTE_PDCP_SDU_T
typedef struct {
    int sap_identity;
    int sequence_number;
    char snssai[10];
} LTE_PDCP_SDU_T;

// Define a global variable to store the next available sequence number
int next_sequence_number = 0;

// Define a mutex for synchronizing access to the shared data structure
pthread_mutex_t sequence_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate memory for an array of LTE_PDCP_SDU_T structures
LTE_PDCP_SDU_T* allocate_pdcp_sdus(int num_elements) {
    // Calculate the required memory size for the array
    int mem_size = sizeof(LTE_PDCP_SDU_T) * num_elements;

    // Allocate memory for the array using malloc
    LTE_PDCP_SDU_T* pdcp_sdus = (LTE_PDCP_SDU_T*)malloc(mem_size);

    // Check if allocation failed
    if (!pdcp_sdus) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the sap_identity field for each structure
    for (int i = 0; i < num_elements; i++) {
        pdcp_sdus[i].sap_identity = i + 1;
    }

    // Generate a random SNSSAI for each structure
    srand(time(NULL));
    for (int i = 0; i < num_elements; i++) {
        snprintf(pdcp_sdus[i].snssai, sizeof(pdcp_sdus[i].snssai), "%d", rand() % 10);
    }

    // Increment the next available sequence number for each new structure
    pthread_mutex_lock(&sequence_lock);
    for (int i = 0; i < num_elements; i++) {
        pdcp_sdus[i].sequence_number = next_sequence_number++;
    }
    pthread_mutex_unlock(&sequence_lock);

    // Log the memory allocation event
    printf("Memory allocated for %d LTE_PDCP_SDU_T structures\n", num_elements);

