        packet_list->packet_data[i].Source_IP[16] = '\0';
        packet_list->packet_data[i].Destination_IP[16] = '\0';
        packet_list->packet_data[i].Payload[256] = '\0';
    }

    // Initialize the log file list
    LOG_LIST *log_list = (LOG_LIST *)malloc(sizeof(LOG_LIST));
    log_list->num_files = 1;
    log_list->log_files = (LOG_FILE *)malloc(sizeof(LOG_FILE) * 1);
    log_list->log_files[0].filename[256] = '\0';
