    strftime(filename, 256, "log_%Y-%m-%d.txt", tm);
    log_list->log_files[0].file = fopen(filename, "w");
    if (log_list->log_files[0].file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    fprintf(log_list->log_files[0].file, "Log File Header\n");

    // Set the number of concurrent connections and packets
