    int port;
    bool is_connected;
} NetworkConnection;

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
