typedef struct {
    int sap_identity;
    int sequence_number;
    char* pdcp_snssai;
} LTE_PDCP_SDU_T;

// Define a custom memory pool to optimize cache performance and reduce memory fragmentation
struct MemoryPool {
    size_t size;
    void* data;
};

// Function to dynamically allocate memory for an array of LTE_PDCP_SDU_T structures
LTE_PDCP_SDU_T* alloc_array(size_t n) {
    // Check if the input is valid
    if (n == 0) {
        return NULL;
    }

    // Calculate the size of each structure in bytes
    size_t struct_size = sizeof(LTE_PDCP_SDU_T);

    // Allocate memory for the array
    LTE_PDCP_SDU_T* arr = malloc(n * struct_size);
    if (arr == NULL) {
        return NULL;
    }

    // Initialize each structure with a valid SAP_IDENTITY, SEQUENCE_NUMBER, and PDCP_SNSSAI
    for (int i = 0; i < n; i++) {
        arr[i].sap_identity = rand() % 1000;
        arr[i].sequence_number = rand() % 1000;
        arr[i].pdcp_snssai = malloc(sizeof(char) * 5);
        strcpy(arr[i].pdcp_snssai, "SNSSAI");
    }

    return arr;
}

// Function to deallocate memory for an array of LTE_PDCP_SDU_T structures
void free_array(LTE_PDCP_SDU_T* arr) {
    // Check if the input is valid
    if (arr == NULL) {
        return;
    }

    // Deallocate memory for each structure in the array
    for (int i = 0; i < n; i++) {
        free(arr[i].pdcp_snssai);
    }

    // Deallocate memory for the array itself
    free(arr);
}

// Function to allocate memory from a custom memory pool
void* alloc_from_pool(struct MemoryPool* pool, size_t size) {
    // Check if the input is valid
    if (pool == NULL || size == 0) {
        return NULL;
    }

    // Calculate the number of bytes to allocate
    size_t alloc_size = size * sizeof(char);

    // Allocate memory from the pool
    void* data = malloc(alloc_size);
    if (data == NULL) {
        return NULL;
    }

    // Update the pool's size and data pointer
    pool->size += alloc_size;
    pool->data = realloc(pool->data, pool->size);
    if (pool->data == NULL) {
        free(data);
        return NULL;
    }

    // Return the allocated memory
    return data;
}

// Function to deallocate memory from a custom memory pool
void free_from_pool(struct MemoryPool* pool, void* data) {
    // Check if the input is valid
    if (pool == NULL || data == NULL) {
        return;
    }

    // Calculate the size of the data to deallocate
    size_t alloc_size = sizeof(char) * pool->size;

    // Deallocate memory from the pool
    void* new_data = realloc(pool->data, pool->size - alloc_size);
    if (new_data == NULL) {
        return;
    }

    // Update the pool's size and data pointer
    pool->size -= alloc_size;
    pool->data = new_data;
}

