void *initialize_network_interface(int num_threads, int max_num_ue) {
    // Allocate memory for the thread pool
    pthread_t *threads = (pthread_t *)malloc(sizeof(pthread_t) * num_threads);
    if (!threads) {
        printf("Error: Failed to allocate memory for thread pool\n");
        return NULL;
    }

    // Allocate memory for the state list
    STATE_LIST *state_list = (STATE_LIST *)malloc(sizeof(STATE_LIST) * max_num_ue);
    if (!state_list) {
        printf("Error: Failed to allocate memory for state list\n");
        free(threads);
        return NULL;
    }

    // Initialize the thread pool and state list
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, (void *)state_list + i * sizeof(STATE_LIST), NULL);
    }

    // Set the next pointer of the last state in the list to point to the newly created state list
    STATE_LIST *last_state = state_list;
    for (int i = 0; i < max_num_ue - 1; i++) {
        last_state->next = state_list + i * sizeof(STATE_LIST);
        last_state = last_state->next;
    }

    // Return the thread pool and state list
