// Define the function for managing the thread pool
int manage_thread_pool(thread_pool_t *thread_pool, int num_threads) {
    // Check if there are enough threads available in the pool
    if (num_threads > thread_pool->max_threads) {
        fprintf(stderr, "Error: not enough threads available in the pool\n");
        return -1;
    }

    // Update the number of threads in the pool
    thread_pool->num_threads = num_threads;

    // Create new threads if necessary
    for (int i = 0; i < num_threads; i++) {
        pthread_t *thread = malloc(sizeof(pthread_t));
        if (!thread) {
