// Define the function for running a task in the thread pool
void *run_task(void *arg) {
    // Get the thread pool and the current thread index
    thread_pool_t *thread_pool = (thread_pool_t *)arg;
    int thread_index = pthread_self() - thread_pool->threads;

    // Loop until there are no more tasks to be executed
    while (1) {
