            // Get the oldest data chunk from the cache
            struct DataChunk* data_chunk = &cache[0];

            // Remove the data chunk from the cache
            for (int i = 1; i < cache_size; i++) {
                cache[i - 1] = cache[i];
            }
            cache_size--;

            // Release the mutex for the cache
            pthread_mutex_unlock(&data_chunk_mutex);

            // Process the data chunk
            process_data_chunk(data_chunk);
        } else {
            // Release the mutex for the cache
            pthread_mutex_unlock(&data_chunk_mutex);

            // Sleep for a short period of time to avoid busy waiting
            usleep(1000);
        }
    }
}

void* monitor_pipeline(void* args) {
    while (true) {
        // Get the current time
        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);

        // Calculate the total processing time and average processing time
        double total_processing_time = 0.0;
        for (int i = 0; i < num_data_sources; i++) {
            struct timespec start_time = data_sources[i].start_time;
            struct timespec end_time = data_sources[i].end_time;
            total_processing_time += (double) (end_time.tv_sec - start_time.tv_sec) + ((double) (end_time.tv_nsec - start_time.tv_nsec) / 1000000000.0);
        }
        average_processing_time = total_processing_time / num_data_sources;

        // Log the monitoring data
        printf("Total processing time: %f\n", total_processing_time);
        printf("Average processing time: %f\n", average_processing_time);
        printf("Number of data chunks processed: %d\n", num_data_chunks);
        printf("Number of failed transformations: %d\n", num_failed_transformations);

        // Sleep for a short period of time to avoid busy waiting
        usleep(1000);
    }
}

int main() {
    // Initialize the pipeline
    init_pipeline(num_data_sources, num_data_sinks);

    // Start the data source threads
    for (int i = 0; i < num_data_sources; i++) {
        pthread_create(&thread_pool[i], NULL, process_data_chunks, &data_chunks[i]);
    }

    // Start the data sink threads
    for (int i = 0; i < num_data_sinks; i++) {
        pthread_create(&thread_pool[num_data_sources + i], NULL, process_data_sinks, &data_chunks[i]);
    }

    // Start the cache thread
    pthread_create(&thread_pool[2 * num_data_sources], NULL, process_cache, NULL);

    // Start the monitoring thread
    pthread_create(&thread_pool[3 * num_data_sources], NULL, monitor_pipeline, NULL);

    // Join all the threads
    for (int i = 0; i < 4 * num_data_sources; i++) {
        pthread_join(thread_pool[i], NULL);
    }

    return 0;
}
