typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(size_t num_elements) {
    // Check if the input is valid and greater than 0
    if (num_elements <= 0) {
        return NULL;
    }

    // Calculate the size of the memory block required for the array
    size_t mem_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements;

    // Allocate the memory block using malloc()
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(mem_size);

    // Check if the allocation was successful
    if (!pdu_array) {
        return NULL;
    }

    // Initialize each element of the array with a valid RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG value
    for (size_t i = 0; i < num_elements; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = 0x1234;
        pdu_array[i].RNTI = 0x5678;
        pdu_array[i].CRCFLAG = calculate_crcflag(pdu_array[i].RX_UE_INFORMATION_TAG, pdu_array[i].RNTI);
    }

    return pdu_array;
}

// Define the function to free the allocated memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_array) {
    // Check if the input is valid and not NULL
    if (!pdu_array) {
        return;
    }

    // Free the memory block using free()
    free(pdu_array);
}

// Define the function to calculate the CRCFLAG value based on a checksum calculation derived from the concatenated binary representations of RX_UE_INFORMATION_TAG and RNTI
uint8_t calculate_crcflag(uint16_t rx_ue_information_tag, uint32_t rnti) {
    // Calculate the checksum by XORing the concatenated binary representations of RX_UE_INFORMATION_TAG and RNTI
    uint8_t crcflag = 0;
    for (size_t i = 0; i < sizeof(rx_ue_information_tag) + sizeof(rnti); i++) {
        crcflag ^= ((uint8_t*)&rx_ue_information_tag)[i] ^ ((uint8_t*)&rnti)[i];
    }

    return crcflag;
}

