        if (expected_crcflag != pdu_array[i].CRCFLAG) {
            fprintf(log_file, "Discrepancy at index %zu: expected CRCFLAG = 0x%02X, actual CRCFLAG = 0x%02X\n", i, expected_crcflag, pdu_array[i].CRCFLAG);
