// Define the function to handle multiple input formats for the binary data used in the checksum calculation, including hexadecimal and binary strings, ensuring graceful handling of both valid and invalid inputs, with appropriate error codes for invalid cases
void parse_binary_data(const char* input, size_t num_elements) {
    // Check if the input is valid and greater than 0
    if (num_elements <= 0 || !input) {
        handle_invalid_input("Invalid input");
        return;
    }

    // Initialize a temporary buffer to store the parsed binary data
    uint8_t* temp_buffer = (uint8_t*)malloc(sizeof(uint8_t) * num_elements);

    // Iterate over each character in the input string and parse it as hexadecimal or binary data
    for (size_t i = 0; i < num_elements; i++) {
        if (input[i] == 'x' || input[i] == 'X') {
            // Parse the next two characters as a hexadecimal value and store it in the temporary buffer
            temp_buffer[i] = strtol(&input[i + 1], NULL, 16);
        } else if (input[i] == 'b' || input[i] == 'B') {
            // Parse the next eight characters as a binary value and store it in the temporary buffer
            temp_buffer[i] = strtol(&input[i + 1], NULL, 2);
        } else {
            // Handle invalid inputs by returning an error code
            handle_invalid_input("Invalid input format");
            return;
        }
    }

    // Free the temporary buffer and return the parsed binary data
    free(temp_buffer);
}

