#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for server metrics
typedef struct {
    uint64_t cpu_usage;
    uint64_t memory_consumption;
    uint64_t network_io;
    uint64_t error_rate;
} SERVER_METRICS_T;

// Define the structure for log entry
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crc_indication_pdu;
    SERVER_METRICS_T server_metrics;
} LOG_ENTRY_T;

// Define the structure for log file information
typedef struct {
    char *filename;
    int fd;
    size_t filesize;
} LOG_FILE_INFO_T;

// Define the structure for thread-safe queue
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int head;
    int tail;
    int size;
    LOG_ENTRY_T *entries;
} QUEUE_T;

// Define the structure for thread-safe hash table
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int size;
    char **keys;
    LOG_ENTRY_T *values;
} HASH_TABLE_T;

// Define the structure for thread-safe counter
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int value;
} COUNTER_T;

// Define the function to generate NFAPI_CRC_INDICATION_PDU_T structures
void generateNfadLogsAndProcessMetrics(char *log_file, char *output_file) {
    // Open the log file and get its size
    int fd = open(log_file, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return;
    }
    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        return;
    }
    size_t filesize = st.st_size;

    // Allocate memory for the log entries
    LOG_ENTRY_T *log_entries = malloc(filesize);
    if (log_entries == NULL) {
        perror("malloc");
        close(fd);
        return;
    }

    // Read the log file into memory
    ssize_t nread = read(fd, log_entries, filesize);
    if (nread == -1) {
        perror("read");
        free(log_entries);
        close(fd);
        return;
    }
    close(fd);

    // Initialize the queue and hash table for storing the log entries
    QUEUE_T *queue = malloc(sizeof(QUEUE_T));
    if (queue == NULL) {
        perror("malloc");
        free(log_entries);
        return;
    }
    HASH_TABLE_T *hash_table = malloc(sizeof(HASH_TABLE_T));
    if (hash_table == NULL) {
        perror("malloc");
        free(queue);
        free(log_entries);
        return;
    }

    // Initialize the counter for tracking the number of log entries processed
    COUNTER_T *counter = malloc(sizeof(COUNTER_T));
    if (counter == NULL) {
        perror("malloc");
        free(queue);
        free(hash_table);
        free(log_entries);
        return;
    }

    // Initialize the mutexes and conditions for thread-safe access to the queue, hash table, and counter
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    pthread_mutex_init(&hash_table->mutex, NULL);
    pthread_cond_init(&hash_table->cond, NULL);
    pthread_mutex_init(&counter->mutex, NULL);
    pthread_cond_init(&counter->cond, NULL);

    // Initialize the head and tail indices for the queue
    queue->head = 0;
    queue->tail = 0;

    // Initialize the size of the hash table
    hash_table->size = 1024;

    // Allocate memory for the keys and values in the hash table
    hash_table->keys = malloc(sizeof(char *) * hash_table->size);
    if (hash_table->keys == NULL) {
        perror("malloc");
        pthread_mutex_destroy(&queue->mutex);
        pthread_cond_destroy(&queue->cond);
        pthread_mutex_destroy(&hash_table->mutex);
        pthread_cond_destroy(&hash_table->cond);
        pthread_mutex_destroy(&counter->mutex);
        pthread_cond_destroy(&counter->cond);
        free(queue);
        free(hash_table);
        free(log_entries);
        return;
    }
    hash_table->values = malloc(sizeof(LOG_ENTRY_T) * hash_table->size);
    if (hash_table->values == NULL) {
        perror("malloc");
        pthread_mutex_destroy(&queue->mutex);
        pthread_cond_destroy(&queue->cond);
        pthread_mutex_destroy(&hash_table->mutex);
        pthread_cond_destroy(&hash_table->cond);
        pthread_mutex_destroy(&counter->mutex);
        pthread_cond_destroy(&counter->cond);
        free(queue);
        free(hash_table);
        free(log_entries);
        return;
    }

    // Initialize the counter value to 0
    counter->value = 0;

    // Create a thread for processing log entries and another for updating the hash table
    pthread_t process_thread, update_thread;
    if (pthread_create(&process_thread, NULL, processLogEntries, queue) != 0) {
        perror("pthread_create");
        pthread_mutex_destroy(&queue->mutex);
        pthread_cond_destroy(&queue->cond);
        pthread_mutex_destroy(&hash_table->mutex);
        pthread_cond_destroy(&hash_table->cond);
        pthread_mutex_destroy(&counter->mutex);
        pthread_cond_destroy(&counter->cond);
        free(queue);
        free(hash_table);
        free(log_entries);
        return;
    }
    if (pthread_create(&update_thread, NULL, updateHashTable, hash_table) != 0) {
        perror("pthread_create");
        pthread_mutex_destroy(&queue->mutex);
        pthread_cond_destroy(&queue->cond);
        pthread_mutex_destroy(&hash_table->mutex);
        pthread_cond_destroy(&hash_table->cond);
        pthread_mutex_destroy(&counter->mutex);
        pthread_cond_destroy(&counter->cond);
        free(queue);
        free(hash_table);
        free(log_entries);
        return;
    }

    // Wait for the processing and updating threads to finish
    if (pthread_join(process_thread, NULL) != 0) {
        perror("pthread_join");
    }
    if (pthread_join(update_thread, NULL) != 0) {
        perror("pthread_join");
    }

    // Destroy the mutexes and conditions for thread-safe access to the queue, hash table, and counter
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
    pthread_mutex_destroy(&hash_table->mutex);
    pthread_cond_destroy(&hash_table->cond);
    pthread_mutex_destroy(&counter->mutex);
    pthread_cond_destroy(&counter->cond);

    // Free the memory for the queue, hash table, and counter
    free(queue);
    free(hash_table);
    free(counter);

    // Free the memory for the log entries
    free(log_entries);
}

// Define the function to process log entries in a separate thread
void *processLogEntries(void *arg) {
    QUEUE_T *queue = (QUEUE_T *) arg;

    // Loop until the queue is empty
    while (1) {
        // Lock the mutex for accessing the queue
        pthread_mutex_lock(&queue->mutex);

        // Check if the queue is empty
        if (queue->head == queue->tail) {
            // Unlock the mutex and return
            pthread_mutex_unlock(&queue->mutex);
            break;
        }

        // Get the next log entry from the queue
        LOG_ENTRY_T *log_entry = &queue->entries[queue->head];

        // Increment the head index of the queue
        queue->head++;

        // Unlock the mutex and process the log entry
        pthread_mutex_unlock(&queue->mutex);

        // Process the log entry
        processLogEntry(log_entry);
    }

    return NULL;
}

// Define the function to update the hash table in a separate thread
void *updateHashTable(void *arg) {
    HASH_TABLE_T *hash_table = (HASH_TABLE_T *) arg;

    // Loop until the queue is empty
    while (1) {
        // Lock the mutex for accessing the hash table
        pthread_mutex_lock(&hash_table->mutex);

        // Check if the hash table is full
        if (hash_table->size == hash_table->keys[hash_table->tail]) {
            // Unlock the mutex and return
            pthread_mutex_unlock(&hash_table->mutex);
            break;
        }

        // Get the next log entry from the queue
        LOG_ENTRY_T *log_entry = &queue->entries[queue->head];

        // Increment the tail index of the hash table
        hash_table->tail++;

        // Unlock the mutex and update the hash table
        pthread_mutex_unlock(&hash_table->mutex);

        // Update the hash table
        updateHashTable(log_entry, hash_table);
    }

    return NULL;
}

// Define the function to process a log entry
void processLogEntry(LOG_ENTRY_T *log_entry) {
    // Increment the counter for tracking the number of log entries processed
    pthread_mutex_lock(&counter->mutex);
    counter->value++;
    pthread_cond_signal(&counter->cond);
    pthread_mutex_unlock(&counter->mutex);

    // Process the log entry
    processLogEntry(log_entry);
}

// Define the function to update a hash table with a new log entry
void updateHashTable(LOG_ENTRY_T *log_entry, HASH_TABLE_T *hash_table) {
    // Compute the hash value for the log entry
    uint64_t hash = computeHash(log_entry);

    // Lock the mutex for accessing the hash table
    pthread_mutex_lock(&hash_table->mutex);

    // Check if the hash table is full
    if (hash_table->size == hash_table->keys[hash_table->tail]) {
        // Unlock the mutex and return
        pthread_mutex_unlock(&hash_table->mutex);
        return;
    }

    // Add the log entry to the hash table
    hash_table->keys[hash_table->tail] = hash;
    hash_table->values[hash_table->tail] = *log_entry;

    // Increment the tail index of the hash table
    hash_table->tail++;

    // Unlock the mutex and return
    pthread_mutex_unlock(&hash_table->mutex);
}

// Define the function to compute a hash value for a log entry
uint64_t computeHash(LOG_ENTRY_T *log_entry) {
    // Compute the hash value for the log entry
    uint64_t hash = 0;
    hash += (hash << 1) + (hash << 4) + (hash << 5) + (hash << 7) + (hash << 8) + (hash << 40);
    return hash;
}
