// Define a function to modify the extension of a given filename by appending a sequence of random digits followed by a specified file type, ensuring the new filename's total length does not exceed 255 characters
char *modifyFilename(char *filename, char *file_type) {
    // Initialize the new filename with the original filename and its extension
    char *new_filename = (char *)malloc(strlen(filename) + strlen(file_type) + 1);
    if (!new_filename) {
        printf("Failed to allocate memory for new filename\n");
        return NULL;
    }
    strcpy(new_filename, filename);
    strcat(new_filename, file_type);

    // Initialize the sequence of random digits based on the original filename's length, not exceeding 10 digits in total
    int num_digits = (int)strlen(filename) / 2;
    if (num_digits > 10) {
        num_digits = 10;
    }
    char *random_digits = (char *)malloc(num_digits + 1);
    if (!random_digits) {
        printf("Failed to allocate memory for random digits\n");
        free(new_filename);
        return NULL;
    }
    srand((unsigned int)time(NULL));
    for (int i = 0; i < num_digits; i++) {
        random_digits[i] = rand() % 10 + '0';
    }
    random_digits[num_digits] = '\0';

    // Append the sequence of random digits to the new filename, ensuring its total length does not exceed 255 characters
    int len = strlen(new_filename);
    if (len + num_digits > 255) {
        printf("New filename is too long\n");
        free(random_digits);
        free(new_filename);
        return NULL;
    }
    for (int i = len - 1; i >= 0; i--) {
        if (i % 2 == 0) {
            new_filename[len + num_digits - i] = random_digits[i / 2];
        } else {
            new_filename[len + num_digits - i] = filename[i];
        }
    }

    // Free the memory allocated for the sequence of random digits and return the modified filename
    free(random_digits);
    return new_filename;
}

