    FILE* fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filepath);
        return;
    }

    // Initialize the metrics and header structures
    struct Metrics metrics;
    struct BlockHeader* block_header = malloc(sizeof(struct BlockHeader));
    if (block_header == NULL) {
        printf("Error: unable to allocate memory for block header\n");
