        return;
    }

    // Read the file line by line and process each line
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Parse the line into a list of integers
        int* numbers = parse_numbers(line);
        if (numbers == NULL) {
            printf("Error: unable to parse line %s\n", line);
            free(line);
            fclose(fp);
            return;
        }

        // Find the largest integer in the list and print it
        int largest = find_largest(numbers, read);
        printf("Largest integer: %d\n", largest);

        // Free the memory allocated for the list of integers
        free(numbers);
    }

    // Close the file
    fclose(fp);
}

// Function to parse a line of space-separated integers into a list of integers
int* parse_numbers(char* line) {
    int* numbers = malloc(sizeof(int) * read);
    if (numbers == NULL) {
        printf("Error: unable to allocate memory for number list\n");
        return NULL;
    }

    // Parse the line into a list of integers
    char* token = strtok(line, " ");
    int i = 0;
    while (token != NULL) {
        numbers[i++] = atoi(token);
        token = strtok(NULL, " ");
    }

    return numbers;
}

// Function to find the largest integer in a list of integers
int find_largest(int* numbers, int size) {
    int largest = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }
    return largest;
}
