// Define the hash function for computing the checksum of a file
uint8_t *compute_hash(const char *filename) {
    // Open the file and compute its size
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return NULL;
    }
    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    // Allocate memory for the hash value and read the file into it
    uint8_t *hash = (uint8_t *)malloc(size);
    if (fread(hash, 1, size, file) != size) {
        printf("Error: unable to read file %s\n", filename);
        fclose(file);
        return NULL;
    }
    fclose(file);

    // Compute the SHA-256 hash of the file content
    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    if (EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL) != 1) {
        printf("Error: unable to initialize SHA-256 hash\n");
        free(hash);
        return NULL;
    }
    if (EVP_DigestUpdate(mdctx, hash, size) != 1) {
        printf("Error: unable to update SHA-256 hash\n");
        EVP_MD_CTX_free(mdctx);
        free(hash);
        return NULL;
    }
    uint8_t *digest = (uint8_t *)malloc(EVP_MAX_MD_SIZE);
    unsigned int digest_len = 0;
    if (EVP_DigestFinal_ex(mdctx, digest, &digest_len) != 1) {
        printf("Error: unable to finalize SHA-256 hash\n");
        EVP_MD_CTX_free(mdctx);
        free(hash);
        return NULL;
    }
    EVP_MD_CTX_free(mdctx);
    free(hash);

    // Return the computed hash value
    return digest;
}

