    int num_input_files;
    InputFile *input_files;
    int case_sensitive;
    char *output_file;
    int limit;
    int verbose;
    int multi_threading;
    int custom_format;
} ProgramState;

// Define a function to parse command-line arguments and initialize the program's state
void init_program(int argc, char **argv) {
    // Initialize the program's state
    ProgramState *state = malloc(sizeof(ProgramState));
    state->num_input_files = 0;
    state->input_files = NULL;
    state->case_sensitive = 0;
    state->output_file = NULL;
    state->limit = -1;
    state->verbose = 0;
    state->multi_threading = 0;
    state->custom_format = 0;

    // Parse command-line arguments
    int c;
    while ((c = getopt(argc, argv, "hco:l:vt:f:")) != -1) {
        switch (c) {
            case OPTION_HELP:
                printf("Usage: %s [options] <input files>\n", argv[0]);
                printf("Options:\n");
                printf("  -h, --help\t\tDisplay brief usage information.\n");
                printf("  -c, --case-sensitive\tProcess input files case-sensitively.\n");
                printf("  -o <output_file>\tRedirect output to a specified file.\n");
                printf("  -l <limit>\t\tLimit the number of lines processed to a specified value.\n");
                printf("  -v, --verbose\t\tShow progress indicators and line numbers.\n");
                printf("  -t, --multi-threading\tEnable multi-threading for parallel processing of files.\n");
                printf("  -f <format>\t\tSpecify a custom file format for parsing.\n");
                exit(0);
            case OPTION_CASE_SENSITIVE:
                state->case_sensitive = 1;
                break;
            case OPTION_OUTPUT_FILE:
                state->output_file = optarg;
                break;
            case OPTION_LIMIT:
                state->limit = atoi(optarg);
                break;
            case OPTION_VERBOSE:
                state->verbose = 1;
                break;
            case OPTION_MULTI_THREADING:
                state->multi_threading = 1;
                break;
            case OPTION_CUSTOM_FORMAT:
                state->custom_format = atoi(optarg);
                break;
        }
    }

    // Check for invalid command-line arguments
    if (state->multi_threading && !state->custom_format) {
        fprintf(stderr, "Error: Custom file format must be specified when using multi-threading.\n");
        exit(1);
    }

    // Initialize the input files array
    state->input_files = malloc(sizeof(InputFile) * argc - optind);

    // Add each input file to the array
    for (int i = optind; i < argc; i++) {
        InputFile *file = &state->input_files[state->num_input_files++];
        file->filename = argv[i];
        file->format = state->custom_format ? state->custom_format : FORMAT_TEXT;
    }
}

// Define a function to process each input file
