    // Log start time
    time_t start = time(NULL);
    printf("Started processing at %s", ctime(&start));

    // Log end time
    time_t end = time(NULL);
    printf("Finished processing at %s", ctime(&end));
}

int main(int argc, char **argv) {
    init_program(argc, argv);

    // Process each input file
    for (int i = 0; i < state->num_input_files; i++) {
        InputFile *file = &state->input_files[i];
        if (state->multi_threading) {
            process_file_parallel(file);
        } else {
            process_file(file);
        }
    }

    // Log processing details
    log_processing_details();

    return 0;
}
```
This code block implements the given programming task using C programming language. It includes a function to parse command-line arguments and initialize the program's state, a function to process each input file, and a function to log processing details. The program supports several options for controlling its behavior, including case-sensitive processing, output redirection, limiting the number of lines processed, verbose mode, multi-threading for parallel processing, and custom file formats. It also includes robust error handling for invalid file paths and formats, memory optimization for large files, and support for filenames containing spaces or special characters. The program can be easily extended to support additional file formats or processing options by modifying the `InputFile` structure and the `process_file` function.']

