    log_entry_t *log_entry = malloc(sizeof(log_entry_t));
    log_entry->server_name = server_name;
    log_entry->rnti = rnti;
    log_entry->crc_flag = rand() % 2;

    // Add the log entry to a buffer for processing and generation of NF-API log files
    log_buffer_t *log_buffer = malloc(sizeof(log_buffer_t));
    log_buffer->entries[log_buffer->num_entries++] = log_entry;

    // Process the log buffer asynchronously in a separate thread to prevent blocking
    pthread_t thread;
    int ret = pthread_create(&thread, NULL, processLogBuffer, (void *)log_buffer);
    if (ret != 0) {
        perror("Error creating processing thread");
        return;
    }
}

void *processLogBuffer(void *arg) {
    log_buffer_t *log_buffer = arg;

    // Generate NF-API log files for each log entry in the buffer
    for (int i = 0; i < log_buffer->num_entries; i++) {
        log_entry_t *log_entry = log_buffer->entries[i];
        char filename[MAX_FILENAME_LEN];
        snprintf(filename, MAX_FILENAME_LEN, "NF-API-%s-%s.log", log_entry->server_name, log_entry->rnti);
        FILE *file = fopen(filename, "w");
        if (!file) {
            perror("Error opening NF-API log file for writing");
            continue;
        }
        fprintf(file, "%s\n", json_object_to_json_string_ext(log_entry->json_object, JSON_C_TO_STRING_PRETTY));
        fclose(file);
    }

    // Clean up the log buffer and free memory
    for (int i = 0; i < log_buffer->num_entries; i++) {
        log_entry_t *log_entry = log_buffer->entries[i];
        json_object_put(log_entry->json_object);
        free(log_entry);
    }
    free(log_buffer);
}
