    struct stat buf;
    return stat(filename, &buf) == 0 && S_ISREG(buf.st_mode);
}

// Define a function to read the contents of a file into a buffer
static void *read_file(const char *filename, size_t *size) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return NULL;
    }
    struct stat buf;
    if (fstat(fd, &buf) != 0) {
        perror("fstat");
        close(fd);
        return NULL;
    }
    *size = buf.st_size;
    void *buffer = malloc(*size);
    if (buffer == NULL) {
        perror("malloc");
        close(fd);
        return NULL;
    }
    ssize_t nread = read(fd, buffer, *size);
    if (nread < 0) {
        perror("read");
        free(buffer);
        close(fd);
        return NULL;
    }
    close(fd);
    return buffer;
}

// Define a function to process a file using a given hash function or cipher
static void process_file(const char *filename, const HashCipherInfo *hash_cipher) {
    size_t size;
    void *buffer = read_file(filename, &size);
    if (buffer == NULL) {
        return;
    }
    // Process the file using the given hash function or cipher
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    EVP_DigestInit(ctx, hash_cipher->func());
    EVP_DigestUpdate(ctx, buffer, size);
    unsigned char digest[EVP_MAX_MD_SIZE];
    int digest_len = EVP_DigestFinal(ctx, digest, NULL);
    printf("%s: %s\n", filename, hash_cipher->name);
    for (int i = 0; i < digest_len; ++i) {
        printf("%02x", digest[i]);
    }
    EVP_MD_CTX_free(ctx);
    free(buffer);
}

// Define a function to process multiple files using a given hash function or cipher
static void process_files(const char *hash_cipher, int argc, char **argv) {
    for (int i = 0; i < argc; ++i) {
        if (!file_exists(argv[i])) {
            fprintf(stderr, "File %s does not exist or is not readable\n", argv[i]);
            continue;
        }
        process_file(argv[i], hash_cipher);
    }
}

// Define a function to handle command-line arguments and start processing files
