    int socket;
    bool connected;
} MQTT_CONNECTION_STATE_T;

// Define the maximum size of the linked list
#define MAX_LIST_SIZE 100

// Define the function to dynamically allocate memory for an array of MQTT messages
MQTT_MESSAGE_T* allocate_messages(int num_messages) {
    // Allocate memory for the array of MQTT messages
    MQTT_MESSAGE_T* messages = (MQTT_MESSAGE_T*)malloc(num_messages * sizeof(MQTT_MESSAGE_T));
    if (!messages) {
        printf("Error: Failed to allocate memory for the array of MQTT messages\n");
        return NULL;
    }

    // Initialize each message in the array with a valid topic and payload
    for (int i = 0; i < num_messages; i++) {
        messages[i].topic = "default";
        messages[i].payload = "default";
    }

    return messages;
}

// Define the function to dynamically allocate memory for a linked list of MQTT connection states
MQTT_CONNECTION_STATE_T* allocate_connection_states(int num_connections) {
    // Allocate memory for the linked list of MQTT connection states
    MQTT_CONNECTION_STATE_T* connection_states = (MQTT_CONNECTION_STATE_T*)malloc(num_connections * sizeof(MQTT_CONNECTION_STATE_T));
    if (!connection_states) {
        printf("Error: Failed to allocate memory for the linked list of MQTT connection states\n");
        return NULL;
    }

    // Initialize each connection state in the linked list with a valid socket and connected status
    for (int i = 0; i < num_connections; i++) {
        connection_states[i].socket = -1;
        connection_states[i].connected = false;
