// Define the function to handle an MQTT message delivery with retry mechanism
void deliver_mqtt_message_with_retry(MQTT_MESSAGE_T* message) {
    // Check if the message is valid
    if (!message || !message->topic || !message->payload) {
        printf("Error: The MQTT message is invalid\n");
        return;
    }

    // Deliver the message to all connected clients with retry mechanism
    for (int i = 0; i < num_connections; i++) {
        handle_mqtt_connection(&connection_states[i]);
        if (!connection_state->connected) {
            // Retry the delivery after a jittered exponential backoff strategy
            int retry_count = 0;
            while (retry_count < MAX_RETRY_COUNT && !connection_state->connected) {
                sleep(pow(2, retry_count));
                handle_mqtt_connection(&connection_states[i]);
                retry_count++;
            }
        }
    }
}

// Define the function to handle an MQTT message delivery with deduplication
void deliver_mqtt_message_with_dedup(MQTT_MESSAGE_T* message) {
    // Check if the message is valid
    if (!message || !message->topic || !message->payload) {
        printf("Error: The MQTT message is invalid\n");
        return;
    }

    // Deliver the message to all connected clients with deduplication
    for (int i = 0; i < num_connections; i++) {
        handle_mqtt_connection(&connection_states[i]);
        if (!connection_state->connected) {
            // Deduplicate the message based on its topic and payload
            if (message->topic == connection_state->topic && strcmp(message->payload, connection_state->payload) == 0) {
                continue;
            }
        }
    }
}

