#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <stdbool.h>

// Define constants for command line options
#define OPTION_MANPAGE "--manpage"
#define OPTION_CASE_SENSITIVE "--cs"
#define OPTION_OUTPUT_FILE "-o"
#define OPTION_LIMIT "-l"
#define OPTION_VERBOSE "-v"
#define OPTION_PATTERN "-p"

// Define constants for regular expression options
#define REGEX_OPTIONS "gim"

// Define a structure to store file information
struct file_info {
    char *file_path;
    int line_count;
};

// Define a structure to store processing details
struct processing_details {
    time_t start_time;
    time_t end_time;
    long total_lines;
    long processed_lines;
    bool verbose;
    bool case_sensitive;
    char *output_file;
    int limit;
    regex_t pattern;
};

// Define a function to validate file paths and handle potential errors
void validate_file_path(char *file_path) {
    struct stat file_stat;
    if (stat(file_path, &file_stat) == 0 && S_ISREG(file_stat.st_mode)) {
        return;
    } else {
        fprintf(stderr, "Error: File %s does not exist or is inaccessible\n", file_path);
        exit(EXIT_FAILURE);
    }
}

// Define a function to count the number of lines in a file
void count_lines(struct file_info *file_info) {
    FILE *file = fopen(file_info->file_path, "r");
    if (file == NULL) {
        fprintf(stderr, "Error: Could not open file %s\n", file_info->file_path);
        exit(EXIT_FAILURE);
    }
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        if (file_info->case_sensitive) {
            if (regexec(&file_info->pattern, line, 0, NULL, 0) == 0) {
                file_info->line_count++;
            }
        } else {
            if (regexec(&file_info->pattern, line, 0, NULL, REG_ICASE) == 0) {
                file_info->line_count++;
            }
        }
    }
    fclose(file);
}

// Define a function to process files in parallel using multi-threading
void process_files(struct processing_details *processing_details, struct file_info **file_infos) {
    int num_threads = 4; // adjust this value based on the number of CPU cores available
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        struct file_info *file_info = file_infos[i];
        if (pthread_create(&threads[i], NULL, count_lines, file_info) != 0) {
            fprintf(stderr, "Error: Could not create thread for file %s\n", file_info->file_path);
            exit(EXIT_FAILURE);
        }
    }
    for (int i = 0; i < num_threads; i++) {
        struct file_info *file_info = file_infos[i];
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Error: Could not join thread for file %s\n", file_info->file_path);
            exit(EXIT_FAILURE);
        }
    }
}

// Define a function to print usage information
void print_usage() {
    printf("Usage: ./program [options] <input_file>\n");
    printf("\nOptions:\n");
    printf("  --manpage\tDisplay detailed usage information.\n");
    printf("  -cs\tEnable case-sensitive line counting (default is case-insensitive).\n");
    printf("  -o output_file\tRedirect output to a specified file instead of stdout.\n");
    printf("  -l limit\tLimit the number of lines processed to the specified limit.\n");
    printf("  -v\tVerbose mode, which includes line numbers and matched patterns in the output, along with a progress indicator showing the percentage of lines processed.\n");
    printf("  -p pattern\tDefine a regular expression pattern used to filter lines.\n");
}

// Define a function to print detailed usage information
void print_detailed_usage() {
    printf("Detailed Usage Information:\n");
    printf("The program takes the following options:\n");
    printf("  --manpage\tDisplay detailed usage information.\n");
    printf("  -cs\tEnable case-sensitive line counting (default is case-insensitive).\n");
    printf("  -o output_file\tRedirect output to a specified file instead of stdout.\n");
    printf("  -l limit\tLimit the number of lines processed to the specified limit.\n");
    printf("  -v\tVerbose mode, which includes line numbers and matched patterns in the output, along with a progress indicator showing the percentage of lines processed.\n");
    printf("  -p pattern\tDefine a regular expression pattern used to filter lines.\n");
}

// Define a function to handle command line arguments
void handle_command_line_arguments(int argc, char *argv[], struct processing_details *processing_details) {
    int i;
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], OPTION_MANPAGE) == 0) {
            print_detailed_usage();
            exit(EXIT_SUCCESS);
