using namespace std;

// Configuration file path
const string configFilePath = "config.txt";

// Keywords to extract from logs
const vector<string> keywords = {"error", "warn"};

// Thresholds for metrics
const map<string, int> thresholds = {{"total_lines", 0}, {"avg_line_length", 0}, {"unique_ips", 0}};

// Progress indicator
mutex progressMutex;
condition_variable progressCondVar;
int progressCount = 0;
int totalFiles = 0;

// Logging system
mutex logMutex;
ofstream logFile("log.txt");

void processFile(const string& filePath) {
    // Open the file and read its contents
    ifstream file(filePath);
    string line;
    vector<string> lines;
    while (getline(file, line)) {
        lines.push_back(line);
    }

    // Calculate metrics for this file
    int totalLines = 0;
    int avgLineLength = 0;
    set<string> uniqueIps;
    for (const string& line : lines) {
        ++totalLines;
        avgLineLength += line.length();
        for (const string& keyword : keywords) {
            if (line.find(keyword) != string::npos) {
                ++thresholds["error"];
            }
        }
        uniqueIps.insert(line.substr(line.find(' ')));
    }

    // Update metrics
    thresholds["total_lines"] += totalLines;
    thresholds["avg_line_length"] += avgLineLength / totalLines;
    thresholds["unique_ips"] += uniqueIps.size();

    // Print progress indicator
    {
        lock_guard<mutex> lock(progressMutex);
        ++progressCount;
        progressCondVar.notify_all();
    }
}

void processDirectory(const string& dirPath) {
    // Get the list of files in the directory
    vector<string> filePaths;
    for (const auto& entry : filesystem::directory_iterator(dirPath)) {
        if (filesystem::is_regular_file(entry.status())) {
            filePaths.push_back(entry.path().string());
        }
    }

    // Process each file in parallel
    vector<thread> threads;
    for (const string& filePath : filePaths) {
        threads.emplace_back([filePath]() { processFile(filePath); });
    }

    // Wait for all threads to finish
    for (auto& thread : threads) {
        thread.join();
    }
}

int main(int argc, char** argv) {
    // Check if a directory was specified
    if (argc < 2) {
        cout << "Usage: " << argv[0] << " <directory>" << endl;
        return 1;
    }

    // Read the configuration file
    ifstream configFile(configFilePath);
    string line;
    while (getline(configFile, line)) {
        istringstream iss(line);
        string keyword;
        int threshold;
        iss >> keyword >> threshold;
        thresholds[keyword] = threshold;
    }

    // Process the directory
    processDirectory(argv[1]);

    // Print metrics
    cout << "Total lines: " << thresholds["total_lines"] << endl;
    cout << "Average line length: " << thresholds["avg_line_length"] << endl;
    cout << "Unique IP addresses: " << thresholds["unique_ips"] << endl;

    // Log processing details
    {
        lock_guard<mutex> lock(logMutex);
        logFile << "Start time: " << chrono::system_clock::now() << endl;
        logFile << "End time: " << chrono::system_clock::now() << endl;
        logFile.close();
    }

    return 0;
}
