#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>
#include <time.h>

// Define data structure for sensor data
typedef struct {
    long timestamp;
    int source_id;
    float temperature;
    float humidity;
    float pressure;
} SensorData;

// Define data structure for priority queue
typedef struct {
    SensorData *data;
    int size;
} PriorityQueue;

// Define data structure for sliding window
typedef struct {
    SensorData **data;
    int size;
    int capacity;
} SlidingWindow;

// Define data structure for logging
typedef struct {
    long timestamp;
    char *thread_name;
    char *operation;
} LogEntry;

// Define data structure for external data analytics module
typedef struct {
    SensorData *data;
    int size;
} AnalyticsData;

// Define function to manage queue of incoming sensor data streams
void manage_queue(PriorityQueue *queue, SlidingWindow *window, AnalyticsData *analytics) {
    // Initialize variables
    long current_time = time(NULL);
    int i, j;
    SensorData *data;
    LogEntry log_entry;

    // Check if queue is empty
    if (queue->size == 0) {
        return;
    }

    // Update priority threshold based on recent averages of environmental stability metrics
    float temperature_avg = get_average(window, "temperature");
    float humidity_avg = get_average(window, "humidity");
    float pressure_avg = get_average(window, "pressure");
    float stability_threshold = (temperature_avg + humidity_avg + pressure_avg) / 3;

    // Iterate through queue and prioritize data streams based on priority threshold
    for (i = 0; i < queue->size; i++) {
        data = &queue->data[i];
        if (data->temperature > stability_threshold || data->humidity > stability_threshold || data->pressure > stability_threshold) {
            // Add data to sliding window and analytics module
            add_to_window(window, data);
            add_to_analytics(analytics, data);
        } else {
            // Remove data from queue and log operation
            remove_from_queue(queue, i);
            log_entry.timestamp = current_time;
            log_entry.thread_name = "manage_queue";
            log_entry.operation = "remove_from_queue";
            add_to_log(log_entry);
        }
    }
}

// Define function to add data to sliding window
void add_to_window(SlidingWindow *window, SensorData *data) {
    // Check if sliding window is full
    if (window->size == window->capacity) {
        // Remove oldest entry from sliding window and log operation
        remove_from_sliding_window(window, 0);
        LogEntry log_entry;
        log_entry.timestamp = time(NULL);
        log_entry.thread_name = "add_to_window";
        log_entry.operation = "remove_from_sliding_window";
        add_to_log(log_entry);
    }

    // Add data to sliding window and update size
    window->data[window->size] = data;
    window->size++;
}

// Define function to remove data from sliding window
void remove_from_sliding_window(SlidingWindow *window, int index) {
    // Check if index is valid
    if (index < 0 || index >= window->size) {
        return;
    }

    // Shift elements to the left and update size
    for (int i = index; i < window->size - 1; i++) {
        window->data[i] = window->data[i + 1];
    }
    window->size--;
}

// Define function to add data to analytics module
void add_to_analytics(AnalyticsData *analytics, SensorData *data) {
    // Check if analytics module is full
    if (analytics->size == analytics->capacity) {
        // Remove oldest entry from analytics module and log operation
        remove_from_analytics(analytics, 0);
        LogEntry log_entry;
        log_entry.timestamp = time(NULL);
        log_entry.thread_name = "add_to_analytics";
        log_entry.operation = "remove_from_analytics";
        add_to_log(log_entry);
    }

    // Add data to analytics module and update size
    analytics->data[analytics->size] = data;
    analytics->size++;
}

// Define function to remove data from analytics module
void remove_from_analytics(AnalyticsData *analytics, int index) {
    // Check if index is valid
    if (index < 0 || index >= analytics->size) {
        return;
    }

    // Shift elements to the left and update size
    for (int i = index; i < analytics->size - 1; i++) {
        analytics->data[i] = analytics->data[i + 1];
    }
    analytics->size--;
}

// Define function to get average of environmental stability metrics in sliding window
float get_average(SlidingWindow *window, char *metric) {
    // Check if sliding window is empty
    if (window->size == 0) {
        return 0.0;
    }

    // Initialize variables
    float sum = 0.0;
    int i;

    // Iterate through sliding window and calculate average
    for (i = 0; i < window->size; i++) {
        SensorData *data = &window->data[i];
        if (!strcmp(metric, "temperature")) {
            sum += data->temperature;
        } else if (!strcmp(metric, "humidity")) {
            sum += data->humidity;
        } else if (!strcmp(metric, "pressure")) {
            sum += data->pressure;
        }
    }

    // Return average of environmental stability metrics
    return sum / window->size;
}

// Define function to add log entry
void add_to_log(LogEntry log_entry) {
    // Check if log is full
    if (log_entry.timestamp == 0) {
        return;
    }

    // Add log entry and update size
    log_entry.size++;
}

// Define function to remove log entry
void remove_from_log(LogEntry log_entry, int index) {
    // Check if index is valid
    if (index < 0 || index >= log_entry.size) {
        return;
    }

    // Shift elements to the left and update size
    for (int i = index; i < log_entry.size - 1; i++) {
        log_entry.data[i] = log_entry.data[i + 1];
    }
    log_entry.size--;
}
