#define CRC_INDICATION_REL8_TAG "crc_indication_rel8"
#define CRCFLAG_MIN 0
#define CRCFLAG_MAX 1

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char *rx_ue_information;
    int rnti;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void processServerMetricsAndGenerateNFLogFiles(char **log_files, int num_logs) {
    // Initialize variables
    int i, j;
    json_object *json_obj = NULL;
    json_object *rx_ue_information = NULL;
    json_object *crc_indication_rel8 = NULL;
    char *rnti_str = NULL;
    int rnti;
    int crcflag;
