    int num_failed = 0;
    char *log_file_name = NULL;
    char *nfapi_log_file_name = NULL;
    time_t start_time, end_time;

    // Initialize the list of NFAPI PDUs
    nfapi_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_STRUCTS);
    if (!nfapi_pdu) {
        printf("Failed to allocate memory for NFAPI PDUs\n");
        return;
    }

    // Initialize the list of log files
    log_file_name = (char **)malloc(sizeof(char *) * num_logs);
    if (!log_file_name) {
        printf("Failed to allocate memory for log file names\n");
        return;
    }

    // Initialize the list of NFAPI log files
    nfapi_log_file_name = (char **)malloc(sizeof(char *) * num_logs);
    if (!nfapi_log_file_name) {
        printf("Failed to allocate memory for NFAPI log file names\n");
        return;
    }

    // Initialize the random seed for generating CRCFLAG values
    srand(time(NULL));

    // Loop through each log file and process its contents
    for (i = 0; i < num_logs; i++) {
        // Open the log file
        FILE *log_file = fopen(log_files[i], "r");
        if (!log_file) {
            printf("Failed to open log file %s\n", log_files[i]);
            continue;
