            }

            // Extract the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG values
            rx_ue_information = json_object_get(json_obj, RX_UE_INFORMATION_TAG);
            if (!rx_ue_information) {
                printf("Failed to extract %s from JSON object\n", RX_UE_INFORMATION_TAG);
                continue;
            }
            crc_indication_rel8 = json_object_get(json_obj, CRC_INDICATION_REL8_TAG);
            if (!crc_indication_rel8) {
                printf("Failed to extract %s from JSON object\n", CRC_INDICATION_REL8_TAG);
                continue;
            }

            // Extract the RNTI value from the RX_UE_INFORMATION_TAG
            rnti_str = json_object_get_string(rx_ue_information, "rnti");
            if (!rnti_str) {
                printf("Failed to extract RNTI from %s\n", RX_UE_INFORMATION_TAG);
                continue;
            }
            rnti = atoi(rnti_str);

            // Generate a CRCFLAG value randomly
            crcflag = rand() % (CRCFLAG_MAX - CRCFLAG_MIN + 1) + CRCFLAG_MIN;

            // Create an NFAPI PDU with the extracted values
            nfapi_pdu[num_structs].rx_ue_information = rx_ue_information;
            nfapi_pdu[num_structs].rnti = rnti;
            nfapi_pdu[num_structs].crcflag = crcflag;

            // Increment the number of structures and allocate memory for the next one
            num_structs++;
            if (num_structs == MAX_STRUCTS) {
                NFAPI_CRC_INDICATION_PDU_T *new_nfapi_pdu = (NFAPI_CRC_INDICATION_PDU_T *)realloc(nfapi_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structs * 2);
                if (!new_nfapi_pdu) {
                    printf("Failed to allocate memory for NFAPI PDUs\n");
                    return;
                }
                nfapi_pdu = new_nfapi_pdu;
            }
        }

        // Close the log file
        fclose(log_file);
    }

    // Generate NF-API log files for each RNTI value
    for (i = 0; i < num_structs; i++) {
        // Create a new NFAPI log file name based on the original log file name and the RNTI value
        asprintf(&nfapi_log_file_name[i], "%s-%d.json", log_files[0], nfapi_pdu[i].rnti);

        // Open the NFAPI log file for writing
        FILE *nfapi_log_file = fopen(nfapi_log_file_name[i], "w");
        if (!nfapi_log_file) {
            printf("Failed to open NFAPI log file %s\n", nfapi_log_file_name[i]);
            continue;
        }

        // Write the NF-API PDU to the NFAPI log file
        json_object *nfapi_pdu_json = json_object_new_object();
        json_object_object_add(nfapi_pdu_json, "rx_ue_information", nfapi_pdu[i].rx_ue_information);
        json_object_object_add(nfapi_pdu_json, "crc_indication_rel8", json_object_new_int(nfapi_pdu[i].crcflag));
        char *nfapi_pdu_str = json_object_to_json_string(nfapi_pdu_json);
        fprintf(nfapi_log_file, "%s\n", nfapi_pdu_str);
        free(nfapi_pdu_str);
        json_object_put(nfapi_pdu_json);

        // Close the NFAPI log file
        fclose(nfapi_log_file);
    }

    // Clean up memory
    free(log_file_name);
    free(nfapi_log_file_name);
    free(nfapi_pdu);
}
