    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Read the number of integers in the file
    int num_integers = 0;
    if (fscanf(fp, "%d", &num_integers) != 1) {
        perror("Error reading number of integers");
        fclose(fp);
        return -1;
    }

    // Allocate memory for the integers
    *integers = (int*)malloc(sizeof(int) * num_integers);
    if (*integers == NULL) {
        perror("Error allocating memory");
        fclose(fp);
        return -1;
    }

    // Read the integers from the file
    for (size_t i = 0; i < num_integers; i++) {
        if (fscanf(fp, "%d", &(*integers)[i]) != 1) {
            perror("Error reading integer");
            fclose(fp);
            free(*integers);
            return -1;
        }
    }

    // Close the file
    fclose(fp);

    // Set the number of integers read
    *count = num_integers;

    return 0;
