}

// Define a callback function for cURL to write data to memory
size_t write_memory_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    char *mem = malloc(realsize + 1);
    if (mem == NULL) {
        printf("Error allocating memory for cURL response\n");
        return 0;
    }
    memcpy(mem, contents, realsize);
    mem[realsize] = 0;
    *((char **)userp) = mem;
    return realsize;
}
