// Define the function to dynamically allocate memory for an array of MQTT messages
MQTT_MESSAGE_T* allocate_messages(int num_messages) {
    // Check if the input is valid
    if (num_messages <= 0) {
        return NULL;
    }

    // Allocate memory for the array of MQTT messages
    MQTT_MESSAGE_T* messages = malloc(sizeof(MQTT_MESSAGE_T) * num_messages);
    if (messages == NULL) {
        return NULL;
    }

    // Initialize each message in the array
    for (int i = 0; i < num_messages; i++) {
        messages[i].topic = NULL;
        messages[i].payload = NULL;
    }

    return messages;
}

// Define the function to dynamically allocate memory for a linked list of MQTT connection states
MQTT_CONNECTION_STATE_T* allocate_connection_states(int max_size) {
    // Check if the input is valid
    if (max_size <= 0) {
        return NULL;
    }

    // Allocate memory for the linked list of MQTT connection states
    MQTT_CONNECTION_STATE_T* head = malloc(sizeof(MQTT_CONNECTION_STATE_T));
    if (head == NULL) {
        return NULL;
    }

    // Initialize the head node
    head->socket = -1;
    head->connected = false;
    head->next = NULL;

    return head;
}

// Define the function to add a new MQTT connection state to the linked list
void add_connection_state(MQTT_CONNECTION_STATE_T* head, int socket) {
    // Check if the input is valid
    if (head == NULL || socket < 0) {
        return;
    }

    // Find the last node in the linked list
    MQTT_CONNECTION_STATE_T* current = head;
    while (current->next != NULL) {
        current = current->next;
    }

    // Create a new node and add it to the end of the linked list
    MQTT_CONNECTION_STATE_T* new_node = malloc(sizeof(MQTT_CONNECTION_STATE_T));
    if (new_node == NULL) {
        return;
    }
    new_node->socket = socket;
    new_node->connected = false;
    new_node->next = NULL;
    current->next = new_node;
}

// Define the function to remove a MQTT connection state from the linked list
void remove_connection_state(MQTT_CONNECTION_STATE_T* head, int socket) {
    // Check if the input is valid
    if (head == NULL || socket < 0) {
        return;
    }

    // Find the node to be removed
    MQTT_CONNECTION_STATE_T* current = head;
    while (current != NULL && current->socket != socket) {
        current = current->next;
    }

    // Remove the node from the linked list
    if (current == NULL) {
        return;
    }
    MQTT_CONNECTION_STATE_T* previous = head;
    while (previous->next != current && previous->next != NULL) {
        previous = previous->next;
    }
    previous->next = current->next;
}

// Define the function to check if a MQTT connection state is in the linked list
bool contains_connection_state(MQTT_CONNECTION_STATE_T* head, int socket) {
    // Check if the input is valid
    if (head == NULL || socket < 0) {
        return false;
    }

    // Find the node in the linked list
    MQTT_CONNECTION_STATE_T* current = head;
    while (current != NULL && current->socket != socket) {
        current = current->next;
    }

    // Return true if the node is found, false otherwise
    return current != NULL;
}

