#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the structure for an MQTT message
typedef struct {
    char* messaging_header;
    char* payload;
} MQTT_MESSAGE_T;

// Define the structure for an MQTT connection state
typedef struct {
    int socket;
    char* hostname;
    char* port;
} MQTT_CONNECTION_STATE_T;

// Define the maximum size of the circular buffer for logging
#define LOGGING_BUFFER_SIZE 1024

// Define the structure for a log message
typedef struct {
    char* timestamp;
    int level;
    char* message;
} LOG_MESSAGE_T;

// Function to dynamically allocate memory for an array of MQTT messages
MQTT_MESSAGE_T* allocate_messages(int num_messages) {
    // Check if the input is valid
    if (num_messages <= 0) {
        return NULL;
    }

    // Allocate memory for the array of MQTT messages
    MQTT_MESSAGE_T* messages = malloc(sizeof(MQTT_MESSAGE_T) * num_messages);
    if (messages == NULL) {
        return NULL;
    }

    // Initialize each message structure with a valid messaging header and payload
    for (int i = 0; i < num_messages; i++) {
        messages[i].messaging_header = malloc(sizeof(char) * 1024);
        if (messages[i].messaging_header == NULL) {
            return NULL;
        }
        messages[i].payload = malloc(sizeof(char) * 1024);
        if (messages[i].payload == NULL) {
            return NULL;
        }
    }

    // Return the allocated array of MQTT messages
    return messages;
}

// Function to dynamically allocate memory for a linked list of MQTT connection states
MQTT_CONNECTION_STATE_T* allocate_connection_states(int max_size) {
    // Check if the input is valid
    if (max_size <= 0) {
        return NULL;
    }

    // Allocate memory for the linked list of MQTT connection states
    MQTT_CONNECTION_STATE_T* head = malloc(sizeof(MQTT_CONNECTION_STATE_T));
    if (head == NULL) {
        return NULL;
    }

    // Initialize the head node with a valid socket and hostname
    head->socket = 0;
    head->hostname = malloc(sizeof(char) * 1024);
    if (head->hostname == NULL) {
        return NULL;
    }
    head->port = malloc(sizeof(char) * 1024);
    if (head->port == NULL) {
        return NULL;
    }

    // Return the allocated linked list of MQTT connection states
    return head;
}

// Function to dynamically allocate memory for a circular buffer of log messages
LOG_MESSAGE_T* allocate_log_buffer(int size) {
    // Check if the input is valid
    if (size <= 0) {
        return NULL;
    }

    // Allocate memory for the circular buffer of log messages
    LOG_MESSAGE_T* buffer = malloc(sizeof(LOG_MESSAGE_T) * size);
    if (buffer == NULL) {
        return NULL;
    }

    // Initialize each log message structure with a valid timestamp and message
    for (int i = 0; i < size; i++) {
        buffer[i].timestamp = malloc(sizeof(char) * 1024);
        if (buffer[i].timestamp == NULL) {
            return NULL;
        }
        buffer[i].level = 0;
        buffer[i].message = malloc(sizeof(char) * 1024);
        if (buffer[i].message == NULL) {
            return NULL;
        }
    }

    // Return the allocated circular buffer of log messages
    return buffer;
}

// Function to free memory for an array of MQTT messages
void free_messages(MQTT_MESSAGE_T* messages, int num_messages) {
    // Check if the input is valid
    if (messages == NULL || num_messages <= 0) {
        return;
    }

    // Free each message structure and its associated memory
    for (int i = 0; i < num_messages; i++) {
        free(messages[i].messaging_header);
        free(messages[i].payload);
    }

    // Free the array of MQTT messages
    free(messages);
}

// Function to free memory for a linked list of MQTT connection states
void free_connection_states(MQTT_CONNECTION_STATE_T* head) {
    // Check if the input is valid
    if (head == NULL) {
        return;
    }

    // Free each node in the linked list and its associated memory
    while (head != NULL) {
        free(head->hostname);
        free(head->port);
        MQTT_CONNECTION_STATE_T* next = head->next;
        free(head);
        head = next;
    }
}

// Function to free memory for a circular buffer of log messages
void free_log_buffer(LOG_MESSAGE_T* buffer, int size) {
    // Check if the input is valid
    if (buffer == NULL || size <= 0) {
        return;
    }

    // Free each log message structure and its associated memory
    for (int i = 0; i < size; i++) {
        free(buffer[i].timestamp);
        free(buffer[i].message);
    }

    // Free the circular buffer of log messages
    free(buffer);
}

// Function to write a log message to a circular buffer
void write_log_message(LOG_MESSAGE_T* buffer, int size, char* timestamp, int level, char* message) {
    // Check if the input is valid
    if (buffer == NULL || size <= 0 || timestamp == NULL || level < 0 || message == NULL) {
        return;
    }

    // Write the log message to the circular buffer
    strcpy(buffer[size % LOGGING_BUFFER_SIZE].timestamp, timestamp);
    buffer[size % LOGGING_BUFFER_SIZE].level = level;
    strcpy(buffer[size % LOGGING_BUFFER_SIZE].message, message);
}

// Function to read a log message from a circular buffer
void read_log_message(LOG_MESSAGE_T* buffer, int size, char* timestamp, int* level, char* message) {
    // Check if the input is valid
    if (buffer == NULL || size <= 0 || timestamp == NULL || level == NULL || message == NULL) {
        return;
    }

    // Read the log message from the circular buffer
    strcpy(timestamp, buffer[size % LOGGING_BUFFER_SIZE].timestamp);
    *level = buffer[size % LOGGING_BUFFER_SIZE].level;
    strcpy(message, buffer[size % LOGGING_BUFFER_SIZE].message);
}']

