#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <dirent.h>
#include <unistd.h>
#include <errno.h>

// Define constants for file extensions and sorting options
#define EXTENSIONS "txt,pdf,doc"
#define SORT_BY_SIZE 0
#define SORT_BY_DATE 1

int main(int argc, char *argv[]) {
    // Check if the directory path is valid
    if (argc < 2) {
        printf("Usage: %s [directory]\n", argv[0]);
        return 1;
    }

    // Get the directory path from the command-line arguments
    char *dir_path = argv[1];

    // Open the directory and check if it exists
    DIR *dir = opendir(dir_path);
    if (dir == NULL) {
        printf("Error: %s\n", strerror(errno));
        return 1;
    }

    // Initialize variables for file size and modification date
    long total_size = 0;
    time_t latest_modified = 0;

    // Iterate over the files in the directory
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (entry->d_name[0] == '.') continue;

        // Get the file path and size
        char *file_path = malloc(strlen(dir_path) + strlen(entry->d_name) + 2);
        sprintf(file_path, "%s/%s", dir_path, entry->d_name);
        struct stat st;
        if (stat(file_path, &st) == -1) {
            printf("Error: %s\n", strerror(errno));
            continue;
        }
        long file_size = st.st_size;

        // Check if the file extension is valid
        char *ext = strrchr(entry->d_name, '.');
        if (ext != NULL && strstr(EXTENSIONS, ext + 1) == NULL) continue;

        // Update the total size and latest modified date
        total_size += file_size;
        if (st.st_mtime > latest_modified) latest_modified = st.st_mtime;

        // Print the file information
        printf("%s\t%ld\t%s\n", entry->d_name, file_size, ctime(&latest_modified));
    }

    // Close the directory stream
    closedir(dir);

    // Sort the files by size or date
    if (argc > 2 && strcmp(argv[2], "--sort-by-size") == 0) {
        qsort(file_path, total_size, sizeof(char *), compare_filesize);
    } else if (argc > 3 && strcmp(argv[3], "--sort-by-date") == 0) {
        qsort(file_path, total_size, sizeof(char *), compare_modified);
    }

    // Print the total disk space used by the files
    printf("Total size: %ld\n", total_size);

    return 0;
}

// Compare function for sorting files by size
int compare_filesize(const void *a, const void *b) {
    char **file1 = (char **)a;
    char **file2 = (char **)b;
    struct stat st1, st2;
    if (stat(*file1, &st1) == -1 || stat(*file2, &st2) == -1) {
        printf("Error: %s\n", strerror(errno));
        return 0;
    }
    return st1.st_size > st2.st_size ? 1 : -1;
}

// Compare function for sorting files by modification date
int compare_modified(const void *a, const void *b) {
    char **file1 = (char **)a;
    char **file2 = (char **)b;
    struct stat st1, st2;
    if (stat(*file1, &st1) == -1 || stat(*file2, &st2) == -1) {
        printf("Error: %s\n", strerror(errno));
        return 0;
    }
    return st1.st_mtime > st2.st_mtime ? 1 : -1;
}
