#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define the structure for NetworkFlow
typedef struct {
    NetFlowHeader header;
    NetFlowSample sample;
    FlowAnnotations annotations[MAX_ANNOTATIONS];
} NetworkFlow;

// Define the function to process and transform network traffic
void processAndTransformNetworkTraffic(const char* logFile, const char* encryptionKey, const char* iv) {
    // Validate input parameters for correctness
    if (logFile == NULL || encryptionKey == NULL || iv == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Open the log file in read-only mode
    int fd = open(logFile, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open log file");
        return;
    }

    // Decrypt and validate the data using the specified encryption key and IV
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create cipher context\n");
        close(fd);
        return;
    }
    int ret = EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, encryptionKey, iv);
    if (ret != 1) {
        fprintf(stderr, "Failed to initialize decryption\n");
        close(fd);
        return;
    }
    char* buffer = malloc(BUFFER_SIZE);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for buffer\n");
        close(fd);
        return;
    }
    int readBytes = 0;
    while ((readBytes = read(fd, buffer, BUFFER_SIZE)) > 0) {
        ret = EVP_DecryptUpdate(ctx, buffer, &readBytes, buffer, readBytes);
        if (ret != 1) {
            fprintf(stderr, "Failed to decrypt data\n");
            close(fd);
            return;
        }
    }
    EVP_CIPHER_CTX_free(ctx);
    close(fd);

    // Parse the log files and dynamically allocate memory for temporary storage of parsed traffic entries
    NetworkFlow* flows = malloc(sizeof(NetworkFlow) * MAX_FLOWS);
    if (flows == NULL) {
        fprintf(stderr, "Failed to allocate memory for flows\n");
        return;
    }
    int numFlows = 0;
    char* line = malloc(LINE_SIZE);
    while (fgets(line, LINE_SIZE, logFile) != NULL) {
        // Parse the current line and update the corresponding NetworkFlow structure
        NetworkFlow* flow = &flows[numFlows];
        parseLine(line, flow);
        numFlows++;
    }
    free(line);

    // Manage resources efficiently to prevent memory leaks
    for (int i = 0; i < numFlows; i++) {
        NetworkFlow* flow = &flows[i];
        if (flow->header.valid) {
            updateAnnotations(flow);
        } else {
            free(flow);
        }
    }
    free(flows);
}

// Define the function to parse a line of log data and update the corresponding NetworkFlow structure
void parseLine(char* line, NetworkFlow* flow) {
    // Parse the current line and update the corresponding NetworkFlow structure
    char* token = strtok(line, " ");
    while (token != NULL) {
        if (strcmp(token, "NetFlowHeader") == 0) {
            parseHeader(token, flow);
        } else if (strcmp(token, "NetFlowSample") == 0) {
            parseSample(token, flow);
        } else if (strcmp(token, "FlowAnnotations") == 0) {
            parseAnnotations(token, flow);
        }
        token = strtok(NULL, " ");
    }
}

// Define the function to parse a NetFlowHeader and update the corresponding NetworkFlow structure
void parseHeader(char* line, NetworkFlow* flow) {
    // Parse the current line and update the corresponding NetworkFlow structure
    char* token = strtok(line, " ");
    while (token != NULL) {
        if (strcmp(token, "version") == 0) {
            flow->header.version = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "flow_count") == 0) {
            flow->header.flowCount = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "source_id") == 0) {
            flow->header.sourceId = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "sequence_num") == 0) {
            flow->header.sequenceNum = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "sampling_interval") == 0) {
            flow->header.samplingInterval = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "flow_records") == 0) {
            flow->header.flowRecords = atoi(strtok(NULL, " "));
        }
        token = strtok(NULL, " ");
    }
}

// Define the function to parse a NetFlowSample and update the corresponding NetworkFlow structure
void parseSample(char* line, NetworkFlow* flow) {
    // Parse the current line and update the corresponding NetworkFlow structure
    char* token = strtok(line, " ");
    while (token != NULL) {
        if (strcmp(token, "source_ip") == 0) {
            flow->sample.sourceIp = inet_addr(strtok(NULL, " "));
        } else if (strcmp(token, "dest_ip") == 0) {
            flow->sample.destIp = inet_addr(strtok(NULL, " "));
        } else if (strcmp(token, "source_port") == 0) {
            flow->sample.sourcePort = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "dest_port") == 0) {
            flow->sample.destPort = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "protocol") == 0) {
            flow->sample.protocol = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "packet_count") == 0) {
            flow->sample.packetCount = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "byte_count") == 0) {
            flow->sample.byteCount = atoi(strtok(NULL, " "));
        }
        token = strtok(NULL, " ");
    }
}

// Define the function to parse FlowAnnotations and update the corresponding NetworkFlow structure
void parseAnnotations(char* line, NetworkFlow* flow) {
    // Parse the current line and update the corresponding NetworkFlow structure
    char* token = strtok(line, " ");
    while (token != NULL) {
        if (strcmp(token, "annotation_type") == 0) {
            flow->annotations[flow->header.numAnnotations].type = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "annotation_value") == 0) {
            flow->annotations[flow->header.numAnnotations].value = strdup(strtok(NULL, " "));
        }
        token = strtok(NULL, " ");
    }
}

// Define the function to update FlowAnnotations and ensure no two annotations have the same type within the same NetworkFlow
void updateAnnotations(NetworkFlow* flow) {
    // Update the corresponding NetworkFlow structure with the new annotation
    for (int i = 0; i < flow->header.numAnnotations; i++) {
        if (flow->annotations[i].type == flow->annotations[i + 1].type) {
            fprintf(stderr, "Duplicate annotation type found\n");
            return;
        }
    }
}

// Define the function to validate the integrity of the NetFlowSample after each update to prevent buffer overflows
void validateSample(NetworkFlow* flow) {
    // Validate the current sample and ensure no buffer overflows
    if (flow->sample.packetCount > MAX_PACKETS || flow->sample.byteCount > MAX_BYTES) {
        fprintf(stderr, "Buffer overflow detected\n");
        return;
    }
}
