#include <nfapi.h>

// Define the maximum number of interfaces that can be configured simultaneously
#define MAX_INTERFACES 100

// Define the structure to hold information about each interface
typedef struct {
    int id; // Unique identifier for the interface
    char *name; // Name of the interface (e.g., "eth0")
    nfapi_handle_t handle; // NFAPI handle for the interface
    nfapi_config_t config; // Configuration parameters for the interface
} interface_info_t;

// Define the array to hold information about each interface
interface_info_t interfaces[MAX_INTERFACES];

// Define the function to initialize and configure a network interface
int init_interface(int id, char *name) {
    // Check if the interface is already configured
    for (int i = 0; i < MAX_INTERFACES; i++) {
        if (interfaces[i].id == id) {
            return -1; // Interface is already configured
        }
    }

    // Allocate memory for the interface information structure
    interface_info_t *interface = malloc(sizeof(interface_info_t));
    if (!interface) {
        return -2; // Memory allocation failed
    }

    // Initialize the NFAPI handle and configuration parameters
    nfapi_handle_t handle = nfapi_create();
    if (!handle) {
        free(interface);
        return -3; // NFAPI handle creation failed
    }
    interface->handle = handle;
    memset(&interface->config, 0, sizeof(nfapi_config_t));

    // Set the configuration parameters for the interface
    interface->config.buffer_size = 16384;
    interface->config.timeout = 5000;
    interface->config.flow_control_limit = 1024;

    // Configure the interface using the NFAPI library
    int ret = nfapi_configure(handle, &interface->config);
    if (ret != 0) {
        free(interface);
        return -4; // NFAPI configuration failed
    }

    // Add the interface to the list of configured interfaces
    for (int i = 0; i < MAX_INTERFACES; i++) {
        if (interfaces[i].id == 0) {
            interfaces[i] = *interface;
            break;
        }
    }

    // Free the memory allocated for the interface information structure
    free(interface);

    return 0; // Interface initialization and configuration successful
}

// Define the function to remove a network interface from the list of configured interfaces
int remove_interface(int id) {
    // Find the index of the interface in the list of configured interfaces
    int i = 0;
    while (i < MAX_INTERFACES && interfaces[i].id != id) {
        i++;
    }

    // Check if the interface was found in the list
    if (i == MAX_INTERFACES) {
        return -1; // Interface not found
    }

    // Remove the interface from the list of configured interfaces
    for (int j = i; j < MAX_INTERFACES - 1; j++) {
        interfaces[j] = interfaces[j + 1];
    }
    interfaces[MAX_INTERFACES - 1].id = 0;

    // Destroy the NFAPI handle for the interface
    nfapi_destroy(interfaces[i].handle);

    return 0; // Interface removal successful
}

// Define the function to monitor and log connection status changes
void monitor_connections() {
    // Loop through each interface in the list of configured interfaces
    for (int i = 0; i < MAX_INTERFACES; i++) {
        // Check if the interface is currently connected
        if (interfaces[i].id != 0) {
            // Get the current connection status and log it
            nfapi_connection_status_t status = nfapi_get_connection_status(interfaces[i].handle);
            printf("Interface %d: %s\n", interfaces[i].id, status == NFAPI_CONNECTED ? "Connected" : "Disconnected");
        }
    }
}

// Define the function to handle asynchronous operation mode for configuring multiple network interfaces
void configure_interfaces(int id, char *name) {
    // Initialize and configure the interface using the NFAPI library
    int ret = init_interface(id, name);
    if (ret != 0) {
        printf("Error initializing and configuring interface %d: %s\n", id, strerror(ret));
    } else {
        // Log the successful configuration of the interface
        printf("Interface %d configured successfully\n", id);
    }
}

// Define the function to handle asynchronous operation mode for removing network interfaces
void remove_interface(int id) {
    // Remove the interface from the list of configured interfaces using the NFAPI library
    int ret = remove_interface(id);
    if (ret != 0) {
        printf("Error removing interface %d: %s\n", id, strerror(ret));
    } else {
        // Log the successful removal of the interface
        printf("Interface %d removed successfully\n", id);
    }
}

// Define the function to handle asynchronous operation mode for monitoring and logging connection status changes
void monitor_connections() {
    // Loop through each interface in the list of configured interfaces
    for (int i = 0; i < MAX_INTERFACES; i++) {
        // Check if the interface is currently connected
        if (interfaces[i].id != 0) {
            // Get the current connection status and log it
            nfapi_connection_status_t status = nfapi_get_connection_status(interfaces[i].handle);
            printf("Interface %d: %s\n", interfaces[i].id, status == NFAPI_CONNECTED ? "Connected" : "Disconnected");
        }
    }
}
