typedef struct {
    int max_readings_per_entry;
    double threshold_value;
} Configuration;

// Function to parse and aggregate sensor data from a JSON file
void parseAndAggregateSensorData(const char* json_file, const char* config_file) {
    // Validate input parameters for correctness
    if (json_file == NULL || config_file == NULL) {
        printf("Invalid input parameters\n");
        return;
    }

    // Open the JSON file and read its contents
    FILE* json_fp = fopen(json_file, "r");
    if (json_fp == NULL) {
        printf("Error opening JSON file: %s\n", strerror(errno));
        return;
    }
    char* json_data = malloc(sizeof(char) * 1024);
    size_t bytes_read = fread(json_data, sizeof(char), 1024, json_fp);
    if (bytes_read == 0) {
        printf("Error reading JSON file: %s\n", strerror(errno));
        return;
    }
    json_data[bytes_read] = '\0';
    fclose(json_fp);

    // Validate the JSON data using a JSON schema
    json_t* json = json_loads(json_data, 0, NULL);
    if (json == NULL) {
        printf("Error parsing JSON data: %s\n", strerror(errno));
        return;
    }
    json_schema_validate(json, "{\"type\": \"object\", \"properties\": {\"sensors\": {\"type\": \"array\"}}}");
    if (json_schema_get_error() != NULL) {
        printf("Error validating JSON data: %s\n", strerror(errno));
        return;
    }

    // Parse the log files and dynamically allocate memory for temporary storage of parsed sensor entries
    json_t* sensors = json_object_get(json, "sensors");
    size_t num_sensors = json_array_size(sensors);
    SensorData** sensor_data = malloc(sizeof(SensorData*) * num_sensors);
    for (int i = 0; i < num_sensors; i++) {
        json_t* sensor = json_array_get(sensors, i);
        char* sensor_id = json_string_value(json_object_get(sensor, "sensor_id"));
        size_t num_readings = json_array_size(json_object_get(sensor, "readings"));
        SensorData* data = malloc(sizeof(SensorData));
        data->timestamp = json_integer_value(json_object_get(sensor, "timestamp"));
        data->sensor_id = sensor_id;
        data->readings = malloc(sizeof(double) * num_readings);
        for (int j = 0; j < num_readings; j++) {
            json_t* reading = json_array_get(json_object_get(sensor, "readings"), j);
            data->readings[j] = json_number_value(reading);
        }
        sensor_data[i] = data;
    }

    // Manage resources efficiently to prevent memory leaks
    free(json_data);
    json_decref(json);

    // Handle file descriptor operations and parsing errors robustly
    FILE* output_fp = fopen("output.txt", "w");
    if (output_fp == NULL) {
        printf("Error opening output file: %s\n", strerror(errno));
        return;
    }
    Configuration config = parseConfigurationFile(config_file);
    for (int i = 0; i < num_sensors; i++) {
        SensorData* data = sensor_data[i];
        if (data->timestamp > config.threshold_value) {
            fprintf(output_fp, "%s %ld %f\n", data->sensor_id, data->timestamp, data->readings[0]);
        }
    }
    fclose(output_fp);

    // Handle edge cases where the JSON might be malformed or contain unexpected fields
    for (int i = 0; i < num_sensors; i++) {
        SensorData* data = sensor_data[i];
        if (data->timestamp > config.threshold_value) {
            fprintf(output_fp, "%s %ld %f\n", data->sensor_id, data->timestamp, data->readings[0]);
        }
    }
}

// Function to parse the configuration file and extract the maximum number of readings per entry and threshold values for triggering anomaly detection alerts
Configuration parseConfigurationFile(const char* config_file) {
    // Open the configuration file and read its contents
    FILE* config_fp = fopen(config_file, "r");
    if (config_fp == NULL) {
        printf("Error opening configuration file: %s\n", strerror(errno));
        return;
    }
    char* config_data = malloc(sizeof(char) * 1024);
    size_t bytes_read = fread(config_data, sizeof(char), 1024, config_fp);
    if (bytes_read == 0) {
        printf("Error reading configuration file: %s\n", strerror(errno));
        return;
    }
    config_data[bytes_read] = '\0';
    fclose(config_fp);

    // Parse the configuration data using a JSON parser
    json_t* json = json_loads(config_data, 0, NULL);
    if (json == NULL) {
        printf("Error parsing configuration file: %s\n", strerror(errno));
        return;
    }
    Configuration config;
    config.max_readings_per_entry = json_integer_value(json_object_get(json, "max_readings_per_entry"));
    config.threshold_value = json_number_value(json_object_get(json, "threshold_value"));
    json_decref(json);

    // Handle edge cases where the configuration file might be malformed or contain unexpected fields
    if (config.max_readings_per_entry < 0 || config.threshold_value < 0) {
        printf("Error parsing configuration file: invalid values\n");
        return;
    }

    // Return the parsed configuration data
    return config;
}
