#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <regex>
#include <filesystem>

using namespace std;

// Define the file formats that can be processed
enum class FileFormat { TIFF, JPEG, PNG };

// Define the processing modes
enum class ProcessingMode { SUMMARY, DETAIL, ERROR_ONLY };

// Define the logging levels
enum class LogLevel { NONE, BASIC, VERBOSE };

// Define the file metadata structure
struct FileMetadata {
    string filename;
    FileFormat format;
    chrono::time_point<chrono::system_clock> timestamp;
    size_t size;
};

// Define the summary report structure
struct SummaryReport {
    vector<FileMetadata> files;
    size_t totalSize;
};

// Define the processing thread function
void processFiles(const string& directory, const string& outputFile, const chrono::time_point<chrono::system_clock>& startTime, const chrono::time_point<chrono::system_clock>& endTime, const regex& pattern, const ProcessingMode& mode, const LogLevel& logLevel) {
    // Initialize the summary report
    SummaryReport report;

    // Iterate over the files in the directory
    for (const auto& file : filesystem::directory_iterator(directory)) {
        // Check if the file is a regular file and matches the pattern
        if (!filesystem::is_regular_file(file) || !regex_match(file.path().filename(), pattern)) continue;

        // Parse the file metadata
        FileMetadata metadata;
        metadata.filename = file.path().string();
        metadata.format = getFileFormat(metadata.filename);
        metadata.timestamp = getTimestamp(metadata.filename);
        metadata.size = filesystem::file_size(file);

        // Check if the file is within the time range
        if (startTime != chrono::time_point<chrono::system_clock>::min() && endTime != chrono::time_point<chrono::system_clock>::max()) {
            if (!isFileWithinRange(metadata.timestamp, startTime, endTime)) continue;
        }

        // Add the file to the summary report
        report.files.push_back(metadata);
    }

    // Sort the files by timestamp
    sort(report.files.begin(), report.files.end(), [](const FileMetadata& a, const FileMetadata& b) { return a.timestamp < b.timestamp; });

    // Calculate the total size of all files processed
    for (const auto& file : report.files) {
        report.totalSize += file.size;
    }

    // Log the processing details
    if (logLevel == LogLevel::VERBOSE) {
        cout << "Processed " << report.files.size() << " files in " << chrono::duration_cast<chrono::milliseconds>(chrono::system_clock::now() - startTime).count() << "ms" << endl;
    }

    // Write the summary report to the output file
    ofstream outFile(outputFile, ios::binary);
    if (!outFile.is_open()) {
        cerr << "Error: unable to open output file '" << outputFile << "' for writing" << endl;
        return;
    }
    outFile << report;
}

// Define the main function
int main(int argc, char** argv) {
    // Parse the command-line arguments
    string directory = "";
    string outputFile = "";
    chrono::time_point<chrono::system_clock> startTime = chrono::time_point<chrono::system_clock>::min();
    chrono::time_point<chrono::system_clock> endTime = chrono::time_point<chrono::system_clock>::max();
    regex pattern(".*");
    ProcessingMode mode = ProcessingMode::SUMMARY;
    LogLevel logLevel = LogLevel::NONE;
    for (int i = 1; i < argc; ++i) {
        if (string(argv[i]) == "--help") {
            cout << "Usage: " << argv[0] << " [options]" << endl;
            cout << "Options:" << endl;
            cout << "-d <directory>  Specify the directory containing files to process" << endl;
            cout << "-o <output_file> Redirect the summary report to a specified file, ensuring atomic output to allow safe overwrites in concurrent environments" << endl;
            cout << "-t <time_range> Process files within a specified time range, defined by start and end timestamps" << endl;
            cout << "-p <pattern> Filter files based on a specified pattern, ensuring that the pattern matching is flexible enough to accommodate common file patterns while avoiding false positives" << endl;
            cout << "-v Enable verbose mode, providing detailed information about the processing steps and any warnings or errors encountered" << endl;
            cout << "-m <mode> Specify a processing mode, such as 'summary', 'detail', or 'error-only'" << endl;
            cout << "-s <size> Limit the size of the summary report to a specified kilobyte limit" << endl;
        } else if (string(argv[i]) == "-d") {
            directory = argv[++i];
        } else if (string(argv[i]) == "-o") {
            outputFile = argv[++i];
        } else if (string(argv[i]) == "-t") {
            startTime = chrono::time_point<chrono::system_clock>(chrono::duration_cast<chrono::milliseconds>(chrono::system_clock::now() - chrono::milliseconds(stoi(argv[++i]))));
            endTime = chrono::time_point<chrono::system_clock>(chrono::duration_cast<chrono::milliseconds>(chrono::system_clock::now()));
        } else if (string(argv[i]) == "-p") {
            pattern = regex(argv[++i]);
        } else if (string(argv[i]) == "-v") {
            logLevel = LogLevel::VERBOSE;
        } else if (string(argv[i]) == "-m") {
            mode = ProcessingMode(stoi(argv[++i]));
        } else if (string(argv[i]) == "-s") {
            size_t limit = stoi(argv[++i]);
            if (limit > 0) {
                cout << "Limiting the summary report to " << limit << " kilobytes" << endl;
            } else {
                cerr << "Error: invalid value for '-s' option" << endl;
                return 1;
            }
        }
    }

    // Check if the required arguments are provided
    if (directory.empty() || outputFile.empty()) {
        cerr << "Error: missing required argument(s)" << endl;
        return 1;
    }

    // Create a thread pool for processing files concurrently
    vector<thread> threads;
    mutex mtx;
    condition_variable cv;
    size_t numThreads = thread::hardware_concurrency();
    if (numThreads == 0) {
        numThreads = 1;
    }
    cout << "Using " << numThreads << " thread(s) for processing" << endl;

    // Split the files into chunks and process them concurrently
    vector<vector<FileMetadata>> fileChunks;
    size_t chunkSize = 0;
    for (const auto& file : filesystem::directory_iterator(directory)) {
        if (!filesystem::is_regular_file(file) || !regex_match(file.path().filename(), pattern)) continue;
        FileMetadata metadata;
        metadata.filename = file.path().string();
        metadata.format = getFileFormat(metadata.filename);
        metadata.timestamp = getTimestamp(metadata.filename);
        metadata.size = filesystem::file_size(file);
        if (chunkSize == 0) {
            chunkSize = metadata.size;
        } else {
            chunkSize += metadata.size;
        }
        fileChunks.push_back(vector<FileMetadata>{metadata});
    }
    size_t numFiles = fileChunks.size();
    if (numFiles == 0) {
        cerr << "Error: no files found in directory '" << directory << "'" << endl;
        return 1;
    }
    cout << "Found " << numFiles << " file(s) matching the pattern" << endl;
    size_t chunkIndex = 0;
    for (size_t i = 0; i < numThreads; ++i) {
        threads.push_back(thread([&]() {
            while (true) {
                unique_lock<mutex> lock(mtx);
                if (chunkIndex >= fileChunks.size()) break;
                vector<FileMetadata>& chunk = fileChunks[chunkIndex];
                ++chunkIndex;
                lock.unlock();
                processFiles(directory, outputFile, startTime, endTime, pattern, mode, logLevel);
            }
        }));
    }

    // Wait for all threads to finish processing the files
    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
