// Define a struct to store user profiles
typedef struct {
    int id;
    char* name;
} UserProfile;

// Define a cache structure to store user profiles
typedef struct {
    UserProfile** profiles;
    int size;
    pthread_mutex_t lock;
} Cache;

// Function to read integers from a file and determine the largest integer
int processFilesAndCacheProfiles(char* files[], int numFiles, Cache* cache) {
    // Initialize variables
    int maxInt = 0;
    double sum = 0;
    int i, j;

    // Loop through each file and read integers
    for (i = 0; i < numFiles; i++) {
        FILE* fp = fopen(files[i], "r");
        if (fp == NULL) {
            printf("Error: unable to open file %s\n", files[i]);
            continue;
        }

        // Read integers from the file and store in a dynamic array
        int* ints = malloc(sizeof(int));
        int count = 0;
        while (fscanf(fp, "%d", &ints[count]) == 1) {
            count++;
            ints = realloc(ints, sizeof(int) * (count + 1));
        }
        fclose(fp);

        // Determine the largest integer and calculate the average of all integers
        for (j = 0; j < count; j++) {
            if (ints[j] > maxInt) {
                maxInt = ints[j];
            }
            sum += ints[j];
        }

        // Add the user profile to the cache
        UserProfile* profile = malloc(sizeof(UserProfile));
        profile->id = i;
        profile->name = "User";
        pthread_mutex_lock(&cache->lock);
        cache->profiles[i] = profile;
        pthread_mutex_unlock(&cache->lock);
    }

    // Return the largest integer and average of all integers
    return maxInt, sum / count;
}
