    printf("  -c, --cs\tPrint the configuration settings for the program\n");
    printf("  -o <output_file>\tSpecify the output file for the program\n");
}

void parse_command_line(int argc, char** argv) {
    // Initialize the command line options and arguments
    int option;
    char* input_file = NULL;
    char* output_file = DEFAULT_OUTPUT_FILE;

    // Parse the command line options
    while ((option = getopt(argc, argv, "mco:")) != -1) {
        switch (option) {
            case 'm':
                print_usage(argv[0]);
                exit(EXIT_SUCCESS);
            case 'c':
                print_help(argv[0]);
                exit(EXIT_SUCCESS);
            case 'o':
                output_file = optarg;
                break;
        }
    }

    // Check if the input file is provided
    if (optind >= argc) {
        fprintf(stderr, "Error: No input file specified\n");
        exit(ERROR_MISSING_ARGUMENT);
    } else {
        input_file = argv[optind];
    }

    // Check if the output file is valid
    FILE* fp = fopen(output_file, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open output file %s\n", output_file);
        exit(ERROR_OUTPUT_FILE_ERROR);
    }

    // Create the thread data structures
    pthread_t threads[NUM_THREADS];
    thread_data_t* thread_data = (thread_data_t*)malloc(sizeof(thread_data_t) * NUM_THREADS);
    for (int i = 0; i < NUM_THREADS; i++) {
        thread_data[i].thread_id = i;
        thread_data[i].file_info = (file_info_t*)malloc(sizeof(file_info_t));
        thread_data[i].file_info->input_file = input_file;
        thread_data[i].file_info->output_file = output_file;
    }

    // Create the semaphore for synchronizing threads
    sem_t* sem = sem_open("sem", O_CREAT, 0644, NUM_THREADS);
    if (sem == SEM_FAILED) {
        fprintf(stderr, "Error: Could not create semaphore\n");
        exit(ERROR_THREAD_CREATION);
