        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Error: Could not join thread %d\n", i);
            exit(ERROR_THREAD_JOIN);
        }
    }

    // Close the semaphore
    if (sem_close(sem) == -1) {
        fprintf(stderr, "Error: Could not close semaphore\n");
        exit(ERROR_THREAD_CREATION);
    }

    // Close the output file
