    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open input file %s\n", td->file_info->input_file);
        exit(ERROR_FILE_NOT_FOUND);
    }

    // Read the input file line by line and print the number of lines
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    int num_lines = 0;
    while ((read = getline(&line, &len, fp)) != -1) {
        num_lines++;
    }

    // Print the number of lines to the output file
    FILE* out = fopen(td->file_info->output_file, "a");
    if (out == NULL) {
        fprintf(stderr, "Error: Could not open output file %s\n", td->file_info->output_file);
        exit(ERROR_OUTPUT_FILE_ERROR);
    }
    fprintf(out, "%d\n", num_lines);
    if (fclose(out) != 0) {
        fprintf(stderr, "Error: Could not close output file %s\n", td->file_info->output_file);
        exit(ERROR_OUTPUT_FILE_ERROR);
    }

    // Free the memory allocated for the line buffer
    free(line);

    // Return NULL to indicate that the thread has completed successfully
    return NULL;
}

int main(int argc, char** argv) {
    parse_command_line(argc, argv);
    return 0;
}
```
