void read_directory(char *dir) {
    // Open the directory specified via command line arguments
    DIR *dp = opendir(dir);
    if (dp == NULL) {
        printf("Error: Could not open directory %s\n", dir);
        return;
    }

    // Declare variables for storing file information and sorting criteria
    struct dirent *ep;
    int sort_criteria = SORT_CRITERIA_SIZE;
    char *filter_criteria = NULL;
    int filter_type = FILTER_CRITERIA_EXTENSION;
    int num_files = 0;

    // Read the directory entry by entry and process each file
    while ((ep = readdir(dp)) != NULL) {
        // Skip hidden files and directories
        if (strncmp(ep->d_name, ".", 1) == 0 || strncmp(ep->d_name, "..", 2) == 0) {
            continue;
        }

        // Get the file type and size
        struct stat st;
        if (stat(ep->d_name, &st) < 0) {
            printf("Error: Could not get information for %s\n", ep->d_name);
            continue;
        }

        // Check if the file type matches the specified filter criteria
        if (filter_criteria != NULL && strcmp(ep->d_name, filter_criteria) != 0) {
            continue;
        }

        // Add the file to the array of files and directories
        NFAPI_CRC_INDICATION_PDU_T *file = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (file == NULL) {
            printf("Error: Memory allocation failed\n");
            continue;
        }
        file->rx_ue_information.tag = FILE_TYPE_REGULAR;
        file->rx_ue_information.file_size = st.st_size;
        file->rnti = rand();
        file->crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
        file->crc_indication_rel8.crflag = rand() % 2;
        num_files++;
    }

    // Sort the array of files and directories based on the specified sorting criteria
    if (sort_criteria == SORT_CRITERIA_SIZE) {
        qsort(arr, n, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_size);
    } else if (sort_criteria == SORT_CRITERIA_MOD_DATE) {
        qsort(arr, n, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_mod_date);
    }

    // Calculate the total disk space used by listed files and directories
    calculate_disk_space(n, arr);
}

// Define a function to handle errors during CRC calculation
void handle_error(char *msg) {
    printf("Error: %s\n", msg);
}

int main(int argc, char *argv[]) {
    // Parse command line arguments and print usage information if no input is provided
    parse_args(argc, argv);

    // Read the directory specified via command line arguments and process all files, categorizing them by their extensions and sorting results by either size or modification date, as specified by the user
    read_directory(argv[1]);

    return 0;
}
