// Define the structure for storing activity entries
typedef struct {
    long timestamp;
    int user_id;
    int session_id;
    char* application_name;
    json_object* action_details;
} ActivityEntry;

// Define the function to process and aggregate user activity logs
void processAndAggregateUserActivityLogs(const char* log_file, const char* output_file) {
    // Validate the input parameters for correctness
    if (log_file == NULL || output_file == NULL) {
        printf("Invalid input parameters\n");
        return;
    }

    // Open the JSON file and parse it into a json_object
    FILE* log_file_ptr = fopen(log_file, "r");
    if (log_file_ptr == NULL) {
        printf("Error opening log file\n");
        return;
    }
    json_object* json_obj = json_tokener_parse_ex(log_file_ptr, -1);
    fclose(log_file_ptr);

    // Validate the JSON object for data integrity
    if (json_obj == NULL) {
        printf("Error parsing log file\n");
        return;
    }

    // Initialize a dynamic array to store activity entries
    ActivityEntry* entries = malloc(sizeof(ActivityEntry) * 100);
    int num_entries = 0;

    // Iterate over the JSON object and extract the necessary data
    json_object_foreach(json_obj, key, val) {
        if (strcmp(key, "timestamp") == 0) {
            entries[num_entries].timestamp = atol(val->string);
        } else if (strcmp(key, "user_id") == 0) {
            entries[num_entries].user_id = atoi(val->string);
        } else if (strcmp(key, "session_id") == 0) {
            entries[num_entries].session_id = atoi(val->string);
        } else if (strcmp(key, "application_name") == 0) {
            entries[num_entries].application_name = strdup(val->string);
        } else if (strcmp(key, "action_details") == 0) {
            json_object* action_details = val;
            int num_actions = json_object_array_length(action_details);
            for (int i = 0; i < num_actions; i++) {
                json_object* action = json_object_array_get_idx(action_details, i);
                if (strcmp(key, "unique_id") == 0) {
                    entries[num_entries].action_details.unique_id = atoi(val->string);
                } else if (strcmp(key, "action_type") == 0) {
                    entries[num_entries].action_details.action_type = strdup(val->string);
                } else if (strcmp(key, "duration") == 0) {
                    entries[num_entries].action_details.duration = atoi(val->string);
                }
            }
        }
        num_entries++;
    }

    // Aggregate the statistical metrics for performance analysis
    int total_actions = 0;
    int total_duration = 0;
    for (int i = 0; i < num_entries; i++) {
        total_actions += entries[i].action_details.num_actions;
        total_duration += entries[i].action_details.duration;
    }
    printf("Total actions: %d\n", total_actions);
    printf("Total duration: %d\n", total_duration);

    // Write the aggregated data to an output file
    FILE* output_file_ptr = fopen(output_file, "w");
    if (output_file_ptr == NULL) {
        printf("Error opening output file\n");
        return;
    }
    fprintf(output_file_ptr, "%d %d\n", total_actions, total_duration);
    fclose(output_file_ptr);

    // Clean up the memory allocated for the dynamic array
    free(entries);
}

// Define a validation function to ensure data integrity before processing
int validateUserActivityLogs(const char* log_file) {
    // Open the JSON file and parse it into a json_object
    FILE* log_file_ptr = fopen(log_file, "r");
    if (log_file_ptr == NULL) {
        printf("Error opening log file\n");
        return 0;
    }
    json_object* json_obj = json_tokener_parse_ex(log_file_ptr, -1);
    fclose(log_file_ptr);

    // Validate the JSON object for data integrity using a JSON schema
    if (json_obj == NULL) {
        printf("Error parsing log file\n");
        return 0;
    }

    // Check that all required fields are present and have valid values
    json_object* timestamp = json_object_object_get(json_obj, "timestamp");
    if (timestamp == NULL || !json_is_integer(timestamp)) {
        printf("Invalid timestamp\n");
        return 0;
    }
    json_object* user_id = json_object_object_get(json_obj, "user_id");
    if (user_id == NULL || !json_is_integer(user_id)) {
        printf("Invalid user ID\n");
        return 0;
    }
    json_object* session_id = json_object_object_get(json_obj, "session_id");
    if (session_id == NULL || !json_is_integer(session_id)) {
        printf("Invalid session ID\n");
        return 0;
    }
    json_object* application_name = json_object_object_get(json_obj, "application_name");
    if (application_name == NULL || !json_is_string(application_name)) {
        printf("Invalid application name\n");
        return 0;
    }
    json_object* action_details = json_object_object_get(json_obj, "action_details");
    if (action_details == NULL || !json_is_array(action_details)) {
        printf("Invalid action details\n");
        return 0;
    }

    // Check that all action details have valid values
    int num_actions = json_object_array_length(action_details);
    for (int i = 0; i < num_actions; i++) {
        json_object* action = json_object_array_get_idx(action_details, i);
        if (action == NULL || !json_is_object(action)) {
            printf("Invalid action\n");
            return 0;
        }
        json_object* unique_id = json_object_object_get(action, "unique_id");
        if (unique_id == NULL || !json_is_integer(unique_id)) {
            printf("Invalid unique ID\n");
            return 0;
        }
        json_object* action_type = json_object_object_get(action, "action_type");
        if (action_type == NULL || !json_is_string(action_type)) {
            printf("Invalid action type\n");
            return 0;
        }
        json_object* duration = json_object_object_get(action, "duration");
        if (duration == NULL || !json_is_integer(duration)) {
            printf("Invalid duration\n");
            return 0;
        }
    }

    // Return success if all validation checks passed
    return 1;
}

