#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

int main(int argc, char *argv[]) {
    // Check for command line arguments
    if (argc == 1) {
        printf("Usage: %s [--help | -s setting_name | -v | -o output_file]\n", argv[0]);
        return 1;
    }

    // Parse JSON file and load settings into memory
    json_object *json = json_object_from_file("config.json");
    if (!json) {
        printf("Error: unable to open config.json\n");
        return 1;
    }

    // Check for --help option and display usage information
    if (strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [--help | -s setting_name | -v | -o output_file]\n", argv[0]);
        return 0;
    }

    // Check for -s option and display specified setting value
    if (strcmp(argv[1], "-s") == 0) {
        char *setting_name = argv[2];
        json_object *value = json_object_get_object(json, setting_name);
        if (!value) {
            printf("Error: unable to find setting %s\n", setting_name);
            return 1;
        }
        printf("%s=%s\n", setting_name, json_object_get_string(value));
        return 0;
    }

    // Check for -v option and display all settings
    if (strcmp(argv[1], "-v") == 0) {
        json_object *settings = json_object_get_array(json);
        int i;
        for (i = 0; i < json_object_array_length(settings); i++) {
            json_object *setting = json_object_array_get_idx(settings, i);
            char *name = json_object_get_string(json_object_object_get(setting, "name"));
            char *value = json_object_get_string(json_object_object_get(setting, "value"));
            printf("%s=%s\n", name, value);
        }
        return 0;
    }

    // Check for -o option and save settings to output file
    if (strcmp(argv[1], "-o") == 0) {
        char *output_file = argv[2];
        json_object *settings = json_object_get_array(json);
        int i;
        for (i = 0; i < json_object_array_length(settings); i++) {
            json_object *setting = json_object_array_get_idx(settings, i);
            char *name = json_object_get_string(json_object_object_get(setting, "name"));
            char *value = json_object_get_string(json_object_object_get(setting, "value"));
            printf("%s=%s\n", name, value);
        }
        return 0;
    }

    // Check for -u option and update specified setting value
    if (strcmp(argv[1], "-u") == 0) {
        char *setting_name = argv[2];
        json_object *value = json_object_get_object(json, setting_name);
        if (!value) {
            printf("Error: unable to find setting %s\n", setting_name);
            return 1;
        }
        char *new_value = argv[3];
        json_object_object_add(value, "value", json_object_new_string(new_value));
        json_object_to_file(json, "config.json");
        return 0;
    }

    // Check for -d option and delete specified setting value
    if (strcmp(argv[1], "-d") == 0) {
        char *setting_name = argv[2];
        json_object *value = json_object_get_object(json, setting_name);
        if (!value) {
            printf("Error: unable to find setting %s\n", setting_name);
            return 1;
        }
        json_object_remove(json, setting_name);
        json_object_to_file(json, "config.json");
        return 0;
    }

    // If no options are specified, display usage information
    printf("Usage: %s [--help | -s setting_name | -v | -o output_file]\n", argv[0]);
    return 1;
}
```
This code uses the `json-c` library to parse and manipulate JSON data. It checks for command line arguments, parses the JSON file, and provides options to display, update, or delete configuration settings. The program handles JSON parsing errors gracefully and provides meaningful error messages. Updates to the settings are saved back to the JSON file using `json_object_to_file()`.

