// Define the function to generate a random filename
static char *generate_random_filename(const char *filename, const char *file_type) {
    // Get the original filename and extension
    char *original_filename = strdup(filename);
    char *extension = strrchr(original_filename, '.');

    // Generate a random sequence of digits for the new filename
    int rand_len = MAX_RAND_LEN;
    if (extension != NULL) {
        rand_len -= strlen(extension);
    }
    char *rand_seq = malloc(rand_len + 1);
    sprintf(rand_seq, "%0*d", rand_len, random() % (int)pow(10, rand_len));

    // Construct the new filename
    size_t new_filename_len = strlen(original_filename) + strlen(file_type) + strlen(rand_seq);
    char *new_filename = malloc(new_filename_len + 1);
    sprintf(new_filename, "%s%s%s", original_filename, rand_seq, file_type);

    // Free the memory allocated for the random sequence and the original filename
    free(rand_seq);
    free(original_filename);

    return new_filename;
}

// Define the function to find a unique filename
static char *find_unique_filename(const char *filename) {
    // Get the directory path of the input file
    char *directory = strdup(filename);
    char *file_name = strrchr(directory, '/');
    if (file_name == NULL) {
        file_name = directory;
    } else {
        *file_name++ = '\0';
    }

    // Generate a random filename with the same extension as the input file
    char *random_filename = generate_random_filename(filename, DEFAULT_FILE_TYPE);

    // Check if the generated filename exists in the current directory
    int retries = 0;
    while (access(random_filename, F_OK) == 0 && retries < NUM_RETRIES) {
        // If it does, generate a new random filename with an incremented suffix
        char *new_random_filename = malloc(strlen(random_filename) + 1);
        sprintf(new_random_filename, "%s%d", random_filename, retries++);
        free(random_filename);
        random_filename = new_random_filename;
    }

    // Free the memory allocated for the directory path and return the unique filename
    free(directory);
    return random_filename;
}

// Define the function to parse the JSON configuration file
static void parse_config(const char *config_file) {
    // Open the JSON configuration file
    FILE *fp = fopen(config_file, "r");
    if (fp == NULL) {
        perror("Error opening JSON configuration file");
        exit(EXIT_FAILURE);
    }

    // Parse the JSON configuration file using json-c library
    json_object *root = json_object_from_file(config_file);
    if (root == NULL) {
        perror("Error parsing JSON configuration file");
        exit(EXIT_FAILURE);
    }

    // Get the file type and random digit sequence length from the JSON object
    json_object *file_type = json_object_object_get(root, "file_type");
    if (file_type == NULL) {
        perror("Error getting file type from JSON configuration file");
        exit(EXIT_FAILURE);
    }
    const char *file_type_str = json_object_get_string(file_type);

    json_object *rand_len = json_object_object_get(root, "rand_len");
    if (rand_len == NULL) {
        perror("Error getting random digit sequence length from JSON configuration file");
        exit(EXIT_FAILURE);
    }
    int rand_len_int = json_object_get_int(rand_len);

    // Close the JSON configuration file
    fclose(fp);
}

// Define the function to initialize a dynamic array of MAC_PDU structures
static void init_mac_pdu_array(struct MAC_PDU **mac_pdu_array, size_t num_mac_pdus) {
    // Allocate memory for the dynamic array of MAC_PDU structures
    *mac_pdu_array = malloc(num_mac_pdus * sizeof(**mac_pdu_array));

    // Initialize each MAC_PDU structure in the dynamic array
    for (size_t i = 0; i < num_mac_pdus; i++) {
        struct MAC_PDU *mac_pdu = &(*mac_pdu_array)[i];
        mac_pdu->header.version = random() % 256;
        mac_pdu->header.type = random() % 256;
        mac_pdu->header.length = random() % (int)pow(10, MAX_RAND_LEN);
        mac_pdu->macsdu.data = malloc(mac_pdu->header.length * sizeof(uint8_t));
        mac_pdu->macsdu.len = mac_pdu->header.length;
        for (size_t j = 0; j < mac_pdu->header.length; j++) {
            mac_pdu->macsdu.data[j] = random() % 256;
        }
        mac_pdu->ie_list.ie_list = malloc(sizeof(struct IE_T));
        mac_pdu->ie_list.num_ies = 1;
        struct IE_T *ie = &mac_pdu->ie_list.ie_list[0];
        ie->ie_id = random() % 256;
        ie->ie_length = random() % (int)pow(10, MAX_RAND_LEN);
    }
}

// Define the function to validate the integrity of the MACSDU
static void validate_macsdu(struct MACSDU *macsdu) {
