    mac_pdu->macsdu.len = mac_pdu->header.length;
    for (size_t i = 0; i < mac_pdu->header.length; i++) {
        mac_pdu->macsdu.data[i] = random() % 256;
    }

    // Populate the IE_LIST field of the MAC_PDU structure
    mac_pdu->ie_list.ie_list = malloc(sizeof(struct IE_T));
    mac_pdu->ie_list.num_ies = 1;
    struct IE_T *ie = &mac_pdu->ie_list.ie_list[0];
    ie->ie_id = random() % 256;
    ie->ie_length = random() % (int)pow(10, MAX_RAND_LEN);

