        flow_log_pdu->packet_loss_flag = packet_loss_flag;
        flow_log_pdu->bytes_transferred = bytes_transferred;

        // Add the flow log PDU to the list of structures
        pthread_mutex_lock(&mutex);
        if (j < MAX_STRUCTS) {
            flow_logs[j++] = flow_log_pdu;
        } else {
