// Define a function to read and process an integer file
int read_and_process_file(const char *filename, ProcessedIntegers *result) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return -1;
    }

    // Allocate memory for the processed integers
    result->integers = malloc(sizeof(int) * BUFFER_SIZE);
    if (result->integers == NULL) {
        printf("Error: unable to allocate memory for processed integers\n");
        fclose(file);
        return -1;
    }

    // Read the file line by line and process each integer
    char buffer[BUFFER_SIZE];
    size_t count = 0;
    while (fgets(buffer, BUFFER_SIZE, file) != NULL && count < BUFFER_SIZE) {
        int integer = atoi(buffer);
        if (integer == INT_MIN || integer == INT_MAX) {
            printf("Error: integer overflow detected\n");
            fclose(file);
            free(result->integers);
            return -1;
        }
        result->integers[count++] = integer;
    }

    // Close the file and update the count
    fclose(file);
    result->count = count;

    // Sort the integers in ascending order
    qsort(result->integers, count, sizeof(int), compare_integers);

    // Calculate the average of all integers
    int sum = 0;
    for (size_t i = 0; i < count; i++) {
        sum += result->integers[i];
    }
    double average = (double)sum / count;

    // Print the results
    printf("File: %s\n", filename);
    printf("Largest integer: %d\n", result->integers[count - 1]);
    printf("Smallest integer: %d\n", result->integers[0]);
