    if (result->count > 1) {
        printf("Sorted list of integers:\n");
        for (size_t i = 0; i < count; i++) {
            printf("%d ", result->integers[i]);
        }
        printf("\n");
    }

    // Return success
    return 0;
}

// Define a function to compare two integers for sorting
int compare_integers(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    if (x < y) {
        return -1;
    } else if (x > y) {
        return 1;
    } else {
        return 0;
    }
}

// Define a function to merge multiple processed integers into a single list
void merge_processed_integers(ProcessedIntegers *result, ProcessedIntegers *addition) {
    // Allocate memory for the merged list
    result->integers = realloc(result->integers, (result->count + addition->count) * sizeof(int));
    if (result->integers == NULL) {
        printf("Error: unable to allocate memory for merged integers\n");
        return;
    }

    // Merge the two lists
    memcpy(result->integers + result->count, addition->integers, addition->count * sizeof(int));
    result->count += addition->count;
}

