// Define a function to parse command line arguments and print usage information if no input is provided
void parse_command_line_arguments(int argc, char *argv[]) {
    // Check if the user has provided any input
    if (argc == 1) {
        printf("Usage: %s [OPTIONS]...\n", argv[0]);
        printf("\n");
        printf("Options:\n");
        printf("  -h, --help                   Print this help message and exit\n");
        printf("  -m, --manpage                 Display the manual page for %s\n", argv[0]);
        printf("  -c, --cs                     Specify the CRC calculation criteria\n");
        printf("  -o, --output-file            Write output to a file instead of standard output\n");
        return;
    }

    // Parse command line arguments and handle errors
