                    printf("CRC calculation criteria: REL8\n");
                } else if (strcmp(optarg, "rel9") == 0) {
                    printf("CRC calculation criteria: REL9\n");
                } else {
                    printf("Error: Invalid CRC calculation criteria specified\n");
                }
                break;
            case 'o':
                // Specify the output file
                if (strcmp(optarg, "-") == 0) {
                    printf("Output will be written to standard output\n");
                } else {
                    FILE *output_file = fopen(optarg, "w");
                    if (output_file == NULL) {
                        printf("Error: Unable to open output file %s for writing\n", optarg);
                    } else {
                        printf("Output will be written to file %s\n", optarg);
                        fclose(output_file);
                    }
                }
                break;
            default:
                printf("Error: Invalid option specified\n");
                return;
        }
    }
}

// Define a function to read a directory and process all files, categorizing them by their extensions and sorting results by either size or modification date
void read_directory(char *directory) {
    // Open the directory
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        printf("Error: Unable to open directory %s\n", directory);
        return;
    }

    // Read all files in the directory and process them
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (strncmp(entry->d_name, ".", 1) == 0 || strncmp(entry->d_name, "..", 2) == 0) {
            continue;
        }

        // Get the file path
        char *file_path = malloc(strlen(directory) + strlen(entry->d_name) + 1);
        sprintf(file_path, "%s/%s", directory, entry->d_name);

        // Check if the file is a regular file or a symbolic link
        struct stat file_stat;
        if (lstat(file_path, &file_stat) == -1) {
            printf("Error: Unable to get information about file %s\n", file_path);
            continue;
        }

        // Process the file based on its type
        if (S_ISREG(file_stat.st_mode)) {
            // Regular file
            process_regular_file(file_path, &file_stat);
        } else if (S_ISLNK(file_stat.st_mode)) {
            // Symbolic link
            process_symbolic_link(file_path, &file_stat);
        } else if (S_ISDIR(file_stat.st_mode)) {
            // Directory
            process_directory(file_path, &file_stat);
        }
    }

    // Close the directory
    closedir(dir);
}

// Define a function to process a regular file
void process_regular_file(char *file_path, struct stat *file_stat) {
    // Get the file extension
    char *extension = strrchr(file_path, '.');
    if (extension == NULL) {
        printf("Error: Unable to get extension for file %s\n", file_path);
        return;
    }

    // Increment the counter for the file extension
    int *counter = malloc(sizeof(int));
    *counter = 1;
    if (extension == NULL) {
        printf("Error: Unable to increment counter for file %s\n", file_path);
        return;
    }

    // Print the file information
    printf("%s\t%ld\t%s\n", file_path, file_stat->st_size, extension);
}

// Define a function to process a symbolic link
void process_symbolic_link(char *file_path, struct stat *file_stat) {
    // Get the target of the symbolic link
    char *target = malloc(sizeof(char) * PATH_MAX);
    if (readlink(file_path, target, PATH_MAX) == -1) {
        printf("Error: Unable to get target for symbolic link %s\n", file_path);
        return;
    }

    // Increment the counter for the symbolic link target
    int *counter = malloc(sizeof(int));
    *counter = 1;
    if (target == NULL) {
        printf("Error: Unable to increment counter for symbolic link %s\n", file_path);
        return;
    }

    // Print the symbolic link information
    printf("%s\t%ld\t%s\n", file_path, file_stat->st_size, target);
}

