    if (strrchr(file_path, '/') == NULL) {
        printf("Error: Unable to get directory name for file %s\n", file_path);
        return;
    }

    // Increment the counter for the directory
    int *counter = malloc(sizeof(int));
    *counter = 1;
    if (dirname == NULL) {
        printf("Error: Unable to increment counter for directory %s\n", file_path);
        return;
    }

    // Print the directory information
    printf("%s\t%ld\t%s\n", file_path, file_stat->st_size, dirname);
}

