int resolveHostname(char *hostname, int port) {
    // Initialize the list of DNS servers
    DNSServerConfig *dns_servers = NULL;

    // Get the number of DNS servers
    int num_dns_servers = getNumDNSServers();

    // Iterate over the DNS servers and try to resolve the hostname
    for (int i = 0; i < num_dns_servers; i++) {
        DNSServerConfig *dns_server = &(dns_servers[i]);
        struct addrinfo hints, *res;
        int status;

        // Set the hints for the getaddrinfo function
        memset(&hints, 0, sizeof(struct addrinfo));
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_DGRAM;

        // Get the address information for the hostname
        status = getaddrinfo(hostname, NULL, &hints, &res);
        if (status != 0) {
            continue;
        }

        // Try to connect to the DNS server
        int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
        if (sockfd < 0) {
            continue;
        }

        struct sockaddr_in *server_address = (struct sockaddr_in *)res->ai_addr;
        server_address->sin_port = htons(port);

        // Try to connect to the DNS server
        if (connect(sockfd, (struct sockaddr *)server_address, sizeof(struct sockaddr)) < 0) {
            close(sockfd);
            continue;
        }

        // Send a query to the DNS server
        char *query = "QUERY";
        send(sockfd, query, strlen(query), 0);

        // Receive the response from the DNS server
        char buffer[1024];
        recv(sockfd, buffer, sizeof(buffer), 0);

        // Close the socket
        close(sockfd);

        // Parse the response and get the IP address
        struct addrinfo *response = (struct addrinfo *)buffer;
        char *ip_address = inet_ntoa(response->ai_addr->sin_addr);

        // Return the IP address
        return ip_address;
    }

    // If no DNS server is available, return an error
    return NULL;
}

// Define the function to process a list of FinancialTransaction structures
int processTransactions(FinancialTransaction *transactions, int num_transactions) {
    // Initialize the running checksum
    long checksum = 0;

    // Iterate over the transactions and process them
    for (int i = 0; i < num_transactions; i++) {
        FinancialTransaction *transaction = &(transactions[i]);

        // Resolve the hostname to IP address using DNS servers
        char *ip_address = resolveHostname(transaction->hostname, transaction->port);
        if (ip_address == NULL) {
            continue;
        }

        // Process the transaction
        checksum += processTransaction(transaction, ip_address);
    }

    // Return the running checksum
    return checksum;
}

// Define the function to process a single FinancialTransaction structure
int processTransaction(FinancialTransaction *transaction, char *ip_address) {
    // Initialize the transaction status
    bool status = false;

    // Try to connect to the IP address
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        return status;
    }

    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(struct sockaddr_in));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(transaction->port);
    inet_pton(AF_INET, ip_address, &server_address.sin_addr);

    // Try to connect to the IP address
    if (connect(sockfd, (struct sockaddr *)&server_address, sizeof(struct sockaddr)) < 0) {
        close(sockfd);
        return status;
    }

    // Send a request to the server
    char *request = "REQUEST";
    send(sockfd, request, strlen(request), 0);

    // Receive the response from the server
    char buffer[1024];
    recv(sockfd, buffer, sizeof(buffer), 0);

    // Close the socket
    close(sockfd);

    // Parse the response and get the status
    struct addrinfo *response = (struct addrinfo *)buffer;
    char *status_string = inet_ntoa(response->ai_addr->sin_addr);
    if (strcmp(status_string, "SUCCESS") == 0) {
        status = true;
    }

    // Return the transaction status
    return status;
}

