void addToCache(CacheEntry *cache_entry) {
    // Check if the cache is full
    if (getCacheSize() >= getMaxCacheSize()) {
        // Evict the least recently used cache entry
        evictCacheEntry();
    }

    // Add the cache entry to the cache
    addToCache(cache_entry);
}

// Define the function to evict a cache entry from the cache
void evictCacheEntry() {
    // Get the least recently used cache entry
    CacheEntry *least_recently_used = getLeastRecentlyUsedCacheEntry();

    // Remove the least recently used cache entry from the cache
    removeFromCache(least_recently_used);
}

// Define the function to get the least recently used cache entry
CacheEntry *getLeastRecentlyUsedCacheEntry() {
    // Initialize the least recently used cache entry
    CacheEntry *least_recently_used = NULL;

    // Iterate over the cache entries and find the least recently used one
    for (int i = 0; i < getCacheSize(); i++) {
        CacheEntry *cache_entry = getCacheEntry(i);
