    int bytes_read = read(fd, buffer, 1024);
    if (bytes_read == -1) {
        perror("Failed to read from file");
        return;
    }

    // Close the file
    close(fd);

    // Split the contents of the buffer into individual integers using strtok()
    char *token = strtok(buffer, " ");
    int num_integers = 0;
    while (token != NULL) {
        num_integers++;
        token = strtok(NULL, " ");
    }

    // Allocate memory for the list of integers and read them into the array
    int *integers = (int*)malloc(num_integers * sizeof(int));
    token = strtok(buffer, " ");
    for (int i = 0; i < num_integers; i++) {
        integers[i] = atoi(token);
        token = strtok(NULL, " ");
    }

    // Determine the largest integer in the list and calculate the average of all integers
    int largest_integer = 0;
    float average = 0.0f;
    for (int i = 0; i < num_integers; i++) {
        if (integers[i] > largest_integer) {
            largest_integer = integers[i];
        }
        average += integers[i];
    }
    average /= num_integers;

    // Print the results
    printf("Largest integer: %d\n", largest_integer);
    printf("Average of all integers: %.2f\n", average);
}
