// Define the function to handle concurrent access to the file system when checking for filename uniqueness
void check_filename_uniqueness(const char* filename) {
    // Open the directory containing the file
    DIR *dir = opendir(".");

    // Check for errors in opening the directory
    if (dir == NULL) {
        printf("Error: Could not open directory\n");
        exit(1);
    }

    // Read the contents of the directory
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(filename, entry->d_name) == 0) {
            printf("Error: File %s already exists\n", filename);
            exit(1);
        }
    }

    // Close the directory
    closedir(dir);
}

