        for (int i = 0; i < MAX_RANDOM_DIGITS; i++) {
            random_digits[i] = rand() % 10 + '0';
        }
        strcat(new_filename, random_digits);
        free(random_digits);
        struct stat file_stat;
        if (stat(new_filename, &file_stat) == -1 && errno == ENOENT) {
            break;
        }
        num_retries++;
    }
    if (num_retries >= MAX_NUM_RETRIES) {
        fprintf(stderr, "Error: Could not find a unique filename after %d retries\n", MAX_NUM_RETRIES);
