    }
    strcpy(new_filename + strlen(new_filename) - 3, DEFAULT_FILE_TYPE);

    // Open the file and write the data
    int fd = open(new_filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    write(fd, pdu, sizeof(MAC_PDU));
    close(fd);
}

