void lock(Lock *lock) {
    pthread_mutex_lock(&lock->mutex);
}

void unlock(Lock *lock) {
    pthread_mutex_unlock(&lock->mutex);
}

// Memory pool for efficient memory allocation
typedef struct {
    void **pool;
    size_t capacity;
    size_t size;
} Pool;

void initPool(Pool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->size = 0;
    pool->pool = malloc(sizeof(void *) * capacity);
}

void freePool(Pool *pool) {
    free(pool->pool);
}

void *allocate(Pool *pool, size_t size) {
    if (pool->size + size > pool->capacity) {
        // Reallocate memory pool to accommodate new allocation
        pool->capacity = pool->capacity * 2;
        pool->pool = realloc(pool->pool, sizeof(void *) * pool->capacity);
    }
    void *ptr = &pool->pool[pool->size];
    pool->size += size;
    return ptr;
}

