void lte_ue_context_list_init(size_t capacity, int seed) {
    // Allocate memory for the list elements
    lte_ue_context_info_t *elements = malloc(capacity * sizeof(lte_ue_context_info_t));
    if (elements == NULL) {
        fprintf(stderr, "Failed to allocate memory for LTE UE Context Information structures\n");
        exit(1);
    }

    // Initialize the list elements with random values
    for (size_t i = 0; i < capacity; i++) {
        elements[i].ue_id = rand() % 1000 + 1;
        elements[i].nas_message = malloc(1024 * sizeof(char));
        if (elements[i].nas_message == NULL) {
            fprintf(stderr, "Failed to allocate memory for NAS message\n");
            exit(1);
        }
        strcpy(elements[i].nas_message, "Random NAS message");
        elements[i].mme_identity = rand() % 10 + 1;
    }

    // Initialize the list with the given capacity and seed
    lte_ue_context_list_t *list = malloc(sizeof(lte_ue_context_list_t));
    if (list == NULL) {
        fprintf(stderr, "Failed to allocate memory for LTE UE Context List\n");
        exit(1);
    }
    list->capacity = capacity;
    list->size = 0;
    list->elements = elements;
}

// Add a new element to the list with a given UE ID, NAS message, and MME identity
void lte_ue_context_list_add(lte_ue_context_list_t *list, int ue_id, char *nas_message, int mme_identity) {
    // Acquire the lock to synchronize access to the list
    pthread_mutex_lock(&lock);

    // Check if the list is full and needs to be resized
    if (list->size == list->capacity) {
        // Double the capacity of the list
        size_t new_capacity = list->capacity * 2;
        lte_ue_context_info_t *new_elements = realloc(list->elements, new_capacity * sizeof(lte_ue_context_info_t));
        if (new_elements == NULL) {
            fprintf(stderr, "Failed to resize LTE UE Context List\n");
            exit(1);
        }
        list->capacity = new_capacity;
        list->elements = new_elements;
    }

    // Add the new element to the end of the list
    list->elements[list->size].ue_id = ue_id;
    list->elements[list->size].nas_message = nas_message;
    list->elements[list->size].mme_identity = mme_identity;
    list->size++;

    // Release the lock to allow other threads to access the list
    pthread_mutex_unlock(&lock);
}

// Remove an element from the list with a given UE ID
void lte_ue_context_list_remove(lte_ue_context_list_t *list, int ue_id) {
    // Acquire the lock to synchronize access to the list
    pthread_mutex_lock(&lock);

    // Find the element with the given UE ID in the list
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->elements[i].ue_id == ue_id) {
            break;
        }
    }

    // Check if the element was found in the list
    if (i == list->size) {
        fprintf(stderr, "UE ID not found in LTE UE Context List\n");
        exit(1);
    }

    // Remove the element from the list by shifting all elements after it one position to the left
    for (size_t j = i; j < list->size - 1; j++) {
        list->elements[j] = list->elements[j + 1];
    }
    list->size--;

    // Release the lock to allow other threads to access the list
    pthread_mutex_unlock(&lock);
}

// Serialize the list of LTE UE Context Information structures into a binary format
void lte_ue_context_list_serialize(lte_ue_context_list_t *list, char *buffer) {
    // Acquire the lock to synchronize access to the list
    pthread_mutex_lock(&lock);

    // Write the size of the list to the buffer
    size_t size = list->size;
    memcpy(buffer, &size, sizeof(size));
    buffer += sizeof(size);

    // Write each element in the list to the buffer
    for (size_t i = 0; i < list->size; i++) {
        lte_ue_context_info_t *element = &list->elements[i];
        memcpy(buffer, &element->ue_id, sizeof(int));
        buffer += sizeof(int);
        memcpy(buffer, element->nas_message, 1024 * sizeof(char));
        buffer += 1024 * sizeof(char);
        memcpy(buffer, &element->mme_identity, sizeof(int));
        buffer += sizeof(int);
    }

    // Release the lock to allow other threads to access the list
    pthread_mutex_unlock(&lock);
}

// Deserialize a binary format into a list of LTE UE Context Information structures
void lte_ue_context_list_deserialize(char *buffer, size_t size) {
    // Acquire the lock to synchronize access to the list
    pthread_mutex_lock(&lock);

    // Read the size of the list from the buffer
    size_t list_size = 0;
    memcpy(&list_size, buffer, sizeof(size));
    buffer += sizeof(size);

    // Allocate memory for the list elements
    lte_ue_context_info_t *elements = malloc(list_size * sizeof(lte_ue_context_info_t));
    if (elements == NULL) {
        fprintf(stderr, "Failed to allocate memory for LTE UE Context Information structures\n");
        exit(1);
    }

    // Read each element in the list from the buffer
    for (size_t i = 0; i < list_size; i++) {
        lte_ue_context_info_t *element = &elements[i];
        memcpy(&element->ue_id, buffer, sizeof(int));
        buffer += sizeof(int);
        element->nas_message = malloc(1024 * sizeof(char));
        if (element->nas_message == NULL) {
            fprintf(stderr, "Failed to allocate memory for NAS message\n");
            exit(1);
        }
        memcpy(element->nas_message, buffer, 1024 * sizeof(char));
        buffer += 1024 * sizeof(char);
        memcpy(&element->mme_identity, buffer, sizeof(int));
        buffer += sizeof(int);
    }

    // Initialize the list with the deserialized elements
    lte_ue_context_list_t *list = malloc(sizeof(lte_ue_context_list_t));
    if (list == NULL) {
        fprintf(stderr, "Failed to allocate memory for LTE UE Context List\n");
        exit(1);
    }
    list->capacity = list_size;
    list->size = list_size;
    list->elements = elements;

    // Release the lock to allow other threads to access the list
    pthread_mutex_unlock(&lock);
}
