    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* data;
} NFAPI_CRC_INDICATION_POOL_T;

// Define the function to create and populate a list of structures
NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_create(size_t num_structures, uint32_t seed, size_t initial_capacity) {
    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_LIST_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        fprintf(stderr, "Error: Failed to allocate memory for the list of structures\n");
        return NULL;
    }

    // Initialize the list with the requested number of structures and initial capacity
    list->capacity = initial_capacity;
    list->size = num_structures;
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    if (!list->data) {
        fprintf(stderr, "Error: Failed to allocate memory for the list of structures\n");
        free(list);
        return NULL;
    }

    // Populate the list with random values
    srand(seed);
    for (size_t i = 0; i < num_structures; i++) {
        list->data[i].rx_ue_information_tag = rand() % 65535;
        list->data[i].rnti = rand() % 4294967295;
        list->data[i].crc_indication_rel8_tag = rand() % 255;
        list->data[i].crcflag = (rand() % 2) ? true : false;
    }

    return list;
}

// Define the function to resize the list of structures if necessary
void nfapi_crc_indication_list_resize(NFAPI_CRC_INDICATION_LIST_T* list, size_t new_capacity) {
    // Check if the new capacity is larger than the current capacity
    if (new_capacity > list->capacity) {
        // Reallocate memory for the list of structures with the new capacity
        NFAPI_CRC_INDICATION_PDU_T* data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!data) {
            fprintf(stderr, "Error: Failed to resize the list of structures\n");
            return;
        }

        // Update the capacity and data pointers in the list
        list->capacity = new_capacity;
        list->data = data;
    }
}

