    // Acquire the lock for thread-safe access
    pthread_mutex_lock(&mutex);

    // Check if the list needs to be resized
    if (list->size == list->capacity) {
        nfapi_crc_indication_list_resize(list, list->capacity * 2);
    }

    // Add the structure to the list
    list->data[list->size++] = *structure;

    // Release the lock for thread-safe access
    pthread_mutex_unlock(&mutex);
}

