// Structure to store metadata for each TCP connection
typedef struct {
    char source_ip[16];
    char destination_ip[16];
    uint16_t port;
    int status_flags;
    time_t last_activity;
} tcp_connection_metadata_t;

// Function to initialize the array of TCP connections with N connections
void init_tcp_connections(int n) {
    // Allocate memory for the array of TCP connections
    tcp_connection_metadata_t* connections = (tcp_connection_metadata_t*)malloc(n * sizeof(tcp_connection_metadata_t));

    // Initialize each connection in the array with a unique combination of IP and port
    for (int i = 0; i < n; i++) {
        sprintf(connections[i].source_ip, "192.168.1.%d", i);
        connections[i].port = i + 1000;
        connections[i].status_flags = 0;
        connections[i].last_activity = time(NULL);
    }
}

// Function to update the last activity timestamp for a given connection
void update_connection_timestamp(tcp_connection_metadata_t* connection) {
    // Update the last activity timestamp for the given connection
    connection->last_activity = time(NULL);
}

// Function to add a new connection to the array while maintaining uniqueness and managing memory efficiently
void add_new_connection(tcp_connection_metadata_t* connection) {
    // Check if the new connection is already in the array
    for (int i = 0; i < n; i++) {
        if (strcmp(connections[i].source_ip, connection->source_ip) == 0 && connections[i].port == connection->port) {
            // If the new connection is already in the array, update its status flags and last activity timestamp
            connections[i].status_flags |= connection->status_flags;
            update_connection_timestamp(&connections[i]);
            return;
        }
    }

    // If the new connection is not in the array, add it to the end of the array and update its last activity timestamp
    connections[n++] = *connection;
    update_connection_timestamp(connection);
}

// Function to clean up all allocated memory when the function exits
void cleanup() {
    // Free the memory allocated for the array of TCP connections
    free(connections);
}
