        return;
    }

    // Allocate memory for the initialization vector
    unsigned char *initialization_vector = (unsigned char*)malloc(sizeof(unsigned char));
    if (!initialization_vector) {
        printf("Error: Failed to allocate memory for the initialization vector\n");
        free(encryption_key);
        return;
    }

    // Set the encryption key and initialization vector
    *encryption_key = EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char*)password, strlen(password), 1000, NULL, NULL);
    *initialization_vector = iv;
}
