// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to generate and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_populate_list(int num_files, char **file_paths) {
    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_files);
    if (list == NULL) {
        perror("Error allocating memory for list");
        exit(EXIT_FAILURE);
    }

    // Loop through each file path and read the integers from each file
    for (int i = 0; i < num_files; i++) {
        char *file_path = file_paths[i];
        int fd = open(file_path, O_RDONLY);
        if (fd == -1) {
            perror("Error opening file");
            exit(EXIT_FAILURE);
        }

        // Read the integers from the file and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
        while (1) {
            int integer;
            if (read(fd, &integer, sizeof(int)) == 0) {
                break;
            }
            list[i].RX_UE_INFORMATION_TAG = i + 1;
            list[i].RNTI = integer;
            list[i].CRC_INDICATION_REL8_TAG = 0;
            list[i].CRCFLAG = rand() % 2;
        }

        // Close the file
        close(fd);
    }

    // Find the largest integer across all files and calculate the average of all integers
    int largest_integer = INT_MIN;
    double average = 0.0;
    for (int i = 0; i < num_files; i++) {
        if (list[i].RNTI > largest_integer) {
            largest_integer = list[i].RNTI;
        }
        average += list[i].RNTI;
    }
    average /= num_files;

    // Print the results
    printf("Largest integer: %d\n", largest_integer);
    printf("Average of all integers: %.2f\n", average);

    // Free the memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures
    free(list);
}

// Define the function to handle error cases
void handle_error(char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

int main(int argc, char **argv) {
    // Check if the correct number of command-line arguments is provided
    if (argc < 3) {
        handle_error("Incorrect number of command-line arguments");
    }

    // Get the number of files and their file paths from the command-line arguments
    int num_files = argc - 2;
    char **file_paths = malloc(sizeof(char *) * num_files);
    if (file_paths == NULL) {
        handle_error("Error allocating memory for file paths");
    }
    for (int i = 0; i < num_files; i++) {
        file_paths[i] = argv[i + 2];
    }

    // Generate and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    generate_populate_list(num_files, file_paths);

    return 0;
}
