void handleAdvancedDataProcessingAndProfileCaching(int argc, char** argv) {
    // Check if there are enough command-line arguments provided
    if (argc < 2) {
        printf("Not enough command-line arguments provided\n");
        return;
    }

    // Initialize the file processing data structure
