// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of NFAPI_CRC_INDICATION_PDU_T structures
static NFAPI_CRC_INDICATION_PDU_T *crc_indication_list = NULL;

// Define the mutex for thread safety
static pthread_mutex_t crc_indication_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the condition variable for signaling when a new element is added to the list
static pthread_cond_t crc_indication_cv = PTHREAD_COND_INITIALIZER;

// Define the file descriptor for logging creation events
static int log_fd = -1;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_crc_indication_list(int num_elements) {
    // Allocate memory for the list
    crc_indication_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the mutex and condition variable
    pthread_mutex_init(&crc_indication_mutex, NULL);
    pthread_cond_init(&crc_indication_cv, NULL);

    // Set the file descriptor for logging creation events
    log_fd = open("crc_indication_log.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);

    // Populate the list with random values
    srand(time(NULL));
    for (int i = 0; i < num_elements; i++) {
        crc_indication_list[i].rx_ue_information_tag = rand() % 10000;
        crc_indication_list[i].rnti = rand() % 100000000;
        crc_indication_list[i].crc_indication_rel8_tag = rand() % 256;
        crc_indication_list[i].crcflag = (rand() % 2) == 0;
    }
}

// Function to add a new element to the list
void add_element(NFAPI_CRC_INDICATION_PDU_T *new_element) {
    // Lock the mutex
    pthread_mutex_lock(&crc_indication_mutex);

    // Check if the RNTI value is already in the list
    for (int i = 0; i < num_elements; i++) {
        if (new_element->rnti == crc_indication_list[i].rnti) {
            pthread_mutex_unlock(&crc_indication_mutex);
            return;
        }
    }

    // Add the new element to the list
    crc_indication_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(crc_indication_list, (num_elements + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    crc_indication_list[num_elements] = *new_element;
    num_elements++;

    // Unlock the mutex and signal the condition variable
    pthread_mutex_unlock(&crc_indication_mutex);
    pthread_cond_signal(&crc_indication_cv);
}

// Function to remove an element from the list
void remove_element(int index) {
    // Lock the mutex
    pthread_mutex_lock(&crc_indication_mutex);

    // Check if the index is valid
    if (index < 0 || index >= num_elements) {
        pthread_mutex_unlock(&crc_indication_mutex);
        return;
    }

    // Remove the element from the list
    NFAPI_CRC_INDICATION_PDU_T *temp = (NFAPI_CRC_INDICATION_PDU_T *)malloc((num_elements - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < index; i++) {
        temp[i] = crc_indication_list[i];
    }
    for (int i = index + 1; i < num_elements; i++) {
        temp[i - 1] = crc_indication_list[i];
    }
    free(crc_indication_list);
    crc_indication_list = temp;
    num_elements--;

    // Unlock the mutex and signal the condition variable
    pthread_mutex_unlock(&crc_indication_mutex);
    pthread_cond_signal(&crc_indication_cv);
}

// Function to iterate over the list
void iterate_list(void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    // Lock the mutex
    pthread_mutex_lock(&crc_indication_mutex);

    // Iterate over the list and call the callback function for each element
    for (int i = 0; i < num_elements; i++) {
        callback(&crc_indication_list[i]);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&crc_indication_mutex);
}

// Function to log creation events to a specified file
void log_creation(NFAPI_CRC_INDICATION_PDU_T *new_element) {
    // Lock the mutex
    pthread_mutex_lock(&crc_indication_mutex);

    // Write the creation event to the file
    char log_buffer[1024];
    sprintf(log_buffer, "%d %d %d %d\n", new_element->rx_ue_information_tag, new_element->rnti, new_element->crc_indication_rel8_tag, new_element->crcflag);
    write(log_fd, log_buffer, strlen(log_buffer));

    // Unlock the mutex
    pthread_mutex_unlock(&crc_indication_mutex);
}
