// Function to initialize and manage the list of NFAPI_CELL_CONFIG structures
void init_cell_configs(size_t num_cells) {
    // Allocate memory for the list of NFAPI_CELL_CONFIG structures
    cell_configs = (NFAPI_CELL_CONFIG *)malloc(num_cells * sizeof(NFAPI_CELL_CONFIG));
    if (!cell_configs) {
        printf("Error: Failed to allocate memory for the list of NFAPI_CELL_CONFIG structures\n");
        return;
    }

    // Initialize each structure in the list with default values
    for (size_t i = 0; i < num_cells; i++) {
        cell_configs[i].frequency_band = 0;
        cell_configs[i].bandwidth = 0;
        cell_configs[i].cell_identity = 0;
    }
}

// Function to add a new NFAPI_CELL_CONFIG structure to the list
void add_cell_config(NFAPI_CELL_CONFIG *new_config) {
    // Acquire the lock on the cell configuration list
    pthread_mutex_lock(&cell_configs_lock);

    // Check if the new configuration overlaps with any existing configurations
    for (size_t i = 0; i < num_cells; i++) {
        NFAPI_CELL_CONFIG *current_config = &cell_configs[i];
        if (new_config->frequency_band == current_config->frequency_band && new_config->bandwidth == current_config->bandwidth) {
            // The new configuration overlaps with an existing configuration, so we cannot add it to the list
            pthread_mutex_unlock(&cell_configs_lock);
            return;
        }
    }

    // Add the new configuration to the end of the list
    cell_configs[num_cells++] = *new_config;

    // Release the lock on the cell configuration list
    pthread_mutex_unlock(&cell_configs_lock);
}

// Function to update a NFAPI_CELL_CONFIG structure in the list
void update_cell_config(NFAPI_CELL_CONFIG *updated_config) {
    // Acquire the lock on the cell configuration list
    pthread_mutex_lock(&cell_configs_lock);

    // Find the index of the NFAPI_CELL_CONFIG structure to update
    size_t i = 0;
    for (; i < num_cells; i++) {
        NFAPI_CELL_CONFIG *current_config = &cell_configs[i];
        if (updated_config->frequency_band == current_config->frequency_band && updated_config->bandwidth == current_config->bandwidth) {
            break;
        }
    }

    // Update the NFAPI_CELL_CONFIG structure at the found index
    if (i < num_cells) {
        cell_configs[i] = *updated_config;
    } else {
        // The updated configuration was not found in the list, so we cannot update it
        pthread_mutex_unlock(&cell_configs_lock);
        return;
    }

    // Release the lock on the cell configuration list
    pthread_mutex_unlock(&cell_configs_lock);
}

// Function to remove a NFAPI_CELL_CONFIG structure from the list
void remove_cell_config(NFAPI_CELL_CONFIG *removed_config) {
    // Acquire the lock on the cell configuration list
    pthread_mutex_lock(&cell_configs_lock);

    // Find the index of the NFAPI_CELL_CONFIG structure to remove
    size_t i = 0;
    for (; i < num_cells; i++) {
        NFAPI_CELL_CONFIG *current_config = &cell_configs[i];
        if (removed_config->frequency_band == current_config->frequency_band && removed_config->bandwidth == current_config->bandwidth) {
            break;
        }
    }

    // Remove the NFAPI_CELL_CONFIG structure at the found index
    if (i < num_cells) {
        memmove(&cell_configs[i], &cell_configs[i + 1], (num_cells - i - 1) * sizeof(NFAPI_CELL_CONFIG));
        num_cells--;
    } else {
        // The removed configuration was not found in the list, so we cannot remove it
        pthread_mutex_unlock(&cell_configs_lock);
        return;
    }

    // Release the lock on the cell configuration list
    pthread_mutex_unlock(&cell_configs_lock);
}

