    printf("Logging configuration change: frequency band = %d, bandwidth = %d, cell identity = %d\n", changed_config->frequency_band, changed_config->bandwidth, changed_config->cell_identity);

    // Release the lock on the cell configuration list
    pthread_mutex_unlock(&cell_configs_lock);
