#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

// Define the structure for connection metadata
typedef struct {
    char source_ip[16];
    char destination_ip[16];
    uint16_t port;
    int status_flags;
    time_t last_activity;
} connection_metadata_t;

// Define the array of connections
connection_metadata_t *connections = NULL;
size_t num_connections = 0;
pthread_mutex_t connections_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the array with N connections
void init_connections(size_t n) {
    // Allocate memory for the array of connections
    connections = (connection_metadata_t *)malloc(n * sizeof(connection_metadata_t));
    if (!connections) {
        perror("Failed to allocate memory for connections");
        exit(1);
    }

    // Initialize each connection with a unique identifier
    for (size_t i = 0; i < n; i++) {
        sprintf(connections[i].source_ip, "192.168.1.%d", i + 1);
        connections[i].port = i + 1;
        connections[i].status_flags = 0;
        connections[i].last_activity = time(NULL);
    }

    num_connections = n;
}

// Update the last activity timestamp for a given connection
void update_connection_timestamp(const char *source_ip, uint16_t port) {
    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&connections_lock);

    // Find the index of the connection with the specified source IP and port
    size_t i;
    for (i = 0; i < num_connections; i++) {
        if (strcmp(source_ip, connections[i].source_ip) == 0 && port == connections[i].port) {
            break;
        }
    }

    // Update the last activity timestamp for the connection
    if (i < num_connections) {
        connections[i].last_activity = time(NULL);
    } else {
        printf("Connection not found\n");
    }

    // Release the lock
    pthread_mutex_unlock(&connections_lock);
}

// Add a new connection to the array
void add_connection(const char *source_ip, uint16_t port) {
    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&connections_lock);

    // Find an empty slot in the array for the new connection
    size_t i;
    for (i = 0; i < num_connections; i++) {
        if (strcmp(source_ip, connections[i].source_ip) == 0 && port == connections[i].port) {
            break;
        }
    }

    // If no empty slot is found, allocate a new array with double the size of the current one
    if (i == num_connections) {
        connection_metadata_t *new_connections = (connection_metadata_t *)malloc(num_connections * 2 * sizeof(connection_metadata_t));
        if (!new_connections) {
            perror("Failed to allocate memory for new connections");
            exit(1);
        }

        // Copy the old array to the new one
        memcpy(new_connections, connections, num_connections * sizeof(connection_metadata_t));

        // Free the old array and update the pointer to the new one
        free(connections);
        connections = new_connections;
        num_connections *= 2;
    }

    // Initialize the new connection with a unique identifier
    sprintf(connections[i].source_ip, "192.168.1.%d", i + 1);
    connections[i].port = i + 1;
    connections[i].status_flags = 0;
    connections[i].last_activity = time(NULL);

    // Release the lock
    pthread_mutex_unlock(&connections_lock);
}

// Remove a connection from the array
void remove_connection(const char *source_ip, uint16_t port) {
    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&connections_lock);

    // Find the index of the connection with the specified source IP and port
    size_t i;
    for (i = 0; i < num_connections; i++) {
        if (strcmp(source_ip, connections[i].source_ip) == 0 && port == connections[i].port) {
            break;
        }
    }

    // If the connection is found, move the last element to the vacant slot and reduce the size of the array by one
    if (i < num_connections) {
        memmove(connections + i, connections + i + 1, (num_connections - i - 1) * sizeof(connection_metadata_t));
        num_connections--;
    } else {
        printf("Connection not found\n");
    }

    // Release the lock
    pthread_mutex_unlock(&connections_lock);
}
