// Define the function to dynamically manage and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
void populate_crc_indication_array(int argc, char **argv) {
    // Initialize the pool of reusable structures if necessary
    if (pool == NULL) {
        pool = malloc(POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memset(pool, 0, POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

