// Define the structure for storing connection metadata
typedef struct {
    char source_ip[16];
    char destination_ip[16];
    uint16_t port;
    uint8_t status_flags;
    time_t last_activity;
    // Additional context-specific metadata fields
} connection_metadata_t;

// Define the array of connections
connection_metadata_t *connections = NULL;
size_t num_connections = 0;

// Function to initialize the array with N connections
void init_connections(size_t n) {
    // Allocate memory for the array of connections
    connections = (connection_metadata_t *)malloc(n * sizeof(connection_metadata_t));
    if (!connections) {
        printf("Error: Failed to allocate memory for connections\n");
        return;
    }
    // Initialize each connection with a unique combination of IP and port
    for (size_t i = 0; i < n; i++) {
        sprintf(connections[i].source_ip, "192.168.1.%d", i);
        connections[i].port = 80 + i;
        connections[i].status_flags = 0;
        connections[i].last_activity = time(NULL);
    }
    num_connections = n;
}

// Function to update the last activity timestamp for a given connection
void update_connection_timestamp(const char *source_ip, uint16_t port) {
    // Find the index of the connection with the specified IP and port
    size_t i = 0;
    while (i < num_connections && strcmp(connections[i].source_ip, source_ip) != 0 || connections[i].port != port) {
        i++;
    }
    // If the connection was found, update its last activity timestamp
    if (i < num_connections) {
        connections[i].last_activity = time(NULL);
    } else {
        printf("Error: Connection not found\n");
    }
}

