        header.rnti |= rand() & 0xFF;
    }
    for (int i = 0; i < 2; i++) {
        header.sequence_number <<= 8;
        header.sequence_number |= rand() & 0xFF;
    }
    // Generate a random SDU for the MAC PDU
    MACSDU sdu;
    memset(&sdu, 0, sizeof(MACSDU));
    srand(time(NULL));
    for (int i = 0; i < sdu.length; i++) {
        sdu.data[i] = rand() & 0xFF;
    }
    // Generate a random IE list for the MAC PDU
    IE_LIST *ie_list = malloc(sizeof(IE_LIST));
    memset(ie_list, 0, sizeof(IE_LIST));
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        ie_list->next = malloc(sizeof(IE_LIST));
        memset(ie_list->next, 0, sizeof(IE_LIST));
        for (int j = 0; j < 2; j++) {
            ie_list->ie_id[j] = rand() & 0xFF;
        }
        for (int j = 0; j < 2; j++) {
            ie_list->ie_length <<= 8;
            ie_list->ie_length |= rand() & 0xFF;
        }
        ie_list->ie_data = malloc(ie_list->ie_length);
        for (int j = 0; j < ie_list->ie_length; j++) {
            ie_list->ie_data[j] = rand() & 0xFF;
        }
        ie_list = ie_list->next;
    }
    // Insert the MAC PDU into the hash table
    insert_rnti(rnti);
}

// Define the function to encrypt a MAC PDU using OpenSSL
void encrypt_mac_pdu(MAC_PDU *pdu, char *password) {
    // Derive the encryption key from the password using a KDF
    unsigned char key[32];
    memset(key, 0, sizeof(key));
    EVP_BytesToKey(EVP_aes_128_cbc(), EVP_sha1(), NULL, (unsigned char *)password, strlen(password), 1, key, NULL);
    // Generate a random initialization vector for the encryption context
    unsigned char iv[16];
    memset(iv, 0, sizeof(iv));
    srand(time(NULL));
    for (int i = 0; i < 16; i++) {
        iv[i] = rand() & 0xFF;
    }
    // Encrypt the MAC PDU using AES-CBC with the derived key and IV
    EVP_CIPHER_CTX *ctx;
    int len;
    unsigned char *ciphertext;
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_128_cbc(), key, iv);
    EVP_EncryptUpdate(ctx, NULL, &len, (unsigned char *)pdu, sizeof(MAC_PDU));
    ciphertext = malloc(len + 16);
    memset(ciphertext, 0, len + 16);
    EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char *)pdu, sizeof(MAC_PDU));
    EVP_EncryptFinal(ctx, ciphertext + len, &len);
    EVP_CIPHER_CTX_free(ctx);
}

// Define the function to decrypt a MAC PDU using OpenSSL
void decrypt_mac_pdu(MAC_PDU *pdu, char *password) {
    // Derive the encryption key from the password using a KDF
    unsigned char key[32];
    memset(key, 0, sizeof(key));
    EVP_BytesToKey(EVP_aes_128_cbc(), EVP_sha1(), NULL, (unsigned char *)password, strlen(password), 1, key, NULL);
    // Generate a random initialization vector for the decryption context
    unsigned char iv[16];
    memset(iv, 0, sizeof(iv));
    srand(time(NULL));
    for (int i = 0; i < 16; i++) {
        iv[i] = rand() & 0xFF;
    }
    // Decrypt the MAC PDU using AES-CBC with the derived key and IV
    EVP_CIPHER_CTX *ctx;
    int len;
    unsigned char *plaintext;
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit(ctx, EVP_aes_128_cbc(), key, iv);
    EVP_DecryptUpdate(ctx, NULL, &len, (unsigned char *)pdu, sizeof(MAC_PDU));
    plaintext = malloc(len + 16);
    memset(plaintext, 0, len + 16);
    EVP_DecryptUpdate(ctx, plaintext, &len, (unsigned char *)pdu, sizeof(MAC_PDU));
    EVP_DecryptFinal(ctx, plaintext + len, &len);
    EVP_CIPHER_CTX_free(ctx);
}

