// Define the function to manage the TCP connection array
void manage_tcp_connections(tcp_connection_array_t *conn_array) {
    // Initialize the mutex for synchronizing access to the connection array
    pthread_mutex_t conn_array_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize the condition variable for signaling new connections
    pthread_cond_t new_connection_cv = PTHREAD_COND_INITIALIZER;

    // Initialize the condition variable for signaling closed connections
    pthread_cond_t closed_connection_cv = PTHREAD_COND_INITIALIZER;

