        // Check if there are any closed connections to be processed
        if (num_active_connections > 0 && conn_array->num_connections < num_active_connections) {
            // Decrement the number of active connections
            num_active_connections--;

            // Signal the condition variable for closed connections
            pthread_cond_signal(&closed_connection_cv);
