#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Define the structure for a resource node
typedef struct ResourceNode {
    int id;
    time_t timestamp;
    int usageCount;
    bool active;
} ResourceNode;

// Define the structure for a MAC PDU
typedef struct MAC_PDU {
    MAC_HEADER header;
    MACSDU macSdu;
    IE_LIST ieList;
} MAC_PDU;

// Define the structure for a MAC SDU
typedef struct MACSDU {
    int size;
    char data[];
} MACSDU;

// Define the structure for an IE list
typedef struct IE_LIST {
    int numIEs;
    IE ieList[];
} IE_LIST;

// Define the structure for an IE
typedef struct IE {
    int id;
    int length;
    char data[];
} IE;

// Define the structure for a hash table with chaining
typedef struct HashTable {
    int size;
    int numEntries;
    ResourceNode *entries[];
} HashTable;

// Function to generate a unique MAC PDU by appending a random number to the original filename until no conflicts exist in the current directory
int generateUniqueMACPDU(const char *filename) {
    // Generate a random number between 0 and 10000
    int randomNumber = rand() % 10000;

    // Append the random number to the original filename
    char newFilename[strlen(filename) + 5];
    sprintf(newFilename, "%s_%d", filename, randomNumber);

    // Check if the new filename exists in the current directory
    struct stat buffer;
    if (stat(newFilename, &buffer) == 0) {
        return generateUniqueMACPDU(filename);
    } else {
        return newFilename;
    }
}

// Function to dynamically allocate and populate an array of MAC PDU structures
MAC_PDU *allocateAndPopulateMACPDUArray(int numEntries) {
    // Allocate memory for the array of MAC PDU structures
    MAC_PDU *macPduArray = (MAC_PDU *)malloc(numEntries * sizeof(MAC_PDU));

    // Populate each MAC PDU structure with a valid header, SDU, and IE list
    for (int i = 0; i < numEntries; i++) {
        macPduArray[i].header.rnti = generateUniqueRNTI();
        macPduArray[i].macSdu.size = rand() % 1000 + 1;
        for (int j = 0; j < macPduArray[i].macSdu.size; j++) {
            macPduArray[i].macSdu.data[j] = rand() % 256;
        }
        macPduArray[i].ieList.numIEs = rand() % 10 + 1;
        for (int j = 0; j < macPduArray[i].ieList.numIEs; j++) {
            macPduArray[i].ieList.ieList[j].id = generateUniqueIEID();
            macPduArray[i].ieList.ieList[j].length = rand() % 100 + 1;
            for (int k = 0; k < macPduArray[i].ieList.ieList[j].length; k++) {
                macPduArray[i].ieList.ieList[j].data[k] = rand() % 256;
            }
        }
    }

    return macPduArray;
}

// Function to dynamically allocate and populate an array of resource nodes
ResourceNode *allocateAndPopulateResourceNodeArray(int numEntries) {
    // Allocate memory for the array of resource nodes
    ResourceNode *resourceNodeArray = (ResourceNode *)malloc(numEntries * sizeof(ResourceNode));

    // Populate each resource node with a unique ID, timestamp, usage count, and status flag
    for (int i = 0; i < numEntries; i++) {
        resourceNodeArray[i].id = generateUniqueID();
        resourceNodeArray[i].timestamp = time(NULL);
        resourceNodeArray[i].usageCount = rand() % 100 + 1;
        resourceNodeArray[i].active = (rand() % 2) ? true : false;
    }

    return resourceNodeArray;
}

// Function to dynamically allocate and populate an array of hash tables with chaining
HashTable *allocateAndPopulateHashTableArray(int numEntries) {
    // Allocate memory for the array of hash tables with chaining
    HashTable *hashTableArray = (HashTable *)malloc(numEntries * sizeof(HashTable));

    // Populate each hash table with a unique size and number of entries
    for (int i = 0; i < numEntries; i++) {
        hashTableArray[i].size = rand() % 100 + 1;
        hashTableArray[i].numEntries = 0;
        hashTableArray[i].entries = (ResourceNode **)malloc(hashTableArray[i].size * sizeof(ResourceNode *));
    }

    return hashTableArray;
}

// Function to generate a unique RNTI
int generateUniqueRNTI() {
    // Generate a random number between 0 and 10000
    int randomNumber = rand() % 10000;

    // Check if the generated RNTI is already in use
    while (isRNTIInUse(randomNumber)) {
        randomNumber = rand() % 10000;
    }

    return randomNumber;
}

// Function to generate a unique IE ID
int generateUniqueIEID() {
    // Generate a random number between 0 and 10000
    int randomNumber = rand() % 10000;

    // Check if the generated IE ID is already in use
    while (isIEIDInUse(randomNumber)) {
        randomNumber = rand() % 10000;
    }

    return randomNumber;
}

// Function to check if a given RNTI is already in use
bool isRNTIInUse(int rnti) {
    // Check if the hash table with chaining contains the given RNTI
    for (int i = 0; i < hashTableArray->numEntries; i++) {
        if (hashTableArray[i].entries[rnti] != NULL) {
            return true;
        }
    }

    return false;
}

// Function to check if a given IE ID is already in use
bool isIEIDInUse(int ieId) {
    // Check if the hash table with chaining contains the given IE ID
    for (int i = 0; i < hashTableArray->numEntries; i++) {
        if (hashTableArray[i].entries[ieId] != NULL) {
            return true;
        }
    }

    return false;
}

// Function to insert a resource node into the hash table with chaining
void insertResourceNode(int rnti, ResourceNode *resourceNode) {
    // Check if the hash table with chaining is full
    if (hashTableArray->numEntries == hashTableArray->size) {
        // Resize the hash table with chaining to accommodate more entries
        resizeHashTable(hashTableArray);
    }

    // Insert the resource node into the hash table with chaining
    hashTableArray[rnti].entries[resourceNode->id] = resourceNode;
    hashTableArray[rnti].numEntries++;
}

// Function to resize a hash table with chaining
void resizeHashTable(HashTable *hashTable) {
    // Allocate memory for the new hash table with chaining
    HashTable *newHashTable = (HashTable *)malloc((hashTable->size + 1) * sizeof(HashTable));

    // Copy the contents of the old hash table with chaining to the new hash table with chaining
    for (int i = 0; i < hashTable->numEntries; i++) {
        newHashTable[i].size = hashTable->size + 1;
        newHashTable[i].numEntries = hashTable->numEntries;
        newHashTable[i].entries = (ResourceNode **)malloc(newHashTable[i].size * sizeof(ResourceNode *));
        for (int j = 0; j < hashTable->size; j++) {
            newHashTable[i].entries[j] = hashTable->entries[j];
        }
    }

    // Free the memory of the old hash table with chaining
    free(hashTable);

    // Set the new hash table with chaining as the current hash table with chaining
    hashTableArray = newHashTable;
}

// Function to query the number of unique RNTIs currently in the hash table with chaining
int getNumUniqueRNTIs() {
    return hashTableArray->numEntries;
}

// Function to query the total number of MAC PDU structures allocated
int getTotalMACPDUStructuresAllocated() {
    int total = 0;
    for (int i = 0; i < numEntries; i++) {
        total += macPduArray[i].header.rnti;
    }

    return total;
}

// Function to encrypt the populated structures using the OpenSSL library based on a command line option provided as a string parameter
void encryptPopulatedStructures(const char *password) {
    // Derive the encryption key from the given password using a secure key derivation function (KDF) with adjustable parameters for key length and iterations
    unsigned char key[32];
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char *)password, strlen(password), 1000, key, NULL);

    // Generate a cryptographically secure initialization vector (IV) for each encryption context
    unsigned char iv[32];
    RAND_bytes(iv, sizeof(iv));

    // Encrypt the populated structures using AES-256 in CBC mode with the derived key and IV
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    for (int i = 0; i < numEntries; i++) {
        EVP_EncryptUpdate(ctx, macPduArray[i].header.rnti, sizeof(macPduArray[i].header.rnti), &macPduArray[i].header.rnti, sizeof(macPduArray[i].header.rnti));
        EVP_EncryptUpdate(ctx, macPduArray[i].macSdu.data, macPduArray[i].macSdu.size, &macPduArray[i].macSdu.data, sizeof(macPduArray[i].macSdu.data));
        EVP_EncryptUpdate(ctx, macPduArray[i].ieList.numIEs, sizeof(macPduArray[i].ieList.numIEs), &macPduArray[i].ieList.numIEs, sizeof(macPduArray[i].ieList.numIEs));
        for (int j = 0; j < macPduArray[i].ieList.numIEs; j++) {
            EVP_EncryptUpdate(ctx, macPduArray[i].ieList.ieList[j].id, sizeof(macPduArray[i].ieList.ieList[j].id), &macPduArray[i].ieList.ieList[j].id, sizeof(macPduArray[i].ieList.ieList[j].id));
            EVP_EncryptUpdate(ctx, macPduArray[i].ieList.ieList[j].length, sizeof(macPduArray[i].ieList.ieList[j].length), &macPduArray[i].ieList.ieList[j].length, sizeof(macPduArray[i].ieList.ieList[j].length));
            EVP_EncryptUpdate(ctx, macPduArray[i].ieList.ieList[j].data, macPduArray[i].ieList.ieList[j].length, &macPduArray[i].ieList.ieList[j].data, sizeof(macPduArray[i].ieList.ieList[j].data));
        }
    }

    // Free the memory of the encryption context
    EVP_CIPHER_CTX_free(ctx);
}

// Function to manage memory allocation and deallocation to prevent leaks
void manageMemory() {
    // Allocate memory for the array of MAC PDU structures
    macPduArray = (MAC_PDU *)malloc(numEntries * sizeof(MAC_PDU));

    // Populate each MAC PDU structure with a valid header, SDU, and IE list
    for (int i = 0; i < numEntries; i++) {
