// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformation;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    size_t capacity; // Maximum number of elements in the list
    size_t count; // Current number of elements in the list
    NFAPI_CRC_INDICATION_PDU_T* elements; // Array of NFAPI_CRC_INDICATION_PDU_T structures
} NFAPI_CRC_INDICATION_LIST_T;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T* createAndPopulateList(size_t numElements) {
    // Check if the input is valid
    if (numElements > 10000) {
        printf("Error: Number of elements exceeds maximum allowed value\n");
        return NULL;
    }

    // Allocate memory for the list
    NFAPI_CRC_INDICATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        printf("Error: Failed to allocate memory for the list\n");
        return NULL;
    }

    // Initialize the list
    list->capacity = numElements;
    list->count = 0;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numElements);
    if (!list->elements) {
        printf("Error: Failed to allocate memory for the elements of the list\n");
        free(list);
        return NULL;
    }

    // Populate the list with random data
    for (size_t i = 0; i < numElements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[i];
        element->rxUeInformation.tag = RX_UE_INFORMATION_TAG;
        element->rxUeInformation.length = sizeof(RX_UE_INFORMATION_TAG);
        element->rxUeInformation.value = (void*)malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (!element->rxUeInformation.value) {
            printf("Error: Failed to allocate memory for the RX_UE_INFORMATION_TAG\n");
            free(list);
            return NULL;
        }
        element->rnti = (RNTI)malloc(sizeof(RNTI));
        if (!element->rnti) {
            printf("Error: Failed to allocate memory for the RNTI\n");
            free(list);
            return NULL;
        }
        element->crcIndicationRel8.tag = CRC_INDICATION_REL8_TAG;
        element->crcIndicationRel8.length = sizeof(CRC_INDICATION_REL8_TAG);
        element->crcIndicationRel8.value = (void*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!element->crcIndicationRel8.value) {
            printf("Error: Failed to allocate memory for the CRC_INDICATION_REL8_TAG\n");
            free(list);
            return NULL;
        }
        element->crcIndicationRel8.crCFlag = (bool)rand() % 2; // Randomly set CRCFLAG to true or false
    }

    // Log the total number of elements processed and any errors encountered during memory allocation
    printf("Total number of elements processed: %zu\n", numElements);
    if (list->count < numElements) {
        printf("Error: Failed to allocate memory for all elements in the list\n");
    }

    // Return the populated list
    return list;
}

// Function to free the memory allocated by createAndPopulateList()
void destroyList(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (!list) {
        return;
    }

    // Free the elements of the list
    for (size_t i = 0; i < list->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[i];
        free(element->rxUeInformation.value);
        free(element->rnti);
        free(element->crcIndicationRel8.value);
    }

    // Free the memory allocated for the list itself
    free(list->elements);
    free(list);
}
